P.entries["topic:plague-of-undeath"] = {n="Чума Нежиття",s="Чума Нежиття — надприродна зараза, яку Король-Ліч зготував за вказівкою Палаючого Легіону, щоб спустошити північ Східних Королівств. Вона поширюється через заражене зерно, котли, що отруюють повітря, і забруднені водойми, швидко вбиває живих смертних і піднімає їх як бездумних рабів Погибелі.",h="Чума Нежиття — надприродна зараза, яку Король-Ліч зготував за вказівкою Палаючого Легіону, щоб спустошити...",kw={"чума нежиття","чума","погибель","культ проклятих","андоргал","кел'тузад","нова чума","чумні землі"},ang={["class:Paladin"]="Орден Срібної Длані розпався, намагаючись стримати заразу, і тепер паладинам лишається покладатися тільки на Святе Світло, щоб очищати її мерзенні рештки.",["class:Priest"]="У чумі жерці стикаються з найглибшим зіпсуттям тіла й духу, і їхня віра мусить випалити некротичну хворобу, перш ніж та загноїться.",["faction:Alliance"]="Утрата північних королівств через чуму — незагоєна рана Альянсу, що спонукає його й далі боротися за очищення Чумних Земель.",["faction:Horde"]="Орки й таурени вважали північну хворобу прокляттям людей, але дослідження Королівського Аптекарського Товариства принесли жах чумних експериментів просто в Орду.",["race:Human"]="Чума Нежиття знищила королівство Лордерон і розлучила родини — саме вона безпосередньо спричинила найбільшу катастрофу в історії людства.",["race:Undead"]="Багато Відступників носять на тілі шрами чуми: вони пережили її муки, померли — і лише роки потому вирвалися з психічної хватки Короля-Ліча."},sec={{t="Витоки серед льодів",b="Чуму вигадав полеглий шаман Нер'жул, після того як Кіл'джеден перетворив його на Короля-Ліча. Зі свого крижаного престолу на Крижаному Троні в Нортренді Нер'жул удосконалював хворобу як несвятий авангард вторгнення Палаючого Легіону. Випробовуючи свою силу на відокремлених людських селах Нортренду, він виявив, що може гасити життя й подумки керувати трупами, які невдовзі підводилися. Телепатичний поклик Нер'жула сягнув через Велике Море до мага Кірін-Тору Кел'Тузада, і той покинув Даларан, щоб служити цій сутності. Кел'Тузад організував таємний Культ Проклятих, чиї смертні лазутчики підготували ґрунт, щоб отруїти Лордерон зсередини."},{t="Зерно Андоргала",b="Кел'Тузад і жахолорд Мал'Ганіс обрали для поширення зарази хлібний край Лордерону. Культ захопив склади довкола Андоргала й пакував чуму в ящики із зерном, призначені для міст і сіл по всій півночі, зокрема для Брілла й Стратгольма. Нічого не підозрюючи, селяни пекли хліб із зараженого зерна й захворювали: суглоби горіли вогнем, сочилися виразки, а очі ставали молочно-каламутними. За три дні гинули цілі громади — і одразу ж підводилися як зомбі-трупоїди, скорені психічному поклику Короля-Ліча. Принц Артас Менетіл поспішав перехопити ці поставки, і все завершилося жахливим винищенням городян Стратгольма, перш ніж заражений хліб перетворив би їх на військо Мал'Ганіса."},{t="Сплюндрована земля",b="Ця зараза вражає не лише людей. Хоча тварини здебільшого не повстають як раби-нежить, а потерпають від виснажливої гарячки чи гниття, сама земля приймає на себе головний удар демонічного й некромантичного тліну. По всіх Чумних Землях величезні чумні котли викидають у повітря алхімічні й магічні випари, отруюючи довколишні землі, де розплоджуються трупні черв'яки й велетенські гриби, обліплені спорами. Срібний Світанок активно бореться з цим повітряним зіпсуттям, псуючи котли й обертаючи їхні суміші-каталізатори так, щоб ті палили Погибель, а не живили її. А тим часом в Андерсіті Королівське Аптекарське Товариство невтомно експериментує, удосконалюючи Нову Чуму, що має вбивати і живих ворогів, і нежить."}},faq={{q="Як чума спочатку поширилася Лордероном?",a="Культ Проклятих Кел'Тузада проник у торговий вузол Андоргал. Культисти заразили чумою запаси зерна й розіслали ящики містам по всьому королівству, як-от Стратгольму й Бріллу. Коли місцеві з'їдали заражене борошно, вони занедужували й вставали нежиттю.",al={"як чума поширилася","заражене зерно","розподіл чумного зерна","зерно андорґала"}},{q="Що відбувається з тим, хто заразився чумою?",a="У жертв швидко з'являються слабкість, нудота, ломота в суглобах і гарячка. Шкіру вкривають запалені нариви й сочливі жовто-зелені виразки, а очі мутніють. Невдовзі починаються сильні кровотечі з вух і очей. Більшість смертних помирає за три дні, а згодом встає ожилими слугами, що чекають наказів Короля-Ліча.",al={"симптоми чуми","що робить чума","як швидко чума вбиває"}},{q="Чому чума діє на людей інакше, ніж на інші раси?",a="Король-Ліч навмисно створив чуму проти людства, щоб знищити Королівство Лордерон. Звірі й нелюдські раси, що зазнали чуми, часто страждають від жахливої гнилі, марення й гарячки, але рідко самі по собі встають рабами Погибелі без додаткових прямих некромантичних чарів.",al={"чому чума діє на людей","чи чума діє на ельфів","чи орки імунні до чуми"}},{q="Чи можна вилікувати Чуму Нежиття?",a="Нині відомих ліків немає. Природні засоби не здатні здолати чуму; щойно жертва померла й піднялася, перетворення вже не скасувати.",al={"чи чума виліковна","ліки від чуми","зцілення чуми"}},{q="Для чого велетенські казани в Чумних Землях?",a="Погибель поставила на колишніх угіддях величезні казани, щоб випускати випари чуми просто в повітря. Так чума отруює ґрунт, затьмарює небо й заражає звірів, що проходять повз. Срібний Світанок невтомно протидіє цим казанам, перетворюючи їхні складники на святі чи отруйні засоби проти Погибелі.",al={"чумні казани","що роблять казани","чому казани на полях"}},{q="Що таке Нова Чума Відступників?",a="Нова Чума — особливий хіміко-магічний збудник, розроблений у надрах Андерсіті Королівським Аптекарським Товариством. На відміну від чуми Погибелі, Відступники створюють свою формулу так, щоб вона вбивала і живих смертних, і неживих рабів Короля-Ліча.",al={"чума відступників","чума королівського аптекарського товариства","нова чума підміська"}}},fp="17,331,18.692.0,21.743.1,16.736.0,54.310.0,47.345.0,63.315.0,35.164.0,52.337.0,34.278.0"}
P.entries["topic:priest"] = {n="Жрець",s="Жерці — духовні провідники й носії величезної незримої сили, що формують віру, загоюють плоть і оберігають душі. Спрямовуючи сяйну енергію віри чи пірнаючи в моторошні глибини Порожнечі, вони стають життєдайним серцем будь-якого бойового загону. По всьому Азероту їхні традиції різняться — від Церкви Святого Світла до Сестринства Місячної Богині й тіньових культів Відступників.",h="Жерці — духовні провідники й носії величезної незримої сили, що формують віру, загоюють плоть і оберігають...",kw={"жрець","жерці","церква святого світла","сестринство елуни","культ забутої тіні","порожнеча","зцілення"},ang={["class:Paladin"]="Паладини поділяють святе вчення зі священством: вони постали з потреби Церкви захищати кліриків у рясах після кривавих уроків Першої війни.",["class:Priest"]="Ви, жрець, ступаєте межею між чистим сяйвом і нищенням розуму, володіючи і цілющим милосердям молитви, і карними жахіттями Порожнечі.",["race:Human"]="Людські жерці успадковують стійку традицію Кліриків Нортшира й через Церкву Святого Світла стають духовною опорою Альянсу.",["race:NightElf"]="Жриці нічних ельфів шанують Сестринство Елуни, спрямовуючи зоряне сяйво й місячну благодать під проводом Верховної Жриці Тіранди Віспервінд.",["race:Undead"]="Жерці-Відступники переосмислюють свою розбиту віру через Культ Забутої Тіні, приймаючи рівновагу темних енергій там, де колишні обітниці принесли лише руїну."},sec={{t="Посудини віри й відданості",b="Жерці визначають духовну долю своїх громад. Поки бійці випробовують себе сталлю, жерці черпають силу просто з переконань. Завдяки зв'язку з божественним вони вгамовують тяжкі рани, повертають полеглих товаришів із порогу смерті й плетуть містичні бар'єри, що відбивають шкоду. Їхня присутність на полі бою часто вирішує, чи загін виживе, чи загине."},{t="Світло й Тінь",b="Священство — не лише знаряддя добра. Як у житті є і світло, і темрява, так і жрець ступає небезпечною межею між божественним зціленням і нищенням розуму. Ті, хто опанував святі мистецтва, закликають на ворогів пекучу праведну кару, а знавці магії Тіні пірнають у Порожнечу, щоб підкоряти розум, ламати волю й завдавати нестерпного болю здалеку."},{t="Мозаїка вір",b="Жодна віра не визначає жерців Азероту одноосібно. У землях людей і дворфів Церква Святого Світла впорядкувала філософію чесноти, а після Першої війни перетворила тендітних Кліриків Нортшира на загартований орден. У Калімдорі Сестринство Елуни нічних ельфів шанує Матір-Місяць зоряним сяйвом і благодаттю, а тролячі знахарі благають первісних Лоа. Серед щойно повсталих Відступників багато хто відвернувся від колишніх догм до Культу Забутої Тіні, що проповідує: темрява й світло мусять існувати в тонкій рівновазі."}},faq={{q="Чим жрець відрізняється від паладина?",a="Під час Першої війни людські клірики масово гинули на полі бою, бо не мали бойового захисту. У відповідь Архієпископ Алонсус Фаол і Церква заснували Лицарів Срібної Длані, навчаючи святих воїнів у латах — паладинів. Жерці ж лишаються заклиначами в ризах, відданими суто духовному служінню, молитві й глибшому опануванню розуму й тіні.",al={"жрець проти паладина","чому грати жрецем а не паладином","лор жреця чи паладина"}},{q="Чи можуть жерці користуватися магією Тіні, не втрачаючи віри?",a="Так. Духовна рівновага вчить, що світла не буває без темряви. Багато жерців вивчають тінь, щоб зрозуміти небезпеки, які загрожують їхній пастві, а інші, як-от Культ Забутої Тіні Відступників, свідомо приймають темні сили як необхідність буття, стверджуючи, що опанувати себе по-справжньому можна, лише розуміючи обидві сили.",al={"чому жерці користуються тінню","лор жреця тіні","баланс тіні й світла"}},{q="Чи жерці всіх рас поклоняються одному й тому самому?",a="Ні. Люди й дворфи переважно сповідують віру Церкви Святого Світла — філософію чеснот, а не поклоніння божеству. Нічні ельфи шанують Елуну через її Сестринство, тролі молять духів і лоа, а жерці з нежиті-Відступників дотримуються Культу Забутої Тіні або борються з надірваним зв'язком зі своєю колишньою людською вірою.",al={"релігії жерців","яким богам поклоняються жерці","жрець елуни проти світла"}},{q="Хто очолює людське жрецтво в Стормвінді?",a="Після падіння Лордерона Собор Світла в Стормвінді став головним осідком людської церкви. Тамтешнє духовенство разом із кліриками Нортшира, що вціліли, опікується духовним відродженням людства й веде душі Альянсу в ці неспокійні часи.",al={"лідер церкви світла","лідер собору стормвінда","лідер жерців стормвінда"}},{q="Чому у Відступників досі є жерці?",a="Багато хто з нежиті зберіг спогади й уміння своєї колишньої побожності в Лордероні. Зазнавши покинутості смерті, дехто прийняв Культ Забутої Тіні, володіючи темними силами й вивчаючи рівновагу між темрявою і світлом. Інші вперто й далі закликають Святе Світло, хоча це завдає їхній гниючій плоті нестерпних мук.",al={"жерці нежиті лор","чи нежить користується світлом","жерці тіні відступників"}},{q="Що таке Сестринство Елуни?",a="Сестринство Елуни — прадавній орден жриць нічних ельфів, заснований задовго до Війни Прадавніх. На чолі з Верховною Жрицею Тірандою Віспервінд вони шанують місячну богиню Елуну й служать цілительками, духовними наставницями й надзвичайно вправними провідницями суспільства нічних ельфів.",al={"нічноельфійські жриці","жриці місяця","сестринство елуни"}}},fp="6,382,29.402.0,16.410.0,20.551.0,54.375.0,56.342.0,56.354.0,44.279.0,39.376.0,32.289.0"}
P.entries["topic:quilboar"] = {n="Шипогрив",s="Шипогриви — войовничі вепроподібні гуманоїди з центрального Калімдору, відомі гострими голками на хребті та невтомною лютістю в обороні своїх земель. Вони вважають себе нащадками полеглого напівбога Агамаґґана й живуть у густих лабіринтах гострих, мов бритва, терниць у Дуротарі, Малгорі та Пустках. Запекла боротьба за воду, ґрунт і священні землі робить їх постійною загрозою для мандрівників і поселень Орди.",h="Шипогриви — войовничі вепроподібні гуманоїди з центрального Калімдору, відомі гострими голками на хребті та...",kw={"шипогриви","агамаґґан","рейзорфен краул","рейзорфен даунс","гостромани","щетиноспини","пустки"},ang={["class:Shaman"]="Геомантія шипогривів — земляна, прадавня гілка шаманської традиції, хоч і спотворена задля жорстокої боротьби за землю та виклику диких духів-вепрів.",["faction:Horde"]="Шипогриви — нагальна загроза для постачання по всьому центральному Калімдору: вони влаштовують засідки на важливі каравани, що ходять між Оргріммаром, Перехрестям і Тандер Блафом.",["race:Orc"]="Щоб утримати Дуротар і Пустки, треба розбити бойові загони шипогривів, чиї набіги раз у раз докучають торговим возам Орди й віддаленим хуторам.",["race:Tauren"]="Ваші предки билися з шипогривами за водопої й пасовиська задовго до того, як орки припливли на захід. Їхні загарбницькі терниці душать живу землю, яку плекає Земна Мати."},sec={{t="Діти Великого Вепра",b="Шипогриви шанують Агамаґґана — велетенського вепра-Прадавнього, що загинув у боротьбі з Палаючим Легіоном під час Війни Прадавніх десять тисяч років тому. За їхніми священними переказами, шипогриви — його смертні нащадки. Там, де Агамаґґан стікав кров'ю й помер у центральному Калімдорі, з випаленої землі вирвалися величезні колючі лози й утворили розлогі лабіринти коріння, які шипогриви вважають святою землею. Його скам'яніла кров досі трапляється в Пустках як багряні Кров'яні Уламки — геоманти шипогривів викопують їх і шанують як могутні талісмани."},{t="Тернисті нори й геомантія",b="Замість будувати звичні селища з каменю чи дерева, шипогриви вирощують велетенські терниці, що душать довколишню рослинність і роблять навколишню землю неродючою. Племена зазвичай ведуть могутні геоманти — знавці приземленого, грубого шаманства, що радяться з каменями й кристалами, щоб спрямовувати клан. Ці містики закликають дух Агамаґґана, щоб викликати в бій примарних вепрів. Оскільки в посушливих центральних рівнинах мало оаз, шипогриви вважають воду найбільшим скарбом: коли випадають рідкісні дощі, вони влаштовують пишні бенкети, а водопої боронять із лютою завзятістю."},{t="Війна за Пустки",b="Поколіннями шипогриви запекло ворогували з кочовими тауренами й мандрівними зграями кентаврів. Коли Тралл привів Орду орків до Калімдору, орки швидко заселили Дуротар і проклали торгові шляхи через Пустки, і витіснені племена підняли відкритий заколот. Загони шипогривів влаштовують засідки на вози з припасами, нападають на застави на кшталт Перехрестя й Табору Тауражо, а ще їх підозрюють у тому, що вони наганяють сполоханих довгоступів на валки возів. Відкритими рівнинами заправляють два головні племена — Гостромани й Щетиноспини, — і обидва водночас ворогують і з Ордою, і між собою."},{t="Тінь над Рейзорфеном",b="Духовне серце цивілізації шипогривів лежить на південному краю Пусток — у Рейзорфен Краулі та сусідньому Рейзорфен Даунсі, заплутаних лабіринтах, що виросли просто з велетенських останків Агамаґґана. Владолюбна стара відьма на ім'я Чарлґа Рейзорфленк захопила владу над Краулом і влаштовує напористі напади на суперницькі клани та землі Орди. Ще гірше те, що споконвічна столиця шипогривів, Рейзорфен Даунс, потрапила під владу Погибелі. У змові з лічем Амненнаром Хладоносцем зіпсовані шипогриви Мертвої Голови піддалися нежиттю й перетворили гробницю предків на зачумлену твердиню."}},faq={{q="Чому шипогриви так ненавидять Орду?",a="Шипогриви займали родючі оази й колючі яри Дуротару та Пусток задовго до приходу Орди. Коли народ Тралла висадився й забрав землю під Оргріммар, він витіснив місцеві лігва шипогривів. До того ж Орда уклала союз із тауренами, з якими шипогриви воювали поколіннями. Тепер племена вважають кожен караван, заставу й криницю вкраденою землею предків.",al={"чому шипогриви нападають на орків","конфлікт шипогривів з ордою","чому шипогриви ворожі"}},{q="Як шипогриви пов'язані з Аґамаґґаном?",a="Аґамаґґан — колосальний напівбог-вепр, що бився з Палаючим Легіоном у Війні Прадавніх десять тисяч років тому. Шипогриви вважають себе його смертними нащадками. Величезні колючі хащі, де вони живуть, проросли там, де його кров просочила землю, а священні тунелі Рейзорфен Даунс, кажуть, вирізьблені з його останків.",al={"аґамаґґан бог шипогривів","хто такий аґамаґґан","напівбог шипогривів"}},{q="Що за червоні камені носять шипогриви?",a="Ці багряні кристали — Кров'яні Уламки, що утворилися зі скам'янілої крові Аґамаґґана. Шипогриви викопують їх по всіх Пустках, вірячи, що в них живе снага й сила їхнього полеглого пращура. Геоманти використовують ці камені як каталізатори в обрядах землі й бойових чарах.",al={"кров'яні уламки","червоні скелі шипогриви","кров аґамаґґана"}},{q="Яку магію використовують шипогриви?",a="Шипогриви практикують геомантію — стихійне ремесло, схоже на примітивне шаманство, зосереджене на камені, землі й колючках. Ворожіння на каменях і самоцвітах вони шанують понад усі інші містичні мистецтва. Племінні геоманти закликають духів землі, викликають ожину, щоб обплутати ворогів, і прикликають духів вепрів на подобу Аґамаґґана.",al={"магія шипогривів","геомансери шипогривів","що таке геомантія"}},{q="Чому шипогриви так ревно бережуть воду?",a="Пустки — посушливе пустище, де природні джерела й оази надзвичайно рідкісні. У культурі шипогривів вода означає виживання, багатство й духовне благословення. Вони святкують навіть найменший дощ у пустелі племінними бенкетами й люто бережуть джерела від караванів і стад, що підступають.",al={"вода шипогривів","чому шипогриви скуповують воду","оази шипогривів"}},{q="Чим Рейзорфен Краул відрізняється від Рейзорфен Даунс?",a="Обидва — величезні лабіринти колючих хащів, що проросли з тіла Аґамаґґана на півдні Калімдору. Рейзорфен Краул — твердиня старої відьми Чарлґи Рейзорфленк, що згуртовує живих шипогривів проти всіх чужинців. Рейзорфен Даунс був прадавньою столицею народу, але його захопив ліч Погибелі Амненнар Хладоносець, що піднімає мертвих шипогривів як неживих прислужників.",al={"краул проти даунсу","рейзорфен підземелля","де живуть шипогриви"}}},fp="8,419,26.543.0,28.581.0,23.582.0,24.632.1,39.401.0,56.327.0,39.289.0,35.305.0,40.300.0,65.385.1"}
P.entries["topic:ravenholdt"] = {n="Рейвенголдт",s="Рейвенголдт, відомий також як Ліга Вбивць, — елітна гільдія розбійників, злодіїв і вбивць, що базується у відлюдному гірському маєтку над Передгір'ям Гілсбреда. Під проводом Лорда Джораха Рейвенголдта ліга суворо тримається осторонь фракційної політики, водночас ведучи нескінченну таємну війну зі своїми заклятими суперниками — Синдикатом. Вона випробовує й приймає лише найхитріших агентів Азероту, понад усе цінуючи бездоганну дисципліну, потайність і смертоносну вправність.",h="Рейвенголдт, відомий також як Ліга Вбивць, — елітна гільдія розбійників, злодіїв і вбивць, що базується у...",kw={"рейвенголдт","ліга вбивць","розбійники","синдикат","джорах рейвенголдт","передгір'я гілсбреда","отрути"},ang={["class:Rogue"]="Рейвенголдт — ваше всесвітнє братство й місце випробувань. Тутешні наставники, отруйники й майстри тіней пропонують випробування, рідкісні креслення зброї та визнання, якого не здобути більше ніде на Азероті.",["faction:Alliance"]="Хоча Матіас Шоу й SI:7 часом діють спільно з Рейвенголдтом, щоб приборкати Синдикат, Лорд Рейвенголдт не присягав Стормвінду й може недбало відхилити навіть найважливіші прохання Альянсу.",["faction:Horde"]="Попри шляхетний людський фасад і розташування в північних нагір'ях, Рейвенголдт судить агентів лише за їхньою майстерністю й радо приймає вистежувачів Орди, які доведуть, чого варті."},sec={{t="Прихована ліга",b="Захований у скелястих горах між Гілсбредом і Альтераком, Маєток Рейвенголдт — нервовий центр найкращого братства вбивць Азероту. Під проводом Лорда Джораха Рейвенголдта організація діє далеко поза владою королів і вождів. У його стінах майстри шліфують кожне смертоносне мистецтво: Майстер Канґ навчає учнів ближнього бою й убивства, брати Тандервуд варять рідкісні смертельні отрути, а гноми-умільці конструюють хитромудрі замки, щоб випробовувати новачків. Для тих, хто не належить до розбійників, увійти до маєтку — відверто загравати зі смертю: один необачний крок легко закінчиться отруєним кинджалом під ребро."},{t="Таємна війна із Синдикатом",b="Роками Рейвенголдт веде дедалі запеклішу ворожнечу із Синдикатом — аристократичним злочинним картелем, що розплодився в Альтераку й Араті. Хоча Ліга вважає членів Синдикату незграбними, пихатими аматорами, через саму їхню кількість знищити їх простою різаниною неможливо. Натомість Рейвенголдт вдається до психологічних і структурних підривних дій: наймані розбійники крадуть емблеми-печатки, які носять ватажки Синдикату, а далі Ліга покладається на параною самого Синдикату та його безжальну ієрархію — зганьблених членів страчують свої ж."},{t="Незалежна гільдія тіней",b="Хоча Рейвенголдт часом співпрацює з іншими розвідувальними службами, як-от SI:7 Стормвінда, він не підкоряється жодній короні. Майстер Матіас Шоу іноді знаходить у Рейвенголдті союзника у стримуванні Синдикату, але Джорах Рейвенголдт затято оберігає свою незалежність. Коли SI:7 зазнала тяжких утрат, розслідуючи справу полеглого слідопита Натаноса Марріса в Чумних Землях, Рейвенголдт навідріз відмовив Шоу в проханні втрутитися. Ліга сама обирає свої битви: спрямовує сили на здобуття давніх реліквій і вдосконалення смертоносних мистецтв і тримає клинок біля горла кожного, кому забракне розуму перейти їй дорогу."}},faq={{q="Що таке Рейвенголдт?",a="Рейвенголдт — давня таємна гільдія злодіїв, убивць і тіньових танцюристів під проводом Лорда Джораха Рейвенголдта. Неофіційно її звуть Лігою Вбивць. Вона діє з потаємного маєтку глибоко в горах над Передгір'ями Гілсбреда, навчає обдарованих розбійників і бере смертельні замовлення.",al={"хто такі рейвенголдт","ліга убивць","фракція рейвенголдт"}},{q="Чому вони воюють із Синдикатом?",a="Синдикат і Рейвенголдт змагаються за панування серед руїн Альтераку й довколишніх нагір'їв. Ліга вважає членів Синдикату недисциплінованими, безчесними розбійниками, чиї неохайні злочинні оборудки загрожують тонкій рівновазі сил у краї. Замість винищувати їх у виснажливій боротьбі, Рейвенголдт методично підточує їхній провід, викрадаючи їхні знаки рангу.",al={"синдикат проти рейвенголдту","війна рейвенголдту й синдикату","чому ненавидять синдикат"}},{q="Чи можуть не-розбійники відвідати Маєток Рейвенголдт?",a="Дістатися до маєтку можуть і не-розбійники, але мешканці чужинців не вітають. Вартові й убивці ледь завуальовано погрожують отруєними напоями й кинджалами в спину кожному, хто забреде сюди без тіньової виучки чи справи до Лорда Рейвенголдта.",al={"чи інші класи можуть у рейвенголдт","воїн у рейвенголдті","чи рейвенголдт тільки для розбійників"}},{q="Хто такий Лорд Джорах Рейвенголдт?",a="Лорд Джорах Рейвенголдт — невловимий володар Ліги Вбивць. Зі свого гірського маєтку він тримає розлогу мережу наставників-розбійників та інформаторів на всіх континентах і посилає довірених учнів добувати могутні артефакти й усувати загрози з боку суперників.",al={"хто веде рейвенголдт","джорах рейвенголдт","лідер рейвенголдту"}},{q="Що таке Обряд Хитрості?",a="Це вступне випробування для охочих стати учнями, що шукають Маєток Рейвенголдт. Проходячи гірським тунелем, що веде до маєтку, новачок мусить покластися на вміння помічати пастки; у чому небезпека, з'ясується під час обряду.",al={"обряд хитрості","випробування розбійників рейвенголдт","тунельний тест рейвенголдт"}},{q="Як Рейвенголдт ставиться до Альянсу й Орди?",a="Рейвенголдт цілком нейтральний щодо фракційної політики й приймає вправних головорізів, хоч би звідки вони були — з Оргріммара чи з Айронфорджа. Він підтримує ввічливі зв'язки з такими організаціями, як SI:7 у Стормвінді, але відмовляється бути пішаком у війні будь-якого королівства.",al={"чи рейвенголдт альянсу чи орди","нахил рейвенголдту","на кого працює рейвенголдт"}}},fp="10,487,17.655.0,29.572.0,31.605.1,19.312.0,36.399.0,38.271.0,30.286.0,28.237.0,52.301.0"}
P.entries["topic:razorfen"] = {n="Рейзорфен",s="Рейзорфен — спільна назва головного племені шипогривів південного Калімдору та їхніх розлогих поселень, оповитих терном. Вирізаний у велетенських терницях уздовж південного кордону Пусток і на краю Тисячі Голок, Рейзорфен охоплює твердині Рейзорфен Краул і Рейзорфен Даунс. Це водночас духовне серце й головний оплот сили шипогривів.",h="Рейзорфен — спільна назва головного племені шипогривів південного Калімдору та їхніх розлогих поселень...",kw={"рейзорфен","рейзорфен краул","рейзорфен даунс","шипогриви","агамаґґан","пустки","тисяча голок"},ang={["class:Druid"]="Терниці Рейзорфену проросли з жертви Прадавнього Агамаґґана; друїди з глибокою тривогою дивляться на осквернення й зіпсуття такого священного місця.",["class:Shaman"]="Геоманти Рейзорфену підкоряють духів землі й каменю грубими обрядами стихій, і шамани, що шукають рівноваги, не можуть лишити це поза увагою.",["faction:Horde"]="Контроль над південними Пустками вкрай важливий для постачання Орди, а войовничі нападники Рейзорфену раз у раз докучають караванам, що ходять між Малгором, Перехрестям і південним прикордонням.",["race:Tauren"]="Шипогриви Рейзорфену поколіннями жорстоко билися з мисливськими загонами й поселеннями тауренів у Пустках, тож їхнє знищення — справа безпеки рідного краю."},sec={{t="Терни Агамаґґана",b="За легендою, велетенські колючі терниці, з яких складається Рейзорфен, проросли десять тисяч років тому, під час Війни Прадавніх. Коли гігантський вепр-Прадавній Агамаґґан загинув у бою з Палаючим Легіоном, його кров усоталася в землю всюди, де він стікав кров'ю й помирав. Із цієї божественної жертви виросли величезні лози скам'янілого терну з колючками, твердими, мов залізо, і створили природну фортецю, де відтоді живуть його нащадки — шипогриви."},{t="Плем'я Рейзорфен",b="Плем'я Рейзорфен — одне з найвойовничіших і найміцніше закорінених серед усіх шипогривів. Замість розселятися у відкритих норах, вони збудували складні громади-лабіринти просто всередині велетенських терниць. Із цих фортець плем'я люто боронить землі предків від сусідніх племен тауренів, поселень Орди в Пустках і будь-яких чужинців, що наважуються вдертися на їхню святу землю."},{t="Розділена цитадель",b="Царство Рейзорфен поділено на два окремі оплоти. Рейзорфен Краул — споконвічна столиця й військовий табір шипогривів, який стережуть їхні шамани й мисливиці. Далі на південь, на межі з Тисячею Голок, лежить Рейзорфен Даунс — священне місто предків і усипальниця старійшин шипогривів, над якою нині нависло глибше некромантичне зіпсуття, що загрожує всім довколишнім землям."}},faq={{q="Що таке Рейзорфен?",a="Рейзорфен — це і впливове плем'я шипогривів на півдні Пусток, і їхні укріплені поселення, вплетені у величезні колючі лабіринти: Рейзорфен Краул і Рейзорфен Даунс.",al={"що таке рейзорфен","значення рейзорфен","лор рейзорфена"}},{q="Звідки взялися велетенські колючки?",a="Колючки — скам'яніла кров і рештки Дикого Бога Аґамаґґана, Великого Вепра. Коли він поліг у бою з Палаючим Легіоном у прадавній Війні Прадавніх, усюди, де його кров упала на землю, виросли величезні колючі пагони.",al={"гігантські терни пустовиськ","терни аґамаґґана","чому гігантські терни"}},{q="Чим Рейзорфен Краул відрізняється від Рейзорфен Даунс?",a="Рейзорфен Краул — живе місто й головна твердиня племені Рейзорфен, повна воїнів і геомантів. Рейзорфен Даунс — прадавнє поховальне місце й священний спочинок старійшин шипогривів, що лежить далі на південь, у бік Тисячі Голок.",al={"краул проти даунсу","різниця підземель рейзорфена"}},{q="Чому шипогриви ворожі до всіх?",a="Шипогриви вважають землю Пусток та її великі хащі своєю божественною спадщиною від Аґамаґґана. Усі чужі раси — особливо Орду, що розростається, — вони мають за злодійкуватих зайд, що вдерлися на їхню святу землю.",al={"чому шипогриви нападають","лор шипогривів"}},{q="Де розташований Рейзорфен?",a="Величезні колючі хащі Рейзорфену лежать на крайньому півдні Пусток, просто вздовж високих урвищ, що спускаються до солончаків і річкового каньйону Тисячі Голок.",al={"мапа рейзорфена","де рейзорфен"}},{q="Яку магію використовують шипогриви Рейзорфену?",a="Здавна шипогриви Рейзорфену практикують магію землі й природи, відому як геомантія, закликаючи силу каменю й колючок. Проте останні події в Рейзорфен Даунс свідчать про тривожне вторгнення темної некромантії.",al={"шамани рейзорфена","магія шипогривів"}}},fp="8,403,23.461.0,18.421.0,17.412.1,17.180.0,37.239.0,65.258.0,41.229.0,26.180.0,48.224.0"}
P.entries["topic:rogue"] = {n="Розбійник",s="Розбійники — майстри потайності, шпигунства й раптового смертоносного бою, що диктують умови сутички з тіні. Покладаючись на легкі шкіряні обладунки, клинки в обох руках і власноруч зварені отрути, вони вражають зненацька, а тоді знову зникають у темряві. По всьому Азероту вони служать розвідниками, вбивцями, кишеньковими злодіями й агентами — і фракцій, і таємних синдикатів.",h="Розбійники — майстри потайності, шпигунства й раптового смертоносного бою, що диктують умови сутички з тіні.",kw={"розбійник","розбійники","потайність","отрути","si:7","скрадачі смерті","ліга вбивць"},ang={["class:Rogue"]="Для розбійника кожне доручення — вправа у важелях впливу, терпінні й смертоносній точності, чи ви працюєте агентом вищого командування, чи спустошуєте кишені в міських провулках.",["faction:Alliance"]="Таємна сила Альянсу тримається на таких організаціях, як SI:7 Стормвінда та Приховане Коло Айронфорджа, які протидіють внутрішнім змовам і зовнішнім загрозам.",["faction:Horde"]="Орда покладається на шпигунів Розтрощеної Руки в Оргріммарі та страшних скрадачів смерті Сильвани Віндраннер в Андерсіті, щоб розвідувати ворожі землі й тихо усувати загрози."},sec={{t="Удар із тіні",b="Розбійники цураються важких лат і відкритого протистояння, звичних для воїнів першої лінії. Вбрані в легку шкіру, щоб рухатися цілком безшумно й спритно, вони непомітно вистежують здобич. Вступаючи в бій, вони перехоплюють ініціативу з перших миттєвостей завдяки точності й раптовості, цілячись у життєво важливі органи чи незахищені суглоби. Користуючись невичерпним запасом енергії та швидкими поєднаннями ударів, розбійник виснажує ворога ретельно продуманою серією, а тоді завдає нищівного завершального удару."},{t="Отрути й вуличний розум",b="Самого клинка рідко досить професійному злодієві чи вбивці. Розбійники — вправні алхіміки смертоносних сумішей: власноруч готують отруйні покриви, що дурманять кінцівки, сповільнюють утечу чи швидко висисають життєву силу цілі. Разом з відмичками, метальною зброєю й хитрощами для відволікання це дає їм змогу прослизати крізь укріплені периметри, знешкоджувати пастки й проникати до сховищ, перед якими спасувала б ціла рота солдатів."},{t="Гільдії, корони й синдикати",b="Хоча багато розбійників діють як вовки-одинаки, грабіжники з великої дороги чи вуличні головорізи, найкращі агенти належать до впорядкованих розвідувальних мереж і гільдій убивць. Стормвінд покладається на таємних агентів SI:7, Айронфордж прихищає потаємне Приховане Коло, а Відступники мають невблаганних скрадачів смерті. В Оргріммарі тіньові рештки клану Розтрощеної Руки служать Вождеві, а елітна нейтральна Ліга Вбивць підкоряється Лордові Джораху Рейвенголдту."}},faq={{q="Які обладунки й зброю використовують розбійники?",a="Розбійники носять шкіряні обладунки, щоб рухатися безшумно й швидко, нічим не обтяжені. У бою вони б'ються двома одноручними клинками — передусім кинджалами, мечами, булавами й кастетами. Також вони носять тиху зброю дальнього бою — метальні ножі, луки чи арбалети, — щоб допомогти собі й виманювати цілі.",al={"спорядження розбійника","що можуть вдягати розбійники","тип броні розбійника"}},{q="Як працює скрадання розбійника?",a="Скрадання — це вивірене поєднання легкої ходи, вміння користуватися тінню й тонкої містики. Воно робить розбійника практично невидимим для віддалених спостерігачів, хоча, підійшовши надто близько до пильного вартового чи ворога, можна себе виказати. У скраданні розбійник може зайти здобичі за спину й завдати нищівного удару з засідки, задушити гароттою чи знешкодити ворога.",al={"як працює скрадання","чи розбійники стають невидимими","лор скрадання"}},{q="Що таке Ліга Рейвенголдт?",a="Ліга Вбивць з осідком у Маєтку Рейвенголдт у Горах Альтерак — давнє таємне братство на чолі з Лордом Джорахом Рейвенголдтом. На відміну від розвідок, прив'язаних до фракцій, Рейвенголдт — гільдія, віддана суто дисципліні, честі й ремеслу вбивці; вона бере замовлення, хоч би якій політичній стороні служив замовник.",al={"хто такі рейвенголдт","ліга убивць","лорд джорах рейвенголдт"}},{q="Що таке SI:7?",a="SI:7 — головна таємна розвідка Королівства Стормвінд. Її штаб у Стормвінді, а польові агенти, снайпери й злодії займаються шпигунством, гучними вбивствами й розвідкою на кордонах, захищаючи інтереси Альянсу по всьому Азероту.",al={"сі:7 стормвінд","сі:7","розвідка стормвінда"}},{q="Як розбійники б'ються в затяжному бою?",a="Коли вбити ціль першим ударом не вдається, розбійник спритністю й роботою ніг ухиляється від відповідних ударів. Він завдає швидких ударів один за одним двома клинками, користаючись слабкими місцями ворога й створюючи нагоди, що завершуються смертельними добивальними ударами, як-от розпорювання чи випатрування.",al={"стиль бою розбійника","лор комбо-очок","як б'ються розбійники"}},{q="Чи користуються розбійники магією?",a="Більшість розбійників покладається передусім на фізичну підготовку, бойову виучку, алхімічні суміші й звичайне скрадання. Проте досвідчені майстри часто вплітають у свій арсенал дрібну містику чи магію тіней, що допомагає їм приховати своє тіло, сховатися в тіні серед білого дня й миттєво зникнути з очей.",al={"чи скрадання розбійника магія","чи розбійники кастують"}}},fp="5,366,23.491.0,25.434.0,30.473.0,37.308.0,34.363.0,30.351.0,13.283.0,40.307.0,20.326.0"}
P.entries["topic:royal-apothecary-society"] = {n="Королівське Аптекарське Товариство",s="Королівське Аптекарське Товариство — алхімічна гільдія, заснована за Леді Сильвани Віндраннер, що має осідок в Апотекаріумі під Андерсіті. До нього входять дослідники-Відступники, і його головна мета — створити смертоносну Нову Чуму, здатну знищити Погибель і водночас помститися живим. Союзники з Орди вважають, що товариство шукає ліки від нежиття, але його дослідники по всьому Азероту збирають отрути, слиз і токсичні реагенти, щоб удосконалити зброю масового знищення.",h="Королівське Аптекарське Товариство — алхімічна гільдія, заснована за Леді Сильвани Віндраннер, що має осідок...",kw={"королівське аптекарське товариство","аптекарі","апотекаріум","нова чума","відступники","андерсіті","фаранелл"},ang={["faction:Horde"]="Представники Відступників запевняють, що їхня алхімічна праця шукає протиотруту, яка поверне їх із проклятого стану, але від їхніх відлюдних котлів в Апотекаріумі тхне смертоноснішими задумами.",["profession:Herbalism"]="Товариство надзвичайно цінує смертоносні рослини: збирає отруйні гриби, душильну водорість і могильний мох у кожному куточку Азероту, щоб живити свої заразні котли.",["race:Tauren"]="Зі співчуття до проклятих мерців старійшини допустили Аптекарку Замах до Ставків Видінь, вірячи, що Відступники щиро шукають очисних ліків від своєї недуги.",["race:Undead"]="Товариство — наукова міць вашого народу: воно обертає ту саму чуму, що вирізала Лордерон, на знаряддя помсти Погибелі й усім, хто вам протистоїть."},sec={{t="Помста через алхімію",b="Засноване невдовзі після звільнення Відступників, Королівське Аптекарське Товариство — наукове й алхімічне крило королівства Леді Сильвани Віндраннер. Зі своїх чанів і підземних лабораторій Апотекаріуму дослідники прагнуть обернути на зброю ту саму силу, що їх прокляла. Їхня головна справа — створення «Нової Чуми», суміші, покликаної знищити Погибель і Короля-Ліча. На відміну від традиційної людської алхімії, що віддає перевагу цілющим еліксирам чи трансмутації, Товариство безжально експериментує з мерзенними збудниками, їдкими кислотами й некромантичними сумішами, піднімаючи полеглих бойових коней як скелетних скакунів і зварюючи дедалі смертоносніші штами отруйної гнилі."},{t="Розрахований обман",b="Для зовнішнього світу Товариство вдає з себе вчених, яких ніхто не розуміє. У стосунках із союзниками в Оргріммарі й Тандер Блафі представники Відступників натякають, що їхні алхіміки невтомно шукають ліки від прокляття нежиття. Насправді ж Головного Аптекаря Фаранелла й темну раду зцілення мало цікавить. Товариство в цілковитій таємниці вдосконалює отрути, що не щадять нікого, потай випробовуючи їхню дію і на живих, і на мертвих піддослідних, щоб гарантувати цілковите знищення ворогів."},{t="Застави по всьому Азероту",b="Вплив Аптекарського Товариства сягає далеко за межі каналів Андерсіті. Польових аптекарів відряджають до віддалених застав Лордерону й Калімдору. У Срібноліссі та Гілсбреді агенти на кшталт аптекарів Ренферрела й Лайдона збирають місцеві рослини й переганяють отрути. У посушливих Пустках Аптекар Гелбрім описує дивну рослинність і тварин пустелі, а Аптекарка Замах працює під Тандер Блафом, у Ставках Видінь. Скрізь, де є природні отрути, мінливі слизні чи заразні організми, Товариство посилає служок збирати зразки для котлів Апотекаріуму."}},faq={{q="Що таке Королівське Аптекарське Товариство?",a="Королівське Аптекарське Товариство — алхімічна організація Відступників з осідком в Апотекаріумі в Андерсіті. Створене за королеви Сильвани Віндраннер, воно вивчає смертельні збудники хвороб, некромантію й отруйні реагенти, щоб виготовляти хімічну зброю для Відступників.",al={"що таке рас","хто такі аптекарі","гільдія алхіміків відступників"}},{q="Що за Нову Чуму вони розробляють?",a="Нова Чума — особливий алхімічний збудник, який Товариство розробляє за прямим наказом Сильвани. Її кінцева мета — мати силу знищити Погибель і Короля-Ліча, лишаючись при цьому смертельною й для живих істот, що загрожують Відступникам.",al={"пояснення нової чуми","яка чума відступників","навіщо нова чума"}},{q="Чи знає Орда, що насправді варить Товариство?",a="Ні. Відступники вдають, що їхні дослідження спрямовані на лікування недуги нежиття й пошук мирного місця для свого роду. Таурени й орки вірять, що аптекарі шукають ліки, не знаючи, що Товариство створює смертоносну зброю винищення.",al={"чи тралл знає про чуму","позиція орди щодо аптекарів","чи орки знають про чуму"}},{q="Хто очолює Королівське Аптекарське Товариство?",a="Зрештою Товариство підкоряється королеві Сильвані Віндраннер, але щоденною науковою роботою й дослідженнями в Андерсіті керують старші наглядачі, як-от Головний Аптекар Фаранелл.",al={"лідер аптекарів","лідер рас","хто керує аптекарнею"}},{q="Чому аптекарі перебувають у таких місцях, як Пустки чи Тандер Блаф?",a="Польові аптекарі шукають рідкісні біологічні речовини, екзотичну отруту, гриби й мутагенні слизи, яких немає в Лордероні. Агенти на кшталт Гелбріма на Перехресті й Замаг у Тандер Блафі вивчають місцеву природу й збирають небезпечні зразки, щоб відсилати їх до лабораторій Андерсіті.",al={"чому аптекарі в калімдорі","аптекарі поза тіріфалем","аптекар замах ставки видінь"}},{q="Як Товариство створює верхових тварин для Відступників?",a="Замість того щоб дати полеглим бойовим коням зогнити, Королівське Аптекарське Товариство поєднує темну алхімію й некромантію, щоб оживляти мертвих скакунів і піднімати їх як кістяних коней для вершників-Відступників.",al={"звідки кістяні коні нежиті","лор верхових відступників","походження скелетного коня"}}},fp="24,504,25.701.0,22.553.1,23.594.0,37.278.0,43.267.0,55.285.0,39.198.0,75.284.0,44.207.0"}
P.entries["topic:scarlet-crusade"] = {n="Багряний Хрестовий Похід",s="Багряний Хрестовий Похід, що постав із розтрощених решток Лицарів Срібної Длані, — фанатичний святий орден, одержимий очищенням Лордерону від нежиті. Отруєні параноєю й крайнім фанатизмом, хрестоносці вважають кожного, хто не належить до їхніх лав, носієм чуми й стріляють у чужинців, щойно побачать. Зі своїх твердинь на Галявинах Тірісфалю та в Чумних Землях вони під багряними стягами ведуть безжальну війну і з Погибеллю, і з живими.",h="Багряний Хрестовий Похід, що постав із розтрощених решток Лицарів Срібної Длані, — фанатичний святий орден...",kw={"багряний хрестовий похід","хрестоносці","багряний монастир","галявини тірісфалю","срібний світанок","балназзар","моґрейн"},ang={["class:Paladin"]="Багряний Хрестовий Похід — найтемніше збочення вчення Срібної Длані, що показує, як праведна переконаність без смирення й співчуття обертається тиранічним фанатизмом.",["class:Priest"]="Вивчення Походу відкриває жахливу силу віри, позбавленої моральних меж, коли святе писання виправдовує безжальні інквізиції та «очищення» цілих сіл.",["faction:Alliance"]="Хоча хрестоносці носять обладунки й говорять мовою полеглого Лордерону, Багряний Хрестовий Похід вважає сучасний Альянс заплямованим і без вагань страчує його посланців.",["race:Undead"]="Багряний Хрестовий Похід — найближчий живий ворог Відступників: він оспорює кордони Галявин Тірісфалю й полює на кожного мерця, що вирвався з-під влади Короля-Ліча."},sec={{t="Повсталі з попелу",b="Коли принц Артас зрадив Лордерон і вбив короля Теренаса Менетіла II, Орден Срібної Длані було розгромлено. Уцілілі паладини й жерці згуртувалися довкола таких провідників, як Александрос Моґрейн, Сайдан Датроган і генерал Аббендіс, щоб відвоювати свою сплюндровану батьківщину. Переформувавши сили в Гартглені й Руці Тіра, вони присягнулися очистити землю від нежиті святим вогнем. Та що довше тривала війна, то більше в їхніх лавах гноїлися горе й підозра. Угруповання на чолі з Аббендісом запеклося в нетерпимості до нелюдських рас, наполягаючи, що доля Лордерону — тягар лише людства. Те, що починалося як відчайдушний опір, невдовзі виродилося в непримиренний ксенофобський хрестовий похід."},{t="Великий розлам",b="Коли догми Походу затверділи в релігійне божевілля, помірковані командири відсахнулися. Лорд Максвелл Тіросус і його прибічники доводили, що для повернення півночі потрібні союзи по всьому Азероту, і шукали допомоги в дворфів, гномів і нічних ельфів. Відкинуті фанатиками, Тіросус та інші розчаровані лицарі покинули орден і заснували Срібний світанок, лишившись вірними чистим, відкритим для всіх засадам Святого Світла. А тим часом Багряний Хрестовий Похід захопив Багряний Монастир на Галявинах Тірісфалю й зробив його серцем своєї влади, вирізаючи мандрівників і біженців в істеричній вірі, що кожен, хто ходить Чумними Землями, несе заразу Погибелі."},{t="Маріонетка в багрянці",b="Крайнє падіння Походу в різанину сталося не лише з їхньої волі. Під час штурму Стратгольма Великий Хрестоносець Сайдан Датроган відбився від своїх людей, і жахолорд Балназзар тихо його вбив. Заволодівши трупом Датрогана, демон безпосередньо очолив багряні лави. Балназзар потай роздмухував їхню параною й підлаштував убивство Верховного Лорда Александроса Моґрейна руками його заздрісного сина Рено. За гучними промовами про чистоту й праведний гнів хрестоносці несвідомо служать маріонетками тієї самої демонічної темряви, яку, на їхню думку, Світло кличе їх знищити."}},faq={{q="Чому Багряний Хрестовий Похід ворожий до всіх?",a="Після падіння Лордерона Похід поринув у крайню параною. Хрестоносці вірять, що кожен, хто бував на півночі Лордерона й не пройшов очищення їхнього ордену, — явний чи прихований носій чуми нежиття. Щоб зберегти своє уявлення про чисте людство, вони страчують усіх чужинців на місці.",al={"чому багряні ворожі","чи багряні погані","чому багряний похід нападає на мене"}},{q="Звідки взявся Багряний Хрестовий Похід?",a="Він постав із лицарів і жерців Срібної Длані, що вціліли після падіння Лордерона в Третій війні. Перегрупувавшись у Гартглені й Багряному Монастирі під проводом таких постатей, як Сайдан Датроган і Александрос Моґрейн, вони заприсяглися будь-що викорінити Погибель.",al={"походження багряного походу","хто заснував багряний похід","історія багряного походу"}},{q="Чим Багряний Хрестовий Похід відрізняється від Срібного Світанку?",a="Обидва ордени відкололися від первісної Срібної Длані, але Срібний Світанок приймає всі раси й лишається вірним милосердним чеснотам Світла, а Багряний Хрестовий Похід став фанатичним культом людської вищості, що вирізає біженців і мандрівників під виглядом святого очищення.",al={"срібний світанок проти багряного походу","різниця багряних і срібного світанку"}},{q="Де головні бази Багряного Хрестового Походу?",a="Їхній головний оплот — Багряний Монастир на північному сході Галявин Тірісфалю. Вони також контролюють укріплене містечко Гартглен у Західних Чумних Землях, Руку Тіра на сході й Багряний Бастіон у руїнах Стратгольма, а ще численні вартові вежі по всьому краю.",al={"бази багряного походу","місця багряних","де хрестоносці"}},{q="Хто насправді очолює Багряний Хрестовий Похід?",a="Зовні Похід очолює Великий Хрестоносець Сайдан Датроган зі Стратгольма, а в Монастирі йому допомагають Верховна Інквізиторка Саллі Вайтмейн і Багряний командир Моґрейн.",al={"лідер багряного походу","великий хрестоносець"}},{q="Чи можуть багряні хрестоносці користуватися Святим Світлом, якщо вони злі?",a="Так. За природою Світла, щоб володіти його силою, потрібна не моральна доброчесність, а абсолютна, непохитна переконаність і віра. Хрестоносці щиро вірять, що їхній жорстокий похід чистий і праведний, тож можуть спрямовувати святий гнів попри свою жорстокість.",al={"чому багряні мають світло","паладини багряного походу світло","чи в багряних є світло"}}},fp="15,435,19.692.0,16.656.0,19.616.2,47.315.0,40.301.0,58.293.0,51.289.0,39.174.2,68.264.0"}
P.entries["topic:scourge"] = {n="Погибель",s="Погибель — апокаліптичне військо нежиті, некромантів і поневолених духів, підкорене волі Короля-Ліча. Палаючий Легіон створив його, щоб розхитати Азерот напередодні Третьої війни, але це військо ходячих мерців вирвалося з-під демонічної влади й розтрощило королівства Лордерон і Кель'Талас. Нині Погибель веде нескінченну війну зі своєї арктичної твердині в Нортренді та зі сплюндрованих володінь у Чумних Землях.",h="Погибель — апокаліптичне військо нежиті, некромантів і поневолених духів, підкорене волі Короля-Ліча.",kw={"погибель","король-ліч","нежить","кел'тузад","чумні землі","артас","крижаний трон","відступники"},ang={["class:Paladin"]="Лицарів Срібної Длані розгромила Погибель, коли принц Артас обернувся проти своїх наставників і вбив Утера Світлоносця. Для кожного паладина очищення світу від Погибелі Святим Світлом — священний обов'язок.",["faction:Alliance"]="Пам'ять про падіння Лордерону — відкрита рана Альянсу, що спонукає його й далі воювати, щоб відвоювати Чумні Землі й помститися за полеглих.",["faction:Horde"]="Відколи Відступників прийняли до Орди, увесь союз опинився втягнутим у жорстоку безперервну війну з рештками армій Короля-Ліча на півночі.",["race:Human"]="Погибель знищила найвеличніше королівство людства, винищила рід Менетілів і перетворила серце Лордерону на сплюндровану пустку.",["race:Undead"]="Кожен Відступник колись був поневоленим знаряддям Погибелі й мусив убивати друзів і родичів, доки хватка Короля-Ліча не послабла. Знищення Погибелі для вас — не просто війна за виживання, а похід особистої помсти без жодних меж."},sec={{t="Чума демонічного задуму",b="Погибель народилася як знаряддя руйнування, викуване Палаючим Легіоном. Владики демонів прикували дух полеглого орка-шамана Нер'жула до Крижаного Трону в далекому Нортренді й зробили з нього Короля-Ліча. Наділений жахливою телепатичною силою, він мав підготувати Азерот до завоювання. Король-Ліч наслав Чуму Нежиття на південь, на нічого не підозрюючі людські землі Лордерону, покладаючись на смертних зрадників із Культу Проклятих, які отруювали запаси зерна. Ті, хто помирав, повставали не спочилими мерцями, а спотвореними рабами, цілком підвладними залізній волі Короля-Ліча."},{t="Падіння Півночі",b="Погибель досягла цілковитого спустошення, коли принц Артас Менетіл піддався шепоту Короля-Ліча. Шукаючи помсти в Нортренді, Артас заволодів проклятим клинком Фростморном і втратив душу, ставши найвищим лицарем смерті Погибелі. Повернувшись додому, Артас убив свого батька, короля Теренаса, вирізав Столичне Місто й наслав орди нежиті на весь Лордерон. Погибель пронеслася такими містечками, як Дарроушир і Андоргал, винищила паладинів Срібної Длані, зруйнувала Даларан, щоб закликати Архімонда, і пропалила мертвий шрам через Кель'Талас, щоб воскресити Кел'Тузада як ліча."},{t="Зрада й розкол",b="Король-Ліч ніколи не збирався служити Палаючому Легіону вічно. Через Артаса Нер'жул потай підготував поразку Легіону, підбуривши Іллідана Стормрейджа вбити жахолорда Тіхондріуса в Скверноліссі. Розлючений владика демонів Кіл'джеден згодом наказав Іллідану знищити Крижаний Трон. Удар Іллідана розколов крижану в'язницю, і психічна хватка Короля-Ліча над слугами захиталася. Скориставшись цим послабленням, група нежиті з вільною волею на чолі з воскреслою баньші Сильваною Віндраннер відкололася, назвалася Відступниками й захопила руїни Лордерону."},{t="Нинішня загроза",b="Хоча Погибель ослабла через розкол Крижаного Трону та повстання Відступників, вона досі лишається найсмертоноснішою силою північного світу. Під проводом ліча Кел'Тузада її гидоти, склепові потвори й некроманти панують у сплюндрованих Іствілді й Вествілді, які нині називають Чумними Землями. Зі своїх похмурих твердинь і спотворених полів вони безперестанку воюють із Відступниками Андерсіті, фанатиками Багряного Хрестового Походу та вцілілими осередками Альянсу."}},faq={{q="Що таке Погибель?",a="Погибель — величезна імперія неживих рабів, некромантів і спотворених звірів, розумом прикутих до Короля-Ліча. Вона існує лише для того, щоб знищувати все живе й перетворювати тіла полеглих на покірних слуг.",al={"що таке погибіль","нежить погибіль","хто такі погибіль"}},{q="Хто очолює Погибель?",a="Погибеллю командує Король-Ліч зі свого Крижаного Трону в далекому крижаному континенті Нортренд. У зруйнованих землях Лордерона його військами на місці керують могутні поручники, як-от ліч Кел'Тузад.",al={"лідер погибелі","володар погибелі","хто керує погибеллю"}},{q="Чим Погибель відрізняється від Відступників?",a="Погибель — безмозка або підкорена нежить, поневолена телепатичною волею Короля-Ліча. Відступники — колишні жертви Погибелі, що повернули собі вільну волю, коли сила Короля-Ліча послабла. На чолі з Леді Сильваною Віндраннер Відступники зневажають Погибель і люто воюють, щоб її знищити.",al={"погибіль проти відступників","чи відступники погибіль","чому нежить б'ється між собою"}},{q="Чому Погибель напала на Лордерон?",a="Палаючий Легіон наказав Королю-Лічу поширити Чуму Нежиття Лордероном, щоб вирізати його народ, послабити Альянс і змести будь-який опір, перш ніж демони почнуть вторгнення в Азерот під час Третьої війни.",al={"чому знищили лордерон","знищення лордерона","чому погибіль вторглася"}},{q="Хто такі Культ Проклятих?",a="Культ Проклятих — організація смертних, заснована архімагом Кел'Тузадом. Її члени — живі люди, що добровільно служать Королю-Лічу, спокушені обіцянками темної магічної сили й вічного життя в нежитті. Саме вони поширили заражене зерно, з якого почалася чума.",al={"культ проклятих","культисти погибелі","чому люди вступають до погибелі"}},{q="Як Погибель спотворила принца Артаса?",a="Одержимий бажанням врятувати королівство від чуми, принц Артас переслідував жахолорда Мал'Ганіса аж до Нортренду. У відчаї Артас узяв проклятий рунний клинок Фростморн, що вкрав його душу. Зламаний і викривлений шепотом Короля-Ліча, він повернувся першим поборником Погибелі й вирізав власну батьківщину.",al={"як артас став нежиттю","артас погибіль","чому артас зрадив свій народ"}}},fp="7,453,26.618.0,21.590.0,23.611.0,18.514.0,20.221.0,22.227.0,46.302.0,37.237.0,30.303.0,47.342.0"}
P.entries["topic:second-war"] = {n="Друга війна",s="Друга війна — зіткнення Орди орків і щойно викуваного Альянсу Лордерону, що охопило всі Східні Королівства. Вона спалахнула після сплюндрування Стормвінда, спустошила Каз Модан і північні людські королівства й переломилася біля воріт Столичного Міста. Завершилася війна знищенням Темного Порталу й розпорошенням старої Орди.",h="Друга війна — зіткнення Орди орків і щойно викуваного Альянсу Лордерону, що охопило всі Східні Королівства.",kw={"друга війна","альянс лордерону","оргрім думхаммер","андуїн лотар","каз модан","темний портал","туральйон"},ang={["class:Paladin"]="Лицарів Срібної Длані заснували саме під час цієї війни архієпископ Алонсус Фаол і Утер Світлоносець, щоб протистояти магії Скверни й лицарям смерті Орди.",["faction:Alliance"]="Друга війна стала вирішальним горнилом, що викувало сучасний Альянс, об'єднавши людей, дворфів, гномів і ельфів проти загрози самому їхньому існуванню.",["faction:Horde"]="Ця війна поклала край старій, проклятій кров'ю Орді й безпосередньо привела до таборів інтернування, а згодом — до відродження нової Орди під проводом Тралла.",["race:Dwarf"]="Каз Модан зазнав страшного спустошення: дворфи довго витримували облогу Орди за замкненими гірськими брамами Айронфорджа, доки армії Альянсу її не зняли."},sec={{t="Континент у вогні війни",b="Після падіння Стормвінда в Першій війні регент Андуїн Лотар повів людських біженців на північ через Велике Море до Лордерону. Король Теренас Менетіл II скликав Раду Семи Народів і викував Альянс Лордерону разом із високими ельфами Кель'Таласу, дворфами клану Бронзбірд з Айронфорджа та гномами Гномреґана. Тим часом Вождь Оргрім Думхаммер згуртовував Орду: уклав союзи з племенами лісових тролів і картелем Стімвідл, а через клан Драконячої Пащі підкорив червоних драконів, щоб вторгнутися на північні землі."},{t="Вторгнення на північ",b="Орда розгорнула нищівні наступи на суші й на морі, швидко захопила Каз Модан і загнала дворфів і гномів за замкнені брами Айронфорджа й Гномреґана. Просуваючись на північ через Міст Тандол і морем, орочі сили пропалили собі шлях крізь Гілсбред і Пригір'я, а тоді взяли в облогу саме Столичне Місто. Королівство Альтерак зрадило Альянс, провівши орочі загони гірськими перевалами. Попри нищівні напади драконів, Альянс згуртувався довкола щойно створених Лицарів Срібної Длані й паладинів, що протиставили Святе Світло орочим чорнокнижникам і лицарям смерті."},{t="Перелом і Темний Портал",b="Перелом настав, коли чорнокнижник Ґул'дан зі своїми прибічниками покинув Орду, щоб шукати особистої влади, і Думхаммерові довелося відвести з передової важливі сили. Альянс перейшов у контрнаступ, прорвав облогу Лордерону й крок за кроком відтіснив Орду на південь через Міст Тандол, звільняючи дорогою Каз Модан. На останніх гірських перевалах Палаючих Степів Андуїн Лотар загинув у двобої з Думхаммером, але його заступник Туральйон згуртував війська й розгромив орків. Альянс переслідував уцілілих аж до Чорного Багна, знищив рештки Орди й зруйнував Темний Портал."}},faq={{q="Як почалася Друга війна?",a="Коли Орда в Першій війні зрівняла Стормвінд із землею, Оргрім Думхаммер зрозумів, що північні людські королівства рано чи пізно відповідять. Він вирішив ударити першим, поки люди не згуртувалися. Тим часом біженці зі Стормвінда на чолі з Андуїном Лотаром попередили короля Лордерона Теренаса Менетіла II, і так постав Альянс Лордерона.",al={"чому почалася друга війна","як вона почалася","причина другої війни"}},{q="Хто переміг у Другій війні?",a="Альянс Лордерона здобув вирішальну перемогу. Відкинувши Орду від Столичного Міста й погнавши її на південь через Каз Модан, війська Альянсу розбили Вождя Оргріма Думхаммера біля підніжжя Гори Блекрок і зруйнували Темний Портал у Чорних Драговинах.",al={"хто переміг","альянс чи орда","переможець другої війни"}},{q="Що сталося з Каз Моданом під час боїв?",a="Орда захопила поверхневі землі Каз Модану, щоб заволодіти його багатими покладами руди й кузнями. Дворфи Бронзбірди та їхні союзники-гноми підривали гірські перевали й тунелі, щоб сповільнити наступ, а зрештою повністю відступили за замкнені брами Айронфорджа й Гномреґана. Орда взяла Айронфордж в облогу, але так і не змогла пробити його браму, доки Альянс не рушив на південь і не визволив королівство.",al={"каз модан друга війна","облога айронфорджа","що сталося з дворфами"}},{q="Чому Орда програла, дійшовши до Столичного Міста?",a="У розпал облоги столиці Лордерона чорнокнижник Ґул'дан покинув передову, забравши з собою клани Штормових Жнеців і Молота Присмерку, щоб шукати прадавню демонічну силу. Думхаммер мусив розділити військо, щоб покарати дезертирів, і цим смертельно послабив облогу якраз тоді, коли вдарив контрнаступ Альянсу.",al={"чому орда програла","зрада ґул'дана друга війна","чому думгаммер зазнав невдачі"}},{q="Хто такий Андуїн Лотар?",a="Сер Андуїн Лотар — Лев Азероту й Регент Стормвінда після вбивства короля Ллейна. Він повів уцілілих на північ і став Верховним Командувачем військ Альянсу. Лотар загинув у двобої з Оргрімом Думхаммером у Палаючих Степах наприкінці війни, надихнувши Туральйона привести Альянс до остаточної перемоги.",al={"хто такий лотар","смерть андуїна лотара","верховний командувач лотар"}},{q="Де відбулася остання битва?",a="The decisive army-level battle took place around Blackrock Mountain in the Burning Steppes, where Doomhammer was defeated. The surviving orcs fled to the Black Morass, where the Alliance fought a final engagement at the Dark Portal itself, demolishing the portal's stone framework and imprisoning or scattering the remaining Horde clans.",al={"остання битва другої війни","битва біля темного порталу","палаючі степи друга війна"}}},fp="10,365,18.566.0,25.636.0,36.644.0,29.358.0,23.274.0,48.409.0,54.333.0,22.356.0,38.337.0"}
P.entries["topic:sentinels"] = {n="Вартові",s="Вартові — елітне військо нічних ельфів, що складається переважно з жінок і постало десять тисяч років тому, після Війни Прадавніх. Під духовним проводом Сестринства Елуни й командуванням генерала Шандріс Фезермун вони стережуть поселення калдореїв і боронять священні землі від Ашенвалю до Фераласу. Нині вони ведуть запеклу війну проти вирубування лісів Ордою й пильнують свій новий дім на Тельдрассилі.",h="Вартові — елітне військо нічних ельфів, що складається переважно з жінок і постало десять тисяч років тому...",kw={"вартові","шандріс фезермун","тіранда віспервінд","сестринство елуни","ашенваль","твердиня перистого місяця","вартові срібнокрилих"},ang={["class:Hunter"]="Лучниці Вартових і мисливиці верхи на звірах — вершина нічної влучності й дружби зі звірами в Калімдорі.",["class:Priest"]="Оскільки Вартові постали просто із Сестринства Елуни, військовий обов'язок і священна відданість Місячній Богині для них нерозривні.",["faction:Horde"]="Вартові — смертоносні лісові бійці, що вражають без попередження з тіней Ашенвалю й запекло опираються вирубуванню лісів Ордою.",["race:NightElf"]="Кожне селище калдореїв завдячує своїм виживанням пильним очам Вартових, і багато молодих жінок мріють заслужити свої відзнаки у війську Шандріс і Тіранди."},sec={{t="Народжені Розколом",b="До Великого Розколу військо давньої Імперії Калдореїв виродилося в занепалу ієрархію, де звання визначав шляхетний родовід, а не бойова майстерність. Спустошення Війни Прадавніх довело, що такий аристократичний устрій цілком непридатний для захисту Азероту. Після війни Верховна Жриця Тіранда Віспервінд очолила докорінні реформи в суспільстві нічних ельфів. Вона звернулася до Сестринства Елуни — ордену, що вцілів і мав чималий досвід у тактиці, бою й зціленні. З його побожних лав Тіранда створила Вартових — постійне військо, покликане самовіддано захищати нове суспільство без огляду на шляхетне походження."},{t="Устрій і війна",b="Хоча духовною верховною командувачкою лишається Тіранда Віспервінд, безпосередньо військом керує її заступниця, генерал Шандріс Фезермун, зі ставкою у Твердині Перистого Місяця у Фераласі. Вартові славляться дисциплінованою влучністю, смертоносними місячними глефами й спеціалізованими підрозділами. Їхні сили складаються з елітних лучниць, мисливиць верхи на нічних шаблезубах і розвідниць на гіпогрифах, що панують у небі. За століття до Третьої війни вони під проводом архідруїда Фандрала Стаґгелма билися в жорстокій Війні Мінливих Пісків у Силітусі й зупинили рій кіраджі. Кожне поселення нічних ельфів — від Астранаару до розлогих віт Дарнасуса — покладається на захист гарнізонів Вартових."},{t="Захист священної землі",b="Під час Третьої війни Вартові відчайдушно оборонялися і від демонічних загарбників, і від перших вторгнень Орди, зазнавши величезних утрат, коли в Ашенвалі загинув Кенарій. Вистоявши в Битві за Гору Гіджал і переслідуючи Іллідана через Лордерон, вони повернулися й побачили, що Калімдор змінився назавжди. Нині Вартовим загрожує небезпека на кількох фронтах. На Тельдрассилі гарнізони протистоять зіпсованим звірам і розлюченим фурболгам. Далі на південь Вартові Срібнокрилих без упину б'ються з Дозорцями Пісні Війни в Ущелині Бойової Пісні, сповнені рішучості вигнати Орду з Ашенвалю й уберегти прадавні ліси від подальшого визиску."}},faq={{q="Хто очолює Вартових?",a="Політичний і духовний провід Вартових належить Верховній Жриці Тіранді Віспервінд, яка заснувала їх на основі Сестринства Елуни. Щоденне ж командування військом лежить на Генералові Шандріс Фезермун, що керує діями по всьому Калімдору з Твердині Перистого Місяця.",al={"лідер вартових","хто керує вартовими","шандріс чи тайранда"}},{q="Чому більшість Вартових — жінки?",a="Після Війни Прадавніх традиційне суспільство нічних ельфів розподілило обов'язки на духовні й військові: жінки панували в жрецтві Елуни й утворили військо Вартових, а чоловіки здебільшого ставали друїдами Кола Кенарія. Цей суворий поділ формував військо тисячоліттями, хоча після Третьої війни суспільство поволі почало змінюватися.",al={"чому лише жінки-вартові","армія жінок нічних ельфів","чи чоловіки можуть бути вартовими"}},{q="Де головна база Вартових?",a="Окрім столиці нічних ельфів, Дарнасуса, їхня головна фортеця — Твердиня Перистого Місяця на острові біля узбережжя Фераласу. Помітні гарнізони стоять також по всьому Ашенвалю, як-от в Астранаарі й на Заставі Срібнокрилих.",al={"база вартових","штаб вартових","твердиня перистого місяця"}},{q="На якій зброї спеціалізуються Вартові?",a="Вартові — славетні стрільці з вигнутими луками, але їхня культурна прикмета — трилеза місячна глефа. Мисливиці орудують цими глефами верхи на лютих нічних шаблезубах-пантерах, а повітряні вершниці б'ють зі спин закутих у броню гіпогрифів.",al={"зброя вартових","місячна глефа","чим користуються вартові"}},{q="Чому Вартові б'ються в Ущелині Бойової Пісні?",a="Вартові Срібнокрилих ведуть війну за територію з Дозорцями Пісні Війни з Орди. Орки дуже вирубали Ашенваль, щоб мати деревину, оскверняючи ліси, священні для нічних ельфів, які заприсяглися вигнати всіх загарбників до одного.",al={"вартові ущелини бойової пісні","вартові срібнокрилих","чому війна в ашенвейлі"}},{q="Чи билися Вартові в Третій війні?",a="Так. Вони були головною лінією оборони, коли Палаючий Легіон і Погибель рушили на Калімдор. Під проводом Тіранди вони тримали фронт, доки не уклали союз із людськими й орківськими біженцями, що завершився вирішальною перемогою в Битві за Гору Гіджал.",al={"вартові в третій війні","вартові гіджал","вартові вк3"}}},fp="9,417,23.714.0,21.720.0,21.656.0,24.291.0,30.386.0,48.247.0,44.257.0,48.270.0,41.269.0"}
P.entries["topic:shadow-council"] = {n="Рада Тіней",s="Рада Тіней — таємне угруповання чорнокнижників і некролітів, що влаштувало зіпсуття Старої Орди на Дренорі й спрямовувало її вторгнення на Азерот. Заснований Ґул'даном за вказівкою Палаючого Легіону, цей культ потай маніпулював вождями кланів, доки Вождь Оргрім Думхаммер не винищив їхнє кубло на Горі Блекрок.",h="Рада Тіней — таємне угруповання чорнокнижників і некролітів, що влаштувало зіпсуття Старої Орди на Дренорі й...",kw={"рада тіней","ґул'дан","чорнокнижники","некроліти","лицарі смерті","гора блекрок","стара орда"},ang={["class:Warlock"]="Рада Тіней упорядкувала серед смертних вивчення чаклунства Скверни й демонічних угод; сучасні чорнокнижники безпосередньо користуються обрядами виклику й способами збирання душ, які вона запровадила.",["faction:Alliance"]="Королівство Стормвінд упало здебільшого через таємні дії Ради Тіней — від відкриття Темного Порталу до вбивства короля Ллейна Рінна.",["faction:Horde"]="Жорстока розправа Вождя Оргріма Думхаммера над Радою Тіней стала переломом: тоді Орда вперше спробувала звільнитися від демонічних лялькарів.",["race:Orc"]="Рада Тіней підготувала загибель Дренору й кривавий договір, що прокляв орочий народ, залишивши глибокий сором на покоління, який нова Орда Тралла завзято прагне змити."},sec={{t="Творці кривавого прокляття",b="Ще до переходу на Азерот Ґул'дан зібрав таємне коло чорнокнижників, некролітів і вождів-пристосуванців, щоб маніпулювати орочими кланами. Піднісши Блекгенда Руйнівника як слухняне знаряддя, Рада Тіней правила Старою Ордою з темряви. Її члени поширювали магію Скверни по Дренору, керували завоюванням Шаттрата й Храму Карабора та напоїли клани кров'ю демона Маннорота, прив'язавши орків до волі Палаючого Легіону."},{t="Перехід і Гора Блекрок",b="Коли Кіл'джеден зник, Рада Тіней уклала угоду з Медівом — Стражем, яким заволодів Саргерас, — щоб пробити бар'єр між світами. Живлячи Темний Портал життєвою силою тисяч полонених, Рада привела Орду до королівства Стормвінд. Згодом Чо'Ґалл уклав хиткий договір із дворфами Темного Заліза й вогняними елементалями Рагнароса, і Гора Блекрок опинилася в руках Орди, а чорнокнижники керували війною з її верхнього шпиля."},{t="Чистка Думхаммера й лицарі смерті",b="Після смерті Медіва Ґул'дан поринув у непритомний транс. Оргрім Думхаммер скористався нагодою: убив Блекгенда, допитав Ґарону, щоб викрити найпотаємніше святилище Ради, і влаштував напад, що знищив більшість чорнокнижників. Прокинувшись і побачивши свій культ розгромленим, Ґул'дан виторгував собі життя, запропонувавши Думхаммерові страшну протидію людській магії. Вселивши духи вбитих чорнокнижників Ради Тіней у трупи полеглих людських лицарів, Ґул'дан створив перших лицарів смерті."}},faq={{q="Хто заснував Раду Тіней?",a="Раду Тіней заснував на Дренорі орк-чорнокнижник Ґул'дан. Служачи демонічному владиці Кіл'джеденові, Ґул'дан зібрав однодумців, що практикували магію скверни, щоб смикати за ниточки кланів, використовуючи Вождя Блекгенда як нічого не підозрюючу маріонетку.",al={"хто заснував раду тіней","засновник ради тіней","рада ґул'дана"}},{q="Що сталося з Радою Тіней під час Першої війни?",a="Коли Ґул'дан після смерті Медіва впав у безпам'ятство, Оргрім Думхаммер убив Блекгенда й очолив Орду. Думхаммер катував убивцю Ґарону, щоб дізнатися, де прихований осідок Ради в Шпилі Блекрок, і влаштував чистку, що знищила майже всіх її чорнокнижників.",al={"падіння ради тіней","думгаммер і рада тіней","чистка ради тіней"}},{q="Як Рада Тіней дала початок першим лицарям смерті?",a="Коли Думхаммер знищив Раду, Ґул'дан виторгував собі помилування, пообіцявши темну зброю, рівну людським чаклунам. Він узяв душі своїх убитих чорнокнижників — передусім Терона Горфінда — і вселив їх у збережені тіла полеглих лицарів Стормвінда, створивши перше покоління лицарів смерті.",al={"лицарі смерті ради тіней","хто став лицарем смерті","терон горефіенд рада"}},{q="Чи всі орки-чорнокнижники належали до Ради Тіней?",a="Ні. Хоча Рада Тіней керувала поширенням магії скверни на Дренорі, дехто з чаклунів відмовився вступати до неї. Помітні постаті, як-от Дрек'Тар із клану Морозного Вовка й Некрос Скалкрашер, опанували темні мистецтва, але лишалися суворо вірними своїм кланам, а не змові Ґул'дана.",al={"чи орки-чорнокнижники в раді тіней","дрек'тар рада тіней","некрос рада тіней"}},{q="Яку роль у Раді відігравав Чо'ґалл?",a="Чо'ґалл був першим учнем і головним поручником Ґул'дана. Він очолював клан Молота Присмерку, що обертався в колі Ради, і, користуючись своїми прихованими зв'язками з Древніми Богами, уклав перемир'я з дворфами Темного Заліза й вогняними елементалями в Горі Блекрок.",al={"чо'ґалл рада тіней","роль чо'ґалла","молот присмерку рада тіней"}},{q="Чи Рада Тіней досі існує?",a="Первісну Раду розгромив Думхаммер, а її рештки розпалися ще більше, коли Ґул'дан загинув у Гробниці Саргераса. Проте розпорошені культисти, уцілілі чорнокнижники й демонічні агенти, що продовжують справу Легіону по всьому Азероту й на руїнах Дренору, досі ведуть свій родовід від організації Ґул'дана.",al={"чи рада тіней існує","рада тіней сьогодні","рада тіней нині"}}},fp="14,365,29.501.0,35.492.0,36.509.1,31.248.0,57.279.0,61.327.0,50.315.0,40.258.0,36.318.0"}
P.entries["topic:shaman"] = {n="Шаман",s="Шамани — духовні посередники й провідники стихій в Орді, що спілкуються з первісними силами землі, повітря, вогню й води. Врівноважуючи дику природу тотемами, блискавками й цілющою силою предків, вони є духовним осердям культури орків, тауренів і тролів під проводом Вождя Тралла.",h="Шамани — духовні посередники й провідники стихій в Орді, що спілкуються з первісними силами землі, повітря...",kw={"шаман","шамани","стихії","тотеми","земляне кільце","тралл","дрек'тар"},ang={["class:Shaman"]="Ваші сили даровані завдяки взаємній повазі з мінливими духами стихій і предків; тримати рівновагу — і ваш бойовий обов'язок, і ваш духовний тягар.",["faction:Alliance"]="Війська Альянсу ставляться до шаманів насторожено: на полі бою це люті воїни, чиї тотеми кличуть блискавки, землетруси й раптове зцілення.",["faction:Horde"]="Шаманство — духовне відродження Орди: воно відкрило шлях честі й шанування природи, що прийшов на зміну демонічному зіпсуттю.",["race:Orc"]="Повернення на шлях шамана допомогло оркам здолати млявість таборів інтернування й повернути спадщину предків.",["race:Tauren"]="Таурени поколіннями практикують шаманство через Земляне Кільце й стали терплячою духовною опорою для молодших культур Орди.",["race:Troll"]="Шамани Темного Списа спрямовують первісні стихії через традиції свого племені, поєднуючи шанування духів природи й давніх лоа."},sec={{t="Посередники стихій",b="На відміну від жерців, що шанують божественне, чи магів, що підкоряють таємні сили, шамани взаємодіють безпосередньо з первісними силами природи. Стихії землі, повітря, вогню й води за своєю суттю хаотичні й одвічно ворогують між собою. Шаман не поневолює ці сили, а просить і домовляється з ними, тримаючи рівновагу між первісною люттю та світом смертних. Через дерев'яні й кам'яні тотеми, встромлені в землю, шамани втілюють ці угоди зі стихіями, щоб захищати союзників, стримувати ворогів чи загоювати поранених очисною водою."},{t="Втрата й відродження в орків",b="Колись шаманство було давньою основою кланового життя орків на Дренорі. Проте Кіл'джеден і Рада Тіней ошукали шаманів і втягнули їх у війну з дренеями, через що духи стихій відвернулися від них. Утративши свої дари, багато колишніх шаманів піддалися демонічному зіпсуттю й стали чорнокнижниками, і традиція ледь не згасла зовсім. Лише після Другої війни Тралл під проводом Дрек'Тара з клану Морозного Вовка знову відкрив давні обряди. Піднесення Тралла до звання Вождя відродило шаманство й зробило його моральним дороговказом Нової Орди."},{t="Традиції Орди",b="У Калімдорі шаманські традиції союзних народів Орди дуже різняться. Містики-таурени, які понад два століття тому заснували давнє Земляне Кільце, вважають єднання із землею та духами священною опорою своєї культури. Тролі Темного Списа приходять до цього мистецтва через шанування лоа й диких духів предків, сплітаючи вуду з обрядами природи. Та в усіх племенах шамани — незамінні старійшини громад, порадники й грізні захисники на передовій."}},faq={{q="Які раси можуть стати шаманами?",a="Орки, таурени й тролі — головні шаманські народи Орди. Їхні традиції спираються на духів стихій, предків, а в тролів — ще й на лоа.",al={"хто може бути шаманом","раси шаманів","чи альянс може бути шаманом"}},{q="Звідки шамани черпають магію?",a="Шамани черпають силу зі спілкування зі стихійними духами землі, повітря, вогню й води, а також із духами предків. Шаман не підкоряє ці сили примусом, а просить їхньої допомоги й урівноважує їхню хаотичну природу, часто закріплюючи цей зв'язок обрядовими тотемами.",al={"як працює магія шаманів","джерело сили шаманів","звідки тотеми"}},{q="Чому орки втратили шаманську силу перед Першою війною?",a="Демонічний владика Кіл'джеден, видаючи себе за духів предків, ошукав орківських шаманів і підбурив їх напасти на мирних дренеїв. Ображені безглуздою різаниною, стихійні духи Дренору розірвали зв'язок і перестали відгукуватися. Лишившись беззахисними, багато зневірених шаманів звернулися до магії скверни й стали чорнокнижниками.",al={"чому орки-шамани стали чорнокнижниками","падіння шаманів дренору","кіл'джеден обдурив шаманів"}},{q="Хто повернув оркам шаманство?",a="Тралл, син Дуротана, розшукав клан Морозного Вовка в Горах Альтерак. Під наставництвом старого шамана Дрек'Тара Тралл опанував давні духовні зв'язки, розвіяв демонічну млявість, що мучила його народ, і знову поставив шаманство в серце Нової Орди.",al={"хто повернув шаманство","тралл і дрек'тар шамани","повернення шаманства"}},{q="Що таке Земляне Кільце?",a="Земляне Кільце — прадавня організація шаманів, яку століття тому заснували таурени. Її члени присвячують себе підтримці злагоди між норовливими стихійними духами й зціленню країв, де панує духовний неспокій.",al={"лор земляного кільця","хто таке земляне кільце","фракція шаманів"}},{q="Чим шаман відрізняється від друїда?",a="Друїди спілкуються зі Смарагдовим Сном, рослинами й духами звірів, щоб берегти живий колообіг природи. Шамани ж урівноважують неживі первісні стихії фізичного світу — землю, вогонь, воду й вітер — разом із духами померлих предків.",al={"друїд проти шамана","різниця друїда і шамана","шаман чи друїд"}}},fp="6,317,25.545.0,27.583.0,23.498.0,30.151.0,30.313.0,63.311.0,39.288.0,25.239.0,38.269.0"}
P.entries["topic:shan-do"] = {n="Шан'до",s="Шан'до — шанобливе звертання дарнаською мовою, що означає «шанований учитель» чи «шанований наставник». Його здавна вживають у суспільстві нічних ельфів і колах друїдів на знак глибокої пошани до наставника, який веде іншого шляхом мудрості й магії природи. Пару до нього становить слово теро'шан — «шанований учень».",h="Шан'до — шанобливе звертання дарнаською мовою, що означає «шанований учитель» чи «шанований наставник».",kw={"шан'до","теро'шан","дарнаська мова","наставник","малфуріон стормрейдж","кенарій","друїди"},ang={["class:Druid"]="Кожен друїд веде своє вчення ланцюжком наставників аж до Шан'до Стормрейджа й самого Кенарія; вимовляючи це звання, ви вшановуєте цей нерозривний ланцюг.",["race:NightElf"]="Шан'до — слово вашої рідної мови й одна з найурочистіших форм пошани, яку ви можете виявити старшому чи вчителеві; за ним стоїть тисячолітня вага культури.",["race:Tauren"]="Друїди-таурени, які навчаються разом із нічними ельфами в Місячному Гаю, знають це звання й шанобливо вживають його, звертаючись до таких наставників, як Малфуріон Стормрейдж."},sec={{t="Звання глибокої пошани",b="Дарнаською шан'до дослівно означає «шанований учитель» або «шанований наставник». Префікс «шан» несе значення пошани, а суфікс «до» вказує на владу, старшинство чи майстерність — цей корінь є й в інших словах, як-от мінн'до («мати»). Це значно більше, ніж назва ремесла: звертаючись до старшого чи наставника «шан'до», нічний ельф висловлює врочисте смирення, синівську відданість і незмінну повагу до його настанов."},{t="Родовід друїдів",b="Найтісніше це звання пов'язане з історією Кола Кенарія. Напівбог Кенарій був першим шан'до Малфуріона Стормрейджа й навчав його шляхів природи ще до Війни Прадавніх. Своєю чергою Малфуріон став шан'до для поколінь смертних друїдів — настільки, що «Шан'до Стормрейдж» стало його звичним титулом серед нічних ельфів, лісових охоронців і шанобливих союзників по всьому Калімдору."},{t="Наставники поза Колом",b="Хоча найчастіше це звертання чути серед друїдів Кенарія — так учні звертаються до архідруїда Наралекса чи до сплячого Малфуріона, — воно за своєю суттю дарнаське, а не суто релігійне. Під час Війни Прадавніх Іллідан Стормрейдж якийсь час називав шан'до людського чарівника Роніна, переймаючи його незвичні таємні прийоми. Звання позначає зв'язок передавання знань між майстром і учнем, хоч би якою була школа думки."}},faq={{q="Що насправді означає слово «шан'до»?",a="Дарнаською «шан'до» означає «шанований учитель» чи «шанований наставник». Це слово виражає глибоку повагу й вдячність до наставника.",al={"значення шан'до","що означає шан'до","переклад шан'до","шан'до мовою дарнасу"}},{q="Як шанобливо звертаються до учня — у пару до «шан'до»?",a="Парне шанобливе звертання — «теро'шан», що означає «шанований учень». Наставники називають своїх учнів «теро'шан», визнаючи їхню відданість і дисципліну.",al={"протилежне до шан'до","слово учня дарнасу","значення теро'шан","що таке теро'шан"}},{q="Кого найчастіше називають Шан'до?",a="Нічні ельфи й Коло Кенарія найчастіше величають Шан'до Архідруїда Малфуріона Стормрейджа. Так само зверталися до Кенарія його перші учні, а інші знані провідники, як-от Наралекс, теж чують це шанобливе звертання від своїх послідовників.",al={"хто такий шан'до","шан'до стормрейдж","хто має титул шан'до"}},{q="Чи звертання «шан'до» вживають лише друїди?",a="Ні. Хоча воно глибоко вкорінене в друїдській традиції Кола Кенарія, «шан'до» — це звичайна дарнаська ввічлива форма. Будь-якого майстра ремесла, магії чи мудрості учень теоретично може назвати «шан'до»; наприклад, Іллідан Стормрейдж колись так звертався до людського чарівника Роніна, вивчаючи його чари.",al={"чи недруїди шан'до","чи шан'до лише для друїдів","шан'до поза друїдизмом"}}},fp="7,329,25.444.0,25.421.0,25.456.0,41.144.0,51.175.0,36.268.0,41.310.0"}
P.entries["topic:skyborne"] = {n="Небороджені",s="Небороджені, або шен'дорей, — гілка високих ельфів, що походять від бунтівників, які втекли з Ельдре'Таласу, бо виступили проти демонічних угод Принца Тортельдріна. Уклавши відчайдушну угоду з духами вітру, їхні предки покинули Азерот і оселилися на летючому Острові Зефрас у Небесній Тверді. Сьогодні, коли їхні стихійні покровителі раптово зникли, летючий прихисток роздирають внутрішні чвари, і йому загрожує руйнування.",h="Небороджені, або шен'дорей, — гілка високих ельфів, що походять від бунтівників, які втекли з Ельдре'Таласу...",kw={"Небороджені","шен'дорей","острів зефрас","небесна твердь","аль'акір","високий орден","вітротворці"},ang={["class:Mage"]="Високий Орден серед Небороджених береже давнє чарівництво Високородних, винесене з Ельдре'Таласу, і прагне врятувати свій острів, що розсипається, суворим опануванням таємної магії.",["class:Shaman"]="Вітротворці — ельфійський рід, глибоко переплетений із духами вітру Небесної Тверді: вони покладаються на єднання зі стихіями, а не на таємні традиції своїх предків-Високородних.",["race:NightElf"]="Небороджені — прямі кровні родичі давніх Шен'дралар і північних нічних ельфів, хоча тисячоліття в Небесній Тверді змінили їхні тіла, перетворивши на високих ельфів, серед яких дедалі частіше трапляється стихійна блакитна шкіра."},sec={{t="Втеча з Ельдре'Таласу",b="Після Розколу Шен'дралар з Ельдре'Таласу занепадали без Колодязя Вічності. Принц Тортельдрін задумав темний порятунок: викликати демона Іммол'тара й черпати його силу. Нажахані вельможі й городяни опиралися, боячись нового вторгнення Легіону. У відповідь Тортельдрін влаштував криваву розправу над десятками родів. З уцілілих тіней постав опір на чолі з постаттю в масці, відомою лише як Шал'нан («Завуальований»). Коли відчайдушний напад повстанців на ритуальне святилище Тортельдріна обернувся катастрофічною хаотичною магією, Шал'нан згуртував уцілілих і втік на захід до порту Ельдре'нарр, а звідти — у море, переслідуваний флотом принца."},{t="Прихисток у небі",b="Загнані в кут у відкритому океані, вигнанці уклали угоду з первісними духами вітру. Ці істоти підняли Острів Зефрас просто в небо й надійно закріпили його в Небесній Тверді — Царстві Стихій Повітря. Звільнившись від тягаря одноосібної влади, Шал'нан зрікся її під час освячення Святині Чотирьох Вітрів, передавши правління виборній раді. За тисячоліття в цьому чужому світі вигнанці з нічних ельфів перетворилися на світлошкірих, струнких високих ельфів. А останніми поколіннями проявився стихійний вплив, відомий як Благословення Небесного Дотику: дедалі більше дітей народжуються з блідо-блакитною шкірою."},{t="Розбитий спокій",b="Століттями життя в Небесній Тверді процвітало у відокремленні. Духи вітру суворо забороняли згадувати Володаря Вітрів Аль'Акіра й відмахувалися від запитань із моторошним неспокоєм. Кілька століть тому сталася катастрофа: стихійні покровителі зникли без пояснень, а разом із ними — і Шал'нан. Без своїх доглядачів таємні пілони, що тримали Острів Зефрас, почали відмовляти. Віддалені клапті суходолу відривалися, біженці заполонили те, що лишилося, а відчай живив розквіт розбійників і Аль'Акет — фанатичного культу, відданого Аль'Акірові. Сьогодні суспільство розколюється між Високим Орденом, що шукає порятунку в поверненні до таємної магії предків, і Вітротворцями, які тримаються стихійних обрядів."}},faq={{q="Хто такі Небороджені?",a="Небороджені, або шен'дорей («прихований народ»), — високі ельфи, що походять від давніх нічних ельфів, які повстали проти Принца Тортельдріна в Ельдре'Таласі. Щоб утекти від його мстивого флоту, вони уклали угоду з духами вітру, і ті перенесли їхній острів, Острів Зефрас, до Царства Стихій Повітря.",al={"що таке Небороджені","хто такі шен'дорей","шендорей","лор Небороджених"}},{q="Чому в деяких Небороджених блакитна шкіра?",a="Тисячоліття в Царстві Стихій Повітря непомітно змінили їхню природу. Нещодавнє явище, відоме як Благословення Небесного Дотику, призводить до того, що дедалі більша частка дітей — нині приблизно троє з десяти — народжуються з блакитною шкірою. Учені передрікають, що успадковані від нічних ельфів риси невдовзі зникнуть цілком.",al={"благословення небесного дотику","чому вони блакитні","блакитні ельфи","небесний дотик"}},{q="Хто такий Шал'нан?",a="Шал'нан, або «Завуальований», — ватажок у масці, що очолив опір проти виклику демона, який задумав Принц Тортельдрін в Ельдре'Таласі. Привівши вцілілих у безпеку до Небесної Тверді, він зрікся влади, щоб заснувати виборну раду, і служив своєму народові, доки кілька століть тому таємниче не зник разом з їхніми стихійними покровителями.",al={"хто такий завуальований","шалнан","бунтар у масці","ватажок Небороджених"}},{q="Що відбувається з Островом Зефрас?",a="Острів Зефрас тримається в повітрі Небесної Тверді завдяки магічним пілонам, налаштованим на стихійну силу. Коли кілька століть тому раптово зникли духи вітру, які їх підтримували, пілони почали відмовляти. Частини суходолу відкололися й канули в порожнечу, лишивши вцілілих напризволяще, а ельфи, що втратили домівки, взялися до розбою.",al={"чому острів зефрас руйнується","зефрас падає","що сталося з островом у небесній тверді"}},{q="Що таке Високий Орден і Вітротворці?",a="Це дві головні культурні течії Небороджених. Високий Орден походить від магістрів-Високородних і прагне відбудувати своє суспільство, що розвалюється, через дисципліноване опанування таємної магії. Вітротворці ведуть родовід від звичайних городян із нічних ельфів і шанують стихійні й духовні звичаї, що склалися за час життя в Небесній Тверді.",al={"фракції Небороджених","високий орден чи вітротворці","лор вітротворців"}},{q="Хто такі Аль'Акет?",a="Аль'Акет — відчайдушний культ Небороджених, що поклоняється Аль'Акірові, Володарю Вітрів. Стихійні покровителі їхніх предків боялися Аль'Акіра й уникали навіть згадувати його, але руйнування Острова Зефрас штовхнуло бездомних і знедолених біженців шукати порятунку й сили в цього володаря стихії.",al={"культ аль'акет","культ аль'акіра","культ Небороджених"}}},fp="8,417,24.687.0,20.628.0,17.716.1,21.300.0,36.317.0,21.348.0,34.318.0,44.342.0,21.290.0"}
P.entries["topic:skywall"] = {n="Небесна Твердь",s="Небесна Твердь — величезні, сповиті бурями володіння елементалів повітря в Царстві Стихій. Сюди їх у давнину вигнали титани, і створіння вітру, хмар і блискавок живуть під владою Ал'Акіра, Володаря вітру.",h="Небесна Твердь — величезні, сповиті бурями володіння елементалів повітря в Царстві Стихій.",kw={"небесна твердь","ал'акір","елементалі повітря","царство стихій","тандераан","рагнарос","джини"},ang={["class:Mage"]="Чарівники й знавці таємної магії здавна прагнули черпати безмежну енергію неба з Небесної Тверді, проте такі спроби висотати бурі Ал'Акіра часто закінчуються руїною.",["class:Shaman"]="Небесна Твердь — первісне джерело диких, шалених вітрів і блискавок, які шанують і благають шамани, спілкуючись із духами повітря."},sec={{t="В'язниця в небесах",b="Коли еони тому титани скинули Древніх Богів, вони створили Царство Стихій як надійну в'язницю в іншому вимірі, щоб утримувати неприборканих духів стихій Азероту. Володарі стихій люто билися між собою й зрештою поділили його на окремі володіння. Край вітру й бурі став відомий як Небесна Твердь, і правив ним Ал'Акір, Володар вітру. Хоча цей край замкнено від світу на поверхні, його бурі й далі вирують у вічній самоті."},{t="Війна стихій",b="Вигнання не поклало край давній ворожнечі між володарями стихій. Небесна Твердь здавна сперечається за кордони з сусідніми царствами, як-от Вогняними Землями. Одна з найсумнозвісніших сутичок — Стихійний Розкол, коли на принца Тандераана Шукача Вітру напали з засідки й зрадили Ґарр і Барон Геддон, головні поплічники Рагнароса, Володаря вогню. Рагнарос поглинув сутність принца, а її уламки ув'язнив у розбитому талісмані."},{t="Острови Імли",b="Небесна Твердь — це не лише шалені вихори й цитаделі джинів. Серед хмарних гряд дрейфує Острів Зефрас — притулок, де живуть Шен'дорей. Смертні Азероту рідко проникають крізь завісу до царства повітря, хоча нерозважливі чарівники та зброярі в усі часи накликали на себе лихо, намагаючись висотати живі бурі Володаря вітру."}},faq={{q="Що таке Небесна Твердь?",a="Небесна Твердь — володіння елементалів повітря в межах Царства Стихій. Створена титанами, щоб ув'язнити слуг Древніх Богів, вона цілком складається з безкрайнього неба, бур, хмар і блискавок.",al={"що таке небесна твердь","лор небесної тверді","домен повітря"}},{q="Хто править Небесною Твердю?",a="Небесною Твердю править Ал'Акір Повелитель Вітрів, верховний Володар Стихії повітря. Зі свого бурхливого царства він панує над джинами, смерчами й живими бурями.",al={"хто керує небесною твердю","бос небесної тверді","правитель повітря"}},{q="Як постала Небесна Твердь?",a="Здолавши Древніх Богів у первісному минулому Азероту, титанотворенні створили Царство Стихій, щоб замкнути хаотичних елементалів. У цій вимірній в'язниці елементалі повітря захопили власну величезну територію, яка й стала Небесною Твердю.",al={"походження небесної тверді","як створили небесну твердь"}},{q="Що сталося з принцом Тандерааном?",a="Під час Розколу Стихій на принца Тандераана напали з засідки поручники Рагнароса, Володаря вогню, — Ґарр і Барон Геддон. Рагнарос поглинув сутність принца повітря, а те, що лишилося, ув'язнив у розбитому талісмані стихійного скування.",al={"лор тандераана","що сталося з тандерааном","доля вітрошукача"}},{q="Хто живе в Небесній Тверді?",a="Небесну Твердь населяють елементалі повітря, могутні володарі-джини, блискавичні ревенанти й стихійні грозові дракони. Тут також розташований Острів Зефрас — прихисток, де живуть Шен'дорей.",al={"мешканці небесної тверді","хто в небесній тверді"}},{q="Чи можуть смертні дістатися Небесної Тверді?",a="Смертним нелегко потрапити до Небесної Тверді, бо вона лежить в окремій вимірній в'язниці. Здавна торкалися її неба лише могутні чаклуни, що маніпулювали стихійними розломами, чи ті, хто шукав відлюдних Шен'дорей на Острові Зефрас.",al={"як потрапити в небесну твердь","подорож до небесної тверді","портал небесної тверді"}}},fp="7,225,23.443.0,19.453.0,17.357.0,16.232.0,18.176.0,24.248.0,35.243.0,21.183.0,26.231.0"}
P.entries["topic:steamwheedle-cartel"] = {n="Картель Стімвідл",s="Картель Стімвідл — найбільше й найвпливовіше гоблінське підприємство сучасного Азероту. Затято нейтральний, картель керує жвавими торговими осередками на кшталт Буті Бей, Раджета й Ґаджетзана, обслуговуючи клієнтів і з Альянсу, і з Орди — аби лиш їхня монета була справжньою. Його розгалужена діяльність охоплює морські перевезення між континентами, алхімію, підйом майна із затонулих кораблів і безжальне найманство.",h="Картель Стімвідл — найбільше й найвпливовіше гоблінське підприємство сучасного Азероту.",kw={"картель стімвідл","гобліни","буті бей","раджет","ґаджетзан","ґазлоу","нейтралітет"},ang={["class:Rogue"]="Беззаконні околиці Буті Бей і Раджета дають удосталь роботи злодіям, зломщикам і таємним найманцям, готовим обскубти і піратів, і суперників.",["faction:Alliance"]="Для мандрівників з Альянсу поромні шляхи Стімвідла й пустельні застави — незамінні перевалочні пункти й льотні маршрути серед віддалених диких країв, де переважає Орда.",["faction:Horde"]="Хоча Ґазлоу та його команда здавна співпрацюють з орками Дуротару, картель однаково вимагає дзвінкої монети за свої послуги й нейтралітет.",["profession:Engineering"]="Осередки картелю, як-от Раджет і Ґаджетзан, — найкращі місця, щоб роздобути креслення гоблінської інженерії, деталі лісорубних машин і експериментальні механізми."},sec={{t="Прибутковий нейтралітет",b="Картель Стімвідл, що походить із підземної гоблінської столиці Андермайн, спершу уклав союз зі Старою Ордою в Другій війні, постачаючи бойові машини, саперів і знання з корабельної інженерії. Коли пил улігся, ватажки картелю збагнули, що вибір сторони коштує більше, ніж приносить. Прийнявши цілковитий нейтралітет, вони розширилися на обидва континенти, відкривши торговельні мережі, де раді і Альянсу, і Орді. Нині, коли відкрита ворожнеча ледь жевріє, порти Стімвідла — важлива нейтральна земля, де кожен, хто має золото, може купити місце на кораблі, покласти статки в банк і найняти місцевих фахівців."},{t="Порти й застави",b="Вплив картелю тримається на стратегічних портах і прикордонних містечках. У Долині Стренглторну Барон Ревілґаз править Буті Бей — укріпленим портовим містечком, вирізаним у скелях, — разом із Нападниками Чорної Води. За Великим Морем Головний Інженер Ґазлоу керує Раджетом на узбережжі Пусток, утримуючи глибоководну поромну лінію просто до Буті Бей. У глибині пустелі Танаріс лежить швидкозросле містечко Ґаджетзан, а менші осередки, як-от Порт Стімвідла, і віддалені застави в Пустограї, Азшарі та Горах Кам'яного Кігтя забезпечують ресурси краю."},{t="Суперники й грабіжники",b="Торгівлі Стімвідла постійно загрожують ласі до наживи головорізи. У Південних морях Буканіри Кривавого Вітрила без упину загрожують морським шляхам Буті Бей, а Флібустьєри Південних морів грабують узбережжя біля Раджета. На суші картель раз у раз сходиться із заклятими корпоративними суперниками — Венчурною Компанією, — запекло змагаючись за права на деревину, нафтові поля й технології лісорубних машин у Горах Кам'яного Кігтя та Пустках. Щоб підтримувати порядок і змушувати виконувати торгові угоди, барони картелю раз у раз наймають заїжджих найманців, які розв'язують суперечки найрадикальнішими методами."}},faq={{q="Що таке картель Стімвідл?",a="Картель Стімвідл — величезний нейтральний гоблінський торговий концерн з осідком в Андермайні. Він керує кількома великими незалежними містами Азероту — зокрема Буті Бей, Раджетом і Ґаджетзаном — і пропонує всім фракціям банки, інженерні послуги, перевезення й аукціони.",al={"хто такі стімвідл","гобліни стімвідл","що таке стімвідл"}},{q="Чи гобліни Стімвідл належать до Орди чи Альянсу?",a="Ні до кого. Картель дотримується суворого політичного нейтралітету. Хоча під час Другої війни він співпрацював зі Старою Ордою, згодом розірвав офіційні фракційні зв'язки заради більшого прибутку. Нині він охоче торгує і з Альянсом, і з Ордою, а мир у своїх містах підтримує озброєними вишибалами.",al={"чи стімвідл орди","чи картель стімвідл нейтральний","фракція стімвідл"}},{q="Які великі міста належать картелю Стімвідл?",a="Their four principal towns are Booty Bay in southern Stranglethorn Vale, Ratchet on the eastern shore of the Barrens, Gadgetzan in Tanaris, and Everlook in Winterspring. They also maintain smaller hubs like Steamwheedle Port and isolated trading outposts.",al={"міста стімвідл","міста картелю","список гоблінських міст"}},{q="Хто очолює картель Стімвідл?",a="Під час Другої війни картель очолював Торговий Князь Стімвідл. Нині справами в окремих краях керують такі боси, як Барон Ревілґаз у Буті Бей і Головний Інженер Ґазлоу в Раджеті.",al={"лідер стімвідл","торговий принц стімвідл","хто керує стімвідл"}},{q="Чому гобліни Стімвідл ворогують із Венчурною Компанією?",a="Венчурна Компанія — гоблінське підприємство-суперник, відоме безжальним відкритим видобутком і вирубкою лісів. Обидва угруповання постійно змагаються за ті самі земельні концесії, промислові креслення й природні багатства по всьому Калімдору й Східних Королівствах.",al={"венчур ко проти стімвідл","чому ненавидять венчур ко","суперництво з венчурною компанією"}},{q="Що буде, якщо битися в порту Стімвідл?",a="Steamwheedle towns employ armed goblin bruisers to keep the peace. Attacking other travelers can bring the guards down on you, while killing cartel guards or citizens damages your standing with the cartel.",al={"вартові бутті бей","пвп у раджеті","бійці раджета"}}},fp="19,409,23.599.0,18.570.0,18.568.0,32.283.0,59.305.0,53.255.0,34.189.0,66.261.0,53.205.0"}
P.entries["topic:stonefield-family"] = {n="Родина Стоунфілдів",s="Стоунфілди — родина людей-фермерів, що живе на Фермі Стоунфілдів у західній частині Лісу Елвінн. Вони здавна тримаються землі, дбають про своє господарство й водночас ворогують із сусідами — Маклурами. Та хоч між двома домами й панує ворожнеча, їхні молоді нащадки не можуть триматися одне від одного осторонь.",h="Стоунфілди — родина людей-фермерів, що живе на Фермі Стоунфілдів у західній частині Лісу Елвінн.",kw={"стоунфілди","ферма стоунфілдів","маклури","томмі джо стоунфілд","мейбелл маклур","ліс елвінн","фермери"},ang={["faction:Alliance"]="Шукачі пригод з Альянсу, що прямують до Вестфолу, часто беруться за буденні клопоти й особисті сварки Стоунфілдів, щоб житниця Елвінну жила спокійно.",["race:Human"]="Для людей Стормвінда Стоунфілди уособлюють витривалий хребет трудового люду, що постачає зерно й харчі всьому королівству."},sec={{t="Життя на хуторі",b="Стоунфілди — справжні елвіннські хлібороби, що обробляють землю на південь від шляху до Вестфолу. Господарство тримається на Бабусі Мілдред Стоунфілд, Ма Стоунфілд і юному Томмі Джо Стоунфілді. Щоденне життя на фермі — це догляд за посівами й худобою, боротьба з місцевими шкідниками й набігами кобольдів, що дошкуляють копальням і околицям краю."},{t="Ворожнеча з Маклурами",b="Стоунфілдів і їхніх сусідів Маклурів розділяє лише вузька смужка лісу й пасовиська, та між ними точиться давня гірка ворожнеча. Старші покоління обох домів не мають одне до одного жодної приязні: дріб'язкові сварки й суперечки за землю забарвлюють кожну їхню зустріч. Та попри цю запеклу сусідську чвару, між юним Томмі Джо Стоунфілдом і Мейбелл Маклур зародилося таємне кохання, тож співчутливим мандрівникам доводиться бути обережними посередниками."}},faq={{q="Де живе родина Стоунфілдів?",a="Стоунфілди живуть на Фермі Стоунфілдів на південному заході Лісу Елвінн, трохи на південь від головної дороги до кордону з Вестфолом.",al={"розташування ферми стоунфілдів","де стоунфілди","де родина стоунфілдів"}},{q="Хто з родини Стоунфілдів відомий?",a="Серед помітних членів родини — бабуся Мілдред Стоунфілд, Ма Стоунфілд, Гомер Стоунфілд і юний Томмі Джо Стоунфілд. Родинні перекази згадують також Берніс Стоунфілд і покійного дядька Стоунфілда.",al={"хто в родині стоунфілдів","члени родини стоунфілдів","родовід стоунфілдів"}},{q="Чому Стоунфілди ненавидять Маклурів?",a="Стоунфілди й Маклури заплуталися в класичній сільській родинній ворожнечі через давні земельні образи й сусідську впертість, і обидві родини вперто не бажають помиритися.",al={"ворожнеча стоунфілдів і маклурів","чому стоунфілди б'ються з маклурами","суперництво маклурів"}},{q="Як ворожнеча позначається на Томмі Джо Стоунфілді?",a="Томмі Джо Стоунфілд таємно закоханий у Мейбелл Маклур із сусідньої ворожої ферми. Через відкриту ворожнечу між родинами парі доводиться покладатися на обережних посередників, щоб обмінюватися листами й дарунками на знак кохання.",al={"томмі джо маклур","романс томмі джо","в кого закоханий томмі джо"}},{q="Чи родина вірна Стормвінду?",a="Так. Як людські мешканці Лісу Елвінн, вони під захистом Королівства Стормвінд і Альянсу, хоча найбільше їх турбує щоденне виживання ферми й місцеві загрози.",al={"чи стоунфілди альянсу","вірність стоунфілдів"}},{q="Яким загрозам протистоїть родина Стоунфілдів?",a="Окрім тертя з родиною Маклурів, Стоунфілдам доводиться давати раду кобольдам, що лізуть на ферму, мов шкідники, бродячим звірам і загальній нестачі вартових Стормвінда, які патрулювали б сільські угіддя.",al={"небезпеки стоунфілдів","проблеми ферми стоунфілдів"}}},fp="17,382,21.402.0,16.479.1,38.149.0,51.237.0,41.209.0,46.227.0,37.221.0,45.198.0"}
P.entries["topic:stonemasons-guild"] = {n="Гільдія Каменярів",s="Гільдія Каменярів — спілка майстрів-будівничих і ремісників, що після Другої війни відбудувала Стормвінд і звела Замок Незерґард. Після запеклої суперечки з Домом Вельмож через плату, яка завершилася кривавими заворушеннями, гільдію силоміць розпустили, її членів вигнали — і так постало Братство Дефіас.",h="Гільдія Каменярів — спілка майстрів-будівничих і ремісників, що після Другої війни відбудувала Стормвінд і...",kw={"гільдія каменярів","едвін венкліф","дім вельмож","братство дефіас","стормвінд","замок незерґард","базіл тредд"},ang={["class:Rogue"]="Перетворення майстрів-ремісників на смертоносних розбійників з великої дороги, зломщиків і вбивць доводить, як далеко сягала тактична хитрість Венкліфа.",["faction:Alliance"]="Розпад гільдії залишив житницю Вестфолу беззахисною й віддав її на поталу розбійникам, підірвавши шляхи постачання Альянсу просто під стінами столиці.",["race:Dwarf"]="Дворфійські мулярі глибоко шанували Гільдію Каменярів, визнаючи, що її точність і високі мури не поступалися роботі айронфорджської Королівської Спілки Каменярів.",["race:Human"]="Прекрасний білий камінь Стормвінда — гірке свідчення найбільшої внутрішньої трагедії королівства, що нагадує мандрівникам-людям про ціну аристократичної пихи."},sec={{t="Будівничі королівства",b="Після спустошень Першої й Другої воєн Альянс Лордерону доручив Гільдії Каменярів звести Замок Незерґард у Спустошених Землях, щоб стежити за розтрощеним Темним Порталом. Під проводом обраного очільника гільдії Едвіна Венкліфа ремісники виявили таку майстерність у мулярстві, що не поступалася дворфійській Королівській Спілці Каменярів. Вражений їхньою працею, Дім Вельмож найняв гільдію для величезної справи — відбудувати Стормвінд із руїн, довіривши їй повернути столиці давню велич."},{t="Праця й зрада",b="Роками Венкліф і ціле військо ремісників трудилися в Елвінні, зводячи стрімкі шпилі Фортеці Стормвінда й величезні арки Собору Світла. Проте королівська скарбниця не витримала тягаря військових боргів, накопичених у південних походах. Піддавшись аристократичним інтригам, Дім Вельмож відмовився виплатити гільдії обумовлену платню й винагороду. Коли Венкліф зажадав відшкодування, вельможі у відповідь самовільно розпустили гільдію, чим викликали величезний гнів робітників, які проливали кров, відбудовуючи місто."},{t="Кров на вулицях",b="Суперечка через платню вибухнула буремними заворушеннями по всьому Стормвінду. Під час відчайдушної спроби помирити сторони в королеву Тіффін Рінн влучив кинутий камінь і вбив її, і король Варіан поринув у глибоке горе й жагу помсти. Корона безжально придушила заворушення й схопила головних змовників, як-от заступника Венкліфа Базіла Тредда, а сам Венкліф і сотні розорених каменярів утекли до Вестфолу. Вигнані й тавровані як зрадники, зневірені ремісники перетворили свою спілку на войовниче Братство Дефіас."},{t="Прихована рука",b="Протистояння знаті й будівничих було не лише справою порожньої скарбниці. За лаштунками придворна радниця Леді Катрана Престор старанно роздмухувала жар розбрату. Вона переконувала аристократів, що рахунки Каменярів грабіжницькі, а робота абияка, і водночас підбурювала ремісників до відкритого бунту. Паралізувавши Стормвінд внутрішніми чварами й відрізавши постачання до Вестфолу, чорна драконка Оніксія успішно розколола королівство зсередини."}},faq={{q="Що таке Гільдія Каменярів?",a="Гільдія Каменярів була об'єднанням людських ремісників, зодчих і каменотесів на чолі з Головою гільдії Едвіном Венкліфом. Вона прославилася відбудовою Стормвінда й Замку Незерґард після Другої війни.",al={"хто були каменярі","лор гільдії каменярів","що робили каменярі"}},{q="Чому Гільдія Каменярів стала Братством Дефіас?",a="Коли відбудову Стормвінда завершили, Дім Вельмож відмовився платити гільдії через непосильні борги й придворні інтриги. Протести переросли в криваві заворушення, і вигнані робітники організували Братство Дефіас, щоб силою забрати вкрадені в них статки.",al={"чому дефіас розлючений","чому каменярі стали злими","походження братства дефіас"}},{q="Хто очолював Гільдію Каменярів?",a="Обраним Головою гільдії був Едвін Венкліф. Під його проводом гільдія прославилася неймовірною роботою з каменем, а згодом його вигнали, і він заснував Братство Дефіас.",al={"гільдмайстер каменярів","гільдія венкліфа","хто очолював каменярів"}},{q="Які визначні споруди звели Каменярі?",a="Гільдія збудувала Замок Незерґард на краю Спустошених Земель, щоб наглядати за Темним Порталом, і повністю відбудувала Стормвінд після Першої війни, зокрема Собор Світла й Фортецю Стормвінда.",al={"що збудували каменярі","чи каменярі збудували стормвінд","будівельники незерґарда"}},{q="Чи всі Каменярі приєдналися до Братства Дефіас?",a="Не всі пристали до заколоту. Зокрема, майстер Барос Алекстон порвав з Едвіном Венкліфом і лишився в Стормвінді, прийнявши посаду Міського Архітектора, чим заслужив довічну ненависть колишніх товаришів по гільдії.",al={"чи всі каменярі стали бандитами","барос алекстон каменяр","чи хтось залишився в стормвінді"}},{q="Як загинула королева Тіффін Рінн?",a="Королева Тіффін була однією з небагатьох знатних осіб, що співчували робітникам, і намагалася вгамувати натовп під час заворушень через платню. Її влучив і вбив на місці камінь, кинутий із юрби, назавжди перекресливши будь-яку надію на мирне примирення.",al={"смерть тіффін рінн","як померла дружина варіана","бунт каменів королева тіффін"}},{q="Ким був Базіл Тредд у Гільдії Каменярів?",a="Базіл Тредд був довіреним помічником і головним поручником Едвіна Венкліфа за часів гільдії. На відміну від Венкліфа, Тредда схопили після заворушень, і він досі сидить у В'язниці Стормвінда.",al={"історія базіла тредда","тредд каменяр","лейтенант венкліфа"}}},fp="17,362,23.549.0,17.544.0,20.545.1,15.522.2,31.215.0,60.285.0,44.178.0,50.203.0,52.217.0,31.258.0,46.228.0"}
P.entries["topic:stormwind-army"] = {n="Армія Стормвінда",s="Армія Стормвінда — постійне військо, покликане захищати королівство Стормвінд і берегти безпеку Великого Альянсу на півдні. Хоча вона славиться стійкими лицарями й маршалами, нині армію калічать відсутність короля, політичні чвари й гостра нестача воїнів у провінціях.",h="Армія Стормвінда — постійне військо, покликане захищати королівство Стормвінд і берегти безпеку Великого...",kw={"армія стормвінда","маршали","лицарі стормвінда","міська варта","фортеця стормвінда","дім вельмож","туральйон"},ang={["class:Paladin"]="Важка кіннота й командування армії тісно співпрацюють з Орденом Срібної Длані та Верховним Лордом Болваром Фордрагоном, щоб нести справедливість Світла в беззаконні землі.",["class:Warrior"]="Для людей-воїнів Лицарі Стормвінда й піхота Лотара — взірець дисциплінованої служби, хоча багатьом гірко бачити, як знать покинула прикордоння.",["faction:Alliance"]="Відколи Погибель розтрощила Лордерон, армія Стормвінда стала головним оборонним хребтом Великого Альянсу в Східних Королівствах.",["race:Human"]="Для городян Стормвінда королівська армія — і незмінний символ виживання всупереч усьому, і прикре нагадування про бюрократичну зневагу до віддалених сіл."},sec={{t="Спадщина заліза й крові",b="Армія веде свій бойовий родовід крізь століття жорстоких війн — від ранніх прикордонних сутичок із гнолами до відчайдушної оборони від тролів Ґурубаші. У Першій війні під проводом короля Ллейна Рінна I і сера Андуїна Лотара Лицарі Стормвінда влаштовували легендарні засідки на Орду орків, але впали, коли столиця згоріла. Уцілілі рештки евакуювалися до Лордерону, стали рушієм створення Альянсу Лордерону й пройшли всю Другу війну. Після падіння Темного Порталу генерал Туральйон допоміг переформувати й вишколити оновлене військо Стормвінда разом із відродженим королівством."},{t="Устрій і ранги",b="Головна ставка армії — у Фортеці Стормвінда, а спирається вона на віддані місцеві гарнізони під наглядом маршалів Стормвінда. У кам'яних мурах столиці порядок підтримує Міська Варта Стормвінда, а елітна Королівська Варта охороняє юного короля Андуїна Рінна й Верховного Лорда Болвара Фордрагона. За брамою армія розставляє застави, щоб патрулювати Ліс Елвінн, підтримувати порядок на торгових шляхах і тримати оборонні вали аж до Гір Редріджу, а на воді їй допомагає флот Стормвінда."},{t="Тонка синя лінія",b="Попри горді традиції, сучасна армія напружена понад межу. Борги, яких Дім Вельмож наробив, розширюючи військову присутність у Стренглторні, роздмухали запеклу сварку з Гільдією Каменярів, що завершилася міськими заворушеннями, загибеллю королеви Тіффін і появою Братства Дефіас. Поки короля Варіана немає, Дім Вельмож раз у раз відмовляє віддаленим поселенням — Вестфолу, Лейкширу й Сутінколіссю — у війську, грошах і припасах, тож місцеві маршали змушені наймати мандрівних шукачів пригод, щоб ті несли тягар королівства."}},faq={{q="Why aren't more troops sent to Lakeshire and Sentinel Hill?",a="Stormwind's forces are stretched thin, and requests for provincial reinforcements have gone unmet. Westfall relies on the People's Militia, while Lakeshire still has royal soldiers who survived the loss of Stonewatch Keep. With too few defenders and dwindling supplies, its officers turn to traveling adventurers for help.",al={"де армія стормвінда","чому немає солдатів у вестфоллі","чому стормвінд не допомагає"}},{q="Чим Армія Стормвінда відрізняється від Варти Стормвінда?",a="Армія Стормвінда — це все національне військо, зокрема прикордонні маршали, гарнізони й лицарі в походах по всьому королівству. Варта Стормвінда — окрема частина, що підтримує порядок, патрулює вулиці й обороняє брами самого Стормвінда та довколишніх сільських осередків.",al={"варта проти армії","хто вартові стормвінда","роди військ стормвінда"}},{q="Хто зараз командує Армією Стормвінда?",a="За відсутності зниклого короля Варіана Рінна військова влада офіційно належить хлопчикові-королю Андуїну Рінну під безпосередньою опікою регента, Верховного Лорда Болвара Фордрагона. Проте їхні стратегічні рішення постійно оскаржують і підривають політичні інтриги в Домі Вельмож.",al={"хто веде армію стормвінда","командир армії стормвінда","верховний командувач стормвінда"}},{q="Чому маршали роздають шукачам пригод значки помічників?",a="Армія Стормвінда гостро потерпає від нестачі людей і не отримує підкріплень зі столиці, тож місцеві маршали, як-от Макбрайд у Нортширі й Дуґан у Ґолдширі, надають здібним чужинцям статус тимчасового помічника, щоб ті могли законно знищувати розбійників і захищати кордони.",al={"статус помічника","чому видають значки помічників","помічник стормвінда"}},{q="Що сталося з армією під час Першої війни?",a="Під проводом сера Андуїна Лотара армія стримувала Орду дисциплінованими кавалерійськими ударами, але не вистояла, коли вбили короля Ллейна. Лотар зібрав уцілілих солдатів і цивільних і втік з ними через Велике Море до Лордерона, де ці ветерани стали ядром перших військ Альянсу.",al={"армія стормвінда перша війна","чи армія стормвінда програла","лотар армія стормвінда"}},{q="Де армія нині тримає діючі гарнізони?",a="Армія має офіційні гарнізони по всьому Лісу Елвінн, зокрема в Нортширі, Ґолдширі й Гарнізоні Вестбрук. Вестфол і Сутінколісся покладаються на місцеві ополчення, а в Лейкширі солдати, що втратили Фортецю Кам'яної Варти, тримаються й чекають на підкріплення.",al={"гарнізони стормвінда","де розташована армія","місця військ стормвінда"}}},fp="14,341,26.615.0,19.510.0,16.561.1,59.322.0,74.316.0,42.292.0,54.275.0,47.318.0,56.252.0"}
P.entries["topic:stormwind-guard"] = {n="Варта Стормвінда",s="Варта Стормвінда — це місцеві гарнізони й вартові, покликані стежити за дотриманням законів королівства й боронити довколишні землі. Через політичний глухий кут і далекі військові походи її сили небезпечно розпорошені, і маршали ледве стримують гнолів, орків і розбійників в Елвінні та Редріджі.",h="Варта Стормвінда — це місцеві гарнізони й вартові, покликані стежити за дотриманням законів королівства й...",kw={"варта стормвінда","маршали","маршал дуґан","гарнізон вестбрук","лейкшир","гори редріджу","вартові"},ang={["class:Warrior"]="Від новобранців Нортширу до загартованих ветеранів Гарнізону Вестбрук — люди-воїни гартуються в походах пліч-о-пліч із місцевими маршалами проти гнолів і розбійників.",["faction:Alliance"]="Варта Стормвінда — передова королівства, але те, що вона покинула сусідні поселення, оголює глибокі політичні тріщини, що загрожують серцю Альянсу.",["profession:Blacksmithing"]="Гарнізон міцний настільки, наскільки міцні його обладунки: у таких місцях, як Лейкшир, місцеві ковалі вичерпують цілі запаси заліза лише на те, щоб клинки й щити гарнізону були придатні до бою.",["race:Human"]="Для людей південних хліборобських земель сині накидки Варти колись означали цілковиту безпеку, тож їхнє раптове зникнення з Вестфолу й Сутінколісся сприймається як гірка зрада."},sec={{t="Щит Корони",b="Як важлива частина армії Стормвінда, Варта патрулює шляхи, перехрестя й кам'яні дозорні вежі, що скріплюють королівство докупи. У віддалених поселеннях управління й оборона лежать на призначених маршалах — як-от Маршал Макбрайд у Долині Нортширу, Маршал Дуґан у Ґолдширі та Маршал Марріс у Лейкширі. Ці офіцери набирають новобранців і підтримують порядок, а між укріпленими заставами на кшталт Гарнізону Вестбрук пересуваються на надійних гнідих конях, відомих своєю витривалістю."},{t="Розтягнутий кордон",b="Після Третьої війни Варта успішно берегла спокій і безпеку Лісу Елвінн, але останні роки принесли кризу. Відколи король Варіан Рінн зник, а постійне військо королівства загрузло далеко за кордоном, місцеві гарнізони майже не отримують допомоги. У Гарнізоні Вестбрук Помічник Рейнер ледве втримує західний кордон від гнолів Річколапів і злодіїв Дефіас, тож місцеві командири змушені перекладати важливі справи безпеки й нагороди за голови на заїжджих шукачів пригод."},{t="Покинуті землі",b="Справжня криза Варти бере початок у рішеннях королівського двору в столиці. Під впливом Леді Катрани Престор королівство визнало, що тримати гарнізон у Вестфолі надто дорого, повністю вивело звідти війська й дозволило Братству Дефіас Едвіна Венкліфа захопити край. Сутінколісся спіткала та сама доля: його солдатів відкликали, на відчай Даркширу, і покинуті мешканці змушені були створити для самозахисту строкату Нічну Варту."},{t="Облога на сході",b="Поки Сутінколісся й Вестфол покинули, у Горах Редріджу корона ще зберігала хитку військову присутність. Та навіть там становище Варти відчайдушне. Під натиском гнолів Тіньової Шкури і орків Блекрок, що спускаються з Палаючих Степів, вояки змушені були поступитися Фортецею Кам'яної Варти. У Лейкширі коваль Вернер Осґуд витрачає все залізо лише на те, щоб спорядити вартових, а виснажені дозорці вдивляються в дорогу, чекаючи на 2-й батальйон, який так і не приходить."}},faq={{q="Чим Варта Стормвінда відрізняється від Міської Варти?",a="Міська Варта Стормвінда пильнує порядок у столиці за її укріпленими мурами, а Варта Стормвінда — здебільшого у вигляді регіональних гарнізонів — обороняє віддалені землі корони, патрулює дороги й тримає сторожові вежі по всьому Лісу Елвінн і Редріджу.",al={"варта стормвінда проти міської варти","чи це та сама варта","міська варта"}},{q="Чому у Вестфолі немає вартових Стормвінда?",a="Під впливом порад Леді Катрани Престор щодо державних видатків королівський двір вирішив, що утримання гарнізонів надто обтяжливе, і відкликав усі офіційні залоги. Цілковита відсутність військового захисту дала змогу Братству Дефіас Едвіна Венкліфа швидко захопити ферми й дороги краю.",al={"чому варта покинула вестфолл","армія вестфолла","де вартові вестфолла"}},{q="Чому варта покинула Сутінколісся?",a="Як і з Вестфолу, із Сутінколісся королівські гарнізони відкликали ближче до столиці, коли ресурси вичерпалися. Позбавлені офіційного захисту корони серед дедалі сильнішої темної магії й жахіть, мешканці Даркшира, що лишилися, мусили створити власне ополчення — Нічну Варту, — щоб вижити.",al={"вартові сутінколісся","чому стормвінд покинув даркшир","гарнізон даркшира"}},{q="Хто очолює місцеві гарнізони?",a="Місцевою обороною керують призначені маршали. Маршал Макбрайд наглядає за Долиною Нортширу, Маршал Дуґан командує силами з осідком у Ґолдширі, а Маршал Марріс керує відчайдушною обороною Лейкшира в Горах Редріджу.",al={"хто головний","керівники варти","маршали"}},{q="Чому вартові в Лейкширі в такому кепському стані?",a="Гарнізон Редріджу вибили з Фортеці Кам'яної Варти орки Блекрок і місцеві гноли. Затиснуті в Лейкширі, вартові гостро потерпають від нестачі спорядження — коваль Вернер Осґуд витрачає майже все наявне залізо лише на те, щоб переозброїти вартових, — і чекають обіцяного підкріплення, яке королівські очільники все відкладають.",al={"вартові редрідж програють","що сталося в кам'яній варті","біда гарнізону лейкшира"}},{q="Хто такий Маршал Гаґґард?",a="Маршал Гаґґард — шанований відставний командир, що колись очолював Варту Стормвінда за спокійніших часів, коли вояки, вільні від служби, ще могли вирушати на південь, щоб разом випити в Таверні «Багряний Крук» у Даркширі.",al={"лор маршала гаґґарда","маршал у відставці","старий маршал варти"}}},fp="15,328,19.511.0,23.462.0,25.450.1,21.470.0,70.281.0,50.302.0,33.279.0,30.248.0,50.327.0,23.209.0"}
P.entries["topic:stormwind-kingdom"] = {n="Стормвінд (королівство)",s="Королівство Стормвінд — найпівденніше й нині наймогутніше людське королівство Азероту, якому належать Ліс Елвінн, Вестфол, Сутінколісся й Гори Редріджу. Сплюндроване й розтрощене в Першій війні, після Другої воно відродилося ціною крові й праці та стало військовим і культурним осередком Альянсу після трагічного падіння Лордерону на півночі. Нині королівству загрожують і зсередини, і ззовні, а правлять ним десятирічний король Андуїн Рінн під пильною опікою Верховного Лорда Болвара Фордрагона, поки коронований монарх лишається зниклим.",h="Королівство Стормвінд — найпівденніше й нині наймогутніше людське королівство Азероту, якому належать Ліс...",kw={"стормвінд","королівство стормвінд","андуїн рінн","болвар фордрагон","варіан рінн","дім вельмож","ліс елвінн"},ang={["class:Paladin"]="Королівство шанує давні святі традиції Церкви Святого Світла й спадщину Срібної Длані, даючи притулок освяченим орденам у Соборі Світла.",["class:Rogue"]="Запеклі внутрішні чвари Стормвінда й тінь повстання Дефіас наповнили його провулки, стоки й околиці спритними кишеньковими злодіями та політичними шпигунами.",["faction:Alliance"]="Як головна військова й господарська опора сучасного Альянсу, Стормвінд дає прихисток, проводирство й ресурси союзникам — дворфам, гномам і нічним ельфам.",["race:Human"]="Стормвінд — живе серце людства й останній незалежний оплот після загибелі Лордерону, Альтераку й Даларана на півночі."},sec={{t="Спадщина непокори",b="Стормвінд заснували понад тисячу років тому нащадки давньої Аратійської імперії, які рушили на південь, за скелі Каз Модану, до родючих лісистих долин. Століттями північні королівства вважали Стормвінд відокремленою сільською глушиною й навіть не відгукнулися на відчайдушні благання про допомогу під час Війни з гнолами. Під проводом короля Баратена Рінна королівство саме здолало гнолів, а згодом і тролів Ґурубаші, і виплекало культуру, що палко пишається своєю самодостатністю та Світлом."},{t="Попіл і відродження",b="Ця незалежність ледь не згасла, коли крізь Темний Портал ринула Орда орків. У Першій війні Стормвінд згорів дотла, а його короля Ллейна вбили. Уцілілий люд утік на північ через Велике Море під проводом сера Андуїна Лотара й згуртував північні королівства в Альянс Лордерону. Коли загрозу орків розгромили в Другій війні, біженці повернулися додому й найняли Гільдію Каменярів, щоб відбудувати свою величну столицю з білого каменю під синіми стягами. Коли ж у Третю війну Погибель знищила Лордерон, Стормвінд став найбільшим уцілілим оплотом людства."},{t="Розколоте королівство",b="Під своїми стрімкими вежами Стормвінд ледве дає раду розлогим південним володінням. Ліс Елвінн лишається відносно безпечним, але сусідній Вестфол кишить розбійниками, на Редрідж постійно нападають орки й гноли, а темні хащі Сутінколісся вийшли з-під влади королівства. Запекла суперечка між Домом Вельмож і Каменярами розпалила криваві заворушення Дефіас, що забрали життя королеви Тіффін і погнали розорених робітників у відкритий бунт по всіх провінціях."},{t="Порожній трон",b="Нестабільність королівства поглибилася, коли король Варіан Рінн раптово й тихо зник, пливучи на дипломатичну зустріч з Ордою в Тераморі. Щоб зберегти крихкий громадський лад, корону поклали на голову його десятирічного сина Андуїна Рінна, а Верховного Лорда Болвара Фордрагона призначили Лордом-регентом. Проте королівська влада роздроблена й скута: Дім Вельмож, яким уміло керує загадкова Леді Катрана Престор, раз у раз накладає вето на розгортання війська, полишаючи містечка напризволяще, а у Фортеці Стормвінда тим часом визрівають небезпечні таємниці."}},faq={{q="Хто зараз править Стормвіндом?",a="Формально корона належить королю Андуїну Рінну, що зійшов на трон десятирічною дитиною. Оскільки він неповнолітній, справжню владу має Верховний Лорд Болвар Фордрагон як Лорд-Регент, а законодавчі справи значною мірою скеровують і контролюють Леді Катрана Престор і Дім Вельмож.",al={"хто король стормвінда","нинішній правитель","хто править стормвіндом","король стормвінда"}},{q="Що сталося з королем Варіаном Рінном?",a="Король Варіан вирушив зі Стормвінда в таємну дипломатичну подорож до Терамору, щоб домовитися про мир з Ордою. Дорогою він зник за загадкових обставин. Його доля — ретельно бережена державна таємниця, щоб не посіяти хаос серед підданих і зовнішніх суперників.",al={"де варіан","варіан зник","що сталося з королем","історія варіана рінна"}},{q="Чому Стормвінд колись зруйнували?",a="Стормвінд був першою людською державою, на яку натрапила Орда, вторгшись крізь Темний Портал у Першій війні. Попри вперту оборону під проводом короля Ллейна й сера Андуїна Лотара, місто проламали, пограбували й зрівняли з землею, і вцілілі мусили тікати морем на північ, до Лордерона.",al={"перша війна стормвінд","падіння стормвінда","коли горів стормвінд","стормвінд зруйновано"}},{q="Чому у Вестфолі, Редріджі й Сутінколіссі бракує королівських вояків?",a="Королівське військо розпорошене й паралізоване придворною політикою. Леді Катрана Престор і Дім Вельмож раз у раз блокують прохання послати гарнізони за межі Лісу Елвінн, доводячи, що не можна марнувати столичні кошти й сили на охорону околиць, тож ополчення на кшталт Народного ополчення й Нічної Варти б'ються самі.",al={"чому немає солдатів","чому немає допомоги армії","покинуті містечка","незахищені містечка"}},{q="Які землі вважає своїми Королівство Стормвінд?",a="Історично Стормвінд править південною частиною континенту Азерот: Лісом Елвінн, Горами Редріджу, Вестфолом і Сутінколіссям (колишнім Світлоліссям). Колись воно мало й прикордонні застави на півночі Долини Стренглторну.",al={"межі стормвінда","землі стормвінда","які землі стормвінду"}},{q="Чому Каменярі обернулися проти Стормвінда?",a="Відбудувавши Стормвінд як шедевр із білого каменю, Гільдія Каменярів виставила рахунок. Під впливом шляхетських інтриг Дім Вельмож відмовився платити сповна, а каменярі не погоджувалися на поступки. Міські заворушення, що спалахнули, стали кривавими: загинула королева Тіффін Рінн, а гільдію вигнали, і вона перетворилася на розбійницьке Братство Дефіас.",al={"чому дефіас розлючений","бунт каменярів","передісторія дефіасу","чому будівельники повстали"}}},fp="19,600,20.493.0,21.598.0,17.522.1,17.558.2,34.297.0,35.304.0,40.302.0,64.350.0,51.256.0,47.362.0"}
P.entries["topic:syndicate"] = {n="Синдикат",s="Синдикат — розгалужена людська злочинна організація, яку заснували й очолюють позбавлені володінь вельможі полеглого королівства Альтерак. Діючи з укріплених твердинь у Горах Альтерак, Передгір'ї Гілсбреда та руїнах Фортеці Стромгард, вони ведуть безкомпромісну війну і з Альянсом, і з Ордою, щоб повернути собі втрачену аристократичну владу.",h="Синдикат — розгалужена людська злочинна організація, яку заснували й очолюють позбавлені володінь вельможі...",kw={"синдикат","альтерак","перенольд","странбрад","дурнгольд","фортеця стромгард","рейвенголдт"},ang={["class:Rogue"]="Гільдія Рейвенголдт щедро платить злодіям, які наважаться прослизнути в тил ворога й поцупити емблеми просто з кишень розбійників Синдикату, граючи на їхній внутрішній параної.",["faction:Alliance"]="Агенти Синдикату вбили колишнього магістрата Саутшора й невпинно штовхають обезсилене ополчення Стромґарду до повного знищення на Аратійському нагір'ї.",["faction:Horde"]="Вождь Тралл і Леді Сильвана оголосили нагороди за голови членів Синдикату й посилають розвідників нищити їхні табори та повертати викрадені реліквії.",["race:Orc"]="Синдикат вважає ваш народ звірами, приреченими на кайдани й табори, тож визволення полонених братів у Странбраді й Дурнгольді — нагальна справа честі."},sec={{t="Занепала знать",b="Коли після зради короля Ейдена Перенольда в Другій війні королівство Альтерак ганебно впало, його аристократію позбавили земель і титулів. Не змирившись із вигнанням, уцілілі альтерацькі вельможі згуртувалися довкола сина покійного короля, принца Алідена Перенольда. Пов'язавши помаранчеві хустки й поповнивши свої лави найманими головорізами, грабіжниками з великої дороги й недоученими чаклунами, вони створили Синдикат. Для стороннього ока вони поводяться як звичайні розбійники: грабують каравани, нападають на мандрівників і тримають мережі вимагачів. Насправді ж усі їхні злочинні справи існують лише для того, щоб фінансувати організовану спробу відвоювати родові володіння й підкорити довколишні землі."},{t="Північні твердині",b="Синдикат міцно закріпився на півночі Лордерону. У засніжених Горах Альтерак вони укріпили зруйноване містечко Странбрад і облаштували табори по всьому нагір'ю та в Кошарі Дандреда. Південніше, у Передгір'ї Гілсбреда, вони тримають руїни Твердині Дурнгольд і використовують її як плацдарм, щоб докучати Саутшору й грабувати шляхи постачання. Далі на схід, за Муром Торадіна, Лорд Фалконкрест очолює окупаційне військо Синдикату в історичних руїнах Фортеці Стромгард в Араті й воює з виснаженим ополченням Стромґарду за владу над Аратійським нагір'ям."},{t="Вороги на всіх фронтах",b="На відміну від звичайних розбійників, Синдикат плекає великі ідейні амбіції, за які його ненавидить майже кожна фракція краю. Альянс вони вважають смертельним ворогом, що вкрав їхню законну спадщину, і раз у раз полюють на урядовців Саутшора, як-от Магістрата Генрі Малеба. До Орди вони ставляться відверто зверхньо: за вченням Еделаса Блекмура, вважають орків лише звірами, придатними для рабської праці, й прагнуть відбудувати систему таборів інтернування. Відступники Сильвани Віндраннер страчують полонених членів Синдикату на місці, а таємна гільдія злодіїв Рейвенголдт веде безперервну тіньову війну проти їхніх незграбних і пихатих агентів."},{t="Маріонетки Ради Тіней",b="Шляхетні ватажки Синдикату вірять, що борються за верховенство людей і своє право народження, але ними зсередини керують темніші господарі. Культисти Пробудження Аргуса глибоко проникли в їхню верхівку й маніпулюють такими людьми, як Лорд Фалконкрест, підштовхнувши його захопити Фортецю Стромгард. Пробудження Аргуса аж ніяк не служить людським інтересам: зрештою воно звітує перед Радою Тіней, що засіла в Джеденарі у Скверноліссі, і використовує війська й захоплені землі Синдикату як смертний авангард, що розчищає шлях Палаючому Легіону."}},faq={{q="Хто такі Синдикат?",a="Синдикат — велика злочинна організація зі знаті, що втратила маєтки, розбійників і найманців, родом із занепалого королівства Альтерак. На чолі з вигнаними аристократами, як-от принц Аліден Перенольд і Лорд Фалконкрест, вони вдаються до грабунку на дорогах, убивств і військової окупації, намагаючись відродити Альтерак.",al={"що таке синдикат","передісторія синдикату","хто ці хлопці в помаранчевому"}},{q="Чому Синдикат ненавидить Альянс?",a="Альтерак зрадив Альянс Лордерона під час Другої війни. За це Альянс ліквідував королівство й позбавив його знать земель. Провідники Синдикату вважають Альянс смертельним ворогом і завзято шкодять містам Альянсу, торговим караванам і гарнізонам, як-от Фортеці Стромгард.",al={"чому синдикат нападає на альянс","відносини синдикату з альянсом","альтерак проти альянсу"}},{q="Чому Синдикат захоплює орків у рабство?",a="Синдикат поділяє жорсткі погляди колишнього коменданта Дурнгольда Еделаса Блекмура, що вважав орків дикими звірами, придатними лише для неоплачуваної неволі. Принц Аліден Перенольд прагнув відродити систему таборів для інтернованих, використовуючи як підневільну робочу силу орків, захоплених у Передгір'ях Гілсбреда й Альтераку.",al={"орки-раби синдикату","чому орки в клітках странбрад","рабство синдикату"}},{q="Які стосунки між Синдикатом і Рейвенголдтом?",a="Рейвенголдт — знана гільдія професійних убивць і злодіїв у Горах Альтерак, яка вважає Синдикат дилетантами й недисциплінованими громилами. Щоб підточити Синдикат, Рейвенголдт наймає розбійників, які крадуть у його членів відзнаки: зганьблених агентів, що їх утратили, власне керівництво Синдикату безжально прибирає.",al={"рейвенголдт проти синдикату","чому рейвенголдт ненавидить синдикат","емблеми синдикату"}},{q="Хто насправді смикає за ниточки Синдикату?",a="Вельможі думають, що борються за втрачені титули, але організацією потай маніпулює секта чорнокнижників під назвою Пробудження Арґуса. На чолі з такими постатями, як Наґаз і Марез Каул, Пробудження Арґуса служить Раді Тіней у Джеденарі, використовуючи територіальні здобутки Синдикату, щоб підготувати край для Палаючого Легіону.",al={"хто керує синдикатом","арґус вейк синдикат","рада тіней синдикат"}},{q="Де головні твердині Синдикату?",a="Синдикат широко діє в трьох краях: у Горах Альтерак (Странбрад і Кошара Дандреда), у Передгір'ях Гілсбреда (Твердиня Дурнгольд) і в Аратійському нагір'ї (Маєток Нортфолд), де він також займає великий квартал Фортеці Стромгард під проводом Лорда Фалконкреста.",al={"бази синдикату","місця синдикату","де знайти синдикат"}}},fp="9,361,15.710.0,24.623.0,21.687.0,29.543.2,22.328.0,41.322.0,48.330.0,53.345.0,55.327.2,46.279.0"}
P.entries["topic:tauren"] = {n="Таурен",s="Таурени, або шу'гало їхньою рідною мовою, — шляхетна раса кочових гуманоїдів, схожих на биків, із центрального Калімдору. Глибоко віддані Земній Матері, шаманству й світу природи, вони ледь не загинули від безжальних кланів кентаврів, доки не поріднилися з Новою Ордою Тралла. Нині, об'єднані під проводом Верховного Вождя Кайрна Бладгуфа, вони мають постійний дім на зелених рівнинах Малгору та на висотах Тандер Блафа.",h="Таурени, або шу'гало їхньою рідною мовою, — шляхетна раса кочових гуманоїдів, схожих на биків, із...",kw={"таурени","шу'гало","кайрн бладгуф","тандер блаф","малгор","земна мати","кодо"},ang={["class:Druid"]="Завдяки архідруїдові Гамуулу Рунтотему друїди-таурени працюють пліч-о-пліч із нічними ельфами Кола Кенарія, відклавши фракційне суперництво, щоб зцілювати землю й оберігати Смарагдовий Сон.",["class:Shaman"]="Шаманські традиції тауренів — одні з найдавніших на Азероті, і їхні настанови стали ключовими, коли орки знову відкривали свої священні зв'язки зі стихіями після демонічного зіпсуття минулих воєн.",["faction:Horde"]="Таурени дають Орді моральний дороговказ і глибоке духовне коріння, стримуючи войовничі пориви орків і тролів давньою мудрістю й честю.",["race:Tauren"]="Давні кочові мандри вашого народу, шу'гало, змінилися квітучою батьківщиною в Малгорі, яку вберегло нерозривне братерство Кайрна й Тралла."},sec={{t="Кочівники Пусток",b="Незліченні покоління таурени жили сезонними кочівниками, мандруючи посушливими рівнинами Пусток, полюючи на великих кодо й дослухаючись до голосу Земної Матері. Проте їхні мирні мандри століттями затьмарювало жорстоке кровопролиття. Люті племена кентаврів, народжені з трагічного союзу Заетара й Принцеси Терадрас, вели проти них безжальну війну на винищення. Не маючи укріпленої батьківщини й не бажаючи нескінченної війни, племена тауренів опинилися на межі загибелі, і саме їхнє виживання висіло на волосині."},{t="Нова Орда й Тандер Блаф",b="Порятунок прийшов від несподіваного союзу з-за моря. Під час Третьої війни вождь Кайрн Бладгуф зустрів Вождя Тралла та його щойно прибулих орків. Відчувши спільний дух честі й тугу за шаманською спадщиною, обидва провідники об'єднали сили. З допомогою Орди таурени розгромили кентаврів-грабіжників і зайняли пишні, захищені луки Малгору. На його обвітрених столових горах Кайрн звів місто Тандер Блаф. Вдячні за порятунок, таурени разом з Ордою вирушили на Гору Гіджал, щоб відкинути Палаючий Легіон."},{t="Духовні охоронці й внутрішня напруга",b="В Орді таурени — врівноважене, миролюбне сумління. Їхнє опанування природи й стихій допомогло відродити шаманство орків, а архідруїд Гамуул Рунтотем плекає рідкісні дипломатичні й духовні зв'язки з друїдами нічних ельфів, щоб розслідувати дедалі глибше зіпсуття в Смарагдовому Сні. Проте єдність лишається крихкою. Більшість племен шанує мудрість Кайрна, але ксенофобський і безжальний клан Ґрімтотем на чолі з підступною старою відьмою Маґатою живе в Тандер Блафі й потай замишляє захопити владу та повести шу'гало до панування над іншими."}},faq={{q="Чому таурени приєдналися до Орди?",a="Тауренів ледь не винищили безжальні кентаври Пусток. Вождь Тралл і його орки прибули й билися пліч-о-пліч із Кайрном Бладгуфом, відкинули кентаврів і допомогли тауренам закріпитися в Малгорі. Пов'язаний глибоким почуттям честі й спільними духовними цінностями, Кайрн на знак вдячності присягнув Новій Орді у вірності свого народу.",al={"чому таврени в орді","таврени орда альянс","навіщо таврени в орді"}},{q="Хто очолює тауренів?",a="Тауренів очолює Верховний Вождь Кайрн Бладгуф, мудрий і шанований провідник племені Бладгуф. Знаний своєю силою й виваженістю, він об'єднує розрізнені племена зі свого осідку на вершині Тандер Блафа, а допомагають йому Архідруїд Гамуул Рунтотем і Стара Відьма Маґата Ґрімтотем.",al={"лідер тавренів","вождь тавренів","хто править тандер блафом"}},{q="Що таке Земна Мати?",a="Земна Мати — головне божество віри тауренів. Шу'гало вірять, що вона створила світ, сонце й місяць, і шанують її способом життя, глибоко співзвучним природній рівновазі: сезонними кочівлями, полюванням і пошаною до стихій.",al={"земна мати","хто така земна мати","релігія тавренів"}},{q="Чому таурени ненавидять кентаврів?",a="Кентаври століттями полювали на тауренів для розваги й воювали з ними по всьому центральному Калімдору. Вважаючи мирну духовність тауренів слабкістю, кентаври гнали їх з місця на місце й ледь не винищили шу'гало дощенту, поки не втрутилися орки.",al={"війна тавренів із кентаврами","ворожнеча з кентаврами"}},{q="Чи можуть таурени бути друїдами?",a="Так. Хоча друїдство згасло в їхній культурі за довгі кочові війни з кентаврами, у давнину таурени навчилися магії природи в Кенарія. Нещодавно Архідруїд Гамуул Рунтотем за допомогою нічних ельфів відродив ці вчення, і друїди-таурени стали наріжним каменем Кола Кенарія.",al={"лор тавренів-друїдів","як таврени стали друїдами"}},{q="Чи всі таурени вірні Кайрнові Бладгуфу?",a="Більшість племен шанує Кайрна, але плем'я Ґрімтотем лишається гірким винятком. На чолі з Маґатою Ґрімтотем вони вірять, що таурени вищі за всі інші раси, зневажають союз Кайрна з Ордою й потай підточують його мирне правління.",al={"ґрімтотеми лояльність","громадянська війна тавренів"}}},fp="6,462,21.570.0,31.574.0,41.579.1,34.343.0,21.294.0,25.253.0,35.285.0,21.327.0,41.255.0"}
P.entries["topic:terenas-menethil-ii"] = {n="Теренас Менетіл II",s="Король Теренас Менетіл II — шановний володар Лордерону, що правив понад п'ять десятиліть і під час Другої війни викував перший Альянс Лордерону. Відомий як мудрий правитель і вправний дипломат, він захистив людство від першої навали Орди й прихистив юного принца Варіана Рінна. Його трагічне вбивство власним сином, принцом Артасом, якого поглинула темрява, безпосередньо призвело до падіння Лордерону під натиском Погибелі.",h="Король Теренас Менетіл II — шановний володар Лордерону, що правив понад п'ять десятиліть і під час Другої...",kw={"теренас менетіл","лордерон","альянс лордерону","артас","фростморн","друга війна","андуїн лотар"},ang={["class:Paladin"]="Теренас разом з архієпископом Алонсусом Фаолом і Утером Світлоносцем плекав Лицарів Срібної Длані й сам привів до ордену свого сина.",["faction:Alliance"]="Сьогоднішній Великий Альянс бере початок від коаліції, яку Теренас викував разом з Андуїном Лотаром, щоб відкинути Стару Орду під час Другої війни.",["race:Human"]="Людство пам'ятає короля Теренаса як легендарного патріарха, що всупереч усьому об'єднав сім королівств, тож зрада власного сина й раптова смерть від його руки — незагойна трагедія всього народу.",["race:Undead"]="Для Відступників, які колись жили в Столичному Місті, Теренас був останнім живим володарем, чиє падіння прирекло королівство на владу Погибелі."},sec={{t="Творець Альянсу",b="Коли біженці зі Стормвінда на чолі із сером Андуїном Лотаром прибули на північ, король Теренас Менетіл II відгукнувся на їхній заклик. Скликавши монархів роз'єднаних людських королівств разом із посланцями Айронфорджа й Кель'Таласу, Теренас утворив Альянс Лордерону. Замість того щоб узяти військове командування собі, він мудро призначив верховним головнокомандувачем Лотара — і вперше за тисячоліття об'єднав людські королівства, щоб здолати Стару Орду."},{t="Тягар перемоги",b="Після Другої війни Теренас наполіг на тому, щоб уцілілих орків помістили до таборів для інтернованих, а не стратили: він вірив, що мир можна зберегти, якщо їхня демонічна лють розвіється. Це гуманне, але дороге рішення лягло на союзників Лордерону непосильними податками. Ґілнеас відгородився Стіною Ґреймейна, Стромґард відокремився через політичні суперечки, а високі ельфи й зовсім вийшли з союзу, тож Теренасові довелося нести тягар разом із коаліцією, що розпадалася."},{t="Падіння трону",b="На схилі літ Теренас зіткнувся з дедалі гучнішими повстаннями орків на чолі з Траллом, чутками про північні культи смерті й загадковою чумою. Коли мандрівний пророк застеріг короля, що слід покинути Лордерон і тікати за море, до Калімдору, Теренас відмахнувся від нього як від божевільного. Невдовзі з північного походу повернувся принц Артас, якого вітали як переможця. Посеред королівських урочистостей Артас став навколішки перед батьком, видобув рунічний клинок Фростморн і пронизав серце Теренаса — назавжди зруйнувавши королівство."}},faq={{q="Хто такий король Теренас Менетіл II?",a="Це був добрий і шанований монарх королівства Лордерон. Правлячи понад п'ятдесят років, він стояв у центрі північної політики, заснував Альянс Лордерона для боротьби з Ордою в Другій війні й правив зі Столичного Міста до свого вбивства.",al={"хто такий теренас","теренас менетіл","король лордерона"}},{q="Як загинув Теренас?",a="Теренаса вбив у його власній тронній залі син, принц Артас Менетіл. Артас, що під час походу до Нортренду піддався безумству й спотворенню через рунний клинок Фростморн, повернувся до Столичного Міста, вдаючи переможця, і пронизав батькові серце.",al={"як помер теренас","артас убиває батька","смерть теренаса"}},{q="Які стосунки були в Теренаса зі Стормвіндом?",a="Теренас відіграв вирішальну роль у виживанні Стормвінда. Коли південне королівство впало в Першій війні, він дав притулок його вцілілим і виховував принца Варіана Рінна разом із власним сином Артасом, ставлячись до юного Варіана як до другого сина, доки Стормвінд не відвоювали й не відбудували.",al={"теренас і стормвінд","теренас і варіан","чи теренас допоміг стормвінду"}},{q="Чому за його правління Альянс Лордерона розпався?",a="Після Другої війни Теренас вирішив ув'язнити полонених орків у таборах для інтернованих, а не страчувати їх. Величезні витрати на ці табори викликали гірке обурення держав-членів. Ґілнеас звів Стіну Ґреймейна, щоб відгородитися, Стромґард вийшов через політичні суперечки, а ельфи Кель'Таласу цілком відійшли.",al={"чому розпався альянс","чому королівства покинули лордерон","податки таборів інтернованих"}},{q="Чи знав Теренас про Чуму Нежиття?",a="Теренас знав про дивні культи й недугу, що ширилася на півночі, але недооцінив загрозу. Даларан закликав його запровадити суворий карантин північних міст, проте Теренас вагався, боячись ще більших страждань для свого народу. Він послав розслідувати принца Артаса й Утера Світлоносця, не знаючи про пастку, що на них чекала.",al={"чи теренас знав про чуму","реакція теренаса на чуму"}},{q="Чому Теренас не послухав таємничого Пророка?",a="Коли в його залі ради з'явився пророк у плащі й благав евакуювати мешканців Лордерона на захід, до Калімдору, Теренас відмахнувся від нього як від божевільного фанатика. Теренас вірив, що його війська, паладини й міцне королівство витримають будь-які випробування, — і цим прирік королівство на загибель.",al={"теренас і пророк","медів і теренас","чому теренас не втік"}}},fp="19,422,25.480.0,22.476.0,22.519.2,33.271.0,20.303.0,47.287.0,61.347.0,45.352.0,52.296.0"}
P.entries["topic:third-war"] = {n="Третя війна",s="Третя війна — апокаліптичний конфлікт, що лише кілька років тому зруйнував старий світовий лад. Задумана Палаючим Легіоном і розв'язана Чумою Нежиття Короля-Ліча, ця війна принесла падіння королівства Лордерон і майже цілковите знищення Кель'Таласу, а завершилася відчайдушним спільним опором на Горі Гіджал.",h="Третя війна — апокаліптичний конфлікт, що лише кілька років тому зруйнував старий світовий лад.",kw={"третя війна","чума нежиття","артас менетіл","гора гіджал","архімонд","нордрассіл","лордерон"},ang={["class:Paladin"]="Лицарів Срібної Длані розірвала війна: Артас розпустив орден, убив Утера Світлоносця й перетворив їхні святі зали на склепи смерті.",["faction:Alliance"]="Падіння Лордерону перемістило осердя проводу Альянсу на південь — до Стормвінда й Айронфорджа, а вцілілі дивляться на північ із палким бажанням повернути батьківщину.",["faction:Horde"]="Для Орди Тралла ця війна стала горнилом спокути: Ґроммаш Хеллскрім убив Маннорота й назавжди зламав демонічний кривавий прокльон, і орки змогли збудувати в Калімдорі незалежну державу.",["race:NightElf"]="Оборона Нордрассілу коштувала калдореям безсмертя й уперше за десять тисяч років відкрила їхні давні землі широкому світові.",["race:Undead"]="Відступники — живі пам'ятники жахіттям війни: громадяни Лордерону, яких убила чума й змусила служити Погибелі, доки вони не вирвалися на волю й не здобули Андерсіті."},sec={{t="Чума й принц",b="Війна почалася непомітно на півночі Лордерону — під виглядом страшної хвороби, яку розносило заражене зерно з Андоргала. Отруєний урожай не просто вбивав своїх жертв: він піднімав їх ненаситними гулями, скореними волі Короля-Ліча. Принц Артас Менетіл кинувся стримувати заразу разом із чарівницею Кірін-Тору Джайною Праудмур. Засліплений горем, люттю й підступами жахолордів, Артас вирізав заражене населення Стратгольма, а тоді погнався за ворогом до крижаних пустищ Нортренду. Там він узяв проклятий рунний клинок Фростморн, відкинувши власну душу. Він повернувся на південь лише для того, щоб убити свого батька, короля Теренаса, і віддати Лордерон Погибелі."},{t="Вторгнення Легіону",b="Сповнений сили смерті, Артас розгромив королівство високих ельфів Кель'Талас, щоб воскресити некроманта Кел'Тузада біля Сонячного Колодязя. Тоді військо нежиті взяло в облогу Даларан і захопило книги заклять, потрібні, щоб закликати на Азерот владику демонів Архімонда. Коли командувач Палаючого Легіону ступив на землю смертних, Даларан зрівняли із землею в нищівному спалаху таємної магії. Погибель виконала свою роль передового загону, і Палаючий Легіон звернув погляд на вічну силу, що спочивала за Великим Морем."},{t="Втеча на захід і Гора Гіджал",b="Дослухавшись до загадкових застережень таємничого Пророка — згодом з'ясувалося, що це Медів, колишній Страж, який шукав спокути, — Вождь Тралл повів Нову Орду через Велике Море, а Леді Джайна Праудмур вивезла вцілілих біженців Альянсу. У давньому Калімдорі прибульці зіткнулися з відлюдними нічними ельфами, доки всі три сторони не усвідомили найбільшої загрози, що нависла над ними. Під Світовим Деревом Нордрассіл на вершині Гори Гіджал смертні разом стали проти неймовірної сили. Коли Архімонд дістався дерева, його знищили вогники предків, і це розтрощило авангард Легіону й поклало край війні."},{t="Пошрамований світ",b="Хоч Архімонд і загинув, мир 25-го року після відкриття Темного Порталу крихкий і затьмарений утратами. Альянсу Лордерону більше немає: опорою Альянсу на півдні тепер є королівства Стормвінд і Айронфордж, а Лордерон гниє, перетворившись на Чумні Землі. У Калімдорі Орда Тралла виборола собі Дуротар, проте стосунки з нічними ельфами, недавніми союзниками, лишаються вибуховими. Погибель досі тримається в північних руїнах, а звільнена нежить — Відступники — тепер володіє катакомбами Столичного Міста й веде боротьбу за виживання і з колишніми господарями, і з мстивими хрестоносцями."}},faq={{q="Коли відбулася Третя війна?",a="Третя війна почалася в 20 році після відкриття Темного Порталу зі спалаху Чуми Нежиття в Лордероні й закінчилася в 21 році Битвою за Гору Гіджал. Нині, у 25 році, від її спустошень минуло лише чотири роки: руїни ще свіжі, а майже кожен дорослий або воював у ній, або втратив у ній рідних.",al={"коли була третя війна","як давно була війна","дати третьої війни"}},{q="Чим Третя війна відрізнялася від Першої і Другої?",a="Перша і Друга війни були здебільшого боротьбою Старої Орди з королівствами Альянсу. Третя війна стала світовим демонічним вторгненням, що розтрощило цілі держави. Смертні билися не лише одні з одними, а й із космічною загрозою Палаючого Легіону та його неживої Погибелі на трьох континентах, тож навіть заклятим ворогам довелося укласти відчайдушне перемир'я.",al={"різниця третьої війни","чому третя війна інша","орда проти альянсу третя війна"}},{q="Що сталося з Королівством Лордерон?",a="Лордерон знищили зсередини. Культ Проклятих заразив Чумою Нежиття зерно краю, вирізаючи населення й піднімаючи його потворами. Власний кронпринц, Артас, піддався спотворенню, убив свого батька короля Теренаса II і віддав розбите королівство Погибелі.",al={"доля лордерона","чому лордерон зруйновано","що сталося з теренасом"}},{q="Хто був той Пророк, що закликав усіх іти на Калімдор?",a="Пророком був Медів, останній Хранитель Тірісфалю. Повернутий, щоб спокутувати свою колишню роль у відкритті Темного Порталу, Медів подорожував в образі мандрівника в плащі з вороновим пір'ям, попереджаючи провідників, що Лордерон приречений, і закликаючи їх об'єднатися на забутому континенті Калімдор.",al={"хто був пророк","ворон-пророк","медів третя війна"}},{q="Чому нічні ельфи тепер в Альянсі?",a="Десять тисячоліть нічні ельфи жили в суворій відособленості. Третя війна знову привела Легіон до їхніх священних лісів і змусила пожертвувати безсмертям, щоб убити Архімонда біля Світового Дерева. Опинившись у докорінно зміненому світі, де наростали суперечки за ресурси з Ордою Тралла й лишалися сліди спотворення Погибелі, вони відмовилися від самоти й уклали союз із расами Східних Королівств.",al={"чому нічні ельфи приєдналися до альянсу","нічні ельфи третя війна","келдореї приєднання"}},{q="Як Орда втекла від війни в Лордероні?",a="Вождь Тралл повірив пророчим снам від Медіва. Він згуртував звільнені з таборів клани, напав на людські порти, щоб захопити вітрильні кораблі, і втік через Велике Море, перш ніж Погибель чи Легіон остаточно поглинули Лордерон.",al={"як тралл покинув лордерон","орки пливуть на захід","втеча орди в калімдор"}}},fp="9,351,25.705.0,26.524.0,31.600.0,15.552.0,30.312.0,63.357.0,42.324.0,59.287.0,49.417.0,46.249.0"}
P.entries["topic:titan"] = {n="Титан",s="Титани — первісна раса велетенських богоподібних істот, що мандрують космосом, несучи лад і творячи світи. У сиву давнину вони прийшли на Азерот, щоб здолати хаотичних Древніх Богів, звести величезні споруди на землі й виплекати життя, а тоді вирушили назад у Велику Темряву За Межею.",h="Титани — первісна раса велетенських богоподібних істот, що мандрують космосом, несучи лад і творячи світи.",kw={"титани","пантеон","древні боги","аспекти","ульдаман","саргерас","творці"},ang={["class:Mage"]="Таємна магія — сама життєва сила титанів, і її впорядковані засади ведуть просто до чарів-конструкцій, якими Пантеон оплів світ.",["profession:Mining"]="Гірники вгризаються глибоко в кістяк землі й часто натрапляють на незаймані жили металу, викуваного титанами, та підмурки споруд, старших за писану історію.",["race:Dwarf"]="Титанів шанують як божественних Творців. Розкрити своє походження через реліквії титанів — головна мета Ліги Дослідників і короля Маґні Бронзбірда.",["race:Gnome"]="Гноми мають механічну спадщину, що походить від творінь титанів, — звідси їхній природний хист до годинникових механізмів і розкопок."},sec={{t="Творці космосу",b="Титани — космічні велетні, викувані з первісної матерії й таємної магії, що втілюють сили порядку й творення. Мандруючи Великою Темрявою За Межею, вони шукали сплячі світи, щоб плекати їх: здіймали континенти, вгамовували хаотичні сили стихій і задумували життя. Щоб підтримувати рівновагу, вони створювали могутніх вартових-конструктів із каменю, заліза й моря, які пильнували їхні творіння."},{t="Упорядкування Азероту",b="Давним-давно Пантеон титанів знайшов Азерот у владі хаотичних володарів стихій і жахливих Древніх Богів. Титани повели війну проти цих паразитичних жахіть: вигнали елементалів до відокремлених вимірів і запечатали потворних Древніх Богів глибоко під земною корою. Убезпечивши світ, вони виліпили великі природні краї, збудували комплекси сховищ, як-от Ульдаман, і довірили п'ятьом великим драконам — Драконячим Аспектам — опіку над землею, магією, часом і самим життям, а тоді повернулися до зірок."},{t="Полеглий поборник",b="Не всі титани лишилися вірними задуму Пантеону про досконалий лад. Саргерас, колись найвеличніший воїн і захисник титанів, занепав духом і жахнувся глибокої космічної темряви та демонічної злоби, з якими мав боротися. Відкинувши справу своїх родичів, Саргерас звернувся до нігілізму й заснував демонічний Палаючий Легіон, щоб знищити все створене, аби воно не дісталося зіпсуттю."}},faq={{q="Чи титани досі живі й чи вони в Азероті?",a="Самі титани покинули Азерот у незапам'ятні часи й пішли у Велику Темряву, здолавши Древніх Богів і впорядкувавши світ. По собі вони лишили титанічних вартових, кам'яні й залізні конструкти та величезні поховані комплекси сховищ, щоб наглядати за своїм задумом.",al={"де титани","чи титани в азероті","місця титанів"}},{q="Чому дворфів так цікавлять титани?",a="Дворфи походять безпосередньо від землян — раси підземних кам'яних істот, яких титани створили, щоб тесати основи світу. Через археологію й розкопки руїн на кшталт Бель Модану й Ульдаману дворфи прагнуть розкрити свій забутий родовід.",al={"чому дворфи цікавляться титанами","зв'язок дворфів і титанів","дворфи й творці"}},{q="Що таке Пантеон?",a="Пантеон — правляча рада титанів на чолі з Всеотцем Аман'Тулом. До неї також входять Каз'ґорот, творець світів, Еонар, що оберігає життя, Норґаннон, хранитель небесної магії, Ґолґаннет, володар небес, і Аґґрамар — поборник, що заступив Саргераса.",al={"що таке пантеон","титан пантеон","лідери титанів"}},{q="Чи титани створили Аспектів драконів?",a="Так. Перш ніж покинути Азерот, Пантеон спрямував свою силу через хранителів, щоб благословити п'ятьох прадраконів. Алекстраза, Ізера, Малігос, Ноздорму й Нелтаріон отримали величезну силу, щоб оберігати життя, природу, магію, час і землю.",al={"чи титани створили драконів","походження аспектів","хто створив аспекти"}},{q="Чи Саргерас — титан?",a="Саргерас колись був поборником Пантеону й захищав космос від хаосу й демонів. Доведений до відчаю й божевілля темрявою, яку побачив, він відколовся від побратимів і створив Палаючий Легіон, присвятивши себе спаленню впорядкованого всесвіту.",al={"хто саргерас","чи саргерас бог","походження саргераса"}},{q="Чи загинув у Силітусі титан?",a="Пророцтва, записані Пророком кіраджі Скерамом, стверджують, що в південних пустелях Силітусу титан бився з прадавнім злом і загинув. Проте вчені й дослідники сперечаються, чи був це справжній титан, чи лише один із титанічних конструктів.",al={"титан у силітусі","пророцтво к'туна титан","чи к'тун убив титана"}}},fp="5,297,24.406.0,23.537.0,19.414.0,42.246.0,49.271.0,21.286.0,41.249.0,20.271.0,29.256.0"}
P.entries["topic:venture-company"] = {n="Венчурна Компанія",s="Венчурна Компанія — сумнозвісно безжальний гоблінський картель, що зосереджується на хижацькому видобутку ресурсів, важкій промисловій техніці та вирубуванні лісу. Не пов'язаний із великими гоблінськими портами, як-от Буті Бей чи Раджет, картель вигризає надра й вирубує ліси по всьому Калімдору та Східних Королівствах, не зважаючи ні на місцевих мешканців, ні на природу.",h="Венчурна Компанія — сумнозвісно безжальний гоблінський картель, що зосереджується на хижацькому видобутку...",kw={"венчурна компанія","гобліни","фіззпрокет","лісорубні машини","малгор","гори кам'яного кігтя","озеро назферіті"},ang={["class:Druid"]="Суцільна вирубка в Горах Кам'яного Кігтя й промислове забруднення природних джерел у Малгорі та Пустках — зухвале, ніким не стримане осквернення землі.",["class:Rogue"]="І Розтрощена Рука, і SI:7 пильно стежать за торгівлею отрутами картелю: проникають до їхніх веж і усувають високопоставлених наглядачів, щоб роздобути їхні смертоносні хімічні суміші.",["profession:Engineering"]="Картель виробляє одні з найкращих і найдосконаліших лісорубних машин і механічних регуляторів Азероту, тож його креслення — бажана здобич для промислових крадіїв.",["race:Tauren"]="Венчурна Компанія без дозволу вдерлася на священні пагорби Малгору, отруїла колодязі предків і вирубує ліс усупереч Земній Матері."},sec={{t="Промисловий грабунок",b="Венчурна Компанія, якою здалеку керує магнат Раздунк, живе за простою корпоративною філософією: якщо щось можна зрубати, пробурити чи висадити з гори, вони це видобудуть. Картель використовує одні з найсучасніших важких машин Азероту, зокрема величезні лісорубні машини, бурові вежі й промислові переробні заводи. На відміну від традиційних торгових домів, що займаються перевезеннями чи роздрібною торгівлею, Венчурна Компанія спеціалізується на захопленні сировини силою, нехтуючи угодами, кордонами й правами місцевих володарів."},{t="Зазіхання на Калімдор",b="Стрімке поширення картелю в Калімдорі накликало на нього загальну ворожість. У Малгорі Наглядач Фіззпрокет поставив бурові й гірничі установки на східних кручах, хоча таурени офіційно відмовили йому в правах на надра, і забруднив чисті колодязі по всіх рівнинах. Далі на північ компанія перетворила Багнисте Болото в Пустках на хімічну клоаку, щоб живити нафтові помпи, а ще захопила колишню ордівську Шахту Кам'яної Жили, де проводить мерзенні досліди із самофланжами й отруйними варивами. На Кручі Вітрорізу в Горах Кам'яного Кігтя лісоруби під проводом божевільного прокаженого гнома Ґерензо Ренчвісла знищили цілі гаї велетенськими машинами «Супержнець 6000»."},{t="Корпоративне суперництво й темні оборудки",b="Венчурну Компанію зневажають навіть інші гобліни. Барон Ревілґаз із Буті Бей раз у раз наймає людей для ударів по її базовому табору й нафтовій вежі на Озері Назферіті, прагнучи і зупинити її зазіхання на чужі землі, і викрасти її найновіші регулятори палива для лісорубних машин. Спілка Винахідників у Раджеті відверто вдається до промислового шпигунства, щоб красти її інженерні креслення. Ба гірше, SI:7 та Розтрощена Рука виявили, що компанія торгує небезпечними алхімічними сполуками: продає смертоносні отрути Занзіла, що змінюють свідомість, некромантам Дефіас у Вестфолі й використовує отруйні випари, щоб виводити мутованих робітників-трутнів."}},faq={{q="Хто очолює Венчурну Компанію?",a="Президент картелю — Магнат Раздунк, що здалеку керує загальними корпоративними справами організації. За щоденною роботою на об'єктах по всьому Азероту наглядають регіональні керівники, виконроби й наймані наглядачі, як-от Наглядач Фіззпрокет у Малгорі, Наглядач Луґвізл у Багнистому Болоті й Ґерензо Ренчвісл у Горах Кам'яного Кігтя.",al={"лідер венчур ко","бос венчурної компанії","хто керує венчур ко","могул раздунк"}},{q="Чому Орда ненавидить Венчурну Компанію?",a="Картель веде незаконний, хижацький видобуток на прадавніх землях Орди. У Малгорі гобліни без дозволу вдерлися в східні гори й отруїли священні криниці тауренів. У Пустках вони захопили в Орди Шахту Кам'яної Жили й перетворили Багняну Драговину на отруйну нафтову пляму.",al={"таврени венчур ко","чому орда ненавидить венчур ко","мулґор венчурна компанія"}},{q="Чи пов'язана вона з картелем Стімвідл чи Буті Бей?",a="Ні. Венчурна Компанія — окрема хижацька організація. Вона — запеклий корпоративний ворог картелю Стімвідл: Барон Ревілґаз із Буті Бей часто наймає найманців, щоб зривати її вирубку в Долині Стренглторну, а Спаттервалв із Раджета регулярно посилає агентів, щоб псувати її шредери й красти креслення.",al={"чи вони стімвідл","венчур ко бутті бей","раджет венчур ко"}},{q="Чому лісозаготівлею на Кручі Вітрорізу керує гном-прокажений?",a="Ґерензо Ренчвісла Венчурна Компанія найняла за його безжальний механічний геній: він сконструював величезну лісозаготівельну машину Супержнець 6000. Його найм обурив гоблінських інженерів картелю, як-от Зіза Фіззікса, і навіть розгнівав Торгових Князів Андермайну, які не схвалювали, що Раздунк водиться з гномом-вигнанцем.",al={"ґерензо рентжсвіст","гном у кам'яному кігті","чому прокажений гном у венчур"}},{q="Що Венчурна Компанія робить у Вестфолі?",a="Венчурна Компанія мала незаконну торгову оборудку з Братством Дефіас. Вона добувала отрути Занзіллі й продавала суміш агентові Дефіас Клавенові Мортвейку у Вестфолі, а той за допомогою цих отруйних зіль виготовляв безвольних трутнів Дефіас, схожих на робітників на об'єктах Венчурної Компанії.",al={"венчур ко вестфолл","клейвен мортвейк венчур ко","венчур дефіас"}},{q="Що виробляють у Багнистому Болоті?",a="Картель поставив промислову бурову установку просто на місці колишнього чистого природного джерела: качає й переганяє нафту, а отруйний мул скидає по всіх північних Пустках. Окрім нафти, тамтешні дослідники випробовують складні механічні самофланці й синтезують отруйні суміші.",al={"нафта багнистого болота","нафтова вишка пустовиськ","самофланж багниста болото"}}},fp="15,358,18.549.0,23.663.1,39.649.2,30.346.0,44.307.0,62.340.0,58.344.0,46.314.1,41.298.0"}
P.entries["topic:war-of-the-ancients"] = {n="Війна Прадавніх",s="Десять тисяч років тому нерозважливе чаклунство королеви Азшари та її Високородних прорвало портал крізь Колодязь Вічності й випустило на Азерот демонічний Палаючий Легіон. Під проводом юного друїда Малфуріона Стормрейджа, Жриці Тіранди Віспервінд і командира Джарода Шедовсонга відчайдушний союз смертних і прадавніх лісових напівбогів відбив загарбників. Знищення Колодязя спричинило Великий Розкол, що вщент розтрощив давній континент Калімдор і назавжди змінив обличчя світу.",h="Десять тисяч років тому нерозважливе чаклунство королеви Азшари та її Високородних прорвало портал крізь...",kw={"війна прадавніх","азшара","малфуріон стормрейдж","тіранда віспервінд","колодязь вічності","великий розкол","джарод шедовсонг"},ang={["class:Druid"]="Ця війна позначила народження друїдизму смертних, коли Малфуріон Стормрейдж навчився шляхів дикої природи в Кенарія й довів, що сила природи здатна здолати космічну руїну.",["class:Mage"]="Нерозважлива пиха Високородних під час війни — найвище історичне застереження для всього Азероту про катастрофічну небезпеку неприборканого черпання таємної сили.",["class:Priest"]="Майстерність, з якою Тіранда Віспервінд під час війни володіла благодаттю Елуни, піднесла Жрецтво Місяця до самого серця військового й громадського проводу нічних ельфів.",["race:NightElf"]="Ця війна сформувала кожну рису сучасного суспільства калдореїв: глибоку недовіру до таємної магії, шанування Кенарія й незмінний провід Малфуріона й Тіранди.",["race:Tauren"]="Воїни-таурени бережуть горду пам'ять про те, як десять тисячоліть тому пліч-о-пліч із лісовими богами й давніми смертними відкидали Легіон."},sec={{t="Безумство Високородних",b="У розквіті давньої Імперії Калдореїв королева Азшара та її елітна каста чарівників, Високородні, невпинно черпали з величезних таємних глибин Колодязя Вічності. Їхні нерозважливі маніпуляції посилали потужні хвилі у Велику Темряву За Межею й привернули увагу Саргераса, володаря Палаючого Легіону. Зачаровані обіцянками найвищої влади й досконалості, Азшара та її радник Ксавіус відчинили в Колодязі розлам між вимірами. У столицю Зін-Азшарі ринули легіони гончаків Скверни, вартових скверни, вартових загибелі й жахливих командирів, вирізаючи всіх, хто не належав до Високородних, і розпочинаючи свій похід, щоб очистити світ від життя."},{t="Опір калдореїв",b="Нажахані різаниною, нічні ельфи, що не належали до касти Високородних, згуртувалися довкола досвідченого полководця лорда Кур'талоса Рейвенкреста. Опір підсилили видатні герої: перший смертний друїд Малфуріон Стормрейдж, побожна жриця Елуни Тіранда Віспервінд і обдарований брат Малфуріона Іллідан. Коли імперські сили вбили Рейвенкреста, а демонічні армії тиснули дедалі сильніше, командування перейшло до блискучого тактика Джарода Шедовсонга. Розуміючи, що самі ельфи не вистоять, Джарод переступив давні межі між расами й залучив земляних, фурболгів і гірських тауренів до спільної лінії оборони проти навали Легіону."},{t="Ціна перемоги",b="Війна набула світоруйнівного розмаху, коли напівбог Кенарій повів у бій прадавніх Диких Богів і драконячі роди. Рішучі не допустити, щоб сам Саргерас ступив на Азерот, Малфуріон і повстанці зробили відчайдушну спробу зруйнувати портал над Колодязем Вічності. Їхній ризикований задум удався: демонічне військо відкинуло назад у Викривлений Нижній Світ, але напруга виявилася надто великою. Колодязь шалено обвалився сам у себе, спричинивши Великий Розкол, що розтрощив Калімдор на окремі континенти й затопив середину світу, — так народилося Велике Море, а культура калдореїв назавжди змінилася."}},faq={{q="Що спричинило Війну Прадавніх?",a="Королева Азшара та її чаклуни-Високородні невпинно експериментували з таємною енергією Колодязя Вічності. Їхні закляття розсилали космосом хвилі, що привабили темного титана Саргераса, і той переконав Високородних відчинити в Колодязі прохід, щоб Палаючий Легіон увійшов в Азерот.",al={"чому почалася війна","хто спричинив війну прадавніх","портал колодязя вічності"}},{q="Що таке Великий Розкол?",a="Великий Розкол — катаклізм, що поклав край війні. Щоб не дати Саргерасу ввійти у світ, повстанці обвалили портал у Колодязі Вічності. Від віддачі Колодязь шалено вибухнув усередину, розірвавши єдиний суперконтинент Калімдор на окремі суходоли й утворивши Велике Море.",al={"що таке розкол","як розколовся калімдор","вибух колодязя вічності"}},{q="Хто очолював смертних у боротьбі з Легіоном?",a="Спершу опір згуртував Лорд Кур'талос Рейвенкрест. Після його загибелі на полі бою верховний провід перейняв командир Джарод Шедовсонг, що керував об'єднаними наземними військами разом із ключовими героями битв, зокрема Малфуріоном Стормрейджем і Тірандою Віспервінд.",al={"хто вів опір","лідери опору келдореїв"}},{q="Чи билися поруч із нічними ельфами інші раси?",a="Так. Зламавши давні ельфійські упередження, командир Джарод Шедовсонг прийняв допомогу кількох смертних рас, об'єднавши землян, племена фурболгів і гірських тауренів проти демонічного вторгнення разом із лісовим напівбогом Кенарієм і його дикими побратимами.",al={"таврени у війні прадавніх","хто допомагав нічним ельфам"}},{q="Що сталося з королевою Азшарою під час війни?",a="Азшара до гіркого кінця лишалася у своєму палаці в Зін-Азшарі, одержима бажанням привести Саргераса в Азерот. Коли Колодязь Вічності вибухнув усередину й океан поглинув столицю, королева та її вцілілі вірні Високородні пішли у вируючі глибини.",al={"де азшара","чи королева азшара померла"}},{q="Чому нічні ельфи сьогодні не довіряють таємній магії?",a="Калдореї на власні очі бачили, як нестримна жага Високородних до таємної магії прикликала Палаючий Легіон і знищила стародавній Калімдор. Після цього нічні ельфи суворо заборонили таємне чаклунство й звернулися натомість до друїдства й віри в Елуну, щоб захищати свої землі.",al={"чому нічні ельфи ненавидять магів","заборона магії келдореїв"}}},fp="19,538,21.647.0,23.661.0,20.640.0,36.304.0,29.319.0,45.285.0,48.255.0,46.269.0,52.287.0"}
P.entries["topic:warlock"] = {n="Чорнокнижник",s="Чорнокнижники — чарівники, що укладають угоди з темними силами, командують демонами, насилають виснажливі прокльони й володіють нищівною магією вогню й тіні. Хоча майже кожне цивілізоване суспільство Азероту глибоко боїться їх і не довіряє їм, дехто застосовує ці заборонені мистецтва на захист своєї фракції, обертаючи зброю Палаючого Легіону проти його ж слуг.",h="Чорнокнижники — чарівники, що укладають угоди з темними силами, командують демонами, насилають виснажливі...",kw={"чорнокнижник","демони","ґул'дан","рада тіней","скверна","біс","блукач порожнечі"},ang={["class:Mage"]="Маги дивляться на чорнокнижників із гострою зневагою й страхом, вважаючи їх недисциплінованими чаклунами, чиї нерозважливі оборудки з Нижнім Світом загрожують усьому смертному життю.",["class:Paladin"]="Віддані Святому Світлу вважають виклик демонів мерзенною єрессю й стежать за чорнокнижниками з відкритою ворожістю.",["class:Shaman"]="Шамани понад усе зневажають магію чорнокнижників, пам'ятаючи, як чаклунство Скверни Ґул'дана розірвало зв'язок їхніх предків із духами й убило землю Дренору.",["race:Orc"]="Для орків демонологія несе гірку пляму кривавого прокляття Старої Орди, хоча дехто зберігає ці мистецтва, щоб вижити у ворожому світі."},sec={{t="Заборонені мистецтва",b="Там, де звичайні чарівники бачать зіпсуття й руїну, чорнокнижники бачать можливість. Вони здобувають перемогу розважливою жорстокістю, вражаючи здалеку, огорнуті тінню й вогнем. Висисаючи життєву силу й душі ворогів, чорнокнижники живлять свої найкатастрофічніші обряди, обрушують із неба сірчаний вогонь і ламають розум нестерпними прокльонами. Оскільки вони носять лише просту тканину й мають мало тілесної витривалості, то покладаються на викликаних потвор, що перехоплюють небезпеку, і охоче жертвують демонічними слугами заради власного виживання."},{t="Демонічне служіння",b="Влада чорнокнижника над Викривленим Нижнім Світом починається з дрібних угод і переростає в залізне панування. Новачки вчаться наказувати бешкетним бісам жбурляти полум'я, та що глибше чорнокнижник осягає темряву, то смертоносніших істот він підкоряє: блукачів Порожнечі, вирваних із тіньових глибин, щоб приймати на себе удари, спокусливих сукубів, здатних заморочити розум ворога, і ненажерливих мисливців Скверни, що пожирають магічну енергію. Кожен виклик вимагає небезпечної обрядової зосередженості, бо мешканці Нижнього Світу постійно випробовують своїх господарів, вишукуючи найменшу слабкість."},{t="Спадщина руїни",b="The roots of orcish demonology trace back to Draenor, where the demon lord Kil'jaeden seduced Gul'dan with the promise of supreme power. Gul'dan founded the secretive Shadow Council and transformed many shaman—starting with members of the Blackrock clan—into masters of fel magic. The rampant use of demonic magic withered Draenor's fertile plains into barren red wasteland, heralding the Old Horde's invasion through the Dark Portal. In human lands, the Kirin Tor forbade demonology and hunted down illicit summonings, yet ambitious mages regularly succumbed to the lure of untamed sorcery."},{t="Терпимі вигнанці",b="Нині чорнокнижники ходять лезом бритви між корисністю й стратою. У Стормвінді вони збираються потай у похмурих підвалах таверн, подалі від пильних очей Собору Світла. В Оргріммарі вони гуртуються в затінених ущелинах Тіньової Розколини під наглядом шаманського правління Тралла. Хоча їхні методи викликають огиду, ні Альянс, ні Орда не можуть цілком відмовитися від нищівної переваги, яку магія чорнокнижників дає на ворожому полі бою."}},faq={{q="Чим чорнокнижник відрізняється від мага?",a="Маги спираються на впорядковану будову таємної магії, щоб керувати вогнем, кригою й енергією. Чорнокнижники нехтують безпечними межами й поринають просто в хаотичну магію скверни, тіні й виклик демонів. Багато чорнокнижників починали як маги, яким урвався терпець через академічні обмеження, і вони шукали заборонених коротких шляхів до нездоланної сили.",al={"чорнокнижник проти мага","різниця чорнокнижника і мага","маг чи чорнокнижник"}},{q="Чи всі чорнокнижники злі?",a="Not all warlocks are inherently wicked, but their magic is dangerous and corruptive. While many fall into madness or join demonic cults, player warlocks often pledge their loyalty to their faction, turning dark sorcery, stolen souls, and bound demons against external threats like the Scourge or the Burning Legion.",al={"чи чорнокнижники злі","чи можуть бути добрими","чому альянс дозволяє чорнокнижників"}},{q="Як чорнокнижники викликають демонів і керують ними?",a="Чорнокнижники за допомогою обрядових кіл, темних заклинань і енергії душ витягують створінь із Викривленого Нижнього Світу. Викликаного демона треба зламати й підкорити волі заклинача самою силою розуму. Якщо зосередженість чорнокнижника похитнеться, демон охоче розірве свого господаря.",al={"як працюють улюбленці чорнокнижника","лор виклику демонів","зв'язування демонів"}},{q="Звідки взялися орки-чорнокнижники?",a="Орки-чорнокнижники з'явилися на Дренорі, коли Кіл'джеден змусив Ґул'дана зректися шаманства заради демонічного чаклунства. Ґул'дан заснував Раду Тіней і навчав інших орків, переважно з клану Блекрок, поширюючи скверну рідною землею, доки ґрунт Дренору не зачах і не вмер.",al={"як орки стали чорнокнижниками","ґул'дан чорнокнижники","походження оркської скверної магії"}},{q="Чому Альянс і Орда терплять чорнокнижників у своїх містах?",a="Жодна з фракцій їм по-справжньому не довіряє. У Стормвінді й Айронфорджі чорнокнижники практикують у потаємних підвалах і забутих тунелях, щоб не викликати обурення людей. В Оргріммарі вони відособлені в Тіньовій Розколині. Провідники терплять їх лише тому, що їхні жахливі прокляття й виклики — безперечно дієва зброя на війні.",al={"чому чорнокнижників дозволяють","чи чорнокнижники легальні","законність чорнокнижників"}},{q="Для чого потрібні уламки душ?",a="Чорнокнижники висмоктують живу сутність переможених ворогів, щоб кристалізувати її в уламки душ. Ці уламки слугують потужними накопичувачами: вони дають сиру енергію, потрібну, щоб обходити природні закони магії, викликати жахливих демонів і творити найруйнівніші закляття.",al={"навіщо уламки душ","лор уламків душ","збір душ"}}},fp="7,344,14.561.0,17.550.0,16.595.0,17.488.0,43.338.0,22.315.0,42.296.0,33.299.0,64.328.0,30.265.0"}
P.entries["topic:warrior"] = {n="Воїн",s="Воїни — справжні бійці передової Азероту, що опанували важкі латні обладунки, щити й майже кожен вид зброї. Живлячи свої найнищівніші удари чистою бойовою люттю, вони кидаються в саму гущу бою, щоб захистити слабших союзників чи прорубатися крізь ворожі лави. Їх можна зустріти серед кожної раси й цивілізації — від стійких міських вартових і королівських поборників до мандрівних найманців.",h="Воїни — справжні бійці передової Азероту, що опанували важкі латні обладунки, щити й майже кожен вид зброї.",kw={"воїн","воїни","лють","лати","щит","передова","братство коня"},ang={["class:Warrior"]="Кожен бій випробовує вашу витривалість і нерви; обертаючи біль від ударів на чисту лють, ви тримаєте передову у своїх руках.",["faction:Alliance"]="Піхотинці й лицарі Альянсу становлять оборонний авангард, що захищає людські королівства, гірські твердині дворфів і ельфійські ліси.",["faction:Horde"]="Для Орди бойова майстерність — спосіб життя: штурмові загони орків-рубак і воїни-таурени очолюють кожен наступ на нові землі.",["profession:Blacksmithing"]="Воїни цілком залежать від ковалів, які викувують важкі лати, міцні щити й гостро заточені клинки, без яких у смертельному бою не вижити."},sec={{t="Майстри сталі й щита",b="Воїни не покладаються ні на божественні молитви, ні на таємні заклинання. Їхня сила — цілком у тілесній витривалості, бойовій дисципліні й досконалому володінні зброєю. Закуті в найважчі лати, вони диктують умови на передовій. Одні б'ються за височенними щитами, витримуючи нищівні удари й відводячи небезпеку від чарівників і лучників. Інші виходять уперед із дворучною древковою зброєю, сокирами й великими мечами або кидаються в ближній бій із клинком у кожній руці, щоб розтинати цілі шеренги."},{t="Сила бойової люті",b="У горнилі бою біль і кров розпалюють внутрішній вогонь воїна. Ця сила, яку просто називають люттю, наростає, коли воїни завдають і приймають удари. Замість піддаватися втомі чи кровотечі, досвідчені бійці спрямовують цю бойову лють у трощильні удари, вихори сталі та громові бойові вигуки, що підбадьорюють товаришів поруч і ламають дух ворога."},{t="Загальна традиція",b="На відміну від класів, пов'язаних із певною вірою чи покровителями-стихіями, традиція воїна властива кожній расі Азероту. Стормвінд покладається на дисциплінованих лицарів-поборників Братства Коня, Айронфордж виставляє свою кремезну Ковальську Варту, а Орда згуртовується довкола орочих майстрів клинка, тауренських хоробрих і вартових смерті Відступників. Ведені честю, захистом рідної землі чи холодною монетою, ті, хто відгукується на заклик до зброї, становлять незламний хребет кожного постійного війська."}},faq={{q="Що дає силу воїнові, якщо він не користується магією?",a="Воїни покладаються на бойову майстерність, тактичну виучку й лють. Лють накопичується просто в сутичці — і від ударів по ворогах, і від ударів, яких зазнає сам воїн. Цей бойовий запал живить їхні найнищівніші прийоми: широкі удари зброєю, приголомшливі удари щитом і залякувальні вигуки.",al={"як воюють воїни","ресурс воїна","що таке лють"}},{q="Які раси можуть стати воїнами?",a="Воїном може бути представник будь-якої ігрової раси Азероту. Важкоброньовані бійці передової потрібні всім смертним культурам — від незворушних дворфійських захисників Каз Модану до лютих орківських штурмовиків Дуротару.",al={"хто може бути воїном","раси воїнів","чи будь-яка раса може бути воїном"}},{q="Яку роль воїни відіграють у загоні?",a="Зазвичай воїни йдуть попереду. Стійкі воїни-захисники зі щитами й у латах приймають удари на себе й тримають небезпечних ворогів зосередженими на собі. Наступальні воїни, що спеціалізуються на зброї чи люті, натомість орудують важкою дворучною зброєю чи парними клинками, долаючи ворогів жорсткою фізичною шкодою.",al={"роль воїна","чи воїни танкують","зброя проти люті проти захисту"}},{q="Якою зброєю можуть орудувати воїни?",a="Воїни — майстри майже всієї зброї, відомої смертним. Вони можуть орудувати мечами, булавами, сокирами, древковою зброєю, кинджалами й посохами — однією чи двома руками, — а також важкими щитами й зброєю дальнього бою: луками, рушницями й арбалетами.",al={"зброя воїнів","чи воїни можуть луки","чим озброєні воїни"}},{q="Хто зі славетних воїнів відомий в історії Азероту?",a="Серед знаних воїнів — Лорд Андуїн Лотар, Поборник Стормвінда й Верховний Командувач Альянсу Лордерона; Громмаш Хеллскрім, вождь клану Бойової Пісні; і Кайрн Бладгуф, Верховний Вождь об'єднаних племен тауренів.",al={"відомі воїни","легендарні воїни","герої-воїни"}},{q="Де нові воїни проходять навчання?",a="Воїни навчаються скрізь, де збираються вояки. Людські новобранці муштруються в Абатстві Нортшира, дворфи й гноми вчаться в Анвілмарі в Долині Холодного Хребта, нічні ельфи тренуються в Тінедолі, орки й тролі — у Долині Випробувань, а бійці-Відступники приходять до казарм Похоронного Подзвону.",al={"наставники воїнів","де вчаться воїни","місця наставників воїнів"}}},fp="7,443,27.512.0,24.411.0,21.484.0,47.318.0,31.224.0,46.303.0,40.252.0,50.241.0,52.280.0"}
P.entries["topic:warsong-clan"] = {n="Клан Пісні Війни",s="Клан Пісні Війни — одна з найлютіших і найлегендарніших бойових сил серед орків, яку колись очолював шанований вождь Ґроммаш Хеллскрім. Переживши вигнання, табори інтернування й демонічне зіпсуття, клан нині діє переважно в Ашенвалі як Дозорці Пісні Війни, запекло добуваючи деревину для молодої Орди й безперестанку б'ючись із нічними ельфами.",h="Клан Пісні Війни — одна з найлютіших і найлегендарніших бойових сил серед орків, яку колись очолював...",kw={"клан пісні війни","ґроммаш хеллскрім","дозорці пісні війни","ашенваль","маннорот","ущелина бойової пісні","кенарій"},ang={["faction:Alliance"]="Клан Пісні Війни уособлює невгамовну войовничість орків і для багатьох в Альянсі доводить: миру між фракціями не бути, доки їхні сокири рубають Ашенваль.",["faction:Horde"]="Без деревини, яку заготовляють Дозорці Пісні Війни в Ашенвалі, Нова Орда не мала б матеріалу, щоб укріплювати поселення й розширювати свої володіння в Калімдорі.",["race:NightElf"]="Нічні ельфи люто ненавидять клан Пісні Війни — не лише за вирубування священних лісів Ашенвалю, а й за непрощенне вбивство напівбога Кенарія.",["race:Orc"]="Клан Пісні Війни — водночас найбільша ганьба й найвища спокута орочого народу: він першим випив кров Маннорота, але саме його вождь загинув, щоб зламати владу демона над усіма орками."},sec={{t="Спадщина непокори",b="Задовго до переходу на Азерот клан Пісні Війни здобув славу на відкритих рівнинах Дренору завдяки рухливій тактиці вовчих вершників, трощачи імперії огрів самою лише завзятістю. Їхню буйну вдачу так боялися, що Вождь Блекгенд залишив їх у тилу під час Першої війни, щоб уникнути непередбачуваних нестримних нападів. Нарешті вони ринули крізь Темний Портал під проводом Ґроммаша Хеллскріма вже після Другої війни — і опинилися відрізаними на Азероті, коли Дренор загинув. Поки інші орки чахли в таборах інтернування Альянсу, клан Пісні Війни уникав полону, блукав дикими краями й тримався свого войовничого духу, доки Тралл не об'єднався з Хеллскрімом, щоб викувати Нову Орду."},{t="Кров і спокута",b="Прибувши до Калімдору під час Третьої війни, Тралл послав Хеллскріма та його клан до Ашенвалю заготовляти деревину й заснувати заставу. Це вторгнення розлютило нічних ельфів і лісового напівбога Кенарія. Опинившись на межі розгрому, воїни Пісні Війни знову скорилися демонічній крові володаря безодні Маннорота, щоб перемогти, і в шаленстві зіпсуття Скверною вбили Кенарія. Траллові та його союзникам вдалося очистити Хеллскріма від прокляття, і все завершилося доленосним двобоєм, у якому Ґром віддав життя, щоб знищити Маннорота. Його героїчна жертва назавжди зламала прокляття демонічної крові й закарбувала місце клану Пісні Війни в історії Орди."},{t="Війна за Ашенваль",b="Нині клан продовжує справу Ґроммаша під стягом Дозорців Пісні Війни. Із твердинь на кшталт Застави Розщепленого Дерева й діяльних лісорубних таборів вони заготовляють деревину, конче потрібну для розбудови молодої держави Орди в посушливих пустищах Дуротару. Їхня присутність розпалила запеклу війну за землю з Вартовими Срібнокрилих нічних ельфів. Ведені завзяттям предків, воїни Пісні Війни й не думають поступатися Ущелиною Бойової Пісні й врізаються все глибше в прадавній ліс попри нескінченні засідки."}},faq={{q="Хто зараз очолює клан Пісні Війни?",a="Після загибелі Громмаша Хеллскріма наприкінці Третьої війни клан Пісні Війни здебільшого влився в Нову Орду Тралла. Його бойові сили, зокрема Дозорці Пісні Війни в Ашенвалі, підкоряються місцевим командирам і загальній владі Вождя Тралла.",al={"лідер бойової пісні","хто вождь бойової пісні","нинішній вождь бойової пісні"}},{q="Чому клан Пісні Війни рубає ліс в Ашенвалі?",a="Нова Орда живе на посушливих рівнинах Дуротару й Пусток, де немає доброї деревини. Клан Пісні Війни послали в багаті ліси Ашенвалю по деревину, необхідну для будівництва міст, як-от Оргріммар, утримання військових укріплень і зростання Орди.",al={"чому рубають ашенвейл","лісозаготівля бойової пісні","орки рубають дерева в ашенвейлі"}},{q="Як клан Пісні Війни вбив Кенарія?",a="Під час Третьої війни напівбог Кенарій повів нічних ельфів у жорстоку оборону Ашенвалю, довівши клан Пісні Війни до відчаю. Клан напився з озерця, отруєного кров'ю володаря безодні Маннорота, і перетворився на орків скверни, чия посилена лють виявилася досить могутньою, щоб здолати й убити Кенарія.",al={"смерть кенарія","хто вбив кенарія","бойова пісня проти кенарія"}},{q="Як клан Пісні Війни уникнув таборів для інтернованих після Другої війни?",a="На відміну від багатьох орківських кланів, яких полонили наприкінці Другої війни, Громмаш Хеллскрім і клан Пісні Війни уникли полону Альянсу, переховуючись у віддаленій глушині Лордерона. Вони вели партизанську війну й зберегли бойовий дух, доки їх не знайшов Тралл.",al={"табори інтернованих бойова пісня","ґром ухилився","втеча бойової пісні"}},{q="Що таке Ущелина Бойової Пісні?",a="Ущелина Бойової Пісні — каньйон на півдні Ашенвалю, де Дозорці Пісні Війни б'ються з Вартовими Срібнокрилих нічних ельфів. Дозорці борються за свою лісозаготівлю, а Вартові — за те, щоб цілком вигнати орків зі своїх священних лісів.",al={"лор ущелини бойової пісні","що таке ущелина бойової пісні","поле бою бойової пісні"}},{q="Хто такий Громмаш Хеллскрім?",a="Громмаш «Гром» Хеллскрім — легендарний вождь клану Пісні Війни й наставник Тралла. Хоча він першим з орків випив демонічної крові на Дренорі, зрештою він спокутував провину й звільнив усіх орків від демонічного рабства, убивши володаря безодні Маннорота ціною власного життя.",al={"хто такий ґром","ґром хеллскрім","ґроммаш"}}},fp="12,388,20.671.0,20.640.0,21.514.0,37.296.0,41.302.0,34.309.0,69.267.0,22.281.0,28.303.0"}
P.entries["topic:westfall-brigade"] = {n="Народне ополчення",s="Народне ополчення — низова сила самооборони, яку заснував Ґраян Стаутмантл, щоб захистити жителів Вестфолу від Братства Дефіас. Ці добровольці, що діють із Сентінел Гілла, стоять самі, відколи Стормвінд вивів свої війська з Вестфолу. Вони покладаються на місцевих фермерів і заїжджих шукачів пригод, щоб утримувати рубежі проти розгулу розбою.",h="Народне ополчення — низова сила самооборони, яку заснував Ґраян Стаутмантл, щоб захистити жителів Вестфолу...",kw={"народне ополчення","ґраян стаутмантл","сентінел гілл","вежа вартових","братство дефіас","едвін венкліф","вестфол"},ang={["class:Warrior"]="Ґраян Стаутмантл і його захисники — втілення практичного проводу на передовій: вони обходяться пощербленими клинками й саморобними обладунками, стримуючи значно сильнішого ворога.",["faction:Alliance"]="Криза у Вестфолі оголює небезпечні тріщини в королівстві й показує героям Альянсу, наскільки крихкий мир навіть у серцевинних землях.",["race:Human"]="Ополчення показує твердість і відчай сільського люду Стормвінда, що змушений сам боронити свої домівки, коли королівський двір відводить очі."},sec={{t="Покинутий край",b="Колись Вестфол був житницею Королівства Стормвінд, але Стормвінд вивів звідти війська й залишив людей беззахисними. У цю порожнечу ринули розбійники Братства Дефіас у масках: вони захоплювали родинні садиби, прибирали до рук залізні копальні й обкладали даниною місцевих фермерів. Перед лицем беззаконня й не бачачи жодних ознак королівського підкріплення, досвідчений воїн Ґраян Стаутмантл згуртував місцевих жителів і відставних солдатів у Народне ополчення."},{t="Утримати Сентінел Гілл",b="Ополчення, що базується у Вежі Вартових на вершині Сентінел Гілла, тримає хиткий периметр уздовж головних шляхів краю. Без професійного військового спорядження й сталого постачання його захисники патрулюють курні дороги, а Стаутмантл скеровує добровольців проріджувати дедалі численніші лави грабіжників, злодіїв і мародерів Дефіасу. Коли сусідні краї на кшталт Редріджу благають про взаємодопомогу, Ополчення мусить відмовити: віддати навіть жменьку людей означало б цілковиту загибель Вестфолу."},{t="Викриття змови",b="Завдяки невтомній розвідці й допомозі ззовні Ополчення з'ясовує справжній розмах загрози Дефіасу. Братство — не прості сільські розбійники: ним керує Едвін Венкліф, колишній майстер Гільдії Каменярів, що відбудувала Стормвінд. Діючи з підземних глибин Мертвих Копалень під Мунбруком, Братство прагне повалити саме королівство, і знесилене Ополчення лишається єдиною стіною між столицею й відкритим заколотом."}},faq={{q="Чому Народне ополчення воює саме, без армії Стормвінда?",a="Стормвінд вивів свої війська з Вестфолу й лишив людей беззахисними — а чому, сільським мешканцям так ніхто й не пояснив. Після того як край покинули напризволяще, Ґраян Стаутмантл зібрав Народне ополчення, щоб урятувати те, що від нього лишилося.",al={"чому ополчення без армії стормвінда","де армія стормвінда","чому вестфолл покинуто"}},{q="Хто очолює Народне ополчення?",a="Ґраян Стаутмантл, досвідчений ветеран-людина, заснував ополчення й керує ним із Вежі Вартових на Сентінел Гіллі.",al={"лідер народного ополчення","хто веде ополчення","роль ґріана стаутмантла"}},{q="Де їхній штаб?",a="Вони діють із Сентінел Гілла, довкола високої кам'яної сторожової вежі в серці Вестфолу.",al={"база ополчення","де сентінел гілл","штаб вестфоллського ополчення"}},{q="Чи може ополчення допомогти іншим неспокійним краям, як-от Редріджу?",a="Ні. Коли Магістрат Соломон із Лейкшира попросив військових резервів, Стаутмантл мусив відмовити, бо ополчення ледве тримається проти Дефіас.",al={"чому не допоможуть лейкширу","прохання соломона стаутмантл"}},{q="Хто головний ворог ополчення?",a="Їхній головний супротивник — Братство Дефіас, величезний злочинний синдикат колишніх каменярів, розбійників і грабіжників із великої дороги на чолі з Едвіном Венкліфом.",al={"з ким воює ополчення","ворог ополчення","ворог дефіас"}}},fp="16,356,18.467.0,21.498.0,25.469.1,68.244.0,31.112.0,36.102.0,58.173.0,41.140.1"}
P.entries["topic:wildhammer-clan"] = {n="Клан Вайлдгаммер",s="Клан Вайлдгаммер — суворе, наближене до природи відгалуження дворфійського народу, що славиться приборканням диких грифонів і молотами, зарядженими силою бурі. Століття тому вигнані зі своєї родової фортеці Ґрім Батол, вони вибороли собі незалежну домівку серед лісистих вершин Пригір'я. Хоча за вдачею вони відлюдні, але лишаються вірними друзями Альянсу й боронять небо щоразу, коли їх кличуть.",h="Клан Вайлдгаммер — суворе, наближене до природи відгалуження дворфійського народу, що славиться приборканням...",kw={"вайлдгаммери","клан вайлдгаммер","грифони","орлиний пік","пригір'я","ґрім батол","курдран вайлдгаммер"},ang={["class:Hunter"]="Зв'язок горян Вайлдгаммерів зі своїми дикими грифонами — вершина приборкання звірів, що тримається на довічному партнерстві, а не на простому пануванні.",["class:Shaman"]="Традиція Вайлдгаммерів спрямовує дику енергію бурі крізь містичні молоти й зберігає зв'язок зі стихійною блискавкою та природою, значно давніший за сучасні церковні традиції Айронфорджа.",["faction:Alliance"]="Альянс значною мірою завдячує своєю перевагою в повітрі Вайлдгаммерам, чиї вершники на грифонах, сповнені сили блискавки, переломили хід боротьби з червоними драконами Орди в Другій війні.",["race:Dwarf"]="Для дворфа з Айронфорджа Вайлдгаммери — родичі, пов'язані давніми присягами. Хоч вони й віддають перевагу вітряним кручам і відкритому небу над глибокими копальнями, їхня відвага з молотом бурі викликає найглибшу повагу."},sec={{t="Вигнання з Ґрім Батолу",b="До Війни Трьох Молотів Вайлдгаммери жили в передгір'ях довкола Айронфорджа. Коли помер Верховний Король Модімус Анвілмар, громадянська війна розколола дворфійське королівство, і переможці Бронзбірди забрали Айронфордж собі. Тан Кардрос повів свій клан на північ і заснував величну твердиню всередині вершини Ґрім Батол. Та мир тривав недовго: переможені дворфи Темного Заліза невдовзі взяли фортецю в облогу. Хоча Кардрос власноруч убив чаклунку Темного Заліза Модґуд, її передсмертне прокляття так глибоко отруїло гору, що зали стали непридатними для життя. Відкинувши запрошення повернутися під владу Бронзбірдів, Вайлдгаммери обрали самостійність і рушили на північ, у ліси й скелясті кручі Пригір'я."},{t="Вершники бурі",b="На пишних нагір'ях свого нового краю Вайлдгаммери збудували Орлиний Пік. На відміну від своїх підземних родичів, ці дворфи полюбили відкрите небо й живий камінь і виплекали глибоку духовну спорідненість із місцевими грифонами. Викуваючи в усамітнених пташниках зачаровані молоти бурі, Вайлдгаммери стали найкращою повітряною кіннотою Азероту. Під час Другої війни, коли Вождь Оргрім Думхаммер рушив своїми силами до Кель'Таласу й напав на Орлиний Пік, на допомогу прийшли Верховний Головнокомандувач Андуїн Лотар і Альянс. На знак вдячності Верховний Тан Курдран Вайлдгаммер віддав своїх вершників на грифонах союзові, і вони билися в повітрі з поневоленими червоними драконами Орди над Лордероном і Великим Морем."},{t="Вірні до кінця",b="Коли Темний Портал відчинився знову, Курдран Вайлдгаммер повів своїх вершників на Дренор разом з Експедицією Альянсу й пожертвував поверненням додому, щоб запечатати розлам, — цей вчинок увічнює велетенська статуя в Долині Героїв Стормвінда. В Орлиному Піку клан очолив Верховний Тан Фалстад. Навіть коли згодом людські королівства сварилися й розколювалися, Вайлдгаммери лишалися вірними союзниками короля Теренаса Менетіла II. Коли в Третю війну Погибель пронеслася Лордероном, летуни Вайлдгаммерів знову злетіли в небо й відчайдушно билися, захищаючи землі союзників і невинних біженців від ходячих мерців."}},faq={{q="Де зараз осідок клану Вайлдгаммер?",a="Їхній головний оплот — Орлиний Пік у гірських лісах Пригір'я, на північ від Багнокраю й Мосту Тандол.",al={"дім вайлдгаммерів","де живуть вайлдгаммери","місцезнаходження вайлдгаммерів"}},{q="Чому Вайлдгаммери не живуть в Айронфорджі?",a="Після смерті Верховного Короля Модімуса Анвілмара клан Вайлдгаммер програв Бронзбірдам громадянську війну за владу в Айронфорджі. Тан Хардрос повів свій клан на північ, щоб почати нове життя в Ґрім Батолі, а не схилятися перед владою Бронзбірдів.",al={"чому вайлдгаммери покинули айронфордж","війна трьох молотів вайлдгаммери"}},{q="Що сталося з їхньою фортецею в Ґрім Батолі?",a="Під час Війни Трьох Молотів чаклунка Темного Заліза Модґуд узяла Ґрім Батол в облогу. Тан Хардрос убив її, але її темні чари отруїли зали мерзенним спотворенням, і гора стала зовсім непридатною для життя, тож клан мусив перебратися в Пригір'я.",al={"чому ґрім батол покинуто","прокляття ґрім батола","модґуд ґрім батол"}},{q="Хто сьогодні очолює клан Вайлдгаммер?",a="Клан очолює Верховний Тан Фалстад Вайлдгаммер з Орлиного Піку. Він перебрав провід після того, як його попередник, Курдран Вайлдгаммер, приєднався до Експедиції Альянсу крізь Темний Портал.",al={"лідер вайлдгаммерів","верховний тан вайлдгаммерів","хто править орлиним піком"}},{q="Як Вайлдгаммери приєдналися до Альянсу?",a="Під час Другої війни Оргрім Думхаммер напав на Пригір'я, ідучи на Кель'Талас. Верховний Командувач Андуїн Лотар повів Альянс на захист Орлиного Піку й відкинув Орду та лісових тролів. Зворушені їхньою хоробрістю, Вайлдгаммери приєдналися до Альянсу Лордерона.",al={"чому вайлдгаммери в альянсі","історія альянсу вайлдгаммерів"}},{q="Чи дворфи Вайлдгаммер у тісному союзі з Айронфорджем?",a="Так. Хоча два клани воювали між собою у Війні Трьох Молотів, вони об'єдналися, щоб здолати Темне Залізо. На знак дружби вони звели Долину Королів у Лох Модані й відтоді зберігають міцний союз.",al={"стосунки бронзбірдів і вайлдгаммерів","чи ладнають айронфордж і вайлдгаммери"}}},fp="15,408,21.732.0,19.709.0,16.624.0,45.134.0,44.240.0,46.268.0,36.176.0,42.286.0,57.238.0"}
P.entries["zone:alterac"] = {n="Гори Альтерак",s="Гори Альтерак — холодне, поруйноване високогір'я в центрі Лордерону. Колись тут лежали підступне людське королівство Альтерак і вчена магократія Даларан. Нині засніжені кручі заполонили огри Трощихребтів, аристократи-розбійники із Синдикату та рештки чародійських сил. Мандрівники вирушають сюди з поселень у передгір'ях і з Даларану, що постає з руїн.",h="Гори Альтерак — холодне, поруйноване високогір'я в центрі Лордерону.",kw={"гори альтерак","даларан","синдикат","огри","кірін-тор","долина альтерак","руїни альтераку"},ang={["class:Mage"]="Вулиці Даларану, що відбудовується, гудуть від залишкових потоків таємної магії й метушні магів Кірін-Тору. Прийти сюди — це урочисте паломництво до спустошеного серця людського чародійства.",["class:Rogue"]="У прихованій долині на східних кручах Альтераку тулиться Маєток Рейвенголдт. Під пильним оком Лорда Джораха Рейвенголдта тут дають елітні замовлення, навчають зламувати замки й відкривають таємниці гільдії.",["faction:Alliance"]="Мандрівникам Альянсу доводиться протистояти ограм Трощихребтів і розбійникам Синдикату, що захопили колишнє королівство.",["faction:Horde"]="Клан Морозного Вовка облаштував собі дім у відлюдних горах, а агенти Відступників із Таррен Мілла дають відсіч ограм і розбійникам Синдикату.",["profession:Herbalism"]="Морозні кручі Альтераку славляться серед травників як єдине місце, де в природі росте Зимокус — незамінна складова сильних зігрівальних настоїв."},sec={{t="Занепале королівство",b="Під час Другої війни Альтерак був одним із Семи Королівств людства, але король Ейден Перенольд зрадив Альянс Лордерону й перейшов на бік Старої Орди, сподіваючись уберегти свою державу. Його зраду викрили й придушили, а країна розпалася на спірні прикордонні землі. Після розпаду королівства й жахіть Третьої війни величну кам'яну столицю Альтераку обернули на руїни. Нині Руїни Альтераку займають жорстокі огри Трощихребтів на чолі з Муґ'толом, а вцілілі людські вельможі згуртувалися в Синдикат — люту злочинну спілку, що силою намагається повернути собі втрачені маєтки."},{t="Місто, що постає з руїн",b="На західному краю гір, на березі Озера Лордамер, лежить те, що лишилося від великого міста-держави Кірін-Тору — Даларану. Коли під час Третьої війни його спустошив володар демонів Архімонд, уцілілі маги звели над руїнами величезний непрозорий фіолетовий купол захисної магії. У Forever щит уже зняли, але місто досі відбудовується. Кірін-Тор і далі відновлює свою твердиню, а Верховного Мага Ансірема Рунотвора можна знайти у Фіолетовій Цитаделі."},{t="Рубежі протистояння",b="Шукачі пригод часто вирушають у гори з Саутшора чи Таррен Мілла. Окрім мандрівних єті, гірських левів і грабіжників Синдикату, тут є й значно більша війна — вона вирує серед снігів. Глибоко між гірськими перевалами лежить Долина Альтерак, де дворфійська Варта Стормпайків здавна б'ється з відлюдним орочим кланом Морозного Вовка за давнє право на землю й копальні."}},faq={{q="Що сталося з Королівством Альтерак?",a="Під час Другої війни король Ейден Перенольд зрадив Альянс, щоб допомогти Орді. Лордерон і Стромґард придушили зраду й окупували край. Коли Погибель у Третій війні пронеслася Лордероном, рештки Альтераку поринули в безвладдя, а зруйнована столиця дісталася ограм-Трощихребтам.",al={"чому альтерак зруйновано","що сталося з перенольдом","лор королівства альтерак"}},{q="Хто такі Синдикат?",a="Синдикат — розбійницька організація, яку створила знать Альтераку, що втратила свої володіння. На чолі з колишніми альтеракськими вельможами, як-от Лорд Аліден Перенольд, вони наймають головорізів, грабіжників із великої дороги й зганьблених лордів, щоб тероризувати довколишні землі й виганяти суперників, у відчайдушній спробі повернути землі предків.",al={"хто такий синдикат","чому в альтераку бандити","лор синдикату"}},{q="Що сталося із сяйливим куполом Даларану?",a="Після того як Архімонд спустошив Даларан під час Третьої війни, Кірін-Тор, що вцілів, підняв над руїнами захисний магічний щит. У Forever щит зняли раніше, ще поки місто відбудовують. Верховний Маг Ансірем Рунотвор нині стоїть у Фіолетовій Цитаделі.",al={"фіолетовий купол альтерак","що фіолетова бульбашка","щит даларана"}},{q="Де в Альтераку знайти шляхи польотів чи безпечні заїзди?",a="Звичні бази для походів у засніжені вершини — Саутшор і Таррен Мілл у Передгір'ях Гілсбреда. Даларан на західному краю у Forever відкритий для відвідин, поки Кірін-Тор його відбудовує.",al={"шляхи польоту альтерак","корчма альтерак","осередок завдань альтерак"}},{q="Що таке Долина Альтерак?",a="Долина Альтерак — відлюдна засніжена долина, за яку змагаються дворфи з Варти Стормпайків і орки клану Морозного Вовка. Стормпайки прибули з археологічною експедицією, що розпалила повномасштабну війну за землю з Морозними Вовками, які мирно жили в долині від свого вигнання ще за Першої війни.",al={"вхід в ав","фроствулф проти сторміке","де альтеракська долина"}},{q="Що таке Маєток Рейвенголдт?",a="Схований у відлюдній гірській складці на схід від головної дороги, Маєток Рейвенголдт — таємна гільдійна зала Ліги Вбивць. Під проводом Лорда Джораха Рейвенголдта він слугує місцем навчання й прихистком для вправних розбійників з усього Азероту.",al={"де рейвенголдт","маєток убивць альтерак","гільдія злодіїв альтерак"}}},fp="17,388,18.642.0,19.516.0,21.407.0,40.308.0,22.320.0,40.276.0,54.206.0,23.309.0,25.249.0"}
P.entries["zone:arathi"] = {n="Аратійське нагір'я",s="Аратійське нагір'я — суворе плато на південному сході Лордерону, відоме як давня колиска Імперії Аратор. Нині королівство Стромґард лежить у руїнах, а скелястий край охопила війна на кількох фронтах: рештки Стромґарду, Орда, вельможі-злочинці із Синдикату й огри-загарбники б'ються тут усі проти всіх.",h="Аратійське нагір'я — суворе плато на південному сході Лордерону, відоме як давня колиска Імперії Аратор.",kw={"аратійське нагір'я","стромґард","аратор","гаммерфолл","синдикат","притулок","троллбейн"},ang={["class:Warrior"]="Стромґард виплекав найславетнішу бойову традицію Азероту, тож його суворі поля битв — шановане випробування зброєю.",["faction:Horde"]="Гаммерфолл — священна земля для сучасної Орди, пам'ятник жертві Оргріма Думхаммера, що визволила поневолений народ із таборів.",["profession:Mining"]="Скелясті хребти нагір'я багаті на залізо й мітрил, а Ущелина Сухих Вусів — єдине відоме джерело руди малого кривавого каменю.",["race:Human"]="Кожне людське королівство веде свій родовід від Імперії Аратор. Бачити колиску людської цивілізації зруйнованою, захопленою ограми й злодіями, — глибока трагедія для вашого народу."},sec={{t="Колиска людства",b="Тисячоліття тому король Торадін об'єднав розрізнені людські племена під стягом араті й звів на цих сухих, зручних для оборони рівнинах величну столицю Стром. Саме тут під час Тролячих воєн людство уклало легендарний союз із високими ельфами й опанувало таємну магію, щоб відкинути Амані. З часом шляхетні роди переселилися на північ, до Лордерону, і на південь, до Стормвінда, але імперська гвардія лишилася й заснувала войовниче королівство Стромґард. Віками Стромґард був оплотом стійких воїнів, які стримували лісових тролів."},{t="Розтрощене королівство",b="За короля Тораса Троллбейна Стромґард відіграв ключову роль в обороні Альянсу під час Другої війни, але Третя війна та її наслідки зламали країну. Хоч королівство й уникло найгіршого лиха від чуми Погибелі, загадкова смерть короля Тораса кинула державу в розбрат. З пагорбів налетіли огри Каменекулаків, а зрадливі альтеракські вельможі із Синдикату захопили чималі квартали Фортеці Стромгард. Нині Принц Ґален Троллбейн і вірні йому вцілілі тримаються за крихітний клаптик міста й за свою твердиню в Притулку, ведучи запеклу партизанську війну, хоч надії майже немає."},{t="Війна за нагір'я",b="Нагір'я — запекло оспорюване перехрестя. На північному сході Орда перетворила покинутий людьми табір ув'язнення на Гаммерфолл, названий на честь легендарного Вождя Оргріма Думхаммера, і тримає його як опору своїх північних володінь і захист для союзників у Гілсбреді. Тим часом плем'я тролів Сухокорих прагне помститися давнім людським гнобителям, а Слід Аргуса потай смикає за ниточки, керуючи окупацією Синдикату. У самому серці плато стоять прадавні Кола Скування, де скуті елементалі стримують загадкову давню силу, поховану під камінням."}},faq={{q="Що сталося з Фортецею Стромгард?",a="Після смерті короля Тораса Троллбейна Стромґард потонув у внутрішніх чварах і нищівних нападах. Огри-Каменекулаки захопили зовнішні квартали міста, а Синдикат, скориставшись нагодою, заволодів святилищем, тож Принц Ґален Троллбейн і його поріділий гарнізон тримаються за один укріплений куток, ведучи відчайдушні бої у власній столиці.",al={"чому стромґард у руїнах","хто контролює стромґард","статус стромґарду"}},{q="Що таке Гаммерфолл?",a="Гаммерфолл — укріплена застава Орди, зведена на рештках людського табору, де після Другої війни тримали орків. Її назвали на честь колишнього Вождя Оргріма Думхаммера, що загинув, ведучи похід за визволення полонених із таборів Лордерона.",al={"база орди араті","історія гаммерфолла","чому гаммерфолл"}},{q="Де діє Альянс в Араті?",a="Вояки Альянсу й захисники Стромґарда діють із Притулку — природно укріпленого каньйону в центрі нагір'я. Звідси вони роблять вилазки, щоб відвоювати Фортецю Стромгард і відбивати наступ огрів і тролів.",al={"база альянсу араті","притулок","де люди стромґарду"}},{q="Що це за кам'яні кола на рівнинах?",a="Кола Скування — Внутрішнє, Зовнішнє, Східне й Західне — прадавні магічні печаті, які підтримують і стережуть непокірні елементалі. Вони тримають ув'язненою невідому первісну сутність, поховану глибоко під нагір'ям.",al={"кола зв'язування","елементалі араті","кам'яні кола"}},{q="Як дістатися до Аратійського нагір'я?",a="Мандрівники з півночі й заходу проходять крізь пролом у Мурі Торадіна з Передгір'їв Гілсбреда. Ті, хто йде з Каз Модану на півдні, перетинають величезний дворфійський Міст Тандол, перекинутий над проваллям, що відділяє нагір'я від Багнокраю.",al={"дістатися до араті","як потрапити в аратійське нагір'я","вхід в араті"}},{q="Що робить Синдикат в Араті?",a="Синдикат — це вигнана знать Альтераку, що прагне вибороти собі нові володіння, грабуючи занепалі королівства. В Араті вони захопили великі частини Фортеці Стромгард і віддалені ферми, як-от Маєток Нортфолд, а потай ними керують темні культисти Пробудження Арґуса.",al={"чому синдикат в араті","синдикат стромґард","хто веде синдикат тут"}}},fp="16,328,18.594.0,19.625.0,25.593.1,33.371.0,19.278.0,42.251.0,45.213.0,38.274.0,38.271.1"}
P.entries["zone:azshara"] = {n="Азшара",s="Азшара — скелясте, обвітрене узбережжя на північному сході Калімдору, вбране в яскраве листя вічної осені. Колись тут була славетна столиця нічних ельфів, та Великий Розкол обрушив її в море. Нині це небезпечний дикий край, усіяний давніми руїнами, де чатують похмурі наги й живуть відлюдні чародії. І Орда, і Альянс тримають на його межах хиткі застави, остерігаючись неспокійних привидів і морських жахіть, що ховаються в глибині краю.",h="Азшара — скелясте, обвітрене узбережжя на північному сході Калімдору, вбране в яскраве листя вічної осені.",kw={"азшара","калдореї","Високородні","наги","зін-азшарі","ксилем","великий розкол"},ang={["class:Mage"]="Розтрощене каміння Ельдарату досі потріскує від забутого чаклунства Високородних, а високо над кручами відлюдний Архімаг Ксилем випробовує тих, хто прагне опанувати таємну магію телепортації й чародійства.",["profession:Herbalism"]="Вічна осінь Азшари живить рідкісні й сильні трави: серед руїн тут ростуть Снолист, Золотий Сансам, Гірський Срібношавлій і Фіолетовий Лотос.",["profession:Mining"]="Стрімкі прибережні кручі й зубчасті хребти Азшари багаті на цінні рудні жили: тут чимало покладів мітрилу, справжнього срібла й торію.",["race:NightElf"]="Кожна затоплена колона й кожна стогнуча тінь Високородних в Азшарі — похмуре, моторошне свідчення безрозсудної пихи королеви Азшари й катастрофічної загибелі давньої цивілізації калдореїв."},sec={{t="Потоплена імперія",b="Десять тисяч років тому це узбережжя було живим серцем цивілізації калдореїв, що оточувало королівську столицю Зін-Азшарі. Коли королева Азшара та її двір Високородних закликали в Азерот Палаючий Легіон, спалахнула Війна Прадавніх, яка скінчилася катастрофічним обвалом Колодязя Вічності. Море ринуло на сушу й поглинуло більшу частину величного міста, лишивши по собі розколоті кручі, підступні коралові рифи й затоплені шпилі. Уцілілі назвали спустошений край на честь своєї загиблої володарки, затаврувавши його як проклятий пам'ятник гордині й страшній зраді."},{t="Осіння пишнота й приховані загрози",b="Азшара славиться приголомшливим багряним, помаранчевим і золотим листям: здається, тут панує вічна осінь, якої не змінюють пори року. Та під цим спокійним покровом лежить негостинний край. Зіпсовані сатири правлять темні обряди в лісових улоговинах, примари Високородних блукають затопленими фундаментами, а наги Злобного Батога нишпорять мілкими рифами Коралового моря. Люті звірі, велетенські гідри й гірські велетні вільно бродять нагір'ями та білосніжними пляжами."},{t="Край вигнанців і відлюдників",b="Через віддаленість і суворий рельєф Азшара вабить відлюдників, що плекають забуті ремесла чи стережуть небезпечні сили. Загадковий Архімаг Ксилем живе у відлюдній вежі високо над кручами й випробовує як здібних чарівників, так і кмітливих розбійників. Далі вздовж узбережжя мисливець на демонів Лорамус Таліпедес вдивляється у хвилі з голого острова, а величезний морський велетень Лорд Арккорок вимагає кривавих жертв у своєму храмі над збуреними водами."}},faq={{q="Чому тут усі дерева червоні й помаранчеві?",a="Азшару огортає вічна осінь. Яскраві помаранчеві, золоті й червоні крони ніколи не скидають листя, надаючи прибережним лісам разючої краси й водночас меланхолії, що триває вже тисячі років.",al={"чому дерева червоні","азшара восени","осіннє листя азшари"}},{q="Як Азшара перетворилася на руїну?",a="Це узбережжя колись було околицями калдорейської столиці Зін-Азшарі. Під час Війни Прадавніх, у Великий Розкол, Колодязь Вічності вибухнув усередину, розколов континент і скинув величезні частини міста в море.",al={"що сталося з азшарою","чому азшара зруйнована","історія азшари"}},{q="Хто править Азшарою нині?",a="Жодна фракція не панує в цьому краї. Альянс тримає невелику варту на Мисі Талрендіс біля Ашенвалю, а Орда діє з табору Валормок. Довколишні землі заполонили небезпечні наги Злобного Батога, люті сатири й дикі чудовиська.",al={"хто контролює азшару","хто править азшарою","чи азшара альянсу чи орди"}},{q="Хто такий Архімаг Ксилем?",a="Архімаг Ксилем — дивакуватий людський чаклун, що живе у віддаленій вежі на скелі над Азшарою. Він не втручається в місцеву політику й допомагає магам і розбійникам, що приходять до нього, розкривати особливі бойові й таємні здібності через складні випробування.",al={"ксилем азшара","вежа магів азшара","чарівник в азшарі"}},{q="Що робить синій дракон серед руїн?",a="Великий синій дракон Азурегос і його виводок пильнують прадавні руїни Ельдарата. Він люто захищає могутні магічні артефакти Високородних, що досі лежать під уламками, від грабіжницьких рук смертних.",al={"азурегос в азшарі","синій дракон азшара","дракон у елдараті"}},{q="Чому нічні ельфи вважають цю землю проклятою?",a="Калдореї вважають Азшару проклятою, бо вона носить ім'я й архітектурну спадщину їхньої зрадливої королеви Азшари, чия угода з Палаючим Легіоном розтрощила їхню імперію й принесла світові руїну.",al={"чи азшара проклята","чому нічні ельфи ненавидять азшару","прокляття азшари"}}},fp="7,468,16.604.0,33.497.0,30.492.0,42.223.0,30.253.0,24.285.0,22.248.0,43.213.0,49.212.0"}
P.entries["zone:badlands"] = {n="Пустища",s="Пустища — посушливий, випалений сонцем край потрісканої землі, пилових бур і кам'янистих каньйонів між Лох Моданом і Палючою Ущелиною. Хоча вони лежать у самому серці дворфійського Каз Модану, це неспокійне прикордоння, де панують дворфи Темного Заліза, троги, огри Пилоригачів і чорні драконороди, що в'ють тут гнізда. Тут же стоять руїни титанів Ульдаман і твердиня Орди Карґат, тож Пустища мають чимале стратегічне значення.",h="Пустища — посушливий, випалений сонцем край потрісканої землі, пилових бур і кам'янистих каньйонів між Лох...",kw={"пустища","ульдаман","карґат","темне залізо","каз модан","троги","земляни"},ang={["faction:Horde"]="Карґат — ваш єдиний військовий притулок у глибині Каз Модану й передова проти Темної Орди, що окупувала Гору Блекрок.",["profession:Mining"]="Посушливий край багатий на залізо, золото, справжнє срібло й мітрил, а в Ульдамані та довкола нього трапляються рідкісні поклади індурію.",["race:Dwarf"]="У Пустищах, в Ульдамані, криються відповіді про ваш власний родовід: саме тут відкриття створених титанами землян змінило те, як дворфи розуміють свою історію."},sec={{t="Похмуре прикордоння",b="На південь від зелених пагорбів Лох Модану земля швидко переходить у задушливу улоговину голих рівнин і крутих ярів. Щоб вижити тут, доводиться мати справу з безжальними койотами, пумами, грифами й лютими піщаними бурями, що затуляють обрій. Плато всіяні грубими таборами огрів Пилоригачів, а похмурий клан Темного Заліза укріпився у Фортеці Анґор і нападає на кожного, хто ступить на його землі."},{t="Таємниці Ульдаману",b="У північних кручах лежить Ульдаман — давній підземний комплекс, висічений землянами, яких створили титани. Нещодавно його відкрили розвідники з Айронфорджа, і розкопки явили світові величні таємниці давнього походження дворфійського народу. Та вторгнення в підземні склепи розбудило полчища лютих трогів Кам'яного Сховища й ожилих вартових-землян. Вони вирізали археологічні загони, і розкопки біля входу перетворилися на криваве поле сутичок."},{t="Тіні Карґата й Летлору",b="Пустища — одна з найхиткіших опор Орди на півдні Східних Королівств. Фортеця Карґат на північному заході дає війську Вождя Тралла базу, звідки можна стежити за Темною Ордою, що засіла неподалік, у Горі Блекрок. А на далекому сході лежить Яр Летлор — підступна прірва, де чорні дракончики й небезпечні чорні драконороди стережуть свої гнізда в тіні гір."}},faq={{q="Чому в Пустищах стоїть Орда?",a="Заставу Карґат заснував Експедиційний Корпус Карґата за наказом Вождя Тралла. Табір під проводом Воєначальника Ґортута дає Орді важливий плацдарм для ударів по Ренду Блекгенду та його клану-відступнику Блекрок, що окопався в Горі Блекрок.",al={"чому каргат","орда в пустищах","що таке каргат"}},{q="Як дістатися до Пустищ?",a="Мандрівники Альянсу можуть пройти просто на південь із Лох Модану через перевал Тераси Творців. Мандрівників Орди чекає довший шлях пішки — південними пагорбами Лох Модану або з Палючої Ущелини західним гірським перевалом, — поки вони не відкриють розпорядника польотів у Карґаті.",al={"дістатися до пустищ","як дійти до пустищ","вхід у пустища"}},{q="Що таке Ульдаман?",a="Ульдаман — величезне підземне сховище, збудоване прадавніми титанами та їхніми слугами-землянами. Нещодавно його розкопали дворфи-шукачі, що прагнули розкрити таємниці походження дворфів, але розкопки пробудили поховані кам'яні конструкти й примітивних трогів Кам'яного Сховища, перетворивши руїни на смертельне поле бою.",al={"що таке ульдаман","лор підземелля ульдаман","хто збудував ульдаман"}},{q="Що роблять чорні дракони в Яру Летлор?",a="Яр Летлор — східний каньйон, де чорна драконячий рід виводить і гніздить потомство. Під охороною молодих драконів і дракончат кладка тримає небезпечну присутність біля гір: дракони полюють на мандрівників і стережуть східні околиці від чужинців.",al={"дракони в пустищах","дракони яру летлор","чорний драконячий політ пустища"}},{q="Хто контролює Фортецю Анґор?",a="Фортецю Анґор тримає ворожий клан Темного Заліза. Розташована на південь від Ульдаману, фортеця слугує місцевою базою, звідки Темне Залізо веде розвідку, змагається за розкопи титанів і воює з сусідніми ограми та дослідниками з поверхні.",al={"фортеця анґор","фортеця пустищ","темне залізо пустища"}},{q="Чи є тут дружні поселення для гравців Альянсу?",a="Ні. У Пустищах немає ні укріплених поселень Альянсу, ні розпорядників польотів. Шукачі з Айронфорджа й самотні відлюдники тримають розкидані, хиткі табори біля розкопів, але по основні припаси шукачам пригод Альянсу доводиться ходити на бази в Лох Модані чи Палючій Ущелині.",al={"містечко альянсу пустища","політ альянсу пустища","дружній альянс пустища"}}},fp="8,424,16.453.0,22.466.0,34.449.0,43.300.0,31.273.0,16.301.0,51.257.0,28.244.0,61.268.0"}
P.entries["zone:barrens"] = {n="Пустки",s="Пустки — безкрая, випалена сонцем савана, що стала географічним і постачальним серцем Орди в центральному Калімдорі. До Великого Розколу тут шумів зелений ліс, а тепер це посушлива рівнина з червоним пилом, витривалими чагарниками й мандрівними звірами. Довкола важливого вузла — Перехрестя — край не виходить із безупинної боротьби з племенами шипогривів, нападниками-кентаврами й повзучою скверною.",h="Пустки — безкрая, випалена сонцем савана, що стала географічним і постачальним серцем Орди в центральному...",kw={"пустки","перехрестя","орда","шипогриви","кентаври","наралекс","печери стогонів"},ang={["class:Druid"]="Спотворені води, що течуть із Печер Стогонів, — глибока трагедія: шляхетна спроба Наралекса відродити Пустки скорилася жахіттю.",["class:Shaman"]="Посушливі рівнини випробовують ваш зв'язок зі стихіями — від сухих духів землі на рівнинах до зачарованих, змінених вод, що б'ють джерелами у відокремлених оазах.",["faction:Horde"]="Пустки — хребет постачання вашої держави: утримати Перехрестя й захистити обози на Золотому Шляху означає забезпечити виживання Оргріммара й Тандер Блафа.",["race:Tauren"]="Задовго до того, як орки висадилися на Калімдорі, ваші предки-кочівники поколіннями мандрували цими саванами, полюючи на священну дичину й борючись за виживання з безжальними кентаврами Колкарами."},sec={{t="Серце нової Орди",b="Незліченні покоління кочові таурени полювали на цих рівнинах на кодо й жевр, ведучи оборонну, нескінченну війну з розбійними кентаврами Колкарами. Коли під час Третьої війни Тралл привів орків на Калімдор, він допоміг Кайрнові Бладгуфу відбити кентаврів і перейти саваною до Малгору. Сьогодні Пустки з'єднують Дуротар, Малгор і Ашенваль. Застави на кшталт Перехрестя й Табору Тауражо захищають торгівлю на Золотому Шляху, а орківські садиби опираються посушливому кліматові, щоб збудувати тут тривку домівку."},{t="Край в облозі",b="Попри панування Орди, за владу над саваною точиться запекла боротьба. Шипогриви Гостромани, схожі на дикобразів, люто нападають на ферми й шляхи постачання зі своїх колючих редутів, а на півдні за ними нависають лігва Рейзорфен Краула. На східному узбережжі сили Терамора тримають гарнізон у Твердині Північної Варти, а дворфи-шукачі вгризаються в комплекс титанів Бель Модан. Тим часом гобліни Раджета підтримують хиткий торговий нейтралітет, радо приймаючи кожного мандрівника з грошима."},{t="Смарагдова скверна",b="Північні рівнини всіяні оазами, чиї води неприродно вирують живодайною силою. Цей вир походить із Печер Стогонів, де друїд нічних ельфів Наралекс спробував звернутися до Смарагдового Сну, щоб повернути Пусткам давню лісову славу. Натомість жахіття спотворило його видіння. Тепер осквернена вода розтікається Забутими ставками й Застояною оазою, породжуючи химерні девіантні рослини, неприродних звірів і друїдів-ренегатів — Друїдів Ікла."}},faq={{q="Звідки посеред посушливих земель буйні оази?",a="Раптові водойми, як-от Забуті ставки й Оаза Буйних Вод, живлять підземні джерела, що витікають із Печер Стогонів. Нічний ельф-друїд Наралекс черпав силу Смарагдового Сну, щоб спрямувати води джерел і знову зазеленити посушливу землю, але задум пішов шкереберть, і північні Пустки просякли потужною, непередбачуваною магією природи.",al={"оази пустовиськ","чому вода в пустовиськах","вода печер стогонів"}},{q="Хто контролює Перехрестя?",a="На Перехресті стоїть гарнізон Орди, здебільшого воїни-орки й таурени, що служать Вождю Траллу. Оскільки Перехрестя лежить на перетині головних торгових шляхів між Дуротаром, Малгором і Ашенвалем, воно — головний стратегічний військовий і транспортний вузол Орди в центральному Калімдорі.",al={"хто керує перехрестям","орда перехрестя","охорона перехрестя"}},{q="Чому шипогриви нападають на всіх?",a="Шипогриви вважають Пустки своєю споконвічною спадщиною: вони вірять, що колосальні хащі проросли з крові їхнього напівбога Аґамаґґана під час Війни Прадавніх. І Орду, що прибула, і корінних тауренів вони мають за загарбників, що крадуть їхні священні збиральні й мисливські угіддя.",al={"лор шипогривів","чому шипогриви агресивні","мотив гостроманів"}},{q="Чому в Пустках є вояки Альянсу?",a="Альянс тримається на околицях савани. У Твердині Північної Варти стоїть гарнізон людських вояків із Терамору, що стежать за рухами Орди, а дворфи Бель Модану й Фортеці Бел'дун віддано розкопують прадавні артефакти титанів, поховані в південних пагорбах.",al={"північна твердиня альянсу","дворфи бел модан","альянс у пустовиськах"}},{q="Чи Раджет належить Орді?",a="Ні. Раджет — незалежний гоблінський порт, яким керує Ґазлоу. Він дотримується суворого нейтралітету й слугує брамою для морської торгівлі, контрабандистів і шукачів пригод і з Орди, і з Альянсу, якщо всі шанують гоблінську торгівлю й тримають зброю в піхвах у місті.",al={"чи раджет орди","фракція раджета","ґазлоу раджет"}},{q="Що відбувається із силітидами на півдні?",a="Комахоподібні створіння, звані силітидами, вилізли із земляних вуликів на півдні Пусток, особливо довкола Поля Велетнів. Їхня раптова поява й швидке розростання колоній дедалі більше загрожують мандрівникам і місцевим заставам, тож Орда взялася з'ясовувати, звідки вони взялися.",al={"комахи пустовиськ","комахи поля велетнів","силітиди південних пустовиськ"}}},fp="11,432,22.521.0,18.482.0,22.482.1,51.341.0,28.293.0,40.311.0,41.300.0,29.271.0,48.290.0"}
P.entries["zone:blastedlands"] = {n="Спустошені Землі",s="Спустошені Землі — безлюдний простір червоної глини й голого каміння на південно-східному краю Східних Королівств, понівечений хаотичною енергією Темного Порталу. Колись це була частина зеленої Чорної Трясовини, а тепер на розтрощеній землі ховаються недобитки Палаючого Легіону, жорстокі огри Дредмолів і витривалі звірі пустелі. Замок Незерґард пильно стереже цей мертвий край, захищаючи Азерот від жахіть, що можуть вирватися з приспаної брами.",h="Спустошені Землі — безлюдний простір червоної глини й голого каміння на південно-східному краю Східних...",kw={"спустошені землі","темний портал","незерґард","каззак","скверна","чорна трясовина","демони"},ang={["class:Mage"]="Маги Замку Незерґард утілюють суворе, оборонне мистецтво таємної магії: вони несуть варту проти скверни й розломів між світами, що лишилися після падіння Медіва.",["class:Warlock"]="Осквернений Шрам кишить демонами високого рангу, а серед скель живе Даіо Старезний, тож ця пустка дає досвідченим чорнокнижникам небачену нагоду підкорити небезпечних істот скверни.",["faction:Alliance"]="Замок Незерґард — ваш єдиний укріплений прихисток у цьому краї. Він стереже південні рубежі королівства від жахіть, які можуть загрожувати Сутінколіссю й Стормвінду.",["faction:Horde"]="Орда не має тут фортеці, але руїни Темного Порталу — похмурий пам'ятник переходу Старої Орди й спустошенню, яке принесла демонічна скверна.",["profession:Herbalism"]="Суха червона глина — одне з украй рідкісних природних місць, де росте Кров ґрома."},sec={{t="Пошрамована пустка",b="До Першої війни цей край був продовженням густих боліт, відомих як Чорна Трясовина. Ті буйні болота знищили дощенту, коли чорнокнижник Ґул'дан і одержимий Медів розчахнули Темний Портал, щоб випустити орочу Орду. Хаотична енергія скверни просочилася крізь пролом між світами, висушила всю вологу й випекла землю на потріскану червону глину. Коли наприкінці Другої війни Темний Портал зруйнували, нищівні ударні хвилі ще дужче обпалили край і пофарбували тутешній камінь у неземний багряний колір."},{t="Самотня варта Незерґарда",b="На північних кручах височіє Замок Незерґард, що стереже єдину дорогу в долину. Цю кам'яну твердиню звели після Другої війни з волі архімага Хадґара й Кірін-Тору, а її залогу становлять суворі маги й стійкі воїни, які присягнули не допустити нового вторгнення демонів чи орків. Служба тут невесела й підкорена суворій дисципліні: за провини вояків засилають до в'язниці Стормвінда. Захисники відбивають безупинний натиск огрів Дредмолів, які лишилися тут після падіння Дренору: з чиєїсь лихої волі вони грабують дороги й атакують ворота фортеці."},{t="Недобитки Легіону",b="На південному заході лежить Осквернений Шрам — поритий кратерами каньйон, де кишить найнебезпечніша демонічна сила на всьому континенті. Застряглий тут після поразки під Горою Гіджал командир вартових загибелі Лорд Каззак збирає під свій стяг бродячих демонів, вартових загибелі й псів скверни. Високо над червоними пустирями його намісник-жахолорд Разеліх Осквернитель підкоряє смертних культистів із Присяглих Тіні біля Вівтаря Бур і командує тутешніми ограми Дредмолів."},{t="Сила крові",b="Попри спустошення, вчені й мандрівники зважуються на тутешні жахіття заради незвичайних відкриттів. Одразу за північним перевалом Маг Крові Дразіал і Маг Крові Ліннор ставлять дивакуваті алхімічні досліди: вони добувають органи місцевих скорпідів, василісків і кабанів, щоб варити надзвичайно сильні зілля для тіла. Далі в пустці самітник-дреней на ім'я Кум'іша шукає розкидані уламки дренетисту й винагороджує мандрівників, які приносять йому ці чужосвітні рештки зруйнованого минулого Дренору."}},faq={{q="Чому земля тут червона й безплідна?",a="Колись Спустошені Землі були частиною болотистих Чорних Драговин. Коли відкрився Темний Портал, сира демонічна магія висмоктала з краю життя й вологу. А коли Темний Портал згодом зруйнували, пекельний жар і хаотична енергія його знищення перетворили глину на тверду багряну землю.",al={"чому спустошені землі червоні","чому все мертве","що сталося з болотом"}},{q="Що таке Темний Портал?",a="Темний Портал — величезна брама між вимірами, зведена, щоб з'єднати Азерот із Дренором, розколотою батьківщиною орків, що нині зветься Аутлендом. Хоча портал зруйнували, щоб розірвати міст між світами, його величезна кам'яна рама досі стоїть, і за нею невпинно стежить Замок Незерґард.",al={"куди веде темний портал","чи темний портал відкритий","що таке врата"}},{q="Хто контролює Замок Незерґард?",a="Замок Незерґард — оплот Альянсу під наглядом магів Кірін-Тору й вояків, вірних Стормвінду. Збудований після Другої війни під проводом Архімага Хадґара, він має гарнізон, що з суворою дисципліною й похмуро несе варту біля Темного Порталу й відбиває напади огрів і демонів поблизу.",al={"хто керує незерґардом","чи незерґард альянсу","маги незерґарда"}},{q="Що таке Осквернений Шрам?",a="Осквернений Шрам — каньйон на півдні Спустошених Земель, що аж кишить демонами. Це прихисток решток сил Палаючого Легіону в Східних Королівствах на чолі з могутнім вартовим загибелі Лордом Каззаком; тут живуть вартові загибелі, вартові скверни й гончаки скверни.",al={"зона осквернений шрам","хто в оскверненому шрамі","долина демонів спустошених земель"}},{q="Хто ці ельфи крові, що отаборилися біля входу?",a="Маг Крові Дразіал і Маг Крові Ліннор — дослідники, що вивчають, як спотворені звірі пристосувалися до суворого краю скверни. В обмін на нутрощі, мізки й легені місцевих василісків, стерв'ятників, скорпідів і вепрів вони варять особливі могутні еліксири, що посилюють властивості смертних.",al={"зілля ельфів крові","дразіал і лінноре","завдання з легенями вепра"}},{q="Хто такий Кум'іша Збирач?",a="Кум'іша — загадковий дренейський містик, що живе в центральних пустищах. Він збирає уламки й сфери дренетисту — кристалічні рештки з Дренору — і обмінює на них запечатані пакунки з рідкісним спорядженням і товарами кожному, хто їх принесе.",al={"дренеї спустошені землі","кум'іша","завдання дренетисту"}},{q="Як дістатися до Спустошених Земель пішки?",a="Ідіть через Перевал Мертвого Вітру на схід до Болота Скорботи. Звідти головною дорогою прямуйте на південь повз поселення Орди Стонард, доки не дійдете до вузького гірського проходу, що веде просто на червону глину Спустошених Земель.",al={"дістатися до спустошених земель","як дійти","вхід у спустошені землі"}},{q="Чому в пустелі живуть огри?",a="Огри-Дредмоли пройшли крізь Темний Портал під час Другої війни. Замість того щоб відступити назад крізь розлом, вони окопалися в Твердині Жахокулака й потрапили під владу жахолорда Разеліха та культу Присягнутих Тіні.",al={"лор огрів дредмол","чому огри тут","твердиня дредмол"}}},fp="13,464,19.556.0,26.619.0,20.471.0,22.514.0,33.288.0,24.290.0,30.291.0,25.273.0,50.292.0,30.253.0,43.256.0,41.247.0"}
P.entries["zone:burningsteppes"] = {n="Палаючі Степи",s="Палаючі Степи — випалена вулканічна пустка біля південного підніжжя Гори Блекрок. Цей підступний край постав століття тому внаслідок катастрофічного виклику Рагнароса, і саме ним пролягає головний суходільний шлях між Стормвіндом і Каз Моданом. Нині тут кишать орки-відщепенці клану Блекрок, огри Вогняного Черева, дворфи Темного Заліза й виводки чорного драконячого роду.",h="Палаючі Степи — випалена вулканічна пустка біля південного підніжжя Гори Блекрок.",kw={"палаючі степи","гора блекрок","рагнарос","тауріссан","темне залізо","андуїн лотар","війна трьох молотів"},ang={["faction:Alliance"]="Палаючі Степи — похмуре, небезпечне прикордоння, де поліг верховний головнокомандувач Андуїн Лотар. Маршал Максвелл у Дозорі Морґана постійно шукає відважних героїв, щоб відбивати загрози, які підбираються до Редріджу.",["faction:Horde"]="Нова Орда Тралла з глибокою тривогою стежить за Полум'яним Гребенем і рішуче налаштована приборкати небезпечний, нерозкаяний клан Блекрок, чия войовничість плямує честь орочого роду.",["profession:Mining"]="Вулканічний край багатий на рідкісні мінерали: це один із небагатьох відкритих куточків Азероту, де можна добувати цінні поклади темного заліза поряд із жилами багатого торію.",["race:Dwarf"]="Кожен камінь у степах свідчить про безумство клану Темного Заліза у Війні Трьох Молотів, яке скінчилося загибеллю їхньої столиці й прикликанням Рагнароса."},sec={{t="Народжені з вогню",b="Колись ці передгір'я були просто північними відрогами Гір Редріджу. Під час Війни Трьох Молотів вигнаний клан Темного Заліза заснував тут своє королівство й звів столицю Тауріссан. Опинившись на межі повної поразки від кланів Бронзбірдів і Вайлдгаммерів, чародій-тан Тауріссан у відчаї спробував викликати сили стихій. Натомість він розколов землю й прикликав в Азерот Рагнароса, Володаря вогню. Нищівний вибух розтер на порох навколишні гори, розверз ріки лави й породив велетенський вулкан — Гору Блекрок, а степи назавжди лишилися обвугленими й безплідними."},{t="Відлуння Другої війни",b="У Другій війні Стара Орда зробила Шпиль Блекрок своєю головною твердинею. У вирішальну мить війни Великий Альянс Лордерону вдерся глибоко в Палаючі Степи, щоб узяти гору в облогу. Саме біля підніжжя Гори Блекрок Вождь Оргрім Думхаммер зійшовся в бою з лордом Андуїном Лотаром і вбив людського героя. Та замість зламати дух Альянсу смерть Лотара згуртувала союзні армії: вони розгромили орків, вибороли перемогу в Другій війні й лишили по собі долину попелу та іржавої сталі, що стоїть донині."},{t="Лігво чудовиськ і драконів",b="Хоча Тралл заснував Нову Орду в далекому Калімдорі, клан Блекрок, що лишився в степах, зберіг кровожерну жорстокість Старої Орди. Ці орки засіли у Твердині Блекрок і відкрито уклали союз із чорним драконячим родом і місцевими ограми Вогняного Черева, не зважаючи на жодні перемир'я. Тим часом дворфи Темного Заліза й прислужники-елементалі чатують серед вогняних руїн, а чорні дракони й драконоподібні полюють на необачних мандрівників, які йдуть цим шляхом зі Стормвінда до північних королівств."}},faq={{q="Чому земля обвуглена й укрита лавою?",a="Століття тому Чаклун-Тан Темного Заліза Тауріссан спробував прикликати стихійного прислужника, щоб урятувати свій клан від поразки у Війні Трьох Молотів. Його закляття помилково пробило межу Царства Стихій і викликало Рагнароса, Володаря вогню: земля розверзлася, постав величезний вулкан Блекрок, а північні Гори Редріджу перетворилися на обвуглене пустище.",al={"чому горить","що сталося з палаючими степами","чому чорна гора вулкан"}},{q="Чи тутешні орки належать до Орди Тралла?",a="Ні. Орки Палаючих Степів — рештки клану Блекрок, що не хочуть приєднуватися до Нової Орди Тралла. Вони не визнають перемир'я з Альянсом і лишаються вірними диким войовничим традиціям Першої і Другої воєн, служачи Шпилю Блекрок і чорній драконячому роду.",al={"чи ці орки орди тралла","чи блекрок орки в орді","чому орки ворожі"}},{q="Де загинув Андуїн Лотар?",a="Андуїна Лотара вбив Вождь Оргрім Думхаммер біля підніжжя Гори Блекрок у Палаючих Степах наприкінці Другої війни. Загибель Лотара підштовхнула його заступника Туральйона й війська Альянсу до шаленого контрнаступу, що розбив лави Орди.",al={"де загинув лотар","місце смерті лотара","дуель оргріма думгаммера й лотара"}},{q="Де Альянс може знайти прихисток у степах?",a="Вояки й мандрівники Альянсу зупиняються в Дозорі Морґана — заставі на височині в південно-східних передгір'ях краю. Нею командує Маршал Максвелл, що наглядає за північним перевалом і стежить за пересуванням ворожих військ довкола гори.",al={"база альянсу палаючі степи","де політ альянсу","дозор морґана"}},{q="Звідки тут діє Орда?",a="Шукачі пригод з Орди прямують до Полум'яного Гребеня — табору на височині вздовж північно-східного хребта. Звідси посланці Орди стежать за ворожим кланом Блекрок і тримають повітряне сполучення з Пустищами, Болотом Скорботи й Палючою Ущелиною.",al={"база орди палаючі степи","полум'яний гребінь","де місто орди"}},{q="Що таке Руїни Тауріссана?",a="Руїни Тауріссана — рештки величного міста, яке клан Темного Заліза збудував після вигнання з Айронфорджа. Коли Тан Тауріссан прикликав Рагнароса, вибух сирої стихійної сили знищив його столицю й поневолив уцілілий народ волі Володаря вогню.",al={"руїни тауріссана","що за зруйноване дворфійське місто","руїни посеред мапи"}}},fp="15,384,20.652.0,24.569.0,29.528.0,46.377.0,42.301.0,28.286.0,51.257.0,43.243.0,33.265.0"}
P.entries["zone:darkshore"] = {n="Темне Узбережжя",s="Темне Узбережжя — холодна, оповита туманом смуга берега на північному заході Калімдору, всіяна давніми руїнами калдореїв і неспокійними звірами. Його опора — портове містечко Альянсу Обердайн, головна брама на континент для мандрівників із Тельдрассилу й Східних Королівств. За межами патрульованої дороги крихкій рівновазі краю загрожують демонічні культи, наги, що наступають, і повзуча скверна з нагір'я.",h="Темне Узбережжя — холодна, оповита туманом смуга берега на північному заході Калімдору, всіяна давніми...",kw={"темне узбережжя","обердайн","нічні ельфи","амет'аран","башал'аран","скверна","калімдор"},ang={["class:Druid"]="Темне Узбережжя — передова для учнів Кола Кенарія, які відгукуються на заклик із Місячного Гаю: тут вони розпізнають отруєні водойми й варять очисні зілля для хворих лісових створінь.",["faction:Alliance"]="Обердайн — головний торговий вузол Альянсу на півночі Калімдору, що підтримує пряме морське сполучення Стормвінда й Айронфорджа зі столицею нічних ельфів Дарнасусом.",["faction:Horde"]="Темне Узбережжя — віддалений, ретельно патрульований оплот Альянсу просто на північ від таборів Орди в Ашенвалі: підступне узбережжя, де никають ворожі вартові й небезпечні культи.",["race:NightElf"]="Для молодих нічних ельфів, що покидають Тельдрассил, Темне Узбережжя — перший крок на материковий Калімдор, де їм доводиться побачити болючі руїни своєї давньої цивілізації та скверну, що шириться дикою природою."},sec={{t="Край туману й пам'яті",b="Темне Узбережжя, що простягається під західними тінями Гори Гіджал і Сквернолісся, — це соснові гаї, морський туман і кам'янисті пляжі, які б'ють холодні хвилі. Тисячоліття тому на цьому березі квітли міста-близнюки калдореїв — Амет'Аран і Башал'Аран. Зруйновані під час Великого Розколу, їхні оголені колони й мармурові арки тепер лежать напівзатоплені в прибої чи порослі корінням; там блукають неспокійні духи Високородних, а хазяйнують мурлоки-падальники й наги-загарбники."},{t="Прихисток Обердайн",b="Після Третьої війни й насадження Тельдрассилу нічні ельфи заснували Обердайн як гамірний морський прихисток серед дикого краю. Його дерев'яні причали приймають регулярні судна із Селища Рут'теран і Гавані Менетіл у далекому Багнокраї, тож Обердайн — життєва нитка, що пов'язує землі нічних ельфів з рештою Альянсу. Вартові старанно патрулюють торговий шлях на південь до Ашенвалю, хоча їхньому невеликому гарнізону важко стежити за глибокими нетрями обабіч дороги."},{t="Отруєні води й шепітливі глибини",b="Попри захист східних гір, Темне Узбережжя страждає від повільного зловісного гниття. Отруєні стоки, що стікають зі Сквернолісся, отруюють джерела на кшталт Водоспаду Скельного Джерела, псують підземні води й доводять місцевих ведмедів, оленів і фурболгів Лігва Чорнолісся до лютого божевілля. Ба гірше, у тіні закріпилися зловісні угруповання: культисти Темного Берега й Молота Присмерку правлять мерзенні ритуали у Вежі Альталакса й збираються довкола моторошного давнього пам'ятника, відомого як Глефа Володаря."}},faq={{q="Як дістатися до Темного Узбережжя?",a="Гравці Альянсу можуть пливти кораблем просто до Обердайна із Селища Рут'теран біля підніжжя Тельдрассила або з Гавані Менетіл у Багнокраї. Мандрівники Орди, що прямують на північ, мусять іти пішки через Ашенваль, головною дорогою на північний схід від Застави Зорам'гар через кордон.",al={"дістатися до темного берега","як дійти до обердіна","човен темного берега"}},{q="Що сталося з місцевими звірами й фурболгами?",a="Річки, що витікають з отруєних висот Сквернолісся, як-от Річка Скельного Джерела, несуть демонічну скверну просто в ґрунтові води Темного Узбережжя. Від води з цих мерзенних потоків корінні племена фурболгів здичавіли, а місцеві олені й хижаки заразилися хворобою й агресією.",al={"чому тварини хворі","скверна фурболгів","зараза темного берега"}},{q="Що сталося з Амет'Араном і Башал'Араном?",a="Це були квітучі калдорейські міста-близнюки, зруйновані десять тисяч років тому під час Великого Розколу. Їхній правитель Атрікус Нарассін обіцяв урятувати свій народ від катаклізму, але натомість ув'язнив їхні душі в самоцвітах, щоб зберегти їх як вічні джерела сили для себе, тож руїни повні плачливих привидів.",al={"історія амет'арана","лор башал'арана","руїни темного берега"}},{q="Що таке Глефа Володаря?",a="Глефа Володаря на півдні Темного Узбережжя — величезний скам'янілий череп, пробитий велетенською кам'яною зброєю. Це прадавня реліквія, пов'язана з первісними Древніми Богами та їхніми слугами, і нині вона вабить небезпечних культистів Молота Присмерку.",al={"що таке глефа володаря","гігантський череп темний берег","монстр глефи володаря"}},{q="Що це за велетенське дерево в Гаю Прадавніх?",a="Це Ону, мудрий і шанований Древо Знань. Спочиваючи у своєму тихому гаю на південь від Обердайна, він міркує над тривожним наступом культу Молота Присмерку й допомагає мандрівникам розслідувати негаразди в лісі.",al={"давній лор темного берега","хто такий ону","дерево-людина темного берега"}},{q="Хто живе у Вежі Альталакса?",a="Вежу займає Культ Темного Берега — лютий культ, що практикує темне чаклунство й викликає демонічних істот. Його змовники влаштовують засідки на необережних мандрівників у північних частинах прибережних лісів.",al={"вежа альталакса","культисти вежі темного берега","культ альталакса"}}},fp="9,443,25.491.0,22.499.0,37.549.0,26.293.0,51.298.0,44.329.1,28.273.0,51.244.0,36.208.0"}
P.entries["zone:darnassus"] = {n="Дарнасус",s="Дарнасус — спокійна столиця нічних ельфів просто неба, збудована серед віт нещодавно висадженого Світового Дерева — Тельдрассила. Ним править Верховна Жриця Тіранда Віспервінд разом із друїдами Ценаріонського Анклаву, і він став тихим прихистком для давнього народу, що вчиться жити смертним. Дарнасус розкинувся просторими терасами довкола кришталевого озера — це серце суспільства нічних ельфів і їхній міст до Альянсу.",h="Дарнасус — спокійна столиця нічних ельфів просто неба, збудована серед віт нещодавно висадженого Світового...",kw={"дарнасус","нічні ельфи","тельдрассил","тіранда","калдореї","столиця","фандрал"},ang={["class:Druid"]="Ценаріонський Анклав — осердя друїдського навчання на Тельдрассилі під наглядом вимогливого й непоступливого Архідруїда Фандрала Стаґгелма.",["class:Priest"]="Величний Храм Місяця — священне осердя Сестер Елуни, яким опікується сама Верховна Жриця Тіранда Віспервінд.",["faction:Alliance"]="Дарнасус — найзахідніший оплот Альянсу, вкрай важливий морський і стратегічний прихисток на континенті Калімдор.",["race:NightElf"]="Дарнасус — серце вашої суверенної цивілізації й ваш прихисток, поки ви проходите небачені досі випробування смертного життя."},sec={{t="Корона високо в гіллі",b="На відміну від щільної кам'яної забудови Стормвінда чи висічених у скелі тунелів Айронфорджа, Дарнасус просторий, тихий і відкритий дикій природі. Столиця постала у верхніх кронах Тельдрассила біля північного узбережжя Калімдору: її витончені дерев'яні споруди й звивисті стежки оточують спокійне озеро посередині. Елегантні мости з'єднують тераси торговців, ремісників, вартових і друїдів, і в місті панує рівновага між громадським ладом і глибокою шаною до природи."},{t="Притулок смертного народу",b="Як на цивілізацію, якій тисячі років, Дарнасус напрочуд молодий. Після Третьої війни й жертви Нордрассила на Горі Гіджал калдореї раптом зіткнулися зі старістю й недугами. Прагнучи повернути втрачену життєву силу, Архідруїд Фандрал Стаґгелм і його прихильники висадили Тельдрассил всупереч застереженням зниклого Архідруїда Малфуріона Стормрейджа. Дарнасус заснували серед його величезних віт як притулок і пам'ятник їхньому виживанню — та серед коріння вже шепочуть тіні недуги."},{t="Розділене вогнище",b="Хоч на поверхні Дарнасус мирний, він балансує на тонкій політичній межі. З високих колонад Храму Місяця Верховна Жриця Тіранда Віспервінд опікується духовним життям свого народу й керує його обороною руками пильних Вартових. По той бік водних шляхів, у Ценаріонському Анклаві, Архідруїд Фандрал Стаґгелм очолює друїдів, поки Малфуріона й далі немає. Перед новими союзниками з Альянсу обоє провідників виступають єдиним фронтом, та тертя між жрицями й колом друїдів відчутне по всьому місту."}},faq={{q="Як дістатися до Дарнасуса з материка?",a="Тельдрассил — відокремлений острів біля північно-західного узбережжя Калімдору, тож спершу треба дістатися кораблем або в польоті до Селища Рут'теран біля підніжжя дерева. Від пристані селища сяйливий чарівний портал переносить мандрівників просто вгору, до міських віт.",al={"як дістатися до дарнасуса","дорога до дарнасуса","вхід до дарнасуса"}},{q="Хто править Дарнасусом?",a="Дарнасусом і калдореями править Верховна Жриця Тіранда Віспервінд із величного Храму Місяця. Архідруїд Фандрал Стаґгелм із Ценаріонського Анклаву очолює друїдів Кола Кенарія й фактично головує серед них, поки Малфуріон Стормрейдж загублений у Смарагдовому Сні.",al={"правитель дарнасуса","хто тут головний","хто керує дарнасусом"}},{q="Чому місто заснували так недавно?",a="Дарнасус заснували невдовзі після Третьої війни. Коли нічні ельфи пожертвували безсмертям, щоб здолати Архімонда на Горі Гіджал, Фандрал Стаґгелм наполіг на тому, щоб виростити нове Світове Дерево — Тельдрассил — і повернути колишню силу. Дарнасус виплекали серед його віт як новий прихисток.",al={"чому дарнасус новий","коли збудували дарнасус","історія дарнасуса"}},{q="Де Архідруїд Малфуріон Стормрейдж?",a="Малфуріон Стормрейдж зник: його дух ув'язнений у Смарагдовому Сні. Поки його немає, друїдами Тельдрассила керує Архідруїд Фандрал Стаґгелм, а Тіранда Віспервінд невпинно шукає способу пробудити й повернути свого коханого.",al={"де малфуріон","чи є малфуріон у дарнасусі","де знайти малфуріона"}},{q="Де знайти наставників професій і крамниці?",a="Місто поділене на тераси з різним призначенням. На північній Терасі Ремісників — збиральні ремесла, кравецтво й корчма, а на південній Терасі Ремісників — торгові ятки й аукціонний дім. Наставники ковальства й бойового мистецтва працюють на Терасі Воїна, а міський банк розташований на центральному острові Храмових Садів.",al={"професії в дарнасусі","аукціонний дім дарнасуса","банк дарнасуса"}},{q="Чому нічні ельфи приєдналися до Альянсу?",a="Після спустошень Третьої війни нічні ельфи опинилися під дедалі більшим тиском Орди — передусім через лісорубні походи орків в Ашенваль. Розуміючи, що проти цих вторгнень та інших загроз Калімдору потрібні союзники, Дарнасус налагодив дипломатичні зв'язки й вступив до Великого Альянсу.",al={"чому нічні ельфи в альянсі","нічні ельфи й альянс","альянс і дарнасус"}}},fp="9,450,28.496.0,25.528.0,16.558.0,49.254.0,20.298.0,37.290.0,39.243.0,52.343.0,42.314.0"}
P.entries["zone:deadmines"] = {n="Мертві Копальні",s="Глибоко під запорошеним хліборобським містечком Мунбрук лежать Мертві Копальні — величезний підземний комплекс, що колись давав третину золотого запасу Стормвінда. Покинуті під час Першої війни й віддавна знані як прокляті, ці лабіринти тунелів таємно захопило Братство Дефіас і зробило своїм головним плацдармом. Тут Едвін Венкліф і його підневільні гобліни-інженери далеко від очей королівства будують знаряддя помсти.",h="Глибоко під запорошеним хліборобським містечком Мунбрук лежать Мертві Копальні — величезний підземний...",kw={"мертві копальні","дефіас","венкліф","мунбрук","вестфол","підземелля","броненосець"},ang={["class:Paladin"]="Ці осквернені шахти — випробування звитяги й віри, що відлунює давніми звершеннями сера Андуїна Лотара та долею зниклих гірників, чиї неупокоєні мерці досі блукають зовнішніми тунелями.",["faction:Alliance"]="Мертві Копальні — найтяжча внутрішня загроза Королівству Стормвінд; перемога над Венкліфом — та вирішальна звитяга, що повертає надію обложеним фермерам Вестфолу.",["profession:Engineering"]="Гоблінська Ливарня й механічна майстерня Сніда дають змогу зазирнути в найновіші парові потрощувачі, керовані на відстані големи та особливі боєприпаси.",["profession:Mining"]="Колись ці кам'янисті тунелі давали третину багатства столиці, і досі вони багаті на жили міді, олова й дорогоцінного срібла."},sec={{t="Спадок золота й руїни",b="До Першої війни Мертві Копальні славилися як найбільший осередок видобутку золота в людських землях, що забезпечував добробут Стормвінда. Коли Орда орків пронеслася королівством і зрівняла столицю з землею, копальні поспіхом покинули на поталу темряві. У ті буремні роки цими глибинами ходили легендарні постаті: сер Андуїн Лотар двадцять місяців пробув у полоні підземних огрів, добуваючи священний Фоліант Божественності, а бунтівна донька вождя Блекгенда, Ґризельда, утекла в нижні ходи разом з огром Туроком, де обоє й знайшли свою смерть. Глибини вважали проклятими, населеними лише шкандибаючою нежиттю та підземною наволоччю, і десятиліттями ніхто їх не торкався."},{t="Твердиня Братства",b="Коли Гільдію Каменярів вигнали зі Стормвінда, так і не заплативши за відбудову міста, Едвін Венкліф згуртував знедолених ремісників у Братство Дефіас. Шукаючи надійного прихистку від Народного ополчення Ґраяна Стаутмантла, злодії облаштували свій головний оплот у покинутих тунелях. Вони вигнали звідти законну Лігу Шахтарів, кинувши приречених робітників Наглядача Тистлнеттла на смерть, — ті згодом повстали гулями, — і перетворили шахти на промисловий воєнний табір. Під охороною незграбних огрів, бувалих розбійників і механічних конструкцій нижні копальні знову відлунюють кайлами, вогнищами й незаконним ремеслом."},{t="Таємниця Бухти Айронклад",b="За задушливою Гоблінською Ливарнею та засипаною колодами Щогловою Кімнатою лежить Бухта Айронклад — величезний підземний грот, видовбаний під Кинджальними Пагорбами. У цій прихованій гавані Венкліф найняв гоблінів-корабелів і майстрів, щоб збудувати колосальний залізний броненосець. Під командою капітана Ґрінскіна й старшого помічника Пана Кари цей бойовий корабель має вийти підводними морськими воротами в океан, де Братство Дефіас збирається полювати на морську торгівлю, що збагачує Стормвінд."}},faq={{q="Де вхід до Мертвих Копалень?",a="Вхід ховається в покинутій стодолі в зруйнованому містечку Мунбрук на південному заході Вестфолу. Звивисті тунелі ведуть крізь зовнішній комплекс, де працюють копачі Дефіас і бродять шахтарі-нежить, і виводять до замкненого порога підземелля.",al={"вхід у мертві копальні","як дійти до мертвих копалень","де мертві копальні"}},{q="Чому всі називають Мертві Копальні «VC»?",a="Шукачі пригод часто звуть це підземелля «VC» на честь його господаря, Едвіна Венкліфа. Це скорочення вживають, щоб не плутати Мертві Копальні з Лютопащем — прадавнім ельфійським комплексом у Фераласі, що в англійській має ті самі ініціали «DM».",al={"чому вс","значення вс","чому так називають"}},{q="Хто такий Едвін Венкліф?",a="Едвін Венкліф — геніальний голова Гільдії Каменярів, що керував величною відбудовою Стормвінда після Першої війни. Коли Дім Вельмож відмовився сплатити борги, Венкліф заснував Братство Дефіас, щоб вимагати відшкодування бунтом і відвертим розбоєм.",al={"передісторія венкліфа","хто останній бос","лідер дефіасу"}},{q="Що будують у Бухті Айронклад?",a="Дефіас найняли гоблінських інженерів, щоб зібрати величезний броньований джаґернаут. Озброєний важкими гарматами й збудований із міцного дерева, цей бойовий корабель має вийти з бухти морською брамою й грабувати торгівлю, що годує столицю.",al={"що будують","корабель мертвих копалень","джаґернот"}},{q="Що сталося з робітниками Ліги Шахтарів біля входу?",a="Наглядача Тистлнеттла та його бригаду послали законно відкрити копальні знову для королівства. Коли Дефіас штурмом узяли розробки, нищівний обвал тунелю замкнув шахтарів у темряві, де вони померли з голоду, а згодом устали безмозкою неприкаяною нежиттю.",al={"доля чортополоха","чому нежить шахтарі","збір спогадів лор"}},{q="Що означає перемога над мурлоком Печивком для корабля Дефіас?",a="Печивко — химерний кок на дредноуті Венкліфа. Убивши Венкліфа, ви відтинаєте бунтові голову, а вбивши Печивка — вичищаєте решту команди, що засіла в камбузі, і остаточно ламаєте присутність команди в Бухті Айронклад, перш ніж вийти прибережним проходом.",al={"печиво мурлок","чому печиво бос","печиво мертві копальні"}},{q="Куди веде вихідний тунель із підземелля?",a="Природний тунель за дредноутом виводить шукачів пригод на прибережні кручі Кинджальних Пагорбів, звідки видно океан і Маяк Вестфолу.",al={"вихід з мертвих копалень","куди веде вихід"}}},fp="13,480,25.717.0,26.666.0,27.519.1,47.241.0,42.224.0,22.296.0,37.235.0,65.255.0,63.314.0,57.189.0"}
P.entries["zone:dunmorogh"] = {n="Дун Мороґ",s="Дун Мороґ — засніжене гірське високогір'я в серці Каз Модану. Це прадавня стартова земля і спільна батьківщина дворфів Айронфорджа та гномів, що втратили Гномреґан. Хоч засніжений край захищають високі вершини й укріплені перевали, зсередини йому дедалі більше загрожують троги, тролі Морозогриви та опромінені прокажені гноми.",h="Дун Мороґ — засніжене гірське високогір'я в серці Каз Модану.",kw={"дун мороґ","зона","дворфи","гноми","айронфордж","гномреґан","троги","морозогриви"},ang={["profession:Cooking"]="Місцеві мисливці та шинкарі в Хараносі й Селі Брюнолл щедро пускають у діло м'ясо вепрів, ведмежі ребра та дворфський стаут, щоб проганяти пронизливий гірський мороз.",["profession:Mining"]="Гірські скелі Дун Мороґу багаті на поверхневі поклади мідних жил, особливо навколо кар'єру Гол'Болар і вздовж засніжених скельних стін.",["race:Dwarf"]="Це батьківщина ваших предків. Від вогнищ Анвілмара до розжареного серця Великої Кузні в Айронфорджі — боронити ці вершини від тролів і трогів є вашим обов'язком перед Королем Маґні.",["race:Gnome"]="Ваш утрачений дім, Гномреґан, лежить опромінений у західній долині. Дун Мороґ — ваша база у вигнанні пліч-о-пліч із дворфськими родичами, поки ви даєте відсіч трогам і здичавілим прокаженим гномам."},sec={{t="Гірська твердиня",b="Дун Мороґ займає найвищі вершини Східних Королівств — альпійський простір, оточений зубчастими піками, що затуляють його від Палючої Ущелини на півдні та Багнокраю на півночі. Ці засніжені гори живлять річки, що течуть по всьому Каз Модану, і дають майже невичерпні жили міді й заліза. Доступ сюди суворо обмежений гірськими тунелями, як-от Перевал Північної Брами та Прохід Південної Брами, за якими пильно стежать дворфські горяни. У серці краю лежить Айронфордж — прадавнє підземне диво й столиця королівства Короля Маґні Бронзбірда, сполучена просто зі Стормвіндом дивовижним Глибинним трамваєм."},{t="Розділений притулок",b="Століття тому дворфи відтіснили тутешніх крижаних тролів Морозогривів у скелі, вивільнивши місце для себе та своїх геніальних гномських союзників. Два народи процвітали в сусідніх гірських залах, аж доки під час Третьої війни не сталася нещодавня катастрофа в Гномреґані. Жахливе вторгнення трогів і згубний викид радіації зруйнували технологічне диво, обернувши його захисників на безтямних прокажених гномів і змусивши Великого Тінкера Ґелбіна Меккаторка з уцілілим народом піти у вигнання. Нині гноми живуть гостями всередині Айронфорджа, а прокажені гноми та вцілілі троги виливаються в Долину Холодного Вітерцю."},{t="Клопоти серед заметів",b="Життя серед заметів аж ніяк не спокійне. Плем'я Морозогривів знахабніло й розбиває добре озброєні табори від Мерехтливого Хребта до Долини Холодного Хребта. Тим часом первісні троги видряпалися з прадавніх підземних розколин у Кар'єр Гол'Болар, загрожуючи гірничим промислам краю. Між хижими вендіго, дикими вепрами, лазутчиками-дворфами Темного Заліза та отруйними опадами, що ширяться з руїн Гномреґану, дворфські горяни ледве дають раду, підтримуючи лад від Хараноса до прикордонних брам."}},faq={{q="Які раси починають у Дун Мороґу?",a="І дворфи, і гноми починають свій шлях тут, у Долині Холодного Хребта — захищеній улоговині на південному заході Дун Мороґу, — а потім виходять через Перевал Холодного Кряжа до Хараноса й решти зони.",al={"стартова раса дун мороґу","хто тут починає","стартова зона дворфів","стартова зона гномів"}},{q="Що сталося з Гномреґаном?",a="Під час Третьої війни підземна раса трогів заполонила Гномреґан. Намагаючись знищити загарбників, Великий Тінкер Ґелбін Меккаторк випустив у нижні рівні радіоактивний газ. План провалився з катастрофічними наслідками: загинули тисячі, багато гномів через опромінення перетворилися на божевільних прокажених гномів, а здорові вцілілі були змушені тікати до Айронфорджа.",al={"чому гномреґан зруйновано","що сталося з гномами","чому тут прокажені гноми"}},{q="Як вийти з Дун Мороґу пішки?",a="Дун Мороґ оточений високими гірськими хребтами. Щоб пішки потрапити на схід, до Лох Модану, ідіть дорогами до Перевалу Північної Брами або Проходу Південної Брами в північно-східних горах. Також можна дістатися просто до Стормвінда Глибинним трамваєм всередині Айронфорджа.",al={"вихід із дун мороґу","з дун мороґу до лох модану","покинути дун мороґ"}},{q="Де в Дун Мороґу розпорядник польотів?",a="Єдиний діючий розпорядник польотів Альянсу в зоні розташований усередині Великої Кузні Айронфорджа; він сполучає мандрівників із місцями по всьому Каз Модану, Стормвіндом і північними заставами Альянсу.",al={"розпорядник польотів дун мороґ","маршрут польоту дун мороґ","куди літати з дун мороґу"}},{q="Хто такі тролі Морозогриви?",a="Морозогриви — плем'я крижаних тролів, яке правило Дун Мороґом задовго до того, як дворфи вийшли з Улдамана. Хоч багато поколінь тому їх розбили й загнали в скелі, вони лишаються запеклими ворогами Айронфорджа й раз у раз нападають на дворфські ферми та дороги зі своїх сховків на кшталт Твердині Морозогривів.",al={"чому в дун мороґу тролі","тролі дун мороґу","плем'я морозогривів"}},{q="Що таке Харанос?",a="Харанос — головне дворфське поселення в центральному Дун Мороґу. Тут розташовані Ґуральня Тандербрю, наставники та припаси, тож це центральний осередок для молодих шукачів пригод і горян, які дають раду місцевим тролям і дикій звірині.",al={"містечко в дун мороґу","осередок харанос","яке тут головне містечко"}}},fp="10,374,21.621.0,16.623.0,21.550.0,31.194.0,28.349.0,36.270.0,41.202.0,29.283.0,17.249.0"}
P.entries["zone:durotar"] = {n="Дуротар",s="Дуротар — посушлива батьківщина серед червоних скель, яку Вождь Тралл заснував після Третьої війни й назвав на честь свого батька Дуротана. Обмежений Річкою Південної Люті та Великим Морем, він є серцем Нової Орди й полігоном для молодих орків і тролів Темного Списа. У його суворих каньйонах лежать укріплені поселення на кшталт Гострого Пагорба, розлоге місто воїнів Оргріммар і ворожі оплоти, що окопалися тут, — від племен шипогривів до відрізаних військ Альянсу.",h="Дуротар — посушлива батьківщина серед червоних скель, яку Вождь Тралл заснував після Третьої війни й назвав...",kw={"дуротар","зона","орки","тролі","тралл","оргріммар","нова орда","калімдор"},ang={["class:Shaman"]="Посушлива земля просякнута первісними духами стихій. Молоді шамани відвідують священні місця на кшталт Каменя Духів і Святині Приспаного Полум'я, щоб налаштуватися на землю та вогонь.",["class:Warlock"]="Тралл суворо стежить за темною магією, змушуючи ковени Ради Тіней ховатися в місцях на кшталт Череп-скелі та під містом, у звивистих печерах Провалля Лютого Вогню.",["faction:Alliance"]="Дуротар — живе серце військової сили Орди. Будь-якого мандрівника Альянсу, спійманого у випалених сонцем каньйонах, негайно вистежать і войовничі патрулі, і місцева звірина.",["race:Orc"]="Дуротар — нова обітована земля вашого народу, здобута потом і кров'ю після років демонічного заціпеніння та інтернування. Довести свою цінність у Долині Випробувань — перший обряд посвяти для кожного нового захисника Орди.",["race:Troll"]="Утікши від морської відьми у Великому Морі, Темний Спис знайшов притулок поруч із Траллом у Дуротарі, та зрадник Залазан відібрав Острови Відлуння зсередини. Повернути острови й захистити Село Сен'джин — справа особиста."},sec={{t="Суворий новий дім",b="Коли Тралл повів свій народ через Велике Море на Калімдор, він свідомо шукав дике порубіжжя, де орки могли б вирвати собі чесне існування працею і завзяттям, а не завоюванням. Потріскана червона земля Дуротару, випалені балки й високі червоні скелясті шпилі глибоко нагадують оркам Дренор, яким той був до знищення. Хоч клімат нещадний і дає мало орної землі та скупу воду, Орда прийняла природний захист і сувору велич цього краю. Обмежений на заході, за Річкою Південної Люті, відкритими Пустками, а на півночі — зруйнованою глушиною Азшари, Дуротар стоїть живим доказом того, що орки викували власну долю."},{t="Вороги на порубіжжі",b="Хоч Дуротар міцно під владою Орди, його убезпечення лишається живою війною. Шипогриви Гостромани, витіснені під час заснування держави, невпинно нападають на поселення й ферми із західних скель. Далі на південь рештки флоту Кул Тірасу Великого Адмірала Дейліна Праудмура досі утримують напівзруйнований гарнізон Фортеці Тіраґард під проводом Лейтенанта Бенедикта й відмовляються здаватися. Ще гірше: демонічні рештки ковену Палаючого Клинка чаяться в прихованих ярах і глибоких морських печерах, нишком прагнучи знову осквернити молодих орків обіцянками сили Скверни."},{t="Випробування Темного Списа",b="На південному узбережжі лежить Село Сен'джин — плацдарм вигнаних тролів Темного Списа. Темний Спис під проводом Майстра Ґадріна був змушений покинути дім на сусідніх Островах Відлуння, коли знахар Залазан з'їхав з глузду й темним вуду поневолив одноплемінників. Не маючи змоги повернути острови самотужки, Темний Спис покладається на щойно навчених воїнів з орків і тролів, що виходять із Долини Випробувань, щоб зламати хватку Залазана й убезпечити узбережжя."}},faq={{q="Чому Тралл оселив Орду в такій безплідній пустелі?",a="Тралл обрав цей нещадний край навмисне. Червона земля та суворі плоскогір'я нагадували оркам прадавній світ Дренор, а суворі умови слугували покутою та горнилом дисципліни. Тралл вважав, що його народ має заслужити виживання чесними злигоднями, а не захоплювати родючі землі війною, щоб не скотитися знову в кровожерливе самовдоволення.",al={"чому оселилися тут","чому дуротар","чому дуротар безплідний"}},{q="На чию честь названо Дуротар?",a="Край названо на честь Дуротана — покійного батька Тралла й колишнього вождя клану Морозного Вовка. Дуротан виступав проти демонічного скверніння орківських кланів і був убитий за наказом чорнокнижника Ґул'дана.",al={"на чию честь дуротар","дуротан","походження назви дуротар"}},{q="Чому у Фортеці Тіраґард людські солдати?",a="Солдати у Фортеці Тіраґард — уцілілі кул-тіраські морські піхотинці під проводом Лейтенанта Бенедикта, що лишилися від загарбницького флоту Великого Адмірала Дейліна Праудмура. Навіть після загибелі Праудмура ці війська відмовилися здатися чи відступити й утримують укріплену ворожу заставу просто на південному узбережжі Дуротару.",al={"чому люди в дуротарі","люди у фортеці тіраґард","війська праудмура в дуротарі"}},{q="Що за конфлікт на Островах Відлуння?",a="Спершу тролі Темного Списа заснували свій калімдорський дім на Островах Відлуння. Та могутній знахар на ім'я Залазан піддався божевіллю й обернув темну магію проти братів, поневоливши їхній розум. Уцілілі втекли на материк і заснували Село Сен'джин, звідки роблять вилазки, щоб зламати його хватку.",al={"що сталося з островами відлуння","чому село сен'джин","лор залазана"}},{q="Що Палаючий Клинок робить у Дуротарі?",a="Палаючий Клинок — підривний демонічний культ, вірний Раді Тіней і Палаючому Легіону. Його агенти чаяться у відлюдних місцях на кшталт Череп-скелі та Ковену Палаючого Клинка, намагаючись підірвати провід Тралла й спокусити вразливих орків назад у демонічне рабство.",al={"палаючий клинок дуротар","культисти череп-скелі","демони в дуротарі"}},{q="Що сполучає Дуротар з іншими краями?",a="Міст через Річку Південної Люті веде на захід, у Пустки. За Оргріммаром вежа цепелінів забезпечує міжконтинентальні перельоти просто до Галявин Тірісфалю і Базового Базового Табору Ґром'ґол у Долині Стренглторну.",al={"як покинути дуротар","подорожі з дуротару","виходи з дуротару"}}},fp="7,482,16.679.0,23.557.0,27.459.0,56.408.0,28.226.0,51.311.0,39.335.0,43.280.0,39.209.0"}
P.entries["zone:dustwallow"] = {n="Багно Пилоброду",s="Багно Пилоброду — величезні задушливі болота в центрі Калімдору, затиснуті між посушливими рівнинами Пусток і Великим морем. Його підступні драговини, які живлять невичерпні підземні джерела, ховають небезпечних хижаків, таємні сутички фракцій і зловісну присутність чорного драконячого роду. На сході тут стоїть острівна фортеця Альянсу Терамор, а на північному заході — Село Папоротяної Стіни, де живуть огри Кам'яного Молота, союзники Орди.",h="Багно Пилоброду — величезні задушливі болота в центрі Калімдору, затиснуті між посушливими рівнинами Пусток і...",kw={"багно пилоброду","терамор","оніксія","кам'яний молот","вірмове болото","село папоротяної стіни","огри"},ang={["class:Mage"]="Маги пробираються драговинами до Ферми Табети на Трясовині, шукаючи унікальних знань цієї відлюдниці про магічні канали й давні джерела сили.",["faction:Alliance"]="У Багні Пилоброду лежить Острів Терамор — серце присутності Альянсу в Калімдорі. Шукачі пригод, які прибувають через Гавань Менетіл, охороняють його греблі й розплутують клубок історій про дезертирів і зниклих посланців.",["faction:Horde"]="Посланці Орди приходять підтримати знеможених огрів Кам'яного Молота в Селі Папоротяної Стіни: вони відбивають напади драконів із Вірмового Болота й пильно стежать за пересуваннями людей на узбережжі."},sec={{t="Затоплений край",b="До Великого Розколу на місці Багна Пилоброду лежала висока трав'яниста рівнина, де паслися численні стада. Катаклізм розколов долину: ґрунтові води піднялися й затопили землю нескінченними стоячими калюжами, мохуватими мілинами й в'язкою багнюкою. Підземні джерела не дають болоту висохнути: тут завжди волого, все вкрите густим туманом і кишить кроколісками, рапторами й павуками. Підступні мілини й мандрівні трясовини роблять подорож небезпечною для кожного, хто зійде з розвалених гребель."},{t="Давня ворожнеча й хиткі перемир'я",b="Багно лишалося переважно диким до кінця Третьої війни, коли Леді Джайна Праудмур привела людей-біженців через море й заснувала на східному узбережжі цитадель на Острові Терамор. Невдовзі култираські війська на чолі з великим адміралом Дейліном Праудмуром пішли війною на молоду Орду Тралла; кривава битва прокотилася болотами й скінчилася поразкою адмірала. Нині між Терамором і Оргріммаром діє офіційне перемир'я, та під поверхнею тліє напруга. Терамор потерпає від дезертирства й диверсій, а шпигуни ведуть на драговинах тиху, смертоносну боротьбу."},{t="Тінь Вірмового Болота",b="Південь багна здіймається підступною кам'янистою трясовиною, відомою як Драконяча Мла та Вірмове Болото. Спершу тут оселилися огри Кам'яного Молота на чолі з героєм із народу мок'натал Рекссаром, але край перетворився на цвинтар, коли чорний драконячий рід жорстоко вигнав клан із Села Кам'яного Молота. Вигнані огри втекли на північ, до Села Папоротяної Стіни, під провід Володаря Мок'Морокка й присягнули помститися. Серед цих зубчастих скель ховається Оніксія, дочка Детвінга: вона керує своїм виводком і плете зловісні змови далеко за межами болота."}},faq={{q="Яке головне поселення Альянсу тут?",a="Осердя присутності Альянсу — Острів Терамор, укріплене місто-держава на скелястому острові біля східного узбережжя. Заснований Леді Джайною Праудмур після Третьої війни, він з'єднаний із Калімдором вузькою дорогою й тримає важливі морські шляхи до Гавані Менетіл у Східних Королівствах.",al={"база альянсу пилотрясина","де терамор","людське місто пилотрясина"}},{q="Де шукачі пригод з Орди можуть знайти прихисток у болоті?",a="Мандрівники Орди отаборюються в Селі Папоротяної Стіни на північному заході болота. Поселення заснував огрський клан Кам'яного Молота, що приєднався до Орди за Рекссара й відчинив брами союзникам-оркам і тауренам.",al={"база орди пилотрясина","де брекенвол","огрівське село"}},{q="Чому на півдні болота стільки чорних драконів?",a="Південна частина, відома як Вірмове Болото й Драконяча Мла, — гніздовища й володіння Оніксії, доньки Детвінга. Її чорні драконороди жорстоко вигнали огрів Кам'яного Молота й перетворили скелясті виступи та глибокі печери на гнізда для дракончат і молодих драконів.",al={"вірмове болото дракони","чому чорні дракони тут","драконяча мряка"}},{q="Що сталося з первісним домом огрів Кам'яного Молота?",a="Спочатку огри Кам'яного Молота мирно жили в Селі Кам'яного Молота на півдні болота. Проте чорна драконячий рід завдала нищівного удару, вирізала багатьох, а вцілілі мусили тікати на північний захід, до Села Папоротяної Стіни.",al={"руїни кам'яного молота","що сталося з селом кам'яного молота","старе огрівське місто"}},{q="Хто живе в самотній хатині на Трясовині?",a="Хатина належить Табеті, дивакуватій і могутній магині-відлюдниці, що тихо живе в глибинах болота. Чарівники часто шукають її, щоб повчитися чи попросити допомоги в очищенні непередбачуваних магічних реліквій.",al={"ферма табети","табета пилотрясина","хто відьма на болоті"}},{q="Що таке Острів Алказ і хто його контролює?",a="Острів Алказ — добре охоронюваний острів біля північно-східного узбережжя болота. Його тримають наги Страшаз, патрулюють небезпечні добірні захисники, а в довколишніх водах чатують гідри.",al={"острів алказ","острів біля пилотрясини","що на алказі"}}},fp="16,455,19.504.0,29.597.0,25.524.2,42.305.0,53.235.0,58.268.2,52.241.0,52.222.0,41.193.2"}
P.entries["zone:elwynn"] = {n="Ліс Елвінн",s="Ліс Елвінн — зелене серце королівства Стормвінд, що постачає столиці конче потрібні деревину, золото, рибу та збіжжя. Під покровом статечних листяних дерев він служить полігоном для новобранців з людей, що виходять з Абатства Нортшира. Та під ідилічним сільським склепінням ліс тяжко потерпає від погані, що насувається, зігнаної з місць звірини й повсюдного розбійництва.",h="Ліс Елвінн — зелене серце королівства Стормвінд, що постачає столиці конче потрібні деревину, золото, рибу та...",kw={"ліс елвінн","зона","люди","стормвінд","стартова локація","дефіас","кобольди","гноли"},ang={["class:Rogue"]="Всюдисуща тінь Братства Дефіас робить Елвінн захопливим перехрестям злодійства, контрабанди та підпільних сигналів бунтівників.",["faction:Alliance"]="Захист Елвінну життєво важливий для виживання головного людського королівства Альянсу: якщо шляхи постачання деревини, руди та збіжжя заваляться, Стормвінд не зможе себе прогодувати.",["profession:Mining"]="Ехо-Рідж, Фарґодіп і Яшмова копальня повні мідних жил, тож попри навалу кобольдів ліс — важливий перший полігон для шахтарів.",["race:Human"]="Це прадавнє серце королівства. Шукачі пригод з людей починають тут, навчаючись в Абатстві Нортшира, перш ніж вирушити боронити батьківщину від розбійників, звірів і політичного краху."},sec={{t="Житниця королівства",b="Елвінн, що тягнеться на південь від брами Стормвінда до річки Назферіті, — родючий край, щедро обдарований дощами й густими листяними лісами. Такі громади, як Ґолдшир і Лісозаготівельний Табір Східної Долини, дають столиці вкрай потрібні збіжжя, худобу, деревину та сиру мідь. Край також славиться витривалими евендейлськими кіньми, яких полюбляють мандрівники й лицарі по всьому королівству."},{t="Хиткий мир",b="Попри зовнішній спокій, ліс стоїть на межі безладу. Армія Стормвінда розтягнута далекими зобов'язаннями, і місцевим маршалам та помічникам доводиться покладатися на неперевірених новобранців. Кобольди заполонили важливі копальні Фарґодіп і Яшмову, гноли Річколапи нишпорять південно-західними кордонами, а дикі мурлоки захопили береги Озера Кам'яного Кургану й Кришталевого Озера. Через дедалі більше скверніння за річкою, у Сутінколіссі, вовки втекли на північ через кордон."},{t="Загроза червоних бандан",b="Значно організованіше за простих падложерів, Братство Дефіас глибоко проникло в ліс. Ці розбійники в масках походять із позбавленої прав Гільдії Каменярів Едвіна Венкліфа після гіркої суперечки про платню з Домом Вельмож; вони захопили володіння по всьому Елвінну, зокрема Виноградники Нортшира, Гарбузову Ділянку Брекуеллів, Пристань Джерода та Сад Дзеркального Озера. Ходять уперті чутки, що їхні злагоджені агенти нишком керують сусідніми гнолами й кобольдами, щоб іще дужче розхитати королівство. Вартових Рольфа й Малакая, посланих розслідувати появу мурлоків біля Озера Кам'яного Кургану, вбили й покинули на його берегах."}},faq={{q="Чому вартові Стормвінда майже не стежать за порядком у лісі?",a="Збройні сили Стормвінда вкрай перенапружені. Королівство розгорнуло великі військові сили на півдні, у Долині Стренглторну, наробивши глибоких боргів і висотавши місцеві людські ресурси. Тому застави на кшталт Гарнізону Вестбрук і Ґолдшира покладаються на жменьку вартових і новобранців-добровольців, щоб відбиватися від розбійників, гнолів і мурлоків.",al={"де вартові","чому немає армії стормвінда","чому елвінн беззахисний"}},{q="Чому в усіх копальнях кобольди?",a="Поки вартових бракувало, спритні кобольди заполонили Копальню Фарґодіп, Яшмову копальню та Шахту Ехо-Рідж у пошуках дорогоцінного золота й мінералів. Вони вигнали людей — шукачів і шахтарів — і люто боронять свої підземні володіння свічками, грубими кайлами та підібраним знаряддям.",al={"чому в копальнях кобольди","кобольди елвінну","фарґодіп заражений"}},{q="Хто ці розбійники в червоних масках?",a="Це члени Братства Дефіас на чолі з Едвіном Венкліфом. Багато з них спершу були ремісниками Гільдії Каменярів, яка відбудувала Стормвінд після Першої війни. Коли знать відмовилася виплатити обіцяну платню, спалахнули заворушення, що призвели до їхнього вигнання й скочування до організованого розбійництва.",al={"червоні маски","розбійники в червоних банданах","хто такі дефіас в елвінні"}},{q="Куди веде дорога на південь?",a="Перейшовши міст через річку Назферіті, ви потрапите до Сутінколісся, історично відомого як Світлолісся. Цей колись мирний край поринув у неприродну темряву й нині кишить нежиттю, жахливими павуками та ненажерливими звірами.",al={"що за річкою","куди веде міст до сутінколісся","міст через назферіті"}},{q="Що за ворожнеча між Маклюрами та Стоунфілдами?",a="Стоунфілди й Маклюри — сусідні фермерські родини на півдні Елвінну, що плекають гірку давню образу одна на одну. Попри нескінченні сварки й звинувачення, двоє їхніх молодших родичів — Мейбелл Маклур і Томмі Джо Стоунфілд — таємно покохали одне одного, ще дужче заплутавши суперництво.",al={"маклюри проти стоунфілдів","ворожнеча ферм елвінну","ворожнеча стоунфілдів і маклюрів"}},{q="Що таке Вежа Азори?",a="Вежа Азори — таємний шпиль при дорозі між Ґолдширом і Лісозаготівельним Табором Східної Долини. У ній живуть маги-відлюдники, зокрема Теокрітус, які спостерігають за лей-лініями краю й провадять магічні дослідження поза прямим наглядом Святилища Чародія в Стормвінді.",al={"вежа на дорозі до східної долини","чародійська вежа елвінн","хто живе у вежі азори"}}},fp="13,409,28.423.0,18.493.0,22.639.1,54.341.0,43.303.0,38.313.0,31.240.0,54.342.0,27.282.0"}
P.entries["zone:felwood"] = {n="Сквернолісся",s="Сквернолісся — сплюндрований ліс між Ашенвалем і Горою Гіджал, глибоко отруєний демонічною магією під час Третьої війни. Колись це був буйний рай лук і гаїв під опікою нічних ельфів, а тепер тут кишать демонічні сатири, скажені звірі й спотворені древні. Друїди Кола Кенарія разом із заставами Альянсу та Орди відчайдушно намагаються очистити землю й викорінити з її глибин Раду Тіней.",h="Сквернолісся — сплюндрований ліс між Ашенвалем і Горою Гіджал, глибоко отруєний демонічною магією під час...",kw={"сквернолісся","скверна","рада тіней","джеденар","коло кенарія","тіхондріус","череп ґул'дана"},ang={["class:Druid"]="Сквернолісся — глибока трагедія для Кола Кенарія: тут друїди присвячують життя очищенню отруєних рослин і заспокоєнню збожеволілих духів природи.",["class:Warlock"]="Темні тунелі Джеденару й рештки демонічних сил роблять Сквернолісся осередком полювання на суперників-культистів із Ради Тіней.",["profession:Herbalism"]="Просякнута скверною земля родить рідкісні й мінливі рослини: це одне з небагатьох місць Азероту, де можна зібрати Кров ґрома й Сльози Артаса.",["race:NightElf"]="Осквернення цих давніх лісів — джерело величезного горя й сорому для калдореїв, які не вберегли їх від дотику Легіону."},sec={{t="Сплюндрований рай",b="До Третьої війни ця долина була мирним прихистком співочих птахів, чистих струмків і тихих гаїв під охороною давніх захисників. Усе скінчилося, коли жахолорд Тіхондріус і Палаючий Легіон пустили в хід Череп Ґул'дана, щоб отруїти північ Калімдору перед наступом на Гору Гіджал. Мерзенні чари черепа перетворили лісову підстилку на почорніле трясовиння. Хоча Іллідан Стормрейдж зрештою вбив Тіхондріуса й поглинув силу артефакту, земля лишилася просякнутою скверною. Могутні деревні велетні й древні зогнили зсередини, річки обернулися на киплячу жовч, а лісові звірі в безумстві почали пожирати одне одного."},{t="Війна за очищення",b="Зцілення Сквернолісся йде болісно повільно. У Смарагдовому Святилищі на південному кордоні Коло Кенарія веде виснажливу боротьбу зі скверною. Друїди дають мандрівникам кенарійські маяки й очисні мазі та силкуються вилікувати отруєні рослини — співоцвіти й цибулини нічного дракона. Обидві фракції мають опорні пункти в отруєних нетрях: нічні ельфи — на Галявині Кігтегілки на півночі, а Орда — на Заставі Кривавої Отрути. Ці застави — крихкі оплоти серед смертоносної дикої місцини, де сама природа повстала проти всього живого."},{t="Тінь у Джеденарі",b="Залишкову скверну старанно плекають темні культисти. У підземному лабіринті Джеденару й Твердині Тіні рештки Ради Тіней правлять мерзенні обряди під проводом Лорда Бейнголлоу. У союзі з підступними сатирами, що оскверняють давні місячні колодязі, ці чорнокнижники черпають силу з агонії лісу й викликають демонічне підкріплення. Щоб урятувати Сквернолісся, цю підступну раду доведеться вирвати з корінням."}},faq={{q="Чому Сквернолісся спотворене?",a="Під час Третьої війни жахолорд Тіхондріус за допомогою демонічного артефакту, відомого як Череп Ґул'дана, спотворив ліс. Так він хотів послабити оборону нічних ельфів, поки Палаючий Легіон ішов на Гору Гіджал, і отруїв звірів, воду й древніх.",al={"як скверноліс зіпсувався","що сталося зі сквернолісом","чому дерева мертві"}},{q="Чи можна очистити спотворені рослини лісу?",a="Так. Друїди Кола Кенарія дають шукачам пригод мазі, зварені із зібраних осадів скверни й мінеральних решток. Якщо помазати ними рослини, як-от співоцвіт, батіжні бульби чи нічних драконів, вони очищаються від спотворення й дають могутні цілющі плоди й благословення.",al={"як очистити рослини","рослинна мазь кенарія","зіпсована пісенна квітка"}},{q="Хто контролює Джеденар?",a="Джеденар тримає Рада Тіней — таємна секта смертних чорнокнижників і поклонників демонів. З глибин підземних печер Твердині Тіні жахолорд Лорд Бейнголлоу наглядає за їхніми темними ритуалами й командує сатирами краю.",al={"що таке джеденар","хто в твердині тіні","бос джеденара"}},{q="Чи ворожі фурболги в Скверноліссі?",a="Здебільшого так. Такі племена, як Мертве Дерево, цілком піддалися демонічному спотворенню й безумству скверни. Проте плем'я Деревопащих, що тримає північну мережу тунелів, лишається незіпсованим, хоча глибоко не довіряє чужинцям, доки ті не доведуть своєї дружби.",al={"фурболги сквернолісу","деревопащі фурболги","село мертволісся"}},{q="Як дістатися через Сквернолісся до Місячного Гаю чи Вінтерспрінга?",a="Дорога веде на північ просто до Твердині Деревопащих — укріпленого печерного комплексу. Незіпсовані фурболги Деревопащих контролюють тунелі, що з'єднують Сквернолісся з Місячним Гаєм і Вінтерспрінгом. Мандрівники мусять або здобути їхню довіру, або пробиватися з боєм.",al={"тунель деревопащих","дорога до вінтерспрінга","прохід до місячної поляни"}},{q="Чому спотворені древні нападають на нічних ельфів?",a="Колись шляхетних древніх і деревнів спотворила й отруїла демонічна магія. Скуті вічною мукою, вони своїм розтрощеним розумом плекають глибоку образу на нічних ельфів, які, на їхню думку, покинули їх на поталу Палаючому Легіону.",al={"скажені ентів","зіпсовані прадавні","чому прадавні ворожі"}}},fp="7,424,19.653.0,21.569.0,22.458.1,25.279.0,51.281.0,22.263.0,36.267.0,60.250.0,49.238.0"}
P.entries["zone:feralas"] = {n="Фералас",s="Фералас — величезний, оповитий туманом дощовий ліс між Пустограєм, Тисячею Голок і Прихованим Морем. Під захистом високих гірських стін тут зберігся прадавній світ, усіяний зарослими руїнами калдореїв і первісними звірами. Нині ці нетрі — спірна територія, за яку змагаються рештки давніх Високородних, огри Ґордунні, що вдерлися сюди, і суперницькі застави Альянсу та Орди.",h="Фералас — величезний, оповитий туманом дощовий ліс між Пустограєм, Тисячею Голок і Прихованим Морем.",kw={"фералас","лютопащ","ельдре'талас","ґордунні","твердиня перистого місяця","табір моджаче","Високородні"},ang={["class:Druid"]="Віття Сну та його зв'язок зі Смарагдовим Сном роблять Фералас священною землею, тож вам слід пильно стерегтися скверни, що підступає, і тих, хто сіє осквернення.",["faction:Alliance"]="Альянс діє з Твердині Перистого Місяця під проводом Шандріс Фезермун: її бійці патрулюють узбережжя від наг і боронять спадщину ельфів.",["faction:Horde"]="Табір Моджаче — важливий прикордонний оплот, якому потрібні надійні воїни, щоб відбивати напади огрів Ґордунні, свавільних тауренів Ґрімтотему й гнолів Лісолапів.",["profession:Herbalism"]="Волога, затінена лісова підстилка родить цінні рослини помірного й тропічного клімату, зокрема Сонцетрав'я, Фіолетовий Лотос і Вус Хадґара.",["race:NightElf"]="Фералас має глибоке значення для вашого народу як колиска давньої калдорейської цивілізації, і вигляд святих руїн на кшталт Ельдре'Таласу, осквернених ограми, будить у серці глибоку скорботу й гнів."},sec={{t="Ліс, якого не торкнулася пустеля",b="Поки сусідні Пустограй і Тисяча Голок висохли на голі пустки й спраглі каньйони, Фералас і далі буяє зеленню. Гірські хребти замикають лісовий покрив, підтримуючи теплий клімат із густими туманами, давніми деревами й високими водоспадами. До Великого Розколу так виглядала більша частина Калімдору. За тисячоліття густі джунглі поглинули пам'ятки калдорейської цивілізації, що колись тут панувала, сховавши забуті храми й павільйони під задушливим мохом і густою папороттю."},{t="Руїни Ельдре'Таласу",b="Посеред Фераласу здіймаються руїни величного міста Ельдре'Талас, яке нині звуть Лютопащем. Збудоване в часи розквіту калдорейської імперії, воно стоїть занедбане: його величезні кам'яні двори осквернив дикий клан огрів Ґордунні. Ці огри розлізлися долиною, грабуючи святі місця, плюндруючи незаймані гаї й доводячи місцевих звірів до шаленства. А в запечатаних залах Лютопаща, кажуть, досі ховаються рештки Високородних і замкнені сили десятитисячолітньої давнини."},{t="Боротьба за плацдарми",b="І Альянс, і Орда спорядили великі експедиції в джунглі, хоча мандрувати ними досі небезпечно. З Твердині Перистого Місяця на Острові Сардор генерал Шандріс Фезермун спрямовує Вартових проти огрів і проти наг, що підступають із моря. На сході лежить Табір Моджаче — головний гарнізон Орди, який відбивається від агресивних гнолів Лісолапів, ворожих тауренів Ґрімтотему й невгамовних огрів. Жодна з фракцій по-справжньому не контролює неприборкане нутро краю."}},faq={{q="Що таке Лютопащ?",a="Лютопащ — теперішня назва Ельдре'Таласу, славетного ельфійського міста, що пережило Розкол. За тисячоліття воно занепало, і його заполонив жорстокий клан Ґордунні. Нині комплекс поділений на спірні крила, де ховаються огри, підступні духи й прадавні таємниці Високородних.",al={"елдре'талас","огрове місто","давні руїни в центрі"}},{q="Як мандрівникам Альянсу безпечно дістатися до Твердині Перистого Місяця?",a="Дослідники Альянсу з Пустограю можуть пройти на південь повз Колосів-Близнюків, хоча звірі там небезпечні. Або ж можна зайти в море біля Узбережжя Сар'теріс у Пустограї й пливти на південь уздовж Забутого Узбережжя просто до Острова Сардор, цілком оминаючи небезпечну суходільну дорогу й Табір Моджаче.",al={"шлях до перистого місяця","вхід альянсу у фералас","як альянсу потрапити у фералас"}},{q="Чому Орда так завзято воює з ограми Ґордунні?",a="Огри Ґордунні агресивно розселяються з Лютопаща, грабують обози й нападають на мандрівників по всіх джунглях. Їхні загарбницькі ватаги загрожують Табору Моджаче, тож провідники Орди, як-от Белґром Рокмол, закликають завдавати швидких, рішучих ударів по заставах клану.",al={"чому вбивати ґордунні","орда проти огрів","огри табору моджаче"}},{q="Що таке Віття Сну?",a="Віття Сну — одне з чотирьох Великих Дерев Азероту, де є містичний природний портал, що з'єднує фізичний світ зі Смарагдовим Сном. Як і його побратимів в Ашенвалі, Сутінколіссі й Пригір'ї, його стережуть зелена драконячий рід й прадавні вартові.",al={"портал зелених драконів","велике дерево фераласу","дерево смарагдового сну"}},{q="Чому у Фераласі є таурени Ґрімтотем?",a="Відступницька секта тауренів Ґрімтотем тримає в глушині власне поселення, не підкоряючись владі Тандер Блафа. Вони ворожі і до Альянсу, і до Орди: ловлять місцевих чарівних дракончиків, і розвідники Орди активно на них полюють.",al={"ґрімтотеми фералас","поселення ґрімтотем","ворожі таурени"}},{q="Чи є у Фераласі силітиди?",a="Так. На південь від головної дороги лежить Звивиста Глибина — підземний вулик, що аж кишить силітидами. Їхня поява в буйному вологому лісі — тривожний знак того, що вулик розростається далеко за пустельні межі південного Калімдору.",al={"звивиста глибина","комахи фераласу","вулик силітидів"}}},fp="7,414,32.516.0,25.502.0,26.486.0,18.309.0,62.340.0,61.302.0,24.275.0,44.273.0,30.249.0"}
P.entries["zone:gnomeregan"] = {n="Гномреґан",s="Гномреґан, вирізаний у засніжених передгір'ях Дун Мороґу, колись був підземною столицею й найбільшим технічним дивом гномів. Сьогодні він лежить у руїнах і на карантині, отруєний радіоактивними викидами після відчайдушної оборони від підземної навали трогів. Уцілілі гноми живуть як біженці в сусідньому Айронфорджі, а опромінені зали заполонили мутовані троги, шалені гноми-прокажені й некеровані механічні вартові.",h="Гномреґан, вирізаний у засніжених передгір'ях Дун Мороґу, колись був підземною столицею й найбільшим...",kw={"гномреґан","гноми","термаплаґ","меккаторк","троги","радіація","підземелля"},ang={["faction:Alliance"]="Гноми стояли пліч-о-пліч з Альянсом у Другій війні, тож визволення їхньої втраченої столиці від Термаплаґа вкрай важливе, щоб повернути їм силу в лавах Альянсу.",["profession:Engineering"]="Зруйноване місто — неперевершене кладовище досконалих шедеврів, креслень і експериментальних пристроїв: серед смертельного механічного хаосу тут можна знайти безцінні креслення.",["race:Dwarf"]="Ваша спорідненість із гномами сягає часів, коли ваші предки допомагали закладати фундаменти Гномреґана, а ваші ж розкопки в Ульдамані ненавмисно випустили орди трогів, які й спричинили його загибель.",["race:Gnome"]="Гномреґан — серце найглибшої трагедії й незагойного сорому вашого народу; спуститися туди — моторошне паломництво, щоб помститися за вісімдесят відсотків полеглих родичів і скинути зрадника Термаплаґа."},sec={{t="Диво із заліза й пари",b="Задовго до трагічного падіння Гномреґан був свідченням вершин гномського генія, честолюбства й працьовитості. Збудований за допомоги сусідніх дворфів Айронфорджа, розлогий механічний комплекс живився велетенськими гуркітливими двигунами, вихором шестерень і складною мережею вентиляції, яку цілодобово обслуговували п'ятнадцять техніків — лише щоб підтримувати свіже повітря. Це був квітучий осередок винахідництва, змагань у ремеслі й політики, зосередженої в Дворі Майстрів, — горда столиця, звідки гноми під час Другої війни постачали Альянсові Лордерона безцінні облогові машини, літальні апарати й озброєння."},{t="Навала трогів і отруєння",b="Приблизно тоді, коли під час Третьої війни Погибель спустошувала Лордерон, під Дун Мороґом заворушився підземний кошмар. Необачні розкопки дворфів у давньому сховищі титанів Ульдаман розбудили орди первісних трогів, і ті прорили ходи до нижніх фундаментів Гномреґана. Не бажаючи обтяжувати Альянс проханнями про допомогу в скрутну для нього годину, Великий Тінкер Ґелбін Меккаторк і його сили п'ять років вели виснажливу війну на знищення проти загарбників. Коли оборона завалилася, Меккаторк піддався порадам свого головного радника, Мехінженера Сікко Термаплаґа, і дозволив випустити радіоактивні відходи міських резервуарів у нижні рівні, щоб винищити трогів. Натомість отруйний газ спричинив некеровану катастрофу, за кілька днів забравши життя майже вісімдесяти відсотків гномів."},{t="Зрада божевільного мехінженера",b="Катастрофа не була механічним нещасним випадком. Сікко Термаплаґ, якого гризла заздрість через обрання Меккаторка Великим Тінкером, навмисне дав навалі розростися й підготував отруйну катастрофу, плануючи потім з'явитися, перебити трогів і очолити вцілілих. Натомість лихо вийшло з-під його контролю. Радіація не вбила трогів, а лише довела їх до шаленої люті, а сам Термаплаґ опинився в пастці на заражених нижніх ярусах. Спотворений радіаційною хворобою на божевільного гнома-прокаженого, Термаплаґ коронував себе техноволодарем Гномреґана й командує бездумними прокаженими та непередбачуваними машинами зі свого трону в Дворі Майстрів."},{t="Хитка перемога",b="Нині Великий Тінкер Меккаторк керує поверненням Гномреґана з Містечка Майстрів в Айронфорджі, посилаючи шукачів пригод з Альянсу в отруйні глибини, щоб зламати владу Термаплаґа. Смерть Мехінженера в серці Двору Майстрів руйнує його владу над некерованою обороною й загонами прокажених і приносить довгоочікувану помсту за його величезну зраду. Та остаточне повернення міста лишається недосяжним: глибші тунелі досі задушені опроміненим мулом, мутованими звірами й трогами, тож Меккаторкові доводиться збирати гіробуроматичні екскаваторатори й розробляти ширші військові плани, щоб колись повернути прадавню домівку свого народу."}},faq={{q="Чому Гномреґан опромінений?",a="Коли з-під землі вторглися троги, Великий Тінкер Ґелбін Меккаторк за порадою Сікко Термаплаґа спробував винищити їх, відкривши клапани тиску на міських резервуарах із радіоактивними відходами. Задум був затопити лише нижні сектори, але смертоносна отруйна радіація просочилася по всьому місту, вбивши вісімдесят відсотків гномів і спотворивши тих, хто вижив.",al={"що сталося з гномреґаном","чому гномреґан зелений","радіація в гномреґані"}},{q="Звідки взялися всі ці троги?",a="Троги — прадавні створіння, яких розбудили з глибокого підземного сну дворфійські археологічні розкопки в комплексі титанів Ульдаман. Принаджені вібраціями й теплом важких машин Гномреґана, вони прорили розгалужені мережі тунелів просто в нижні рівні й інженерні квартали міста.",al={"чому тут трогги","походження троггів","навала троггів"}},{q="Чому гноми не попросили Альянс про допомогу проти трогів?",a="Навала трогів сталася в розпал Третьої війни, коли Королівство Лордерон падало під ударами Погибелі. Вважаючи виживання всього Альянсу важливішим, Великий Тінкер Меккаторк вирішив не відволікати людські, дворфійські чи ельфійські сили з північних фронтів і спробував упоратися з навалою власними силами — гномською технікою й вояками.",al={"чому альянс не допоміг гномреґану","чи альянс покинув гномів"}},{q="Хто такі прокажені гноми?",a="Прокажені гноми — це гноми, що пережили радіоактивний викид у Гномреґані, але від тривалого опромінення зазнали тяжких фізичних і розумових спотворень. Їхня шкіра стала хворобливо-блідо-зеленою, тіла вкриті пухирями й виразками, а розум занепав до шаленої кровожерної манії під владою Мехінженера Термаплаґа.",al={"чому гноми зелені й божевільні","опромінені гноми","лор прокажених гномів"}},{q="Хто такий Сікко Термаплаґ?",a="Сікко Термаплаґ був найближчим довіреним і головним радником Великого Тінкера Меккаторка. Збожеволілий від заздрощів і жаги влади, він навмисно влаштував радіоактивне очищення, щоб занапастити Меккаторка й захопити трон. Опромінений разом із містом, він нині править як безумний прокажений деспот із Двору Майстрів.",al={"термаштепсель","хто останній бос","мехінженер термаштепсель"}},{q="Що зміниться, коли Мехінженера Термаплаґа буде переможено?",a="Перемога над Термаплаґом позбавляє прокажених гномів і збунтовану оборону проводу, дає змогу врятувати важливі технічні дані й неабияк підносить дух гномів. Проте місто вона одразу не очищує. Смертоносна радіація й густі зграї трогів досі душать нижні коридори, тож Меккаторк мусить готувати глибші розкопки, перш ніж стане можливим повне відвоювання.",al={"чи ми відвойовуємо гномреґан","що буде коли термаштепсель помре","чи гномреґан врятований"}},{q="Чому в Гномреґані дворфи Темного Заліза?",a="Ворожий клан Темного Заліза послав у Гномреґан своїх посланців на чолі з Послом Темного Заліза. Завжди охоче шкодячи Айронфорджу й Альянсу, Темне Залізо шукає вигідного союзу з Термаплаґом, сподіваючись використати гномську техніку й бойові машини для власних воєн.",al={"посол темного заліза","чому темне залізо в гномреґані","дворфи в гномреґані"}},{q="Де нині живуть уцілілі гноми?",a="Після радіоактивної катастрофи вцілілі незаражені гноми втекли горами до Айронфорджа. Їхні дворфійські родичі дали їм притулок у Містечку Майстрів — інженерному кварталі в гірській фортеці, де Ґелбін Меккаторк править своїм народом у вигнанні, плануючи повернення додому.",al={"де живуть гноми","місто гномів","біженці в айронфорджі"}}},fp="10,464,26.669.0,36.818.0,27.701.1,17.647.1,29.409.0,35.313.0,67.382.0,22.335.0,25.321.0,53.396.1,48.315.0,42.319.0"}
P.entries["zone:hallofthanes"] = {n="Зала Танів",s="Глибоко під гамірним містом Айронфордж лежить Зала Танів — давній підземний комплекс, просякнутий історією дворфів. Це відлюдне підземелля для шукачів пригод з Альянсу на початку їхнього шляху: тут зберігаються реліквії минулого гірського королівства, яким нині загрожує небезпека. Щоб потрапити всередину, доведеться віднайти забуті шляхи крізь саму гору.",h="Глибоко під гамірним містом Айронфордж лежить Зала Танів — давній підземний комплекс, просякнутий історією...",kw={"зала танів","айронфордж","дворфи","дурґен дерджгаммер","підземелля","карта підземелля"},ang={["faction:Alliance"]="Стабільність Айронфорджа прямо зміцнює Альянс, тож очищення цих глибоких печер украй важливе для безпеки Високого Престолу.",["race:Dwarf"]="Для дворфів спуск до Зали Танів — мандрівка в саму прадавню основу Дун Мороґу, щоб вичистити оскверників зі священних залів, які носять легендарні імена кланів.",["race:Gnome"]="Як близькі союзники, що живуть в Айронфорджі, гноми також кровно зацікавлені знешкодити механізми на кшталт Здобичі, що загрожують їхньому спільному прихистку."},sec={{t="Таємниці під горою",b="Поки Айронфордж гуде дзвоном молотів у Великій Кузні, забуті зали сягають значно глибше в камінь. Зала Танів — один із цих шанованих підземних куточків. Здавна пов'язана з родами предків-дворфів і реліквіями майстрів каменю, тепер вона потребує відважних героїв Альянсу, які зважаться спуститися в її темні склепіння й убезпечити глибини."},{t="Пошуки шляху",b="Потрапити до Зали Танів непросто. Коридори, що ведуть до цих давніх склепінь, замуровані або сховані від звичайних мандрівників Айронфорджа. Шукачі пригод мають розібратися в забутих мапах — і почати з того, щоб здобути Карту Підземелля, — перш ніж вони зможуть пройти глибшими тунелями й переступити поріг підземелля."},{t="Загроза Дерджгаммера",b="У серці комплексу зібралися грізні загрози — від зачарованих охоронців на кшталт Здобичі та вогняного громила Магматуса до ренегатів давнього дворфійського роду на кшталт Фалдріма Анвілмара. Над внутрішнім святилищем панує Дурґен Дерджгаммер, і лише його поразка нарешті вгамовує неспокій, що визріває під містом, і вберігає священні дворфійські зали від підривних сил."}},faq={{q="Де розташована Зала Танів?",a="Зала Танів міститься під дворфійською столицею Айронфорджем. Вона захована в глибших підземних секторах гори з обмеженим доступом, а не на головних міських вулицях.",al={"розташування зали танів","де зала танів","підземелля айронфорджа"}},{q="Як потрапити до Зали Танів?",a="Щоб відкрити це підземелля, треба пройти ланцюжок завдань-допуску. Шукачі пригод починають із завдання «Підземна мапа», щоб прокласти шлях до нижніх сховищ гори.",al={"як зайти в залу танів","допуск до зали танів","завдання підземної мапи"}},{q="Які боси є в Залі Танів?",a="Експедицію чекають чотири головні загрози: Фалдрім Анвілмар, вулканічний велетень Магматус, зачарований голем на ім'я Здобич і останній супротивник — Дурґен Дерджгаммер.",al={"список босів","хто боси","боси зали танів"}},{q="Який рівень рекомендовано для цього підземелля?",a="Підземелля розраховане на шукачів пригод Альянсу 13–18 рівнів і слугує раннім підземним випробуванням у глибинних ходах Айронфорджа.",al={"який рівень зали танів","діапазон рівнів зали танів"}},{q="Чи можуть гравці Орди потрапити до Зали Танів?",a="Ні. Зала Танів — підземелля лише для Альянсу, розташоване просто під столицею Альянсу Айронфорджем.",al={"чи орда може в залу танів","чи зала танів лише для альянсу"}},{q="Чого досягає перемога над Дурґеном Дерджгаммером?",a="Здолавши Дурґена Дерджгаммера, ви ламаєте владу збунтованих дворфійських сил і їхніх викликаних конструктів глибоко в підвалинах Айронфорджа. Його загибель повертає безпеку прадавнім родовим сховищам під Великою Кузнею.",al={"чому вбити дерджгаммера","сюжет останнього боса","дурґен дерджгаммер лор"}}},fp="14,344,28.365.0,19.340.0,25.399.1,36.188.0,43.182.0,42.174.0,49.153.0,43.116.0,47.227.1"}
P.entries["zone:hillsbrad"] = {n="Передгір'я Гілсбреда",s="Передгір'я Гілсбреда — зелений, родючий край, останній пасторальний оплот занепалого королівства Лордерон. Хоч його здебільшого оминула чума Погибелі, землю роздирає жорстока відкрита війна між людьми Саутшора й Відступниками, що окопалися в Таррен Міллі. Це криваве перехрестя, де армії Альянсу й Орди сходяться без жалю.",h="Передгір'я Гілсбреда — зелений, родючий край, останній пасторальний оплот занепалого королівства Лордерон.",kw={"передгір'я гілсбреда","саутшор","таррен мілл","дурнгольд","лордерон","альянс","орда"},ang={["class:Rogue"]="Високо в горах над передгір'ям ховається Маєток Рейвенголдт — таємне місце зборів і вишколу найелітнішої гільдії злодіїв і вбивць Азероту.",["race:Dwarf"]="Вояки Дун Ґарока втілюють непохитну військову відданість Айронфорджа справі захисту союзників-людей і стримування загрози нежиті на північ від Багнокраю.",["race:Human"]="Саутшор — один з останніх прихистків вашого народу в Лордероні; ходити цими пасовищами — болюче нагадування про велике королівство, втрачене через зраду й нежиття.",["race:Orc"]="Ця земля має величезне значення для вашого народу: у зруйнованих мурах Твердині Дурнгольд Вождь Тралл розірвав кайдани й пробудив дух Орди.",["race:Undead"]="Таррен Мілл — опора південного прикордоння королівства Відступників, де Аптекар Лайдон невтомно працює над Новою чумою, щоб забезпечити майбутнє вашого народу."},sec={{t="Сад поруч із руїнами",b="Поки північний Лордерон гниє під пошестю Погибелі, Гілсбред лишається напрочуд зеленим. Його пологі пасовища, соснові гаї й діючі ферми дають мандрівникам рідкісну змогу побачити, яким було королівство до Третьої війни. Та цей мирний вигляд оманливий. Тихими полями й сільськими дорогами раз у раз прокочуються озброєні патрулі, найманці-ренегати й звірі-падальники. Те, що мало бути житницею Лордерона, стало натомість його найспірнішим прикордонням."},{t="Війна Саутшора й Таррен Мілла",b="Політичне серце Гілсбреда визначають дві вкорінені твердині. На півдні, на узбережжі, лежить Саутшор — прихисток Альянсу, населений людьми-біженцями й вояками, затято відданими Альянсу. На півночі стоїть Таррен Мілл — колись тихе людське хліборобське село, яке винищила Погибель, а згодом Відступники укріпили як свій найпівденніший гарнізон. Відкрита місцевість між двома поселеннями відома на весь Азерот як нещадна смуга смерті, де герої Альянсу й Орди ведуть нескінченні сутички за владу над краєм."},{t="Старі шрами й приховані загрози",b="Історія насильства в Гілсбреді сягає глибоко. Під час Другої війни його узбережжя й пагорби бачили перші масштабні зіткнення Великого Альянсу зі Старою Ордою. Пізніше у Твердині Дурнгольд був табір для інтернованих, де виріс Тралл, перш ніж очолити повстання орків. Сьогодні Дурнгольд лежить у руїнах, захоплений Синдикатом — вигнаними людськими вельможами, що стали розбійниками й головорізами. Прибережні мурлоки, ворожі гноли й темні мерці на Острові Спокути дбають про те, щоб жоден куточок пагорбів не був по-справжньому безпечним."}},faq={{q="Чому Гілсбред не спаплюжений, як решта Лордерона?",a="Погибель наступала переважно центральними шляхами до столиці й північних королівств, тож Гілсбред здебільшого оминули чумні казани, що занапастили північ. Тому ґрунт тут лишається родючим, а рослинність — здоровою, і це найнезайманіший клапоть давнього Лордерона.",al={"чому гілсбред зелений","чи гілсбред заражений","чому в гілсбреді немає чуми"}},{q="Хто зараз контролює Гілсбред?",a="Жодна фракція не має повного контролю. Альянс тримає Саутшор і ферми поблизу, як-от Поля Гілсбреду, а Відступники — Таррен Мілл на півночі. Дворфійські сили утримують фортецю Дун Ґарок на сході, а злочинний Синдикат займає руїни Твердині Дурнгольд.",al={"хто володіє гілсбредом","контроль фракцій гілсбреду","чи гілсбред альянсу чи орди"}},{q="Що таке Твердиня Дурнгольд?",a="Колись Дурнгольд був штабом системи таборів для інтернованих Альянсу після Другої війни. Ним керував Еделас Блекмур, що виростив там Тралла як раба-гладіатора. Тралл утік, згуртував орків і спустошив фортецю. Після падіння Лордерона руїни зайняв Синдикат.",al={"лор дурнгольда","що сталося в дурнгольді","хто керує дурнгольдом"}},{q="Чому Відступники й люди так запекло воюють тут?",a="Таррен Мілл — південний рубіж володінь Сильвани Віндраннер, а Саутшор — головний плацдарм і порт Альянсу в Лордероні. Відступники вважають Саутшор смертельною загрозою своєму південному флангу, а люди вважають нежить жахливими узурпаторами, яких треба вигнати з рідної землі.",al={"війна саутшора","саутшор проти таррен мілла","причина конфлікту гілсбреду"}},{q="Що таке Острів Спокути?",a="Острів Спокути — відлюдний скелястий острів біля південного узбережжя Гілсбреда. На відміну від пагорбів на суходолі, острів кишить могутніми гулями, скелетами й мстивими духами, тож це надзвичайно небезпечний прихисток темної магії й неприкаяних мерців посеред моря.",al={"лор острова спокути","острів біля саутшора","чому нежить на острові спокути"}},{q="Хто ці бандити, що займають табори й вежі?",a="Вони належать до Синдикату — організованої мережі колишньої знаті й піхотинців із занепалого людського королівства Альтерак. Вигнані через зраду свого королівства в Другій війні, вони тепер діють як безжальні бандити, прагнучи повернути свої землі шантажем, крадіжками й різаниною.",al={"бандити гілсбреду","хто синдикат","синдикат у гілсбреді"}}},fp="19,398,25.489.0,37.558.0,28.528.0,56.305.0,33.287.0,23.316.0,54.333.0,23.275.0,51.299.0"}
P.entries["zone:hinterlands"] = {n="Пригір'я",s="Пригір'я — суворий, густо зарослий лісом край на сході Лордерону, затиснутий між Чумними Землями й морем. Його обличчя визначають руїни давніх храмів тролів Амані, високі гнізда клану Вайлдгаммерів на Орлиному Піку й велетенське Велике Дерево, в якому ховається загадковий розлом у Смарагдовий Сон.",h="Пригір'я — суворий, густо зарослий лісом край на сході Лордерону, затиснутий між Чумними Землями й морем.",kw={"пригір'я","орлиний пік","вайлдгаммери","тролі амані","джинта'алор","серадейн","ревантуски"},ang={["class:Druid"]="Давнє дерево Серадейн глибоко пов'язане зі Смарагдовим Сном, але гниль Жахіття, що підкрадається, вимагає від вас пильної уваги.",["faction:Alliance"]="Хоча дворфи-вайлдгаммери дорожать своєю гордою незалежністю, допомога їхнім заставам і високим ельфам Кель'Даніла здобуває цінну прихильність у боротьбі зі спільною загрозою тролів.",["faction:Horde"]="Селище Ревантусків дає Орді важливий плацдарм на сході північного Лордерону, але щоб вижити тут, доведеться відбиватися від лютого племені Гидогілок.",["race:Dwarf"]="І для родичів-вайлдгаммерів, і для гостей-бронзбірдів Орлиний Пік — це дворфійське життя без кам'яної стелі над головою: високе небо, шаманська сила й легендарні грифони.",["race:Troll"]="Пригір'я зберігає давню славу Амані: тут роди тролів б'ються на сходах прадавніх храмів, а Ревантуски доводять, що лісові тролі мають тривке місце в Новій Орді."},sec={{t="Земля спірних прав",b="Задовго до того, як на півночі Лордерону ступили люди чи дворфи, Пригір'ям володіли лісові тролі Імперії Амані. Після поразки в давніх Тролячих війнах їхня імперія розпалася на розрізнені племена. Століттями пізніше, коли трагічна Війна Трьох Молотів вигнала дворфів-вайлдгаммерів із Ґрім Батолу, ті подалися на північ і оселилися на поверхні, на Орлиному Піку. Приручивши місцевих грифонів і прийнявши шаманські традиції, Вайлдгаммери звели величезну твердиню під самим небом. Тролі вважали цих дворфів, що жили на поверхні, непроханими зайдами на землях предків, і так спалахнула нескінченна ворожнеча сутичок і набігів."},{t="Лісові племена",b="Густі хащі й руїни кам'яних храмів займають три окремі угруповання лісових тролів. Найсильніше з них — жорстоке й фанатичне плем'я Гидогілок, що тримає розлогі твердині в терасованому місті-храмі Джинта'Алор і біля високого Вівтаря Зула. На півдні слабше плем'я Сухокорих чіпляється за Шадра'Алор і Гірі'Вату. Кочове плем'я Ревантусків, яке родичі довго зневажали і яке не мало справжнього дому, після Третьої війни обрало радикальний шлях: уклало договір із Новою Ордою Тралла. За підтримки орків і Відступників Ревантуски заснували Селище Ревантусків на східних морських кручах і вибороли собі зухвалий прибережний оплот."},{t="Сплячий розлом",b="In the northern reaches of the Hinterlands stands Seradane, a colossal Great Tree sheltering a portal to the Emerald Dream. Deep within its boughs sits a massive mystical portal opening into the Emerald Dream, guarded by creatures of nature and members of the green dragonflight. However, a creeping shadow known as the Emerald Nightmare has begun to seethe across the portal's threshold, twisting once-benevolent drakes and dragonspawn into furious guardians of the grove."}},faq={{q="Як дістатися до Пригір'я?",a="І мандрівники Альянсу, і мандрівники Орди йдуть із Передгір'їв Гілсбреда на північний схід гірським перевалом за Твердинею Дурнгольд. Звідти мандрівники Альянсу йдуть дорогою до Орлиного Піку, а шукачі пригод з Орди перетинають глушину на схід, аж до Селища Ревантусків на східному узбережжі.",al={"вхід у пригір'я","як зайти в пригір'я","дістатися до пригір'я"}},{q="Хто править Орлиним Піком?",a="Фалстад Вайлдгаммер, володар Орлиного Піку, очолює тут клан Вайлдгаммер. Під час Другої війни кланом керував Тан Курдран Вайлдгаммер.",al={"лідер вайлдгаммерів","хто очолює вайлдгаммерів","правитель орлиного піку"}},{q="Чому тролі Ревантуск у союзі з Ордою?",a="На відміну від ворожих племен Лихогіллів і Сухокорів, що відкинули посланців Орди, кочове плем'я Ревантуск шукало захисту й кінця блуканням. Нова Орда дала їм потрібні ресурси й вояків, щоб звести на узбережжі Селище Ревантусків, і завоювала люту вірність племені проти місцевих суперників.",al={"ревантуск орда","чому тролі в орді в пригір'ї","лор ревантуска"}},{q="Що таке Джинта'Алор?",a="Джинта'Алор — величезна багатоярусна прадавня троляча фортеця, вирубана в південних скелях. Це головний оплот безжального племені Лихогіллів, де повно мерзенних жертовних вівтарів, добірних воїнів і знахарів, що правлять криваві обряди на служіння своїм темним лоа.",al={"лор джинта'алор","троляче місто пригір'я","місто мерзенної гілки"}},{q="Що це за Велике Дерево в Серадейні?",a="Серадейн — одне з Великих Дерев Азероту, що прихищає портал до Смарагдового Сну. Гай стережуть зелені дракони й дикі місячники.",al={"портал серадейн","велике дерево пригір'я","зелений дракон пригір'я"}},{q="Що таке Ложа Кель'Даніл?",a="Ложа Кель'Даніл — лісовий притулок високих ельфів із Гайвейлу. Уникнувши прямого удару Погибелі по Кель'Таласу, ці рейнджери й учені співпрацюють із сусідніми дворфами Вайлдгаммер і діляться важливими відомостями про ворожих лісових тролів.",al={"висока ложа ельфів пригір'я","кель'даніл","ельфи пригір'я"}}},fp="15,316,25.673.0,20.653.0,19.473.1,32.304.0,21.132.0,51.310.0,20.285.0,35.131.0,25.266.0"}
P.entries["zone:ironforge"] = {n="Айронфордж",s="Айронфордж, висічений у серці гори Айронфордж у засніженому Дун Мороґу, — родова столиця дворфів Бронзбірдів і неприступний бастіон Альянсу. Це розлоге підземне місто, у центрі якого пашить жаром Велика Кузня, — гамірний осередок торгівлі, ремесла й давніх дворфійських переказів. Під непохитною владою Короля Маґні Бронзбірда воно нині прихищає й гномів, вигнаних із сусіднього Гномреґана.",h="Айронфордж, висічений у серці гори Айронфордж у засніженому Дун Мороґу, — родова столиця дворфів Бронзбірдів...",kw={"айронфордж","дворфи","маґні бронзбірд","каз модан","велика кузня","столиця","гноми"},ang={["faction:Alliance"]="Глибинний трамвай легко сполучає Айронфордж зі Стормвіндом, і місто стоїть північною опорою Альянсу й однією з його найнадійніших військових твердинь.",["profession:Blacksmithing"]="Велику Кузню шанують по всьому Азероту як найкращий осередок металообробки: тут стоїть Велике Ковадло, на якому майстри-ковалі й сам Король Маґні перетворюють метал на легенду.",["race:Dwarf"]="Айронфордж — родова домівка вашого народу, горде свідчення вашої стійкості, майстерності в роботі з каменем і священного родоводу, що сягає титанів.",["race:Gnome"]="Відтоді як лихо поглинуло Гномреґан, Містечко Майстрів стало вашою тимчасовою домівкою й штабом, де Великий Тінкер Меккаторк готує визволення вашого міста."},sec={{t="Місто каменю й вогню",b="Айронфордж заснували дві з половиною тисячі років тому, коли перше покоління дворфів пробудилося в Ульдамані й вирушило на захід, до зубчастих вершин Дун Мороґу. Заглибившись у найвищу гору, вони звели величезну святиню на честь свого творця-титана Каз'ґорота, а поруч — колосальну Велику Кузню. Відтоді місто розросталося концентричними кільцями довкола цього вогняного осердя. На відміну від столиць на поверхні, Айронфордж повністю схований під кам'яними склепіннями; його зігрівають ревучі горнила й підземні ріки розплавленої магми. Укріплена брама й печерні глибини століттями війн доводили, що місто майже неприступне."},{t="Війна Трьох Молотів",b="Поколіннями в Айронфорджі пліч-о-пліч жили три дворфійські клани: Бронзбірди, Вайлдгаммери й Темне Залізо. Коли 230 року до відкриття Темного Порталу помер Верховний Король Модімус Анвілмар, спалахнула запекла громадянська війна за владу над горою. Клан Бронзбірд переміг і вигнав суперників. Згодом Чаклун-Тан Тауріссан повів дворфів Темного Заліза в мстиву облогу, що дісталася самого серця Айронфорджа, та сили Бронзбірдів її відбили. На півдні Тауріссан ненароком прикликав Рагнароса, Володаря вогню, — це розтрощило Гори Редріджу й прирекло його власне військо. Відтоді Бронзбірди одноосібно володіють Айронфорджем."},{t="Вірність Альянсу",b="Під час Другої війни орочий клан Кривавої Западини захопив більшу частину Каз Модану, та Айронфордж вистояв за зачиненою брамою, аж поки Альянс Лордерона не зняв облогу. Зв'язаний цим боргом честі, Король Маґні Бронзбірд присягнув, що Айронфордж повік буде вірний Альянсу, і не відступився навіть тоді, коли такі королівства, як Ґілнеас і Кель'Талас, від нього відвернулися. У Третій війні Маґні вклав скорботу за братом Мурадіном, загиблим у Нортренді, у славетний клинок Ешбрінгер, який викував на Великому Ковадлі. Нині Айронфордж лишається одним із найзапекліших оплотів Альянсу."},{t="Прихисток для вигнанців",b="Після трагічного падіння Гномреґана, який захопили троги й отруїла радіація, Король Маґні відчинив браму Айронфорджа тисячам гномських біженців. Під проводом Великого Тінкера Ґелбіна Меккаторка вигнанці заснували Містечко Майстрів і облаштували в кам'яному місті гамірний технічний прихисток. А разом із підземним Глибинним трамваєм, що сполучає Айронфордж просто зі Стормвіндом, дворфійська твердиня перетворилася на жваве роздоріжжя дворфійської сталі й гномської винахідливості."}},faq={{q="Хто править Айронфорджем?",a="Айронфорджем і королівством Каз Модан править із Високого Престолу Король Маґні Бронзбірд. Вправний воїн і майстер-коваль, він провів свій народ крізь Другу й Третю війни й лишається відданою опорою Альянсу.",al={"король айронфорджа","правитель айронфорджа","хто король дворфів"}},{q="Чому в Айронфорджі так багато гномів?",a="Коли сусідня гномська столиця Гномреґан упала через раптове вторгнення трогів і катастрофічну аварію з радіацією, уцілілі гноми втекли до Дун Мороґу. Король Маґні прийняв їх в Айронфорджі й віддав їм цілий квартал міста, відомий нині як Містечко Майстрів.",al={"гноми в айронфорджі","чому тут гноми","гноми містечка майстрів"}},{q="Що таке Велика Кузня?",a="Велика Кузня — вогняне промислове серце міста, яке живлять підземні водоспади розплавленої магми. Вона оточує Велике Ковадло, на якому дворфійські зброярі кують легендарну зброю й обладунки. Сам Король Маґні викував на цьому ковадлі славетний святий клинок Ешбрінгер.",al={"велика кузня","ковадло айронфорджа","центр айронфорджа"}},{q="Як дістатися з Айронфорджа до Стормвінда?",a="Айронфордж сполучений зі Стормвіндом напряму Глибинним трамваєм — дивовижною підземною залізницею, яку створили гномські інженери. Вона пролягає просто крізь гірську основу Східних Королівств.",al={"з айронфорджа до стормвінда","глибинний трамвай","потяг до стормвінда"}},{q="Чи захоплював Айронфордж колись ворог?",a="Айронфордж ніколи не підкорявся жодному загарбникові ззовні. Під час Другої війни клан Кривавої Западини на чолі з Кілроґґом Дедаєм місяцями тримав його в облозі, а у Війні Трьох Молотів Темне Залізо пробилося до самого міста, але брама й захисники вистояли.",al={"чи захоплювали айронфордж","чи падав айронфордж","облога айронфорджа"}},{q="Куди поділися інші дворфійські клани?",a="Після Війни Трьох Молотів переможений клан Вайлдгаммер перебрався на північ — у Багнокрай й Пригір'я, а ворожий клан Темного Заліза осів у краях Редріджу й Блекроку під владою Володаря вогню.",al={"де вайлдгаммери","де темне залізо","клани трьох молотів"}}},fp="9,441,24.622.0,28.636.0,21.574.0,18.482.0,20.241.0,42.268.0,24.269.0,50.210.0,43.250.0,35.236.0"}
P.entries["zone:lochmodan"] = {n="Лох Модан",s="Лох Модан — гірська долина з помірним кліматом на схід від Дун Мороґу, славетна своїм величезним альпійським озером, яке тримає монументальна Каменетесна Гребля. Край, серцем якого є дворфійське містечко Телсамар, потерпає від навали трогів, кобольдів у шахтах і агресивних огрів на північно-східному нагір'ї.",h="Лох Модан — гірська долина з помірним кліматом на схід від Дун Мороґу, славетна своїм величезним альпійським...",kw={"лох модан","телсамар","каменетесна гребля","троги","темне залізо","дворфи","каз модан"},ang={["class:Hunter"]="Хутір Далекоходів на південно-східних кряжах — славетне місце зборів для слідопитів, що полюють у долині на ведмедів, кроколісків і гірських канюків.",["faction:Alliance"]="Лох Модан, що стереже рубіж між Дун Мороґом і північними шляхами до Багнокраю, — важливий оплот територіальної оборони Айронфорджа.",["profession:Mining"]="Пагорби, кар'єри й заполонені трогами печери Лох Модану багаті на доступні жили міді, олова й срібла.",["race:Dwarf"]="Лох Модан уособлює і неперевершений інженерний геній дворфійського каменярства, і небезпечну давню історію, яку ваш народ раз у раз відкопує під каменем."},sec={{t="Самоцвіт нагір'я",b="Лох Модан, що лежить у східному Каз Модані, — приємна протилежність замерзлим сніговим полям Дун Мороґу. Суворі гірські вершини оточують помірну долину з соснами й березами, що колише саме Озеро. Цю величезну прісну водойму тримає Каменетесна Гребля — архітектурний тріумф, що височіє на північному краю. Мирне поселення Телсамар — громадське серце краю: тут зупиняються мандрівні горяни, мисливці й рудокопи, що розробляють багаті жили міді й олова, розкидані по пагорбах."},{t="Відкопані жахи й навали",b="Спокійні краєвиди Лох Модану приховують насильство, що повертається знову й знову. На дні озера досі лежать розбиті катапульти й балісти з часів Другої війни, коли орківська Орда захопила долину, доки дворфи не вигнали її. А нещодавно дворфійські археологічні розкопки ненароком відкрили підземні рої диких трогів. Під проводом лютих ватажків племена трогів заполонили південні каньйони Долини Кам'яного Уламка й Долини Королів, загрожуючи торговим шляхам і змушуючи айронфорджських горян вести відчайдушну оборону."},{t="Змови в тіні",b="Троги й кремезні огри Твердині Мо'ґрошів — не єдині небезпеки, що загрожують долині. Глибше розслідування місцевих диверсій показує, що в Лох Модані діють підступні дворфи Темного Заліза. Проникнувши з палаючих перевалів на півдні, лазутчики Темного Заліза полюють на дворфійські запаси вибухового пороху й виношують зловісні задуми проти самої Каменетесної Греблі."}},faq={{q="Що стримує озеро, щоб воно не затопило Багнокрай?",a="Усе озеро стримує Каменетесна Гребля — величезне диво дворфійської кам'яної роботи й інженерії. Дворфійські інженери ретельно доглядають її, бо якби вона прорвалася, вода змила б низинні болота Багнокраю на півночі.",al={"що таке гребля","призначення каменетесної греблі","чому в лох модані гребля"}},{q="Звідки взялися всі ці троги?",a="Дворфійські дослідницькі експедиції й шахтарі випадково пробили підземні зали глибоко в горах і випустили орди диких трогів, які швидко вилізли на поверхню й облаштували табори в долинах.",al={"чому тут трогги","навала троггів лох модан","походження троггів"}},{q="Яке головне поселення Альянсу в цьому краї?",a="Головне містечко Альянсу й вузол сполучення — Телсамар на західних кручах. Тут є Корчма «Міцний Лагер», ремісники й розпорядники грифонів із польотами до Айронфорджа й далі.",al={"місто лох модан","осередок лох модану","телсамар"}},{q="Хто править Твердинею Мо'ґрошів?",a="Твердиню в північно-східних горах тримають кремезні огри, що спустилися в долину й облаштували укріплену заставу — невелике підземелля, — яка тероризує мисливців і мандрівників поблизу.",al={"огри лох модан","огри північного сходу лох модану","мо'ґрош"}},{q="Що сталося з Місцем розкопок Айронбенда?",a="Археологічні розкопки Шукача Айронбенда заполонили троги, що висипали з підземних залів, і загін мусив покинути роботу й битися, щоб урятувати рештки припасів.",al={"розкопки айронбенда","чому покинуто розкопки айронбенда","проблема шукача айронбенда"}},{q="Чи можна з Лох Модану дістатися до Пустищ чи Палючої Ущелини?",a="Так. Стежки ведуть на південь крізь гори до посушливих Пустищ, а Каменетесний Прохід через Долину Королів веде на південний захід, до вулканічних скель Палючої Ущелини.",al={"лох модан до пустищ","південний вихід лох модану","шлях до пустищ"}}},fp="10,325,16.560.0,31.544.0,20.406.1,52.229.0,35.216.0,52.188.0,30.188.0,44.207.0,64.202.0"}
P.entries["zone:mulgore"] = {n="Малгор",s="Малгор — прабатьківська домівка тауренів: пишна, захищена долина смарагдових пасовищ, високих плато й хвилястих рівнин під Горами Кам'яного Кігтя. Оточений високими природними гірськими стінами, край став безпечним після того, як Кайрн Бладгуф уклав союз із Ордою Тралла й вигнав кентаврів-мародерів. Сьогодні це духовне й територіальне серце об'єднаних тауренських племен, яким правлять із великого міста на плато — Тандер Блафа.",h="Малгор — прабатьківська домівка тауренів: пишна, захищена долина смарагдових пасовищ, високих плато й...",kw={"малгор","таурени","тандер блаф","кайрн бладгуф","кентаври","венчурна компанія","земна мати","зона"},ang={["class:Druid"]="Хвилясті рівнини й незаймані гаї — один із найчистіших природних заповідників Калімдору, де тауренські друїди вивчають рівновагу й дари природи.",["class:Hunter"]="Традиція Великого Полювання квітне на цих рівнинах, де пуми, вовки й дикі кодо випробовують уміння й терпіння кожного слідопита.",["faction:Horde"]="Малгор — серце духовності та землеробства Орди в центральному Калімдорі, пов'язане з народом Тралла кровною клятвою взаємної оборони.",["race:Tauren"]="Ця долина — ваша прабатьківська домівка, повернута ціною жертв і єдності. Берегти її криниці й очищати священні місця — ваш головний обов'язок перед Земною Матір'ю."},sec={{t="Повернута земля",b="Поколіннями таурени жили кочовиками, яких ватаги агресивних кентаврів без упину гнали й витісняли центральними рівнинами. Їхня доля змінилася, коли Верховний Вождь Кайрн Бладгуф зустрів Тралла та його орків-вигнанців. Побачивши спільні ідеали честі, шаманізму й сили, таурени уклали союз із молодою Ордою. З допомогою орків Кайрн розірвав хватку кентаврів на краї й привів свій народ у Малгор. Тут вони вперше за століття звели постійні поселення, увінчавши найвищі північні плато своєю столицею — Тандер Блафом."},{t="Випробування Земної Матері",b="Щоб дорослішати в Малгорі, треба відповісти на поклик Великого Полювання і вшанувати Земну Матір. Молоді таурени починають навчання на південному плато — Плато Червоної Хмари, у Таборі Нарачі під проводом Вождя Гоквінда. Спускаючись до Золотих Рівнин і Села Бладгуф, вони проходять Обряди Земної Матері: вчаться спілкуватися з духами предків, збирати тутешні трави й шанувати стада кодо та довгоступів, що годують їхню цивілізацію."},{t="Тіні, що насуваються",b="Попри мирний вигляд, Малгор зусібіч оточують дедалі більші загрози. Витіснені шипогриви засіли в Яру Тернистого Клинка й осквернили священні поховання Червоних Скель. У горах гарпії Вітрофурії полюють на дичину, а гноли Пейлмейн б'ють із прихованих печер. Ще тривожніші чужинські зазіхання: торгові гобліни Венчурної Компанії заходилися оскверняти священні криниці й розробляти східні пагорби, а дворфійські дослідники з Бель Модану, попри протести тауренів, заклали Розкопки Бел'дуну, щоб видобути стародавні артефакти титанів."}},faq={{q="Чому таурени оселилися в Малгорі назавжди?",a="Таурени здавна були кочовим народом, що мандрував Калімдором, рятуючись від кентаврів-мародерів. Об'єднавши сили з Ордою Тралла, Кайрн Бладгуф здобув військову міць, потрібну, щоб прогнати кентаврів і повернути прабатьківську долину Малгор. Вони звели постійні поселення, зокрема Село Бладгуф і Тандер Блаф, щоб створити єдину батьківщину, де всі тауренські племена могли б жити в мирі.",al={"чому таурени живуть тут","історія батьківщини тауренів","чому оселилися в тандер блафі"}},{q="Як вийти з Малгору пішки?",a="Малгор повністю оточений непрохідними гірськими стінами, за винятком єдиного південно-східного проходу. Головна ґрунтова дорога, що веде на схід повз Село Бладгуф і пост Моріна Клаудсталкера, проходить цим гірським коридором просто в посушливі рівнини Пусток.",al={"вихід із малгору","як дістатися до пустищ із малгору","дорога з малгору"}},{q="Хто така Венчурна Компанія і чому вона тут?",a="Венчурна Компанія — безсовісний торговий картель під орудою гоблінів, що полює на природні багатства Калімдору. У Малгорі вони ведуть видобуток у східних горах і захопили життєво важливі криниці — Тандергорнів, Вайлдмейнів і Вінтергуфів, — оскверняючи землю й загрожуючи водопостачанню краю.",al={"венчурна компанія в малгорі","чому тут гобліни","шахта венчурної компанії"}},{q="Чому дворфи копають на землях тауренів?",a="Дворфи з експедиції Бель Модану заклали Розкопки Бел'дуну в західних передгір'ях Малгору. Спонукувані Лігою Дослідників відшукати реліквії своїх творців-титанів, вони розкопують тауренську землю без дозволу, нехтуючи протестами тауренів, що такі роботи ранять Земну Матір.",al={"розкопки бел'дуну","чому дворфи в малгорі","бел'дун"}},{q="Що таке Обряди Земної Матері?",a="Обряди Земної Матері — священна низка випробувань, які проходить кожен молодий таурен, досягнувши повноліття. Ці завдання перевіряють уміння полювати й вистежувати, спілкування через видіння та знання природної рівноваги, доводячи відданість молодого посвячуваного землі й прабатьківським традиціям свого народу.",al={"обряди земної матері","завдання зрілості тауренів","обряд земної матері"}},{q="Хто править Малгором?",a="Верховний Вождь Кайрн Бладгуф править усіма землями тауренів зі столиці — Тандер Блафа на північних плато. Його син Бейн Бладгуф керує Селом Бладгуф і дбає про повсякденні справи нижніх рівнин, спираючись на мудрість Кайрна.",al={"правитель малгору","хто вождь малгору","вождь кайрн бладгуф"}}},fp="7,468,16.598.0,29.471.0,19.619.0,49.434.0,33.269.0,50.321.0,44.297.0,38.306.0,18.246.0"}
P.entries["zone:orgrimmar"] = {n="Оргріммар",s="Оргріммар — столиця-фортеця орків і живе серце Нової Орди Тралла. Висічене просто у височенних червоних каньйонах північного Дуротару, укріплене місто стоїть пам'ятником орочій витривалості й непохитним прихистком і для тролів, і для тауренів, і для союзників-Відступників.",h="Оргріммар — столиця-фортеця орків і живе серце Нової Орди Тралла.",kw={"оргріммар","орда","тралл","орки","дуротар","столиця","долина сили"},ang={["class:Shaman"]="Тралл повернув шаманство в самий осередок проводу Орди: шамани збираються в спокійній Долині Мудрості, щоб вивчати стихії й єднатися з духами предків.",["class:Warlock"]="Чорнокнижники знаходять тут непевний прихисток: вигнані до відлюдної Тіньової Розколини, вони діють під пильним оком Тралла й відточують свої темні мистецтва подалі від чужого осуду.",["faction:Horde"]="Як найвищий військовий і культурний осідок Нової Орди, Оргріммар дає всім поборникам Орди майстрів зброї, наставників класів, торгові осередки й змогу постати перед самим Вождем Траллом.",["race:Orc"]="Для орків Оргріммар — тяжко здобута свобода від демонічної млявості й таборів інтернування, їхня горда родова фортеця на землі Дуротару.",["race:Troll"]="Утративши Острови Темного Списа, тролі цього племені знайшли надійний прихисток поруч з орками й обрали Долину Духів своєю безпечною духовною домівкою."},sec={{t="Дім, витесаний із каменю",b="Після Третьої війни Вождь Тралл повів орків до посушливих берегів Калімдору, щоб збудувати батьківщину, вільну від демонічної скверни й людського ярма. Назвавши цей суворий край Дуротаром на честь свого батька, Тралл заснував Оргріммар на пам'ять про свого полеглого наставника Оргріма Думхаммера. Місто зводили кров'ю та потом: з допомогою тауренів, тролів Темного Списа, гоблінських інженерів і Поборника Рекссара Орда відтіснила кентаврів, гарпій і лютих громових ящерів, що насідали звідусіль, і закріпилася в цій твердині серед каньйону."},{t="Долини Орди",b="Оргріммар природно захищений скелястими горами, що вберігають його і від чужоземних загарбників, і від лютих, гострих, як лезо, вітрів, які мчать Дуротаром. Поселення поділене на окремі природні улоговини. Долина Сили — гамірна громадська брама міста, звідки дорога веде вглиб, до торгового базару Проходу. Друїди й шамани тауренів збираються біля спокійних озерець Долини Мудрості, а мисливці тіней і знахарі Темного Списа живуть серед павільйонів на палях у Долині Духів."},{t="Тіні в червоній скелі",b="Під бойовою гордістю Долини Честі й висотами Фортеці Ґроммаш криється темніша дійсність. У підземній печері, відомій як Тіньова Розколина, чорнокнижники й розбійники практикують мистецтва, за якими Тралл суворо наглядає, хоч і неохоче їх терпить. Ще глибше пірнає Провалля Лютого Вогню — вогняний лабіринт вулканічних тунелів під дном каньйону, де розплодилися темні культисти й підземні звірі, що загрожують фортеці просто з її власних підвалин."}},faq={{q="Хто править Оргріммаром?",a="Містом править Вождь Тралл зі свого осідку у Фортеці Ґроммаш. Він веде Нову Орду, спираючись на честь, виживання й шаманську спадщину, а найближчу підтримку йому дають вождь Темного Списа Вол'джин і бувалий командувач Варок Саурфанг.",al={"провідник оргріммара","хто керує оргріммаром","нинішній вождь"}},{q="Чому місто назвали Оргріммаром?",a="Тралл назвав місто на честь Оргріма Думхаммера — легендарного колишнього Вождя, що зламав владу Ради Тіней над Старою Ордою, а перед загибеллю в бою передав Траллові свої бойові лати й молот Думхаммер.",al={"походження назви оргріммар","на честь кого названо оргріммар"}},{q="Хто, крім орків, живе в Оргріммарі?",a="Місто заснували орки, але воно стало прихистком і для тролячого племені Темного Списа, що займає Долину Духів, а в Долині Мудрості гостюють посланці тауренів. Після нещодавнього вступу Відступників до Орди тут оселилася і їхня посольська делегація.",al={"раси в оргріммарі","хто тут живе","тролі в оргріммарі"}},{q="Що таке Тіньова Розколина?",a="Тіньова Розколина — тьмяна печерна ущелина, що ховається під скелями каньйону біля Проходу. Тут розташовані міські гільдії розбійників і чорнокнижників: їхня сумнівна торгівля й небезпечні демонічні закляття лишаються осторонь від мирних кварталів.",al={"тіньова розколина","підземний оргріммар","квартал чорнокнижників оргріммара"}},{q="Які загрози чигають у самому місті?",a="Просто під Тіньовою Розколиною лежить Провалля Лютого Вогню — підступна мережа підземних вулканічних розломів, де кишать троги, палючі елементалі й зрадливі чорнокнижники, що прагнуть підірвати владу Тралла з глибин.",al={"небезпеки в оргріммарі","загроза провалля лютого вогню","культисти оргріммара"}},{q="Як дістатися з Оргріммара на інші континенти?",a="За головною брамою на вежах причалюють цепеліни, збудовані гоблінськими інженерами. Вони регулярно перелітають Велике Море до Галявин Тірісфалю поблизу Андерсіті й на південь — до Базового Базового Табору Ґром'ґол у Долині Стренглторну.",al={"цепеліни оргріммара","з оргріммара до тірісфалю","подорожі з оргріммара"}}},fp="9,300,26.525.0,20.512.0,23.464.1,20.231.0,32.212.0,36.284.0,28.241.0,35.230.0,53.203.0"}
P.entries["zone:ragefire"] = {n="Провалля Лютого Вогню",s="Провалля Лютого Вогню — мережа звивистих вулканічних тунелів просто під орківською столицею Оргріммаром. Вхід до нього лежить у темних западинах Тіньової Розколини, а саме провалля заполонили дикі троги й демонічна секта культистів, відома як Пекучий Клинок. Якщо їх не зупинити, темні сили й підземні рої, що визрівають унизу, загрожують самим підвалинам молодої держави Орди.",h="Провалля Лютого Вогню — мережа звивистих вулканічних тунелів просто під орківською столицею Оргріммаром.",kw={"провалля лютого вогню","оргріммар","пекучий клинок","троги","ніру файрблейд","підземелля"},ang={["class:Warlock"]="Темні обряди й демонічні фоліанти Джерґоша Призивача й Баззалана дають учням-чорнокнижникам змогу на власні очі побачити темну магію Пекучого Клинка.",["faction:Horde"]="Очищення провалля під Оргріммаром — важливе випробування для молодих героїв, щоб довести свою силу й захистити вразливу столицю Орди.",["race:Tauren"]="Трагічна загибель Маура Ґрімтотема від рук трогів Лютого Вогню робить полювання на підземних звірів справою честі й відплати для Тандер Блафа."},sec={{t="Підземна небезпека",b="Під пилом і червоним камінням Оргріммара лежить пекучий лабіринт вулканічних коридорів і лавових ям. Поки орківські будівничі зводили нагорі свою нову домівку, з глибин почали вириватися агресивні троги Лютого Вогню. Маґата Ґрімтотем від імені Тандер Блафа спробувала налагодити з ними дипломатичні стосунки, але її посланця Маура Ґрімтотема по-звірячому вбили, — і стало ясно, що троги поступаються лише силі."},{t="Пекучий Клинок",b="Значно небезпечніший за звичайних трогів Пекучий Клинок — фанатичний осередок, вірний Раді Тіней. Діючи з темних печер уздовж потоків магми, цей демонічний культ замишляє цілковиту загибель молодої Орди. Його очолюють чорнокнижник Джерґош Призивач, хитрий сатир на ім'я Баззалан і лютий вартовий скверни Тараґаман Голодний, що панує над вівтарем серед лавового озера."},{t="Гра Вождя",b="Ніру Файрблейд, нібито наставник чорнокнижників, що живе біля входу до провалля в Тіньовій Розколині, таємно очолює місцевий осередок Палаючого Клинка. Ніру посилає шукачів пригод з Орди в глибини під приводом випробувань на вірність, сподіваючись проредити слабких культистів і позбутися прихильників Тралла. Проте Тралл добре знає про обман Ніру. Вождь використовує ці вилазки, щоб знищувати небезпечних ватажків культу на кшталт Джерґоша й Баззалана, а самого Ніру лишає на місці, щоб стежити за ширшими задумами Ради Тіней."}},faq={{q="Де вхід до Провалля Лютого Вогню?",a="Портал-вхід міститься в Оргріммарі, у підземному кварталі, відомому як Тіньова Розколина, біля намету наставника чорнокнижників Ніру Файрблейда.",al={"де лютий вогонь","розташування лютого вогню","вхід у лютий вогонь"}},{q="Чому під Оргріммаром є троги?",a="Троги Лютого Вогню прорилися вгору з підземних глибин під Дуротаром. Їхню раптову появу під столицею вважають серйозною небезпекою, яку не вдалося вгамувати дипломатією.",al={"походження троггів лютого вогню","чому тут трогги","трогги оргріммара"}},{q="Хто очолює культистів у проваллі?",a="Пекучим Клинком у проваллі керують чорнокнижник Джерґош Призивач і сатир Баззалан, а підтримує їх викликаний вартовий скверни Тараґаман Голодний.",al={"боси провалля","лідери палаючого клинка","хто править лютим вогнем"}},{q="Чого досягає вбивство Баззалана й Джерґоша для сюжету?",a="Убивши Баззалана й Джерґоша, ви ламаєте діючий провід культистів Пекучого Клинка, що ховаються під Оргріммаром. Їхня загибель показує стійкість Орди й дає змогу Траллові знешкодити осередок поклонників демонів просто під своїм троном.",al={"лор баззалана","чому вбити баззалана","результат прихованих ворогів"}},{q="Чи можуть шукачі пригод з Альянсу потрапити до Провалля Лютого Вогню?",a="Фізично будь-хто може пройти крізь портал, але щоб члену Альянсу дістатися Тіньової Розколини глибоко в Оргріммарі, доведеться уникати високорівневих вартових Орди й ворожих захисників по всьому місту.",al={"чи альянс може в лютий вогонь","альянс у лютому вогні"}},{q="Чому Тралл просто не стратить Ніру Файрблейда?",a="Тралл терпить тих, хто практикує темну магію в Тіньовій Розколині, вважаючи за краще тримати їх поруч і під пильним наглядом, аніж виганяти з очей.",al={"тралл ніру файрблейд","чому тралл не страчує ніру"}}},fp="14,396,18.413.0,17.420.0,19.540.1,40.172.0,31.184.0,40.169.0,64.237.1,46.216.0,50.177.1"}
P.entries["zone:razorfenkraul"] = {n="Рейзорфен Краул",s="Рейзорфен Краул, що сховався на далекому півдні Пусток, — прадавнє серце земель шипогривів Калімдору. Ці люті племена шанують густий лабіринт велетенських терновиків як священне місце спочинку свого праотця, полеглого напівбога Аґамаґґана. Сьогодні Краул став украй ворожим під тиранією матріархині шипогривів Чарлґи Рейзорфленк, чиї темні оборудки загрожують усьому краю.",h="Рейзорфен Краул, що сховався на далекому півдні Пусток, — прадавнє серце земель шипогривів Калімдору.",kw={"рейзорфен краул","шипогриви","чарлґа рейзорфленк","аґамаґґан","погибель","підземелля","пустки"},ang={["class:Shaman"]="Геомантія шипогривів спотворює землю й стихії довкола крові Аґамаґґана — наочний приклад первісної шаманської сили в руках дикунів.",["faction:Horde"]="Знешкодити загрозу з Краула конче потрібно, щоб захистити обози з припасами й молоді поселення по всьому півдню Пусток.",["race:Tauren"]="Шипогриви давно зазіхають на кордони Малгору, а їхнє осквернення землі темними союзами робить очищення Краула нагальною справою оборони племені.",["race:Undead"]="Аптекарі з Андерсіті пильно цікавляться дивними інгредієнтами, кажанячим послідом і чутками про проникнення Погибелі серед терновиків."},sec={{t="Кров Бога-Вепра",b="Десять тисяч років тому, під час апокаліптичної Війни Прадавніх, велетенський дикий бог Аґамаґґан кинувся в бій проти Палаючого Легіону. Зрештою великий вепр загинув у битві, але його жертва зберегла життя на Азероті. Легенди кажуть, що там, де його кров просочилася в землю, вирвалися величезні колючі лози, утворивши густі оборонні лабіринти по всіх південних рівнинах. Шипогриви, що шанують Аґамаґґана як божественного предка, оголосили ці колосальні хащі своєю святою землею, а найбільшу з них назвали Рейзорфеном."},{t="Задуми старої",b="Рейзорфен Краулом залізним іклом править стара Чарлґа Рейзорфленк. Під її деспотичним проводом шамани-шипогриви покинули звичні сутички за території й ведуть агресивну, злагоджену війну проти суперницьких племен, торгових шляхів краю й молодих поселень Орди. Ба гірше, тривожні чутки й донесення розвідників розповідають про потвор-нежить, що никають біля терновиків. Є побоювання, що Чарлґа почала перемовини з посланцями грізної Погибелі, прагнучи скористатися забороненою некромантією, щоб посилити лютість свого племені."}},faq={{q="Що таке Рейзорфен Краул?",a="Рейзорфен Краул — прадавня підземна мережа величезних колючих лоз на півдні Пусток. Це духовне серце й твердиня народу шипогривів, які вважають цей заплутаний лабіринт домом предків.",al={"що таке рфк","поясніть рейзорфен краул","огляд рейзорфена"}},{q="Як з'явилися велетенські колючки?",a="Величезні хащі проросли із землі десять тисяч років тому, під час Війни Прадавніх, просто з крові, пролитої полеглим напівбогом-вепром Аґамаґґаном.",al={"чому гігантські терни","звідки колючки","терни аґамаґґана"}},{q="Хто править Рейзорфен Краулом?",a="Краулом править Чарлґа Рейзорфленк, безжальна стара відьма-шаманка шипогривів, що командує племенем Рейзорфен і влаштовує напади на сусідні поселення й мандрівників.",al={"бос рфк","чарлґа гострий бік","хто править краулом"}},{q="Чому Орда стурбована Рейзорфен Краулом?",a="Окрім постійних набігів шипогривів на молоді поселення в Пустках, розвідники Орди помітили, що довкола хащів нишпорить нежить, і це викликає страшні підозри, що Чарлґа злигалася з Погибеллю.",al={"чому орда стурбована","інтерес орди рфк","загроза пустовиськ"}},{q="Чому Рейзорфен Краул цікавить сили Альянсу?",a="Агресивне розростання племені Чарлґи загрожує заставам біля Фераласу й Тисячі Голок, тож командири й розвідники Альянсу в Таланаарі прагнуть смерті старої відьми, щоб убезпечити кордон.",al={"завдання альянсу рфк","чому альянс іде сюди","завдання таланаару"}},{q="Що означає для сюжету перемога над Землекличником Галмґаром?",a="Перемога над Землекличником Галмґаром, рідкісним і впливовим геомантом із глибин хащів, — удар по жрецтву шипогривів, що керує землею. Позбавлений таких могутніх стихійних заклиначів, Краул втрачає частину оборонних укріплень Чарлґи Рейзорфленк, а шипогривам стає важче керувати священними хащами Аґамаґґана.",al={"що буде після галмґара","землекличник галмґар лор","галмґар переможений"}}},fp="14,417,21.573.0,20.556.1,23.229.0,34.186.0,25.174.0,48.203.0,48.207.0,59.348.0"}
P.entries["zone:redridge"] = {n="Гори Редріджу",s="На схід від Лісу Елвінн лежать Гори Редріджу — бурхливі річки, лісисті схили й безтурботна гладінь Озера Незрушного. Попри мальовничі висоти, край обложили ворожі гноли Тіньової Шкури й орки Блекрок із Темної Орди, що насуваються дедалі ближче. Військо королівства зв'язане внутрішніми чварами в Стормвінді, тож приозерне містечко Лейкшир мусить покладатися на мандрівних найманців, щоб утримати лінію.",h="На схід від Лісу Елвінн лежать Гори Редріджу — бурхливі річки, лісисті схили й безтурботна гладінь Озера...",kw={"гори редріджу","лейкшир","озеро незрушне","блекрок","гноли","фортеця кам'яної варти","морґант"},ang={["faction:Alliance"]="Лейкшир — важливий вузол на передовій, де молоді воїни Альянсу відточують майстерність проти організованих сил орків і гнолів.",["faction:Horde"]="Орки Блекрок, що засіли в Редріджі, належать до ворожої Темної Орди, тож вони такі ж вороги Орди Тралла, як і люди Лейкшира.",["profession:Herbalism"]="На помірних гірських схилах рясно ростуть Браєрторн, Синяк-трава, Чарівна Королиця й Прудкочортополох.",["profession:Mining"]="Скелясті кручі й долини довкола Озера Незрушного рясніють покладами міді, олова й рідкісними жилами срібла, особливо біля Печер Ретбану."},sec={{t="Бастіон в облозі",b="Колись Редрідж був одним із наймирніших куточків королівства й постачав Стормвіндові деревину, прісноводну рибу й урожай. Нині те тихе життя розвіялося. Приозерне містечко Лейкшир повсякчас тримає оборону від агресивних вторгнень. На сході Фортеця Кам'яної Варти — колись гордий бастіон королівства — опинилася під владою орків-ренегатів Блекрок, що перерізали дороги й погрожують цілком захопити східні долини."},{t="Розколотий хребет",b="Ці вершини — частина гірського хребта, що тягнеться вздовж субконтиненту Азерот. Століття тому гірське пасмо сягало значно далі на північ, доки клан Темного Заліза ненароком не викликав Володаря вогню Рагнароса, який розірвав землю й утворив вогняний кратер Гори Блекрок. Та катастрофа відколола північні вершини, що стали вкритими попелом Палаючими Степами, і лише південні долини Редріджу лишилися пишними, зеленими — й вразливими для нападів зі схилів над ними."},{t="Забуті короною",b="While Magistrate Solomon and Marshal Marris plead for reinforcements, the regency council in Stormwind has effectively abandoned Lakeshire to fend for itself. Desperate entreaties sent to Sentinel Hill and Darkshire yield nothing, as both sister settlements are crippled by their own crises. With reinforcements nowhere in sight, local magistrates must hire any capable sellsword willing to brave the Lakeridge Highway, clear the gnoll camps, and push back the shadow looming over Lake Everstill."},{t="Приховані союзи",b="Чорнокнижник-ренегат Морґант спершу уклав союз з орками Блекрок, щоб захопити Фортецю Кам'яної Варти, а потім зрадив їх і з Вежі Ілґалара підкорив собі гнолів Тіньової Шкури. Донесення, здобуті під час розслідування щодо Блекрок, також відкривають союз орків із чорними драконами."}},faq={{q="Чому Стормвінд не посилає вояків на допомогу Лейкширу?",a="Lakeshire's surviving royal soldiers are badly outnumbered after losing Stonewatch Keep. Magistrate Solomon has appealed for troops, weapons, food, and supplies, but Stormwind's forces are stretched thin and the neighboring settlements have troubles of their own. The garrison therefore relies on adventurers to help hold the region.",al={"чому немає варти стормвінда","чому редрідж покинуто","де армія стормвінда"}},{q="Хто контролює Фортецю Кам'яної Варти?",a="Фортецю Кам'яної Варти захопили орки Блекрок, пов'язані з Темною Ордою. З цієї укріпленої гірської твердині вони загрожують східним долинам і рухові Шосе Лейкрідж. Їхні зв'язки з іншими місцевими загрозами з'ясовуються під час розслідування.",al={"хто в кам'яній варті","вороги кам'яної варти","що сталося з кам'яною вартою"}},{q="Які загрози чатують в Озері Незрушному?",a="З берега озеро здається спокійним, але в його водах кишать ворожі племена мурлоків, що грабують причали й руїни поблизу. Плавцям доводиться остерігатися й хижих трешадонів, що чатують під поверхнею, — звідси вперті чутки про водяних чудовиськ у глибинах.",al={"монстри озера незрушного","небезпеки озера редріджа","мурлоки озера"}},{q="Чи є в Редріджі застави Орди?",a="Ні. У Горах Редріджу немає ні поселень Орди, ні торговців, ні шляхів польоту. Мандрівники Орди, що проходять краєм, зазвичай прямують між Палаючими Степами на півночі й Болотом Скорботи на південному сході, долаючи дороги Альянсу й ворожу глушину.",al={"міста орди редрідж","чи редрідж орди чи альянсу","політ орди редрідж"}},{q="Що таке Три Кути?",a="The Three Corners is a vital crossroads in the southwest corner of Redridge. It connects the Lakeridge Highway with the eastern border of Elwynn Forest and the road into Duskwood, making it an essential transit hub frequently targeted by wandering gnolls and wild beasts.",al={"три кути","перехрестя трьох кутів","перехрестя редріджа"}},{q="Чому північний шлях до Палаючих Степів такий небезпечний?",a="Стежка, що веде на північ повз Табір Рендера, піднімається просто в Палаючі Степи — спустошену вулканічну пустку, де панують могутні орки Блекрок, вогняні елементалі й драконороди. Через різкий стрибок небезпеки цей північний гірський перевал — один із найсмертельніших підйомів на півдні Азероту.",al={"північна дорога редріджа","кордон палаючих степів","північний прохід редріджа"}}},fp="18,413,21.465.0,17.498.0,22.496.0,22.308.1,52.333.0,29.281.0,37.293.0,41.293.0,26.271.0,60.305.0"}
P.entries["zone:riverglades"] = {n="Річкові Галявини",s="Річкові Галявини — спірна річкова долина на схід від Палаючих Степів і Пустищ, яку здавна вважало своєю королівство Стормвінд. Під час Першої війни її захопила Стара Орда, а корона майже покинула край напризволяще, тож він досі лишається полем бою: місцеві люди, вірні короні, б'ються із заставами сучасної Орди й дикими звірами. На південному заході долина межує з Горами Редріджу, на півдні — з Болотом Скорботи, а за морем навпроти лежить Танаріс.",h="Річкові Галявини — спірна річкова долина на схід від Палаючих Степів і Пустищ, яку здавна вважало своєю...",kw={"річкові галявини","сонячна галявина","фаргольд","братство коня","перша війна","стормвінд","роґ'мар"},ang={["faction:Alliance"]="Воїни Альянсу бачать у Річкових Галявинах старі незагоєні рани: тут рештки Братства Коня ведуть неоспіваний похід, щоб повернути землю, яку Стормвінд покинув у Першій війні.",["faction:Horde"]="Для Орди застави на кшталт Роґ'мару — це надійний прибережний плацдарм і змога тримати під тиском старі людські твердині, що досі стоять на схід від Редріджу.",["race:Human"]="У Сонячній Галявині ви побачите трагічну сторінку історії власного народу — нагадування про тяжку ціну, яку Перша війна взяла зі східного прикордоння вашого королівства."},sec={{t="Забуте прикордоння",b="Колись Річкові Галявини належали королівству Стормвінд, але під час Першої війни, коли краєм прокотилася Стара Орда, вони занепали. Головне поселення, Сонячну Галявину, розграбували орки; вони вберегли лише вежу магів, щоб вивчати людське чаклунство, а вцілілих городян поневолили. Хоча воїни Стормвінда спробували визволити полонених і відбудувати край, зрештою королівство визнало всю долину втраченою й спрямувало сили на захист рідних земель. Роками край лишався майже без офіційної підтримки корони."},{t="Боротьба за Фаргольд",b="Хоча верхівка Стормвінда залишила їх напризволяще, людські захисники так і не склали зброї. Під проводом лицаря-командора Демара Бранта з легендарного Братства Коня вірні короні вцілілі утримують Фортецю Фаргольд як оплот проти дикої природи й ворожих загарбників. Тим часом сучасна Орда міцно закріпилася неподалік, на заставах Роґ'мар і Болдер'ок, тож давня боротьба за галявини досі тліє."},{t="Землі й подорожі",b="Річкові Галявини простягаються вздовж узбережжя Грізного моря, і їх оточують гори та звивисті водні шляхи. Пішки можна перейти на захід через Перевал Блекрок до Палаючих Степів, звернути на південний захід через Перевал Редрідж до Гір Редріджу, рушити на південь до Болота Скорботи або вирушити на північний захід повз Сутінковий Покров до Пустищ. На узбережжі з Порту Паудерф'юз ходять кораблі просто через океан до Порту Стімвідла в Танарісі."}},faq={{q="Що таке Річкові Галявини?",a="Річкові Галявини — спірний край на схід від Пустищ і Палаючих Степів, що виходить до Неприступного Моря. Колись квітуча земля Стормвінда, нині це діючий фронтир, за який змагаються Альянс у Фортеці Фаргольд і Орда в Роґ'марі.",al={"огляд річкових галявин","що це за зона","про річкові галявини"}},{q="Що сталося з Сонячною Галявиною?",a="Під час Першої війни Стара Орда напала на Сонячну Галявину й зруйнувала її. Орки забрали вцілілих селян у рабство й лишили неушкодженою місцеву вежу магів, щоб розгадати людську магію. Хоча вояки Стормвінда звільнили полонених і спробували відбудувати селище, королівство зрештою покинуло край, зосередившись на західних кордонах.",al={"історія сонячної галявини","падіння сонячної галявини","що сталося з містом"}},{q="Хто контролює Фортецю Фаргольд?",a="Фортецю Фаргольд тримають вірні Альянсу вояки на чолі з Лицарем-Командором Демаром Брантом із Братства Коня. Його сили роками борються за повернення Річкових Галявин, після того як Стормвінд колись списав цей край як утрачений.",al={"хто керує фаргольдом","альянс у річкових галявинах","братство коня"}},{q="Як дістатися з Річкових Галявин до Танарісу?",a="Між Портом Паудерф'юз на східному березі Річкових Галявин і Портом Стімвідла в Танарісі регулярно ходить прибережний корабель — пряме морське сполучення через море.",al={"човен до танарісу","човен порту пауерфьюз","як дістатися до танарісу"}},{q="Які перевали ведуть до інших країв?",a="На південний захід можна пройти через Перевал Редріджу до Гір Редріджу або на південь — просто до Болота Скорботи. На заході Перевал Блекрок веде повз Щетинисті Пагорби до Палаючих Степів, а стежки на північ від Сутінкового Покрову виводять просто в Пустища.",al={"як дістатися до редрідж","проходи з річкових галявин","виходи з річкових галявин"}},{q="Що таке Твердиня Крол'док?",a="Твердиня Крол'док — укріплений комплекс-підземелля в Річкових Галявинах, головний осередок ворожої сили в цьому спірному краї.",al={"твердиня крол'док","підземелля річкових галявин","яке підземелля тут"}}},fp="11,442,22.570.0,25.482.0,20.493.0,24.255.0,28.330.0,27.236.0,46.172.0,34.289.0,28.141.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Руїни Лордерона",s="Руїни Лордерона, що височіють просто над підземним Андерсіті, — порожні рештки колись могутнього північного людського королівства. Їх захопили Погибель і принц Артас під час Третьої війни, і тепер вулицями й потрісканими площами нагорі никають мандрівні потвори, мстиві примари й мерзенні експериментатори. І Альянс, і Орда посилають загони в цю сплюндровану цитадель, щоб повернути реліквії полеглого минулого чи винищити жахіття, що ховаються над столицею Відступників.",h="Руїни Лордерона, що височіють просто над підземним Андерсіті, — порожні рештки колись могутнього північного...",kw={"руїни лордерона","андерсіті","артас","теренас менетіл","капітан лордерона","підземелля"},ang={["class:Paladin"]="Лордерон був колискою Лицарів Срібної Длані; пройти його оскверненими залами, щоб винищити жахіття й упокоїти неспокійних капітанів, — урочистий обов'язок Світла.",["faction:Alliance"]="Похід до Лордерона дає Альянсові змогу вдарити просто на порозі столиці Відступників і водночас принести справедливість і спокій духам своїх убитих північних братів.",["race:Human"]="Шукачі пригод із людей бачать у зруйнованій столиці святу землю, вкрадену через зраду, і прагнуть повернути втрачені родинні реліквії та вшанувати полеглих родичів.",["race:Undead"]="Для Відступників руїни нагорі — колишня домівка й вічне кладовище. Очистити їх — означає убезпечити свої парадні двері й постачати аптекарям складники для Нової чуми."},sec={{t="Двір занепалої імперії",b="Місто Лордерон колись було перлиною Східних Королівств, осідком короля Теренаса Менетіла II і серцем людської цивілізації. Повернувшись із Нортренду, принц Артас убив свого батька в тронній залі й нацькував нежить на городян. Сьогодні, поки Відступники живуть у катакомбах Андерсіті внизу, руїни на поверхні лишаються покинутою сутінковою зоною. Розбиті арки й порослий бур'янами брук дають прихисток диким звірам на кшталт Візерфенга й божевільним рештам минулого."},{t="Муки й мор",b="Небезпеки на зруйнованих землях не обмежуються неспокійними мерцями. Аптекарі й зловісні постаті на кшталт Віктора Мерзенного випробовують нові чуми в тіні, а спотворені витвори дослідів, як-от Покинуті, вільно блукають довкола. Мстиві духи на кшталт Рат'маеля й прокляті слуги на кшталт Барона бродять зруйнованими коридорами, приречені на нескінченні муки, і кидаються на кожного живого чи мертвого, хто стане на їхньому шляху."},{t="Привиди королівської варти",b="Серед найзворушливіших небезпек верхніх руїн — примарні рештки захисників міста, і найгрізніший серед них — привид Капітана Лордерона. Досі чіпляючись за розбиті присяги, ці привиди вважають загарбником кожного, хто наближається до трону. Упокоївши Капітана та його вояків, ви приносите гірко-солодке завершення безперервній варті, що триває від дня, коли впала столиця."}},faq={{q="Де розташоване підземелля Руїни Лордерона?",a="Підземелля лежить просто на поверхні Столичного Міста в Галявинах Тірісфалю, якраз над мережею входів, що ведуть униз, до столиці Відступників Андерсіті.",al={"розташування руїн лордерона","де підземелля лордерона","вхід у підземелля підміської"}},{q="Чому це місце цікавить і Орду, і Альянс?",a="Для Альянсу похід у Лордерон — священне паломництво, щоб повернути втрачені родинні реліквії, зібрати королівські герби й дати останній спокій полеглим предкам. Для Орди, особливо для Відступників, очищення верхніх руїн необхідне, щоб убезпечити околиці Андерсіті й добути зразки для нової чуми Королівського Аптекарського Товариства.",al={"чому йти до руїн лордерона","завдання альянсу лордерон","завдання орди лордерон"}},{q="Хто такий Віктор Мерзенний?",a="Віктор Мерзенний — одна з лиховісних постатей, що користуються беззаконням руїн: він ставить мерзенні досліди й підживлює гнійне спотворення, через яке верхня столиця й далі кишить викривленими гидотами.",al={"лор віктора мерзенного","хто такий віктор мерзенний"}},{q="Що таке «Покинуті», яких зустрічають у руїнах?",a="Це потворне чудовисько з нежиті, яке лишилося в руїнах. Як і багато зшитих жахіть, створених під час і після завоювання Погибеллю, воно безцільно блукає занедбаними залами й нападає на все, що трапиться.",al={"бос покинутих","хто покинутий"}},{q="Що означає для сюжету перемога над Капітаном Лордерона?",a="Перемога над примарним Капітаном Лордерона звільняє високопоставленого королівського захисника від вічного, божевільного обов'язку. Скутий честю від першої різанини Погибелі, Капітан роками охороняв зруйноване королівство від усіх, хто наближався. Упокоївши його, ви розриваєте болісне коло примарного служіння й можете забрати його закривавлену відзнаку.",al={"перемога над капітаном лордерона","значення капітана лордерона","що буде коли капітан помре"}},{q="Чи Руїни Лордерона окремі від Андерсіті?",a="Так. Відступники живуть у печерах Андерсіті внизу, а руїни на поверхні — діюча зона бойових дій, де кишать неприкаяні привиди, дикі хижаки й експериментальні загрози, яких Відступники так і не викорінили.",al={"чи андерсіті в цьому підземеллі","руїни проти андерсіті"}}},fp="18,495,27.507.0,22.431.0,25.419.1,48.191.0,61.370.0,23.229.0,49.228.0,61.375.1,54.232.0"}
P.entries["zone:scarlet"] = {n="Багряний Монастир",s="На північно-східних пагорбах Галявин Тірісфалю стоїть Багряний Монастир, колись мирний прихисток і осередок науки Церкви Святого Світла. Після падіння Лордерону його захопив і міцно укріпив Багряний Хрестовий Похід, зробивши своєю головною передовою базою на заході. Нині це розлога твердиня з чотирма крилами, де фанатики муштруються, катують полонених і ведуть безкомпромісну війну з усіма чужинцями.",h="На північно-східних пагорбах Галявин Тірісфалю стоїть Багряний Монастир, колись мирний прихисток і осередок...",kw={"багряний монастир","багряний хрестовий похід","вайтмейн","собор","бібліотека","збройня","кладовище"},ang={["class:Mage"]="У крилі Бібліотеки зберігаються рідкісні історичні й богословські фоліанти під охороною арканіста Доана — колишнього вченого з Даларану, що перейшов на бік Хрестового Походу.",["class:Paladin"]="Колись монастир був священною семінарією, де навчалися й молилися перші паладини Срібної Длані, тож його падіння в багряний фанатизм — трагічне нагадування про те, як відданість може скиснути в безумство.",["class:Priest"]="Колись присвячені архієпископу Алонсусу Фаолу й Церкві Святого Світла, величні каплиці монастиря показують, що свята сила й досі може коритися смертним, спотвореним ненавистю й жагою помсти.",["race:Undead"]="Багряний Монастир на межі Галявин Тірісфалю — смертельна загроза для Відступників: звідси засилають шпигунів до Похоронного Подзвону, а в підземеллях катують полонену нежить."},sec={{t="Занепала святиня",b="До Третьої війни монастир був гордим осідком лордеронського священства й семінарією для молодих паладинів Срібної Длані, яку плекав сам архієпископ Алонсус Фаол. Після спустошення, якого завдала Погибель, уцілілі хрестоносці вичистили зали від нежиті й павуків, що там лишилися, і перетворили тихі архіви та двори на укріплений гарнізон. Гнані параноєю й горем, бійці Багряного Хрестового Походу почали вважати всіх чужинців — живих чи мертвих, людей чи ні — носіями чуми, яких треба очистити вогнем."},{t="Чотири крила",b="За Великим Вестибюлем монастиря лежать чотири окремі частини. Кладовище — неосвячена тераса під відкритим небом, де загиблі хрестоносці встають мерзенною нежиттю, а кати видирають зізнання з в'язнів. Бібліотека зберігає дорогоцінні богословські тексти й історичні фоліанти під охороною мага-ренегата, арканіста Доана, та його псів. Збройня — вишкільний табір, де багряні майстри зброї на кшталт Герода муштрують фанатичних новобранців, гартуючи з них залізних воїнів. А найглибше стоїть Собор — величне серце твердині, звідки провідники Хрестового Походу спрямовують свій похід через сплюндровану північ."},{t="Падіння Верховної інквізиторки",b="Внутрішнім святилищем Собору командують Багряний командир Моґрейн і справжня господиня монастиря — Верховна інквізиторка Саллі Вайтмейн. Перемога над Вайтмейн завдає нищівного удару по командуванню Хрестового Походу в Галявинах Тірісфалю. Її здатність закликати сліпуче Святе Світло й воскрешати полеглих героїв змушувала вірних вважати гарнізон непереможним. Її загибель розвіює ореол божественного благословення, що живив фанатизм монастиря, показує, що провідники Хрестового Походу смертні, і тяжко підриває їхню війну проти Відступників і сусідніх земель."}},faq={{q="Чому Багряний Хрестовий Похід ворожий до живих шукачів пригод з Альянсу?",a="Похід поринув у крайнє безумство й параною. На думку хрестоносців, кожен, хто не носить їхнього багряного табарда, — можливий носій чуми Погибелі. Вони більше не розрізняють друзів і ворогів і вважають усіх чужинців зараженими, яких треба очистити, перш ніж ті поширять спотворення.",al={"чому багряні нападають на людей","багряний похід ворожий до альянсу","чому вони злі"}},{q="Що станеться, коли ви здолаєте Верховну інквізиторку Вайтмейн?",a="Перемога над Верховною інквізиторкою Вайтмейн обезголовлює західне військове командування Багряного Хрестового Походу. Як духовна провідниця монастиря, вона своєю дивовижною силою воскресіння підтримувала дух вояків і тримала Командира Моґрейна в бою поруч із собою. Її загибель позбавляє Похід найсильнішої жриці в Галявинах Тірісфалю, гарнізон розлагоджується, і загроза для довколишнього краю значно слабшає.",al={"що значить убити вайтмейн","вайтмейн переможена","кінцівка собору"}},{q="Що таке Багряний Ключ і де його знайти?",a="Багряний Ключ зберігається глибоко в крилі Бібліотеки монастиря, у скрині арканіста Доана за його особистим кабінетом. Цей ключ потрібен, щоб відімкнути зовнішні брами крил Збройні й Собору.",al={"де багряний ключ","як відімкнути зброярню і собор","ключ монастиря"}},{q="Чому арканіст Доан у Багряному Монастирі?",a="Арканіст Доан — обдарований людський чарівник із Даларану, що покинув своїх колег-магів із Кірін-Тору й перейшов до Багряного Хрестового Походу. Шукаючи усамітнення, щоб вивчати рідкісні рукописи й опанувати могутню вогняну й таємну магію, він прибрав до рук велике крило Бібліотеки монастиря.",al={"хто арканіст доан","лор доана","маг у бібліотеці"}},{q="Хто такий Александрос Моґрейн і як він пов'язаний із цим місцем?",a="Александрос Моґрейн, славетний Ешбрінгер і колишній очільник Срібної Длані в Лордероні, замолоду молився й навчався в монастирі. Після Третьої війни він зробив його передовим плацдармом проти нежиті; його син Рено нині командує Собором разом із Верховною інквізиторкою Вайтмейн.",al={"історія моґрейна монастир","ашбрінґер монастир","ренольт моґрейн батько"}},{q="Чим крило Цвинтаря відрізняється від решти монастиря?",a="Решта монастиря зовні видається бездоганно побожною, а на Цвинтарі фанатизм Походу гниє зсередини. Тут їхні жорстокі катівні, якими заправляє дізнавач Вішас, а занедбані склепи й неприкаяних мерців використовують або підкоряють собі занепалі чарівники на кшталт мага крові Талноса.",al={"чому кладовище нежить","лор талноса","допитувач віша"}}},fp="17,466,18.553.0,14.615.0,31.585.1,66.315.0,55.420.1,46.238.0,46.273.0,57.303.1,74.330.0"}
P.entries["zone:searinggorge"] = {n="Палюча Ущелина",s="Палюча Ущелина — випалений, безлюдний каньйон на півдні Каз Модану, що на півдні межує з Горою Блекрок. Колись це був зелений край Гір Редріджу, але понад два століття тому його спустошив апокаліптичний виклик Рагнароса, Володаря вогню. Нині в ущелині невтомно працює клан Темного Заліза, а за його розлогими рабськими копальнями в Казані пильно стежить Братство Торію, що відкололося від клану.",h="Палюча Ущелина — випалений, безлюдний каньйон на півдні Каз Модану, що на півдні межує з Горою Блекрок.",kw={"палюча ущелина","казан","шлакова яма","братство торію","темне залізо","торієвий мис","рагнарос"},ang={["class:Rogue"]="Якщо ви вправно зламуєте замки, вам тут раді: ви можете відімкнути ворота Каменетесного Проходу, що з'єднують Лох Модан просто з ущелиною.",["faction:Alliance"]="Альянс тримає ворота Каменетесного Проходу замкненими, щоб відрізати Темне Залізо від мирних дворфійських поселень у Лох Модані, хоча відважним шукачам пригод дозволено вдиратися в ущелину.",["faction:Horde"]="Використовуючи Карґат як базу, Орда проклала суходільний шлях в ущелину, щоб збирати відомості про Гору Блекрок і зривати роботу Темного Заліза в Каз Модані.",["profession:Mining"]="Вулканічний край і глибокі розробки Шлакової Ями роблять Палючу Ущелину одним із головних місць для пошуку багатих жил мітрилу, справжнього срібла й жаданої руди темного заліза.",["race:Dwarf"]="Для дворфів Айронфорджа Палюча Ущелина — гірке нагадування про Війну Трьох Молотів і катастрофічне безумство клану Темного Заліза, чиї розкопки тепер загрожують південним підступам Каз Модану."},sec={{t="Випалена пустка",b="До Війни Трьох Молотів край, де нині лежить Палюча Ущелина, був зеленим горбистим нагір'ям, що продовжувало хребет Редрідж. Той буйний край зник понад двісті тридцять років тому, коли чародій-тан Тауріссан, у відчаї намагаючись переломити хід програної війни, викликав Рагнароса з надр під світом. Катастрофічна поява Володаря вогню розірвала землю, підняла Гору Блекрок, обернула велике місто Темного Заліза Тауріссан на димні руїни й випалила північну долину на потріскану пустку попелу, сірки й вулканічного скла."},{t="Казан і Шлакова Яма",b="Шукаючи сировину для своєї військової машини після втрати давньої столиці, дворфи Темного Заліза захопили безлюдну ущелину. Посеред долини лежить Казан — величезний відкритий кар'єр, що глибоко врізається в камінь. У його нижніх закутках розташована Шлакова Яма — жорстокий підземний рудничний комплекс. Тут наглядачі Темного Заліза й неповороткі бойові ґолеми женуть полонених ворогів на виснажливу рабську працю: ті видобувають із розпеченої скелі залізо, мітрил і рідкісну руду темного заліза під постійною загрозою лавових викидів і бродячих звірів."},{t="Братство Торію й спірні шляхи",b="На північних скелях над розкопками стоїть Торієвий Мис — укріплена застава Братства Торію. Відколовшись від родичів у Горі Блекрок, ці майстри-ремісники пропонують нейтральний прихисток мандрівникам, які готові підривати роботу Темного Заліза чи постачати рідкісні складники для плавлення. Доступ до самої ущелини суворо обмежений: Альянс тримає Каменетесний Прохід до Лох Модану замкненим за важкими залізними воротами, а експедиції Орди з недалекого Карґата прорубали вузьку стежку через Пустища на сході, щоб розвідати край."}},faq={{q="Чому Палюча Ущелина обпалена й укрита попелом?",a="Понад двісті тридцять років тому, під час Війни Трьох Молотів, Чаклун-Тан Темного Заліза Тауріссан спробував прикликати надприродну силу, щоб уникнути поразки. Натомість він викликав Рагнароса, Володаря вогню. Нищівне виверження розтрощило південний кряж Редріджу, утворило вулкан Гору Блекрок і спопелило довколишні долини, перетворивши їх на Палючу Ущелину й Палаючі Степи.",al={"чому вона обпалена","лор палючої ущелини","як утворилася палюча ущелина"}},{q="Хто ці дворфи, що живуть на Торієвому Мисі?",a="Вони належать до Братства Торію — незалежного угруповання дворфів Темного Заліза, які розірвали зв'язки зі своїми імперськими родичами під Горою Блекрок. Зі свого табору на Торієвому Мисі вони працюють як майстри-ковалі й винахідники, ділячись знаннями й ремісничими секретами з кожним мандрівником, що допомагає їм проти сил Темного Заліза внизу.",al={"дворфи торієвого мису","хто братство торію","лор братства торію"}},{q="Що відбувається в Казані?",a="Казан — величезний відкритий кар'єр, де панує клан Темного Заліза; у ньому є підземна Шлакова Яма. Наглядачі й бойові големи Темного Заліза змушують полонених рабів добувати цінні руди — зокрема дорогоцінні поклади темного заліза, — щоб живити великі кузні в Горі Блекрок.",al={"що таке казан","лор шлакової ями","що копає темне залізо"}},{q="Як потрапити до Палючої Ущелини з Лох Модану?",a="Шлях із Лох Модану через Каменетесний Прохід перекриває важка замкнена брама, яку стережуть горяни Айронфорджа. Мандрівникам доведеться або здобути Ключ до Палючої Ущелини, виконавши офіційне доручення Куратора Торіуса, або попросити вправного розбійника зламати замок, або взагалі оминути браму відкритою стежкою на південь від Карґата в Пустищах.",al={"брама каменетесного проходу","як відчинити двері палючої ущелини","ключ до палючої ущелини"}},{q="Чому Палюча Ущелина цікавить Орду?",a="Діючи з фортеці Карґат у сусідніх Пустищах, командири Орди проклали в ущелину гірський прохід, щоб стежити за пересуванням військ Темного Заліза й убезпечити тактичні шляхи до Гори Блекрок, що має величезне стратегічне значення.",al={"чому орда тут","зв'язок каргата з ущелиною","присутність орди"}},{q="Чи є в Палючій Ущелині входи до підземель чи рейдів?",a="У самій ущелині порталів немає, але південний вхід веде просто до Гори Блекрок. У цій горі містяться Глибини Блекрок, Шпиль Блекрок і глибокі проходи до Розплавленого Ядра.",al={"підземелля палючої ущелини","підземелля тут","де розплавлене ядро"}}},fp="13,419,20.591.0,29.570.0,39.591.0,51.408.0,44.334.0,33.304.0,50.349.0,45.248.0,62.233.0"}
P.entries["zone:shendralas"] = {n="Шен'дралас",s="Шен'дралас — суворий, спірний дикий край між Фераласом, Малгором і південно-східною частиною Пустограю. Тут панують рештки давніх нічних ельфів і неспокійні кордони, а сам край — бурхливе перехрестя, де стикаються кентаври-загарбники, вигнанці без даху над головою й наїжачені шипогриви.",h="Шен'дралас — суворий, спірний дикий край між Фераласом, Малгором і південно-східною частиною Пустограю.",kw={"шен'дралас","кентаври","шипогриви","фронт маґрамів","долина кісток","схованка вигнанців","Високородні"},ang={["faction:Alliance"]="Віддалений спірний дикий край, що відкриває обхідні шляхи між Фераласом і центральним Калімдором, сповнений небезпек, які вимагають від вас пильності.",["faction:Horde"]="Край лежить одразу за південними межами Малгору, тож стримувати тут маґрамів і шипогривів украй важливо для захисту кордонів Орди.",["race:NightElf"]="Сама назва нагадує про давні перекази Високородних з Ельдре'Таласу, тож Вартові пильно стежать, чи не вдається тут хтось до безрозсудної магії на півдні Калімдору.",["race:Tauren"]="Край межує з Малгором і Пустограєм, тож агресія шипогривів і кентаврів на цих хребтах — пряма загроза мисливським угіддям ваших предків неподалік."},sec={{t="Неспокійне прикордоння",b="Захований у висотах на південний схід від Пустограю, між Малгором і Фераласом, Шен'дралас — дике прикордоння, далеке від великих столиць фракцій. Його скелясті перевали й приховані закутки дають притулок людям у відчаї, які виборюють собі існування на краю дикого Калімдору. Від відлюдних оглядових місць на кшталт Скелі Вечірньої Тіні до беззаконних сховищ на зразок Схованки Вигнанців — цей край належить тим, хто хоче стежити непоміченим або лишитися забутим."},{t="Кентаври, шипогриви й давні руїни",b="Земля носить виразний відбиток спадщини Високородних, що дала їй ім'я, та про спокій тут годі й мріяти. Війна кентаврів перехлюпується через Фронт Маґрамів, підтримуючи давню кровну ворожнечу вздовж кордонів. Тим часом шипогриви-загарбники тримають укріплені сховища на кшталт Притулку Щетиноспинів, перетворюючи кожен затінений яр на спірну землю для будь-якого мандрівника."},{t="Долина Кісток",b="На північний захід, до Пустограю, веде Долина Кісток — похмурий коридор, головний суходільний шлях до Шен'драласу. Вибілений сонцем і вітром, цей прохід — суворе нагадування про жорстокі сутички, що раз у раз прокочуються цими скелями."}},faq={{q="Де розташований Шен'дралас?",a="Шен'дралас лежить на південний схід від Пустограю, між кордонами Фераласу й Малгору. Пішки мандрівники зазвичай заходять сюди з Пустограю через Долину Кісток.",al={"де шен'дралас","розташування шен'драласу","як дістатися до шен'драласу"}},{q="Шен'дралас контролює Альянс чи Орда?",a="Жодна з фракцій тут не панує. Шен'дралас — спірне прикордоння, де бродять кентаври, ворожі шипогриви, вигнанці й стоять відокремлені табори.",al={"чи шен'дралас орди","чи шен'дралас альянсу","хто володіє шен'драласом"}},{q="Які тут головні поселення й орієнтири?",a="Серед помітних орієнтирів — Долина Кісток, Притулок Щетиноспинів, Оглядова Круча Вечірньої Тіні, Фронт Маґрамів, Схованка Вигнанців і центральні простори самого Шен'драласу.",al={"підзони шен'драласу","орієнтири шен'драласу","цікаві місця шен'драласу"}},{q="Чому тут є кентаври?",a="Війни кентаврів за землі сягають із рівнин Пустограю просто в цей край уздовж Фронту Маґрамів, де клан б'ється з місцевими захисниками й ворожими угрупованнями.",al={"кентаври шен'драласу","фронт маґрам","чому тут маґрам"}},{q="Що таке Притулок Щетиноспинів?",a="Притулок Щетиноспинів — укріплена застава шипогривів-Щетиноспинів, що люто закріпилися на околицях краю.",al={"притулок щетиноспинів","шипогриви шен'драласу"}},{q="Як цей край пов'язаний з Озером Дюмон?",a="Географічно глушина Шен'драласу лежить на гористих землях, де на старих розвідувальних мапах сховане відлюдне Озеро Дюмон.",al={"озеро дюмон","історія карти шен'драласу"}}},fp="11,286,23.441.0,36.393.0,19.282.0,29.189.0,55.155.0,45.172.0,27.175.0,28.139.0,57.153.0"}
P.entries["zone:silithus"] = {n="Силітус",s="Силітус — безлюдна пустеля, яку шмагають вітри, на далекому південному заході Калімдору. Під її сухими пісками лежать величезні колонії комахоподібних силітидів і давні руїни Ан'Кіража, запечатані тисячу років тому за грізною Стіною Скарабея. Нині друїди Кола Кенарія несуть тяжку варту проти роїв, що підкрадаються, і культистів, які пророкують кінець світу.",h="Силітус — безлюдна пустеля, яку шмагають вітри, на далекому південному заході Калімдору.",kw={"силітус","ан'кіраж","силітиди","стіна скарабея","війна рухомих пісків","цитадель кенаріуса","молот присмерку"},ang={["class:Druid"]="Силітус — серце діяльності Кола Кенарія на півдні Калімдору: він кличе друїдів спинити сплюндрування землі й дати відсіч протиприродним виводкам, що загрожують рівновазі природи.",["profession:Herbalism"]="Попри сувору пустелю, тут квітнуть рідкісні рослини: Гірський Срібношавлій, Снолист, Сонцетрав'я і надзвичайно цінний Чорний Лотос.",["profession:Mining"]="Сухі скелі й тунелі комах у Силітусі ховають одні з найбагатших покладів торію у світі, зокрема рідкісні жили, вкриті слизом, у глибині вуликів силітидів.",["race:NightElf"]="Силітус — похмуре місце спочинку, де ваші предки проливали кров у Війні Рухомих Пісків, віддавши тисячі життів, щоб запечатати брами Ан'Кіража."},sec={{t="Пустельне прикордоння",b="Щоб дістатися Силітусу, треба пройти первісними джунглями Кратера Ун'Ґоро й піднятися широким кам'янистим перевалом у його північно-західному куті. Перехід разючий: буйна первісна зелень раптом зникає, поступаючись безмежжю рухомих дюн, зубчастого каміння й неприродно високих вуликів. Води тут майже немає, а вітер несе дзижчання крил і шепіт пісків. Посеред пустелі Коло Кенарія утримує Цитадель Кенаріуса — єдиний оплот цивілізації й прихисток для мандрівників, дослідників і воїнів, що наважуються вирушити в ці ворожі пустки."},{t="Відлуння рухомих пісків",b="Тисячу років тому ця посушлива пустка стала полем битви у Війні Рухомих Пісків. Об'єднане військо нічних ельфів і великих драконячих родів відчайдушно билося, щоб відкинути кіраджі — підступну імперію комах, що постала з давньої цивілізації акірі. Коли повна перемога виявилася неможливою, захисники замкнули рої в їхній твердині за Стіною Скарабея й зачарованим Помостом Скарабея. Величні ворота встояли, але підземними тунелями звіроподібні силітиди прокопалися назовні й заснували по всіх пісках розлогі колонії — Вулик'Аші, Вулик'Зора й Вулик'Реґал."},{t="Буря, що насувається",b="Апокаліптичний культ Молота Присмерку окопався на кількох укріплених заставах: його прибічники викликають жахливих елементалів і шанують темну силу, що дрімає під Ан'Кіражем. Спостерігачі Кола Кенарія стежать за колоніями силітидів, що розростаються пустелею, і за давньою загрозою по той бік Стіни Скарабея."}},faq={{q="Як дістатися до Силітусу пішки?",a="Ідіть до північно-західного кута Кратера Ун'Ґоро. Біля звивистого вигину річки, між двома помітними природними кам'яними стовпами, похила ґрунтова дорога піднімається гористою стіною кратера просто в пустелю Силітусу.",al={"вхід у силітус","як дістатися до силітусу","шлях до силітусу"}},{q="Що таке Стіна Скарабея?",a="Стіна Скарабея — величезний зачарований бар'єр на півдні Силітусу. Тисячу років тому, під час Війни Рухомих Пісків, його звели нічні ельфи й драконячі роди, щоб ув'язнити лиховісну імперію кіраджі в Ан'Кіражі.",al={"ворота ан'кіраджа","стіна скарабея","велика стіна в силітусі"}},{q="Хто керує Цитаделлю Кенаріуса?",a="Цитадель Кенаріуса — застава, яку заснувало й утримує Коло Кенарія. Його друїди й союзні вартові спостерігають за роями силітидів, що підступають, досліджують прадавні руїни й приймають нейтральних мандрівників і з Альянсу, і з Орди.",al={"хто в твердині кенарія","фракція твердині кенарія","твердиня кенарія дружня"}},{q="Що це за велетенські комашині горби по всьому краю?",a="Це головні підземні вулики силітидів: Вулик'Аші, Вулик'Зора й Вулик'Реґал. Кожен вулик — розлога мережа тунелів, де живуть окремі касти комахоподібних створінь, що служать волям, замкненим за Ан'Кіражем.",al={"вулики силітусу","комашині вулики силітусу","вулик аші вулик зори"}},{q="Що тут робить Молот Присмерку?",a="Культ Молота Присмерку тримає в Силітусі кілька укріплених баз, зокрема Сутінковий Базовий Табір і Сутінкову Заставу. Культисти проводять мерзенні ритуали, щоб викликати елементалів, і поклоняються прадавнім лиховісним сутностям, похованим за Стіною Скарабея.",al={"культисти сутінків силітус","сутінкова передова силітус","чому молот присмерку в силітусі"}}},fp="8,366,19.594.0,28.622.0,18.305.0,33.234.0,24.246.0,23.233.0,49.227.0,41.250.0"}
P.entries["zone:silverpine"] = {n="Срібнолісся",s="Срібнолісся — моторошний, оповитий туманом ліс уздовж західного узбережжя Лордерона між Галявинами Тірісфалю й замкненою Стіною Ґреймейна. Досі пошрамований чумою Погибелі, він став спірним південним прикордонням Відступників. Мандрівників тут чекають дикі воргени, що никають у тінях, хворі гноли й ворожі людські анклави.",h="Срібнолісся — моторошний, оповитий туманом ліс уздовж західного узбережжя Лордерона між Галявинами Тірісфалю...",kw={"срібнолісся","відступники","гробниця","воргени","фортеця шадовфенг","амбермілл","лордерон"},ang={["class:Mage"]="Амбермілл і падіння Архімага Аруґала у вовче божевілля роблять Срібнолісся похмурою пересторогою про магію Кірін-Тору, що катастрофічно збилася на манівці.",["faction:Alliance"]="Дослідники з Альянсу знайдуть тут украй ворожий ліс, де трапляються хіба що хиткий даларанський гарнізон в Амберміллі та трагічні прокляті селяни Села Пайрвуд.",["race:Undead"]="Срібнолісся — передова розширення Відступників на південь від Галявин Тірісфалю, де Королівське Аптекарське Товариство випробовує нові зілля, а Вартові Смерті б'ються з недобитими агентами Погибелі."},sec={{t="Проклятий рубіж",b="Колись Срібнолісся славилося як пишне диво Лордерона, яким шляхетні мандрівники подорожували до Міста Лордерон, але під подихом Третьої війни воно зів'яло. Примарні тумани в'ються між сосен зі срібною корою, що всихають, а зруйновані хутори покинуті напризволяще дикій природі. На півночі лежать Галявини Тірісфалю, а східний берег межує з Озером Лордамер. На півдні стоїть грізна й замкнена Стіна Ґреймейна, що відгороджує відокремлене королівство Ґілнеас від хаосу довкола. Відступники тримають свою головну заставу в Гробниці, намагаючись убезпечити ліс від ворогів з усіх боків."},{t="Воргени й Шадовфенг",b="Найлиховісніша небезпека Срібнолісся — прокляття воргенів. Високо над південно-західними лісами стоїть Фортеця Шадовфенг — колишній осідок Барона Сільверлейна, де тепер панує божевільний даларанський архімаг Аруґал. Прагнучи відбити Погибель під час Третьої війни, Аруґал викликав вовкоподібних звірів з іншого виміру. Створіння обернулися проти тих, хто їх викликав, поширивши прокляття перевертнів південними лісами. У Селі Пайрвуд звичайні на вигляд люди-селяни вдень порядкують по господарству, а під нічним небом обертаються на лютих воргенів."},{t="Суперницькі анклави й Погибель",b="Право Відступників на Срібнолісся запекло оскаржують і живі, і мертві. На сході, на Острові Фенріс, Тул Рейвенклов очолює недобитків Погибелі й командує враженими чумою гнилошкірими гнолами, що спустошують північні угіддя. На півдні люди-маги з Даларана тримають укріплене поселення Амбермілл, ведуть містичні дослідження й опираються розширенню Відступників. Королівське Аптекарське Товариство й Верховний Екзекутор Гадрек у Гробниці ведуть жорстоку, багатофронтову кампанію, щоб знищити ці загрози й випробувати нові смертоносні чуми."}},faq={{q="Що таке Стіна Ґреймейна на південному кордоні?",a="Стіна Ґреймейна — величезний кам'яний бар'єр, який звів король Ґенн Ґреймейн, щоб цілком відгородити своє королівство Ґілнеас від решти Лордерона. Коли під час Третьої війни Погибель спустошувала континент, Ґілнеас замкнув брами й відмовився від сторонньої допомоги, лишивши землі на північ від стіни — зокрема південне Срібнолісся — напризволяще.",al={"чому величезна стіна","лор стіни ґреймейна","брама до ґілнеасу"}},{q="Чому мешканці Села Пайрвуд нападають уночі?",a="Мешканці Села Пайрвуд страждають від воргенського прокляття Архімага Аруґала. Удень вони зберігають людську подобу, живуть звичним життям і приязні до Альянсу. Коли сходить місяць, прокляття бере своє, і все населення перетворюється на лютих кровожерних воргенів, що жорстоко нападають на всіх поблизу.",al={"таємниця пайрвуду","воргени пайрвуду","чому люди пайрвуду ворожі вночі"}},{q="Хто такий Тул Рейвенклов?",a="Тул Рейвенклов — могутній некромант на службі Погибелі. Діючи з Фортеці Фенріс на Острові Фенріс посеред Озера Лордамер, він командує легіонами нежиті й тримає під своїм впливом хворих гнилошкірих гнолів по всьому східному Срібноліссю, прямо загрожуючи східному флангу Відступників.",al={"хто керує островом фенріс","лор тула рейвенклова","погибіль на фенріс"}},{q="Чому Даларан займає Амбермілл?",a="Амбермілл тримають чарівники Даларану на чолі з Архімагом Атаеріком. Із селища ці людські маги стежать за рухами Відступників, вивчають магічні недуги, що мучать ліс, і намагаються стримати спалах воргенів, що поширюється з Фортеці Шадовфенг.",al={"маги амберміла","чому альянс в амберміллі","даларан у сілверпайні"}},{q="Що таке Гробниця?",a="Гробниця — головна військова застава й транспортний вузол Відступників у Срібноліссі. Під командуванням Верховного Екзекутора Гадрека вона слугує базою для патрулів Варти Смерті, розвідників-Скрадачів смерті і Королівського Аптекарського Товариства, що борються за контроль над лісом.",al={"місто орди сілверпайн","де політ","лор гробниці"}},{q="Чи можуть гравці Альянсу виконувати завдання в Срібноліссі?",a="У Срібноліссі немає ні осередків завдань Альянсу, ні дружніх містечок: усі місцеві завдання — лише для Орди. Шукачі пригод з Альянсу зазвичай заходять у ліс лише дорогою із Саутшора, щоб дослідити Фортецю Шадовфенг чи битися з ворожими силами Відступників.",al={"чи сілверпайн лише для орди","завдання альянсу сілверпайн","чи альянс може в сілверпайн"}}},fp="17,362,18.611.0,25.536.0,30.560.1,49.350.0,57.329.0,23.292.0,35.268.0,22.284.0,48.260.0"}
P.entries["zone:stockade"] = {n="В'язниця",s="В'язниця — тюремний комплекс суворого режиму в Стормвінді, захований під міським кварталом каналів біля Кварталу магів. Збудована, щоб тримати найнебезпечніших головорізів королівства, політичних бунтарів і полонених ворогів держави, нещодавно вона поринула в жорстоку анархію. Наглядача Телвотера відтіснили до самого входу, і він відчайдушно наймає вправних шукачів пригод, щоб придушити бунт зсередини, доки той не вихлюпнувся на вулиці столиці.",h="В'язниця — тюремний комплекс суворого режиму в Стормвінді, захований під міським кварталом каналів біля...",kw={"в'язниця","стормвінд","бунт","базіл тредд","дефіас","наглядач телвотер","підземелля"},ang={["class:Mage"]="В'язниця лежить просто біля каналу Кварталу магів; її кулачні бійці вразливі до сповільнювальних чарів, а огр-маг Окіст здатен вивільнити Ланцюгову блискавку.",["class:Rogue"]="Плетиво замкнених залізних камер і зв'язків Дефіас у в'язниці дає неабияку практику зі зламування замків і змогу зазирнути в підпільну мережу Базіла Тредда.",["faction:Alliance"]="Бунт загрожує самому серцю столиці; придушивши його, ви збережете внутрішню безпеку Стормвінда й виконаєте неофіційні замовлення Редріджу, Сутінколісся та Айронфорджа.",["race:Dwarf"]="Присутність Кама Діпф'юрі в камерах Стормвінда — образа для Дун Модра; Королівство Айронфордж вимагає його голови, щоб помститися за життя дворфів, утрачені в Багнокраї."},sec={{t="В'язниця в облозі",b="Під тихими каналами Стормвінда В'язниця перетворилася на поле бою. Коли регулярна армія вирушила воювати на далекі фронти, в'язниця, якій бракувало людей, покладалася на недосвідчену молодь — аж до чотирнадцятирічних новобранців. Цього виявилося замало. В'язні підняли кривавий злагоджений бунт: порвали вовняні ковдри на пов'язки для своїх банд і вирізали решту вартових. Наглядач Телвотер ледве втримав вхід, а камери, коридори й блоки опинилися в безжальних руках каторжників."},{t="Вельможі й убивці",b="Бунт оголив потворну зворотну сторону політичної машини Стормвінда. Віддалені краї давно обурювалися тим, що Дім Вельмож зупиняє страти заради власних інтересів. Вартовий Редріджу Бертон хотів, щоб полоненого орка Тарґорра Жахливого стратили за звірства, — і бачив, як вельможі заморозили вирок. Радник Даркшира Міллстайп бачив, як грабіжник могил Декстрен Ворд уникнув шибениці, хоча оскверняв могили для некроманта Морбента Фела. Навіть дворфи Дун Модра надіслали вимогу стратити диверсанта Темного Заліза Кама Діпф'юрі. Поки у В'язниці панує хаос, місцева влада потай наймає шукачів пригод, щоб виконати страти, яких столичні суди виконувати відмовилися."},{t="Натхненник і бунтарі",b="За злагодженим падінням в'язниці стоїть Базіл Тредд — хитрий злочинець, безпосередньо пов'язаний із Братством Дефіас, що керував бунтом зі своєї камери. Серед бунтарів — Бруеґал Айроннакл, небезпечний дворф, кулачний боєць. Він лише один із кількох загартованих каторжників, яких шукачі пригод можуть зустріти, допомагаючи Телвотерові повернути в'язницю."}},faq={{q="Чому у В'язниці відкритий бунт?",a="Братство Дефіас влаштувало заколот на всю в'язницю, коли там гостро бракувало варти. Поки армія Стормвінда воювала на далеких фронтах, вартувати запеклих убивць лишили юних добровольців. В'язні напали на охорону, захопили зброю й витіснили Наглядача Телвотера з камер.",al={"чому бунт","що сталося у в'язниці","причина бунту у в'язниці"}},{q="Хто керує заколотом усередині?",a="Натхненник бунту — Базіл Тредд, впливовий злочинець із Дефіас, ув'язнений у східному блоці камер. Серед інших небезпечних в'язнів — Бруеґал Айроннакл, Окіст і Кам Діпф'юрі.",al={"бос в'язниці","хто веде бунт","хто керує в'язницею"}},{q="Чому такі в'язні, як Тарґорр і Декстрен Ворд, досі живі?",a="Обох засудили до страти, але продажні політики в Домі Вельмож бюрократично затримали виконання вироків, щоб використати в'язнів як політичний важіль. Це втручання обурило союзників у Лейкширі й Даркширі, і ті послали шукачів пригод, щоб у метушні покінчити з цими в'язнями.",al={"чому таргорр не страчений","суд декстрена варда","корупція дому вельмож"}},{q="Що означає для в'язниці перемога над Бруеґалом Айроннаклом?",a="Бруеґал Айроннакл — небезпечний дворф-громило серед бунтівників. Перемога над ним усуває одну із загроз у в'язниці, поки шукачі пригод придушують заколот.",al={"лор бруеґала","вбити бруеґала","хто бруеґал"}},{q="Чому в людській в'язниці дворфи Темного Заліза й орки?",a="В'язниця слугує загоном найсуворішого режиму для важливих військовополонених. Тарґорр Жахливий водив орків Блекрок у напади на Редрідж, а Кам Діпф'юрі чинив диверсії для клану Темного Заліза в Багнокраї, перш ніж обох схопили й перевели до столиці.",al={"чому темне залізо тут","лор кам діпфурі","таргорр в'язниця"}},{q="Чи можуть гравці Орди потрапити до В'язниці?",a="Так, але це надзвичайно небезпечно. Вхід до підземелля міститься просто в Стормвінді біля каналів Кварталу магів. Лазутчикам Орди доведеться прокрастися повз міську варту й захисників столиці, щоб дістатися порталу.",al={"чи орда може у в'язницю","орда у в'язниці стормвінда"}}},fp="12,455,20.556.0,20.705.1,30.341.1,38.314.0,35.198.0,60.303.0,60.167.0,61.278.0,37.226.0"}
P.entries["zone:stonetalon"] = {n="Гори Кам'яного Кігтя",s="Гори Кам'яного Кігтя — суворий, обточений вітрами ланцюг скелястих вершин на межі з Ашенвалем, Пустками та Пустограєм. І нічні ельфи, і таурени шанують цей край як священний притулок, і його святі висоти разюче контрастують із димом і машинами, що душать нижні каньйони. Сьогодні гори роздирають вирубки, руйнівна стихія елементалів і прикордонна ворожнеча, що ледь жевріє.",h="Гори Кам'яного Кігтя — суворий, обточений вітрами ланцюг скелястих вершин на межі з Ашенвалем, Пустками та...",kw={"гори кам'яного кігтя","венчурна компанія","лихі вітри","оракул","нічні ельфи","таурени","обвуглена долина"},ang={["class:Druid"]="Осквернення Кручі Вітрорізу та випалена порча Обвугленої Долини — грізний заклик до друїдів: угамувати розлючених духів природи й захистити священні гнізда.",["class:Shaman"]="Крик гірських духів, яких терзають гоблінські бури, чути аж в Оргріммарі: він кличе шаманів угамувати розлючених кам'яних елементалів і повернути вершинам рівновагу.",["faction:Alliance"]="Альянс, що закріпився на вершині Піка Кам'яного Кігтя та в прихованих таборах довкола Кручі Вітрорізу, захищає прадавні підземні обителі калдореїв від гоблінських машин і суперників, що зазіхають на ці землі.",["faction:Horde"]="Шукачі пригод Орди спираються на відлюдний Притулок Сонячної Скелі та південну тролячу заставу Малака'джин, щоб приборкати промислове забруднення Венчурної Компанії й викорінити віроломних вигнанців Ґрімтотем."},sec={{t="Лихі Вітри та вершини",b="Хребет Кам'яного Кігтя, що круто здіймається з центрального Калімдору, перехоплює вологу із західних морів — звідси раптові зливи й підступні, слизькі від дощу пісковикові стежки. Нижні долини найбільше відомі невщухаючим вітром, що шмагає все довкола, — його звуть Лихими Вітрами: він може засліпити мандрівника піском або скинути необачного з прямовисної кручі. Вище вічнозелені ліси вкривають гребені довкола Піка Кам'яного Кігтя, де нічні ельфи доглядають підземні обителі й галявини предків, оберігаючи священні гнізда віверн і гіпогрифів на берегах Озера Міркфаллон."},{t="Промисел і вторгнення",b="Мирну самотність хребта брутально порушив прихід Венчурної Компанії. Гобліни розбили величезні лісозаготівельні табори, вирили глибокі кар'єри в Кручі Вітрорізу і — з допомогою божевільного прокаженого гнома Ґерензо Ренчвісла — вирубали праліс, затягли небо пічним димом і залили гірські стоки промисловим мулом. Їхня жадоба не лишилася без швидкої відплати: на страдницькі крики гірських духів відгукнулися шамани з Оргріммара, а невеликі табори Альянсу неподалік дають відсіч осквернителям, щоб уберегти те, що лишилося від височин."},{t="Шрами минулого",b="На півдні лежить Обвуглена Долина — колись квітуча дика місцина, а нині вкрита попелом пустка, де вирують некеровані вогняні елементалі, чорні драконороди та гарпії. Саме на цих вершинах під проводом загадкового Оракула Орда й Альянс уклали хиткий мир під час Третьої війни, проте нині стосунки знову тріщать. Ренегати-таурени Ґрімтотем діють із захоплених таборів, а тролі Темного Спису з Малака'джина б'ються із загонами Альянсу, що просуваються з Пусток і Ашенвалю."}},faq={{q="Як дістатися до Гір Кам'яного Кігтя?",a="Більшість мандрівників заходить Перевалом Глибокого Пазура — гірською стежкою, що врізається в кряж із південного заходу Ашенвалю. Є також високі стежки на південь до Пустограю й шляхи, що спускаються на схід просто в північні простори Пусток.",al={"вхід у кам'яний кіготь","як дістатися до кам'яного кігтя","дорога кам'яного кігтя"}},{q="Чому Обвуглена Долина спалена й зруйнована?",a="Колись Обвуглена Долина була буйним прихистком, але катастрофічне спустошення поглинуло її у вогні. Тепер це тліюча руїна, де кишать агресивні вогняні елементалі, здичавілі дракони й смертоносні гарпії.",al={"вогонь обвугленої долини","що сталося з обвугленою долиною","чому обвугленої долини спалена"}},{q="Що Венчурна Компанія робить на Кручі Вітрорізу?",a="Венчурна Компанія безжально вирубує ліс і глибоко свердлить гори в пошуках копалин. Її діяльність забруднила Озеро Скельної Заводі машинним мастилом, оголила долини й розлютила місцевих духів і корінних мешканців.",al={"венчур ко кам'яний кіготь","гобліни вітрорізу","чому гобліни рубають дерева"}},{q="Де головні розпорядники польотів?",a="Герої Альянсу користуються розпорядником польотів у високому прихистку на Піку Кам'яного Кігтя на півночі, а шукачі пригод з Орди отаборюються в центральному гірському селищі — Притулку Сонячної Скелі.",al={"політ кам'яного кігтя","де політ кам'яного кігтя","майстри польотів кам'яного кігтя"}},{q="Що сталося на Піку Кам'яного Кігтя під час Третьої війни?",a="Ведені видіннями Пророка Медіва, Тралл і Джайна Праудмур піднялися печерами Піку Кам'яного Кігтя на пошуки Оракула. Там провідники двох фракцій уклали історичний тимчасовий союз, що об'єднав їх проти Палаючого Легіону на Горі Гіджал.",al={"лор піку кам'яного кігтя","оракул кам'яного кігтя","третя війна кам'яний кіготь"}},{q="Хто такі Ґрімтотеми в Горах Кам'яного Кігтя?",a="Ґрімтотеми — безжальне відступницьке плем'я тауренів, вороже до будь-якого чужого впливу. У Горах Кам'яного Кігтя вони зайняли гірську заставу біля кордону з Пустками, тероризують місцевих мандрівників і беруть полонених.",al={"застава ґрімтотем","ґрімтотеми кам'яного кігтя"}}},fp="20,410,27.610.0,22.630.0,17.537.0,41.251.0,42.215.0,52.258.0,42.193.0,54.257.0,36.219.0"}
P.entries["zone:stormwind"] = {n="Стормвінд",s="Стормвінд — гамірна столиця королівства Стормвінд і найбільший оплот людей у світі після падіння Лордерона. Відбудовані з попелу Гільдією Каменярів після руйнування в Першій війні, його величні квартали з білого каменю нині вміщують серце Великого Альянсу. Та під розкішними каналами й соборами місто потерпає від раптового зникнення короля Варіана Рінна і дедалі гострішої політичної інтриги.",h="Стормвінд — гамірна столиця королівства Стормвінд і найбільший оплот людей у світі після падіння Лордерона.",kw={"стормвінд","столиця","варіан рінн","андуїн рінн","болвар","гільдія каменярів","дефіас"},ang={["class:Paladin"]="Собор Світла — найвища святиня вашої віри на півдні: тут навчають лицарів Срібної Длані й стоять на сторожі справедливості.",["class:Rogue"]="Під бездоганними кам'яними вулицями, у Старому Місті, ховається штаб SI:7 — головна розвідувальна й шпигунська мережа Альянсу.",["faction:Alliance"]="Як найлюдніше місто Великого Альянсу, Стормвінд дає йому морську міць, духовну опору й незамінне дипломатичне лідерство.",["race:Dwarf"]="Завдяки Глибинному трамваю ваші родичі з Дворфійського Кварталу мають тісні торговельні зв'язки з королівством людей і кують із ним братерський військовий союз.",["race:Human"]="Стормвінд — останній великий осередок суверенної влади вашого народу після загибелі Лордерона, Альтерака й Даларана на півночі."},sec={{t="Відродження з попелу",b="Заснований понад тисячу років тому нащадками араті, Стормвінд поколіннями був квітучим, самодостатнім королівством. Ця золота доба скінчилася, коли Орда орків ринула крізь Темний Портал, спустошила південний континент і зрівняла столицю з землею в Першій війні. Уцілілі на чолі з сером Андуїном Лотаром утекли на північ, за Велике Море, до Лордерона. Після поразки Орди в Другій війні король Теренас Менетіл II та Альянс профінансували повну відбудову. Гільдія Каменярів ретельно відродила столицю як Новий Стормвінд — сяйливу цитадель із полірованого білого каменю й кварталів, порізаних каналами."},{t="Розколотий двір",b="Попри зовнішню велич, столицю роздирають внутрішні негаразди. Суперечка між Домом Вельмож і Гільдією Каменярів через платню загнала королівство в борги й паралізувала його. Заворушення, що спалахнули, забрали життя королеви Тіффін Рінн, а вигнаних майстрів штовхнули на злочинний шлях — так постало Братство Дефіас. Тепер король Варіан Рінн загадково зник дорогою на дипломатичні перемовини. Щоб уникнути паніки, корону поклали на голову його малого сина, десятирічного принца Андуїна Рінна, а правити як регент і командувач війська став Верховний Лорд Болвар Фордрагон разом із королівською радницею Леді Катраною Престор."},{t="Серце Великого Альянсу",b="Відколи Лордерон захопила Погибель, Стормвінд успадкував роль найбільшого прихистку людства й осередку Альянсу. З дворфійським королівством Айронфордж його сполучає підземний Глибинний трамвай Великого Тінкера Меккаторка. Гостей, що перетинають Долину Героїв, зустрічають велетенські статуї Синів Лотара, які зникли за Темним Порталом. Від духовного маяка — Собору Світла — до чародійських студій у Святилищі Чародія Стормвінд лишається найважливішим осередком торгівлі, культури й оборони на південних морях."},{t="Тіні у фортеці",b="Розбрат, що терзає королівство, — не просто адміністративна випадковість. Леді Катрана Престор потай спрямовує рішення Дому Вельмож, розпалює ворожнечу з каменярами й навмисно ігнорує прохання про військову допомогу з віддалених поселень на кшталт Вестфола та Редріджа. Нашіптуючи отруйні поради Верховному Лорду Болвару й розпорошуючи увагу королівства, вона тримає легіони Стормвінда бездіяльними й розділеними, поки неспокій за мурами міста загрожує самому трону."}},faq={{q="Хто зараз править Стормвіндом?",a="Корону носить десятирічний принц Андуїн Рінн, але насправді королівством керує Верховний Лорд Болвар Фордрагон — регент Стормвінда й верховний командувач його війська. Поки король Варіан Рінн вважається зниклим, Болвар значною мірою покладається на поради королівської радниці Леді Катрани Престор.",al={"нинішній король","хто король","хто очолює стормвінд","король стормвінда"}},{q="Що сталося з королем Варіаном Рінном?",a="Король Варіан за підозрілих обставин зник дорогою на дипломатичні перемовини в Тераморі, куди плив кораблем. Щоб зберегти лад, про його зникнення мовчать, але чутки вже ширяться вулицями міста й селами.",al={"де варіан","зниклий король","варіан зник","зникнення варіана рінна"}},{q="Чому місто відбудовували і хто це зробив?",a="Перше місто Орда орків спалила дотла в Першій війні. Після Другої війни Гільдія Каменярів на чолі з майстром Едвіном Венкліфом ретельно відбудувала столицю з сяйливого білого каменю, а гроші на це дав Альянс Лордерону.",al={"хто відбудував стормвінд","гільдія каменярів","новий стормвінд","відбудова міста"}},{q="Чому каменярі повстали проти корони?",a="Дім Вельмож загнав королівство в борги, нарощуючи військо Стормвінда, і відмовився заплатити Гільдії Каменярів обіцяну платню. Коли Едвін Венкліф зажадав розрахунку, вельможі розпустили гільдію. Робітники збунтувалися, королеву Тіффін Рінн убив кинутий камінь, а вигнані каменярі заснували Братство Дефіас.",al={"звідки дефіас","чому дефіас розлючені","бунт каменярів","смерть королеви тіффін"}},{q="Кому стоять велетенські статуї в Долині Героїв?",a="Статуї вшановують Синів Лотара: генерала Туральйона, капітана рейнджерів Аллерію Віндраннер, архімага Хадґара, Курдрана Вайлдгаммера й Даната Троллбейна. Їх звели на честь героїв, що пішли крізь Темний Портал на Дренор, аби закрити розлом і вберегти Азерот.",al={"статуї біля входу","статуї долини героїв","статуї синів лотара"}},{q="Як Стормвінд сполучений з Айронфорджем?",a="Стормвінд сполучає з Айронфорджем Глибинний трамвай — підземна залізниця, яку збудував Великий Тінкер Ґелбін Меккаторк на замовлення короля Маґні Бронзбірда, щоб між двома столицями швидко йшла торгівля й так само швидко прибувало підкріплення.",al={"глибинний трамвай","потяг до айронфорджа","як дістатися айронфорджа"}},{q="Чому Стормвінд не посилає війська на допомогу Вестфолу й Редріджу?",a="Королівський двір, де головне слово має Леді Катрана Престор, твердить, що місто не може зняти солдатів зі своїх мурів і найближчих кордонів. Скарбниця виснажена, Дім Вельмож паралізують чвари, тож віддалені містечка покинуто напризволяще: вони мусять покладатися на місцеве ополчення.",al={"де армія стормвінда","чому вестфолу не допомагають","у підкріпленні відмовлено"}}},fp="14,461,19.657.0,15.605.0,27.577.0,19.516.2,30.299.0,35.231.0,38.286.0,48.333.0,50.279.0,40.240.0,65.292.0"}
P.entries["zone:stranglethorn"] = {n="Долина Стренглторну",s="Долина Стренглторну — неприборкані густі джунглі на південному краю Східних Королівств, на південь від Сутінколісся. Колись тут був осідок великої Імперії Ґурубаші, а нині дощовий ліс усіяний руїнами тролячих споруд, кишить лютими звірами й таборами гоблінів, піратів і солдатів, що змагаються між собою. За владу над краєм запекло борються місцеві племена тролів, Венчурна Компанія й суперницькі фракції, що виборюють собі плацдарми в цій спеці.",h="Долина Стренглторну — неприборкані густі джунглі на південному краю Східних Королівств, на південь від...",kw={"долина стренглторну","буті бей","зул'ґуруб","ґурубаші","гаккар","ґром'ґол","несінгварі"},ang={["class:Hunter"]="На північному березі річки живе славетний мисливець на великого звіра Гемет Несінгварі. Він кидає виклик стрільцям: випробуйте свою вправність, вистежуючи найлютіших рапторів, пантер і кроколісків джунглів.",["faction:Alliance"]="Спроби Стормвінда підкорити й угамувати джунглі обтяжили королівство великими боргами, а нині його інтереси тут обстоюють лише знесилені заколотники з Табору Повстанців.",["faction:Horde"]="Базовий Табір Ґром'ґол — незамінна стратегічна твердиня Орди на південному континенті, яку цепеліни постачають просто з Дуротару й Андерсіті.",["profession:Herbalism"]="Волога лісова завіса живить цінні рослини, тож береги річок і узбережжя — чудові угіддя для збирання Дикого Сталецвіту, Блідолисту, Золотошипу й Фіолетового Лотосу.",["race:Troll"]="Стренглторн — прадавня колиска тролів джунглів, чия давня імперія Ґурубаші загинула в громадянській війні після поклоніння Гаккару Душолупу, і саме тоді племена на кшталт Темного Спису подалися за море."},sec={{t="Руїни імперії",b="Тисячоліттями долиною правила могутня Імперія Ґурубаші зі своєї столиці Зул'Ґуруб. Її владі настав край, коли жерці-радикали викликали Гаккара Душолупа й кинули край у катастрофічну громадянську війну. Хоча зандаларі втрутилися й придушили повстання кривавого бога, імперія безповоротно розкололася. Нині джунглі заполонили ворожі між собою племена-спадкоємці — передусім Кривавого Скальпа на північному заході й Череполоми на сході, — і обидва ревно вирізають чужинців, щоб повернути собі землю предків."},{t="Пірати й ділки",b="Де замовкають давні руїни, порожнечу заповнює торговельна жадоба. На південному краю лежить Буті Бей — гамірна гавань, яку збудував картель Стімвідл і якою керують Нападники Чорної Води на чолі з Бароном Ревілґазом. Порт — головний осередок південної торгівлі й морських перевезень, хоча його невпинно облягають суперники — Буканіри Кривавого Вітрила, що стоять на якорі вздовж узбережжя. Углиб суходолу Венчурна Компанія хижацьки вирубує ліс і риє пагорби в пошуках рідкісних співочих кристалів."},{t="Спірні нетрі",b="Долина Стренглторну — одне з найнеспокійніших прикордонь світу. Орда утримує Базовий Табір Ґром'ґол на західному узбережжі, з'єднаний гоблінськими цепелінами з Дуротаром і Галявинами Тірісфалю, а вірні Альянсу діють із Табору Повстанців, вистежуючи свавільного Полковника Курзена. У густих хащах легендарний мисливець Гемет Несінгварі веде відважні експедиції на великого звіра, втягуючи мандрівників у небезпечні зустрічі з пантерами, велетенськими мавпами й ворожими вояками."},{t="Безумство в джунглях",b="Не всі загрози північного Стренглторну — дикі звірі. Полковник Курзен, колись нагороджений командир, якого вислав сюди Стормвінд, збожеволів серед хащ і заснував тиранічний табір найманців. Насправді ж розум Курзена поневолили чари Ока Розуму — артефакту, яким володіє огр-маг Май'Зот із недалекого Кургану Огрів Мош'Оґґ. Саме це звело експедицію з розуму, і колишні солдати Курзена відкололися й заснували Табір Повстанців."}},faq={{q="Хто контролює Долину Стренглторну?",a="Жодна сила не панує в долині. Джунглі поділені між ворожими племенами тролів джунглів, як-от Кривавий Скальп і Череполоми, табори відступників на кшталт Поселення Курзена, найманців Венчурної Компанії й розкидані військові застави Орди й Альянсу. Найбільше місто — нейтральний гоблінський порт Буті Бей, яким керують Барон Ревілґаз і Нападники Чорної Води.",al={"хто володіє стренґлторном","хто править стренґлторном","фракції стренґлторну"}},{q="Що таке Буті Бей?",a="Буті Бей — розлоге портове місто на південних кручах Мису Стренглторну. Спочатку це було людське поселення під назвою Бухта Чорної Води; його захопили тролі, а згодом там закріпився картель Стімвідл. Нині Барон Ревілґаз і Флотоводець Сігорн керують ним як нейтральним торговим портом, звідки мандрівники пливуть через Велике Море до Раджета.",al={"що таке бутті бей","порт бутті бей","хто керує бутті бей"}},{q="Чому Полковник Курзен став відступником?",a="Полковник Курзен повів експедицію в джунглі від імені Стормвінда, але його розум підпав під владу Май'Зота — огра-мага з могутньою реліквією під назвою Око Розуму. Курзен ставав дедалі непередбачуванішим і деспотичнішим, тож вірні вояки, як-от Лейтенант Дорен, відкололися й заснували Табір Повстанців, щоб зупинити його.",al={"чому курзен злий","що сталося з курзеном","передісторія курзена"}},{q="Що таке Зул'Ґуруб?",a="Зул'Ґуруб — прадавня столиця імперії Ґурубаші, всіяна храмами, що ховається на північному сході Стренглторну. Це був осередок громадянської війни, що поклала край імперії півтори тисячі років тому, коли радикальні жерці викликали бога крові Гаккара Душолупа. Хоча місто давно поглинули ліани й руїни, темні ритуали й далі загрожують його залам.",al={"що таке зґ","історія зул'ґуруб","столиця ґурубаші"}},{q="Що таке Камінь Припливів?",a="Камінь Припливів — легендарна реліквія з прадавньої історії Ґурубаші, яку знайшов на узбережжі троль-воїн. Він давав власникові владу над водою й силу викликати стихії, як могутньому магові, і за це власника звали «Носієм Припливів». Проте на камені лежало прокляття: власник поволі зникав зі світу живих, тож кожен носій зрештою заходив у море й зникав.",al={"камінь припливів","легенда приливоносця","водяний камінь ґурубаші"}},{q="Як дістатися до Долини Стренглторну?",a="Мандрівники можуть пройти на південь через річковий кордон із Сутінколісся в північний Стренглторн. Орда тримає вежі цепелінів, що з'єднують Базовий Табір Ґром'ґол із Дуротаром і Галявинами Тірісфалю. Мандрівники з Калімдору можуть також сісти на торговий корабель, що регулярно ходить між Раджетом у Пустках і Буті Бей.",al={"дістатися до стренґлторну","як потрапити до стренґлторну","подорож стренґлторном"}}},fp="18,435,18.552.0,22.509.0,22.494.0,25.463.1,32.373.0,18.360.0,32.325.1,18.354.0,32.393.0,38.317.0"}
P.entries["zone:swampofsorrows"] = {n="Болото Скорботи",s="Болото Скорботи — каламутні солонуваті мочарі між Перевалом Мертвого Вітру й посушливими Спустошеними Землями. Колись це була північна частина давньої Чорної Трясовини, а нині на її вкритих сольовою кіркою драговинах живуть небезпечні звірі й зелені драконороди, а на дні Ставка Сліз лежать руїни затонулого Храму Атал'Гаккара. Орда утримує тут укріплений гарнізон Стонард, а Альянс не має в трясовині безпечного прихистку, тож край лишається здебільшого диким.",h="Болото Скорботи — каламутні солонуваті мочарі між Перевалом Мертвого Вітру й посушливими Спустошеними Землями.",kw={"болото скорботи","стонард","храм атал'гаккара","затонулий храм","ставок сліз","загублені","ераникус"},ang={["faction:Alliance"]="Без застави, де можна перевести дух, подорож болотом — самотня, небезпечна справа, до якої варто ретельно підготуватися в Даркширі чи Замку Незерґард.",["faction:Horde"]="Стонард — ваш важливий передовий оплот на південному континенті, звідки виверни літають просто до Карґата, Полум'яного Гребеня й Базового Базового Табору Ґром'ґол.",["profession:Blacksmithing"]="Загартовані шукачі пригод можуть добувати залізо, золото, мітрил та справжнє срібло на гірських кручах уздовж північного й південного країв болота.",["profession:Herbalism"]="Болото — одне з небагатьох місць Азероту, багатих на Сліпотрав, а ще тут щедро ростуть Живокорінь, Блідолист і Душиводорість.",["race:Troll"]="Затоплені руїни Атал'Гаккара — грізне нагадування про темну магію крові, що розколола Імперію Ґурубаші й накликала гнів Аспектів драконів."},sec={{t="Потоплена історія",b="Задовго до приходу орочої Орди ці мочарі становили північну половину величезних боліт, відомих як Чорна Трясовина. Після розпаду Імперії Ґурубаші фанатичні тролі атал'аї втекли в трясовину й звели Храм Атал'Гаккара, щоб викликати свого кровожерного лоа — Гаккара Душолупа. Відчувши наближення катастрофи, Аспект Ізера вивільнила свою силу й затопила прокляту піраміду у водах Ставка Сліз. Охоронці із зеленого драконячого роду на чолі з Ераникусом залишилися тут пильно стерегти затоплену споруду. Коли ж згодом катаклізм Темного Порталу випалив південну частину трясовини на Спустошені Землі, це північне болото дістало свою нинішню скорботну назву."},{t="Застави й зламані вигнанці",b="Стонард — головний осередок цивілізації на болоті. Цю заставу заснували ще в Першу війну разом із нині зруйнованими поселеннями Рокард і Кірос, а за Тралла її відбудували як найпівденніший плацдарм Орди у Східних Королівствах. За частоколом Стонарда болотом блукають дивні мандрівники. Гурт дренеїв, що застрягли в Азероті, піддався тузі за домом і безумству й виродився в диких Загублених. Проте невелика громада Зламаних, які зберегли ясний розум, живе в Пристанищі: вони насторожені, але готові мирно торгувати з мандрівниками."},{t="Драговина, що засмоктує",b="Щоб вижити на болоті, треба постійно стерегтися його хижих мешканців. Глибокі драговини ховають кроколісків, що кидаються з води, отруйних павуків, болотяних ягуарів і бродячих болотяних звірів, обліплених намулом. Прибережні печери й Узбережжя Туманного Очерету кишать лютими мурлоками, а солона вода невпинно підступає вглиб суходолу, консервуючи гнилі колоди в товстій сольовій кірці. Далі на сході лежить Скорботна Мла, де агресивні елітні драконороди люто стережуть підступи до Затонулого Храму, нападаючи на кожного, хто наблизиться."}},faq={{q="Як дістатися до Болота Скорботи?",a="Найпоширеніший суходільний шлях веде на схід від Даркшира в Сутінколіссі, крізь небезпечну моторошну ущелину Перевалу Мертвого Вітру, і просто вниз, у болото. А мандрівники з півдня можуть пройти на північ головною дорогою зі Спустошених Земель.",al={"як дістатися до болота скорботи","дорога болота скорботи","дістатися до стонарда"}},{q="Чому Храм Атал'Гаккара під водою?",a="Століття тому жрецтво Атал'аї спробувало викликати Гаккара Душолупа в Азерот. Ізера, Аспект зеленої драконячого роду, викрила їхні демонічні криваві обряди й затопила весь храм у болоті, щоб відвернути лихо, лишивши зелених драконородів стерегти затоплені зали.",al={"чому затонулий храм під водою","хто потопив храм","лор затонулого храму"}},{q="Що таке Стонард?",a="Стонард — одне з перших поселень, які Орда збудувала, перейшовши крізь Темний Портал у Першій війні. Спустошений у боях, він нещодавно був відвойований і відбудований за наказом Тралла, щоб стати опорою постачання Орди біля Спустошених Земель.",al={"історія стонарда","орківська база на болоті","хто збудував стонард"}},{q="Чи є тут поселення Альянсу?",a="Ні. У Болоті Скорботи Альянс не має ні містечок, ні варти, ні шляхів польоту. Шукачам пригод з Альянсу, що діють у цьому краї, доводиться базуватися в Даркширі в Сутінколіссі на заході чи в Замку Незерґард у Спустошених Землях на півдні.",al={"база альянсу болото скорботи","політ альянсу болото","де табір альянсу"}},{q="Хто ці дивні спотворені людиноподібні в болоті?",a="Це дренеї, що застрягли в Азероті після руйнування Темного Порталу. Відрізані від свого світу, більшість збожеволіла з відчаю й стала ворожими Загубленими. Невелика громада розважливих вигнанців із Розбитих знайшла прихисток на північному заході, у Пристані, обравши нейтральне виживання замість безумної люті.",al={"хто загублені","що таке притулок","дренеї на болоті"}},{q="Що таке Скорботна Мла?",a="Скорботна Мла — густий масив боліт просто на схід від Ставка Сліз. Тут патрулюють добірні зелені драконороди й дракончата, що жорстоко відганяють смертних, оберігаючи таємниці Затонулого Храму.",al={"зона драконів болота скорботи","скорботна мла дракони","зелені драконороди болота"}}},fp="16,454,17.720.0,26.592.0,16.542.0,36.265.0,44.301.0,16.273.0,40.245.0,51.306.0,19.225.0"}
P.entries["zone:tanaris"] = {n="Танаріс",s="Танаріс — безмежна спекотна пустеля на півдні Калімдору, край хвилястих піщаних дюн і пекучої спеки. У її серці лежить Ґаджетзан — нейтральне торговельне поселення, яким керують гобліни картелю Стімвідл. За межами гамірних поселень дюни ховають ворожих піщаних тролів, небезпечні вулики силітидів і потаємні володіння бронзового драконячого роду.",h="Танаріс — безмежна спекотна пустеля на півдні Калімдору, край хвилястих піщаних дюн і пекучої спеки.",kw={"танаріс","ґаджетзан","картель стімвідл","зул'фаррак","печери часу","гобліни","пустеля"},ang={["faction:Horde"]="Ґаджетзан — зручний торговельний вузол для розвідників Орди: він з'єднує шляхи від Застави Вільного Вітру й Табору Моджаче з пустками далекого півдня, де кишать силітиди.",["profession:Herbalism"]="Суха спека живить невловимий Вогнецвіт серед рухомих дюн, а затінені руїни й вологі оази дають прихисток цінному Фіолетовому Лотосу.",["profession:Mining"]="Сухі кручі й скелясті виступи довкола дюн багаті на жили мітрилу, справжнього срібла, заліза й золота, а глибше трапляються розкидані поклади малого торію.",["race:Troll"]="Піщана Лють із Зул'Фаррака дає вам змогу побачити своїх давніх родичів, які, відрізані Розколом, змінилися й загартувалися, створивши жорстоку культуру."},sec={{t="Море дюн",b="До того як Великий Розкол розтрощив світ, тут росли буйні джунглі, де жили перші таурени й на які зазіхала Імперія Ґурубаші. Катаклізм позбавив землю лісів, лишивши голу, випалену сонцем пустку. Відрізані зміненою географією, місцеві тролі пристосувалися й загартувалися, ставши племенем Піщаної Люті, і збудували свою відокремлену імперію в обнесеному мурами місті Зул'Фаррак. Нині поверхнею пустелі владарюють гієни, василіски й скорпіди, а під розпеченою землею звиваються підземні тунелі."},{t="Гоблінське підприємство",b="З усього материка Танаріс лежить найближче до рідного острова гоблінів, Кезану, тож картель Стімвідл розгорнув тут процвітаюче підприємство. Від обнесеної мурами оази Ґаджетзан до прибережних доків Порту Стімвідла гобліни суворо дотримуються нейтралітету й радо беруть монети і в Альянсу, і в Орди. Мир тут тримається на кулаках дужих громил, хоча свавільні загрози на кшталт Флібустьєрів Південних морів раз у раз нападають на кораблі й розкопки вздовж узбережжя."},{t="Давні таємниці й нові загрози",b="Піски ховають сили, значно давніші за імперії смертних. На сході лежать Печери часу — прадавні володіння Ноздорму та його бронзового драконячого роду; часом можна побачити, як їхні дракони ширяють у висхідних потоках над пустелею. На півдні величезні кам'яні ворота позначають комплекс титанів Ульдум. Та з підземних гнізд на кшталт Зяючої Безодні й Отруйного Лігва здіймається темніша небезпека: рої силітидів почали прокопуватися назовні по всіх пісках."}},faq={{q="Як дістатися до Танарісу?",a="Мандрівникам треба пройти через Тисячу Голок до Мерехтливих Низин. Гірський прохід, прорубаний у скелях у південному кінці солончаків, веде просто вниз у пустелю, і звідти одразу видно мури Ґаджетзана.",al={"як дістатися до танарісу","дорога до танарісу","вхід у танаріс"}},{q="Чому Ґаджетзан нейтральний до обох фракцій?",a="Ґаджетзаном керує картель Стімвідл, вірний лише прибутку. Щоб торгівля процвітала, а торгові шляхи пустелею були захищені, гобліни суворо дотримуються нейтралітету й наймають вишибал, що лупцюють кожного, кому стане дурості почати бійку між фракціями в міських мурах.",al={"чому ґаджетзан нейтральний","чи орда й альянс можуть у ґаджетзан","гоблінський нейтралітет"}},{q="Що таке Зул'Фаррак?",a="Зул'Фаррак — укріплена пустельна столиця піщаних тролів-фарраків. Відрізане тут відтоді, як Великий Розкол перетворив прадавні джунглі на посушливе пустище, плем'я Піщаної Люті стало ворожим до всіх чужинців і стереже свої священні басейни й таємничі святилища від шукачів пригод.",al={"що таке зул'фаррак","хто живе в зул'фарраку","місто піщаних тролів"}},{q="Що за комахи гніздяться по всій пустелі?",a="Ці комахоподібні звірі — силітиди, страхітливі колоніальні копачі, що будують величезні вулики, як-от Зяюче Провалля й Отруйне Лігво. Їхня поява в Танарісі стривожила спостерігачів на кшталт Старшого Землеміра Фіззлдаузера, нагадавши про прадавні жахіття Війни Рухомих Пісків.",al={"що за комахи в танарісі","вулики танарісу","силітиди танарісу"}},{q="Що за величезними кам'яними дверима на півдні?",a="Монументальна брама в Долині Вартових позначає вхід до Ульдуму — легендарного дослідницького осередку й володіння прадавніх титанів. Вхід надійно запечатаний, його стережуть колосальні кам'яні вартові, а здалеку за ним спостерігають допитливі вчені й гобліни.",al={"гігантські двері півдня танарісу","брами руїн ульдуму","брама титанів танаріс"}},{q="Хто живе в Печерах часу?",a="Печери часу — прадавнє лігво бронзової драконячого роду та її Аспекта, Ноздорму. З цих прихованих звивистих глибин позачасові дракони пильнують плин історії, часом патрулюючи небо високо над південними дюнами.",al={"лор печер часу","що в печерах часу","дракони танарісу"}}},fp="7,385,14.524.0,17.488.0,35.467.0,27.251.0,42.292.0,19.302.0,56.294.0,52.271.0,38.255.0"}
P.entries["zone:teldrassil"] = {n="Тельдрассил",s="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного узбережжя Калімдору. Виплекане друїдами після Третьої війни, його могутнє гілля тримає на собі цілу сутінкову дику природу й столицю нічних ельфів — Дарнасус. Та під його тихою, залитою місячним світлом кроною почала ворушитися скверна.",h="Тельдрассил, що означає «Корона Землі», — велетенське нове Світове Дерево, вирощене біля північно-західного...",kw={"тельдрассил","світове дерево","нічні ельфи","дарнасус","фандрал стаґгелм","скверна","нордрассил","зона"},ang={["class:Druid"]="Поки Малфуріон ув'язнений у Смарагдовому Сні, Коло Кенарія тут очолює Архідруїд Фандрал Стаґгелм, хоч багато друїдів непокоїться, що Тельдрассил виростили поспіхом.",["faction:Alliance"]="Тельдрассил — найпівнічніший бастіон Альянсу в Калімдорі, що тримає морське сполучення й торгівлю між Дарнасусом і материковими королівствами.",["profession:Herbalism"]="Зовсім позбавлена мінералів і руди, зелена крона дерева надолужує це як рай для збирачів Мирноцвіту, Срібнолисту й Земнокореня.",["race:NightElf"]="Це могутнє дерево — новий початок вашого народу після спустошення Гори Гіджал, але відсутність благословення Аспектів робить його захист нагальним обов'язком."},sec={{t="Крона над морем",b="Тельдрассил — не просто дерево; це піднесена над водами Прихованого Моря жива система. Його велетенські гілки тримають хвилясті пагорби, річки, живлені вранішньою росою, імлисті озера й густі прадавні гаї. На західному краю лежить Дарнасус — велична столиця калдореїв. Біля підніжжя монументального стовбура — Селище Рут'теран, з'єднане з кроною містичною брамою; це головна гавань острова."},{t="Відмова Аспектів",b="Після жертви Нордрассила в Третій війні й таємничого зникнення Шан'до Малфуріона Стормрейджа в Смарагдовому Сні Архідруїд Фандрал Стаґгелм переконав Коло Древніх виростити заміну. Стаґгелм сподівався повернути калдореям утрачене безсмертя. Та Ноздорму й Аспекти драконів визнали цей задум гординею й відмовили в благословенні. Без їхнього життєво важливого захисту ріст Тельдрассила потерпає від неприродних вад."},{t="Недуга, що підкрадається",b="Попри зовнішню велич, молоде Світове Дерево приховує темну хворобу. Місцева живність стала лютою: мирні племена фурболгів упали в божевілля, покручені ґрелли плодяться в курганах, а мерзенні сатири чинять темні обряди в тінях на кшталт Скелі Скверни. Унизу, на берегах Темного Узбережжя, морські велети, трешери й черепахи викидаються на берег, тікаючи від отруєних вод довкола дерева. Натуралісти й вартові тепер гарячково працюють по всьому гіллю, щоб розпізнати тінь, яка повільно душить їхню нову домівку."}},faq={{q="Навіщо виростили Тельдрассил?",a="Коли Нордрассил було спустошено наприкінці Третьої війни, нічні ельфи втратили безсмертя. Архідруїд Фандрал Стаґгелм схилив Коло Древніх і друїдів Кола Кенарія посадити в морі нове Світове Дерево, щоб повернути втрачене їхнім народом.",al={"навіщо створили","хто створив тельдрассил","походження тельдрассила"}},{q="Чому Тельдрассил не повернув нічним ельфам безсмертя?",a="Нордрассил дарував безсмертя, бо його благословив Ноздорму, Позачасний. Коли виростили Тельдрассил, Ноздорму визнав бажання нічних ельфів зухвалим і відмовився дарувати новому дереву своє благословення.",al={"безсмертя","чому не безсмертні","благословення ноздорму"}},{q="Як вийти з Тельдрассила?",a="Мандрівникам треба пройти через Дарнасус до рожевого порталу в Храмових Садах, який переносить униз, до Селища Рут'теран біля підніжжя стовбура. З Рут'терана корабель пливе через море до Обердайна на материку, на Темному Узбережжі; є й маршрути гіпогрифів.",al={"як вибратися","покинути дерево","корабель з тельдрассила"}},{q="Чому в Тельдрассилі немає рудних жил?",a="Уся зона лежить на живих гілках і деревині велетенського Світового Дерева, а не на природній материковій породі. Оскільки тут немає кам'яних підземних шарів, не утворюються ні жили металу, ні поклади руди, зате трави ростуть у великому достатку.",al={"де мідь","немає руди","видобуток у тельдрассилі"}},{q="Чому фурболги й звірі божеволіють?",a="Лиховісна присутність почала просочуватися в неблагословенне коріння Тельдрассила. Хвороба зіпсувала місцеву воду й рослинність, штовхнувши мирних деревляників і плем'я фурболгів-Вузлошкірів у шалену агресію, а рештки сатирів свідомо плекають цю заразу.",al={"зіпсуті фурболги","божевільні вузлошкіри","що за скверна"}},{q="Що таке Тінедол?",a="Тінедол — захищена відлюдна долина на східному гіллі Тельдрассила довкола великого дерева Алдрассил. Це мирне святилище, де молоді нічні ельфи починають навчання, перш ніж вирушити в широкий світ.",al={"тінедол","стартова зона","зона алдрассила"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:thousandneedles"] = {n="Тисяча Голок",s="Тисяча Голок — розлогий каньйон із прямовисних пісковикових стовпів і випалених сонцем солончаків на півдні Калімдору. Таурени чіпляються за поселення на вершинах височенних столових гір, ховаючись від агресивних зграй кентаврів, а гноми й гобліни-винахідники ганяють ракетні автомобілі висохлим морським дном Мерехтливих Низин.",h="Тисяча Голок — розлогий каньйон із прямовисних пісковикових стовпів і випалених сонцем солончаків на півдні...",kw={"тисяча голок","столові гори","кентаври","ґрімтотем","мерехтливі низини","перегони міражу","застава вільного вітру"},ang={["faction:Horde"]="Великий Підйомник з'єднує Пустки з вашою твердинею на Заставі Вільного Вітру й править за стратегічний південний рубіж проти кланів кентаврів і тауренів-бунтівників.",["profession:Engineering"]="Солончаки — місце прощі для майстрів, які прагнуть вивчати ракетне пальне, деталі машин і швидкісну тягу на Перегонах Міражу.",["race:Gnome"]="Перегони Міражу в Мерехтливих Низинах — найкраща нагода показати точність і витонченість гномської інженерії на тлі абияк зліплених гоблінських вигадок.",["race:Tauren"]="Застава Вільного Вітру нагадує, як високо довелося видертися вашому народові, щоб урятуватися від різанини кентаврів, і водночас є плацдармом проти віроломних Ґрімтотемів зі Шпиля Темної Хмари."},sec={{t="Кам'яний ліс",b="До того як Великий Розкол розтрощив прадавній Калімдор, тут був пишний річковий каньйон, який живили внутрішні водні шляхи, що текли до моря. Катаклізм розірвав континент, виштовхнув річище вище від ґрунтових вод і змінив русло річки, тож лишилися тільки сухий камінь і пісковикові шпилі. Нині з дна каньйону здіймаються десятки тонких стовпоподібних колон, наче скам'янілий ліс. Таурени оселилися на вершинах і натягли між ними хиткі мотузяні мости, щоб облаштувати селища поза досяжністю ворожих кентаврів-грабіжників, які никають затіненим дном каньйону внизу."},{t="Небезпеки на столових горах",b="На вершинах голкоподібних шпилів життя зовсім не мирне. На Заставі Вільного Вітру таурени, вірні Орді, протистоять не лише хижим вітряним зміям і вівернам із Високосіду, а й своїм віроломним родичам — войовничому клану Ґрімтотем, що окопався на Шпилі Темної Хмари. Скельний Вартовий Лонггорн керує обороною плато й шукає сміливих бійців, щоб ударити по підбурювачах Ґрімтотем і вберегти хиткі мости між вершинами. На півночі величезні механічні лебідки Великого Підйомника спускають мандрівників із південних Пусток, хоча перейти дно каньйону — і далі смертельний ризик."},{t="Перегони Міражу",b="На південному сході стіни каньйону розступаються, відкриваючи Мерехтливі Низини — величезний висохлий солончак нижче рівня моря. Посеред цієї суворої, сліпучо-білої рівнини гноми й гобліни тримають хиткий нейтралітет довкола Перегонів Міражу. Інженери-суперники Поззік і Фіззл Брассболтс ганяють експериментальні ракетні машини твердою сіллю, щоб з'ясувати, чия раса технічно вправніша. Цей піт-стоп приваблює пройдисвітів, шахраїв на кшталт Кравела Колбірда та мисливців, що полюють на витривалих скорпіонів, черепах і василісків, які никають розпеченою улоговиною."}},faq={{q="Звідки взялася назва Тисяча Голок?",a="Край названо на честь десятків величезних циліндричних шпилів із пісковику, що здіймаються з дна каньйону. Колись, ще до Великого Розколу, їх вирізьбили бурхливі річкові течії, і тепер ці кам'яні вежі схожі на ліс велетенських голок.",al={"чому тисяча голок","походження стовпів-голок","лор шпилів"}},{q="Як спуститися в Тисячу Голок із Пусток?",a="Мандрівники користуються Великим Підйомником — величезним двокабінним ліфтом, яким керують вартові Орди на південному кордоні Пусток. Ступити з краю — вірна смерть, тож платформу треба дочекатися. Мандрівники Альянсу можуть також прийти із заходу, через Таланаар у Фераласі.",al={"як дістатися до тисячі голок","вхід великого підйомника","ліфт до голок"}},{q="Чому таурени живуть на вершинах столових гір?",a="Колись ватаги кентаврів ледь не винищили кочових тауренів. Застави, як-от Застава Вільного Вітру, на неприступних кам'яних стовпах уберігали їх від нападів із землі. Столові гори таурени з'єднали дерев'яними підвісними мостами, щоб пересуватися високо над хижаками й грабіжниками внизу.",al={"чому таврени на стовпах","історія вільного вітру","висота тавренів"}},{q="Що таке Перегони Міражу?",a="Перегони Міражу — випробувальний полігон інженерів на солончаку Мерехтливих Низин. Гномські й гоблінські майстри ганяють рівною сольовою рівниною експериментальні гоночні машини на ракетній тязі, щоб вирішити свою давню суперечку, хто з них будує найкращі машини.",al={"траса солончаків","гонка гномів і гоблінів","ракетна траса"}},{q="Що Ґрімтотеми роблять у каньйоні?",a="Клан Ґрімтотем займає Шпиль Темної Хмари — укріплену групу шпилів просто навпроти Застави Вільного Вітру. На відміну від решти племен тауренів, що присягнули Орді, Ґрімтотеми нападають на інших тауренів і змовляються, щоб захопити владу над столовими горами.",al={"ґрімтотеми тисяча голок","шпиль темної хмари таврени","злі таврени голок"}},{q="Що таке Мерехтливі Низини?",a="Мерехтливі Низини — величезне висохле дно озера на схід від столових гір каньйону. Сольова кірка утворилася, коли прадавнє внутрішнє море випарувалося після Розколу. Пекучий жар, сліпучо-біла сіль і люті хижаки роблять цю пустку непривітною, і нею користуються переважно для швидкісних випробувань машин.",al={"солончак","біла пустеля голок","східна пустеля"}}},fp="16,315,17.605.0,18.606.0,18.558.0,38.246.0,59.275.0,43.301.0,27.259.0,45.264.0,30.290.0"}
P.entries["zone:thunderbluff"] = {n="Тандер Блаф",s="Тандер Блаф — велична столиця тауренів на вітряних червоних столових горах, що здіймаються над травами Малгору. Її заснував Верховний Вождь Кайрн Бладгуф, коли з допомогою Нової Орди об'єднав кочові племена, і нині місто — культурне, духовне й торговельне серце його народу. З'єднане хиткими мотузяними мостами й дерев'яними підйомниками, воно захищає від набігів кентаврів і дарує мирний прихисток мандрівникам з усього Калімдору.",h="Тандер Блаф — велична столиця тауренів на вітряних червоних столових горах, що здіймаються над травами...",kw={"тандер блаф","таурени","кайрн бладгуф","малгор","столиця","узвишшя"},ang={["class:Druid"]="Узвишшя Старійшин — найвище святилище магії природи в Орді на чолі з Верховним Друїдом Гамуулом Рунтотемом, першим за тисячі років тауреном, що навчився друїдства.",["class:Shaman"]="Узвишшя Духів і підземні Ставки Видінь — спокійне осердя, де шанують і чують стихійних духів і духів тауренських предків.",["faction:Horde"]="Значно спокійніший і духовніший за суворі мури Оргріммара, Тандер Блаф — пасторальна опора південного впливу Нової Орди в Калімдорі.",["race:Tauren"]="Тандер Блаф уособлює тяжко здобуту єдність і відродження вашого народу після поколінь кочування й набігів кентаврів — під проводом Верховного Вождя Кайрна Бладгуфа."},sec={{t="Постійний прихисток",b="Незліченні покоління таурени кочували Калімдором, ведучи жорстоку боротьбу за виживання з ненажерливими племенами кентаврів. Ця відчайдушна доба скінчилася в Третій війні, коли Кайрн Бладгуф об'єднав сили з Вождем Траллом. Разом орки й таурени зламали натиск кентаврів і відвоювали соковиті пасовища Малгору. Щоб уберегти своє майбутнє, Кайрн повів союзні племена під захист цих природних кам'яних бастіонів і заснував Тандер Блаф — перший за багато століть спільний, постійний дім тауренів."},{t="Місто в хмарах",b="Тандер Блаф розкинувся на кількох високих столових горах, з'єднаних підвісними мотузяними мостами, і плавно поєднує природну архітектуру з тауренською практичністю. На центральних скелях — гамірні ринки, банк, корчма й височенне гніздовище вітрокрилів, а над прірвою розходяться три окремі гори. Узвишшя Мисливців служить міським розвідникам і слідопитам; на Узвишші Старійшин живуть хранителі переказів і Коло Кенарія на чолі з Верховним Друїдом Гамуулом Рунтотемом; а Узвишшя Духів присвячене духовному єднанню й прихищає шаманів, жерців і таємничі підземні печери, відомі як Ставки Видінь."},{t="Непевна єдність",b="Кайрн Бладгуф має величезну повагу майже серед усіх племен, та правити гордим народом, що лише нещодавно осів, — справа не без тертя. Зокрема, плем'я Ґрімтотем на чолі з хитрою й гострою на язик Старою Відьмою Маґатою Ґрімтотем похмуро тримається на Узвишші Старійшин. Маґата відкрито ставить під сумнів примирливі методи Кайрна та його вірність чужоземним народам Орди. Під пильним оком вождя мир поки тримається, та біля вогнищ ради над рівнинами шепочуть ідейні розбіжності."}},faq={{q="Хто править Тандер Блафом?",a="Тандер Блафом править і веде об'єднані тауренські племена Верховний Вождь Кайрн Бладгуф. Шанований за мудрість, терпіння й величезну силу, Кайрн заснував місто, коли уклав союз з Ордою Тралла й вигнав кентаврів із Малгору.",al={"провідник тандер блафа","хто тут головний","вождь тандер блафа","кайрн"}},{q="Як піднятися до Тандер Блафа?",a="Ті, хто прибуває пішки чи верхи на кодо, мають скористатися величезними дерев'яними підйомниками на південно-західному й північно-східному боках центральної гори. Крім того, у місті є гніздовище вітрокрилів із маршрутами польотів по всьому Калімдору.",al={"підйомник тандер блафа","як потрапити всередину","вхід до тандер блафа","як піднятися"}},{q="Чому таурени будували на високих горах, а не на землі?",a="Століття кочового життя минули під безупинними наскоками войовничих кланів кентаврів. Прямовисні скелі Малгору дають природний захист: вони вберігають оселі, кузні й священних старійшин тауренів від засідок із землі й дають змогу нарешті осісти в мирі.",al={"чому на горах","чому вони на скелях","скелі тандер блафа","таурени на висоті"}},{q="Які є узвишшя в місті?",a="Місто займає центральну гору (поділену на нижній, середній і верхній яруси) та три зовнішні гори довкола неї. Узвишшя Мисливців віддане воїнам, мисливцям і слідопитам. На Узвишші Старійшин живуть друїди, мудреці й плем'я Ґрімтотем. На Узвишші Духів — святині Земної Матері, наставники шаманів, жерців і магів та печерні Ставки Видінь.",al={"райони тандер блафа","що таке узвишшя","квартали тандер блафа"}},{q="Що таке Ставки Видінь?",a="Ставки Видінь — священні підземні печери під Узвишшям Духів. Тауренські провидці, духоходи й знавці чародійства збираються біля цих тихих, оповитих туманом вод, щоб єднатися зі стихіями й тлумачити знамення про майбутнє свого народу.",al={"ставки видінь","печера узвишшя духів","печера тандер блафа"}},{q="Хто така Маґата Ґрімтотем?",a="Маґата Ґрімтотем — матріарх і Стара Відьма грізного клану Ґрімтотем. Вона живе на Узвишші Старійшин і прилюдно бере участь у раді Кайрна, але лишається затятою прихильницею старих звичаїв: не довіряє чужинцям і потай опирається поступливості племені Бладгуф щодо Орди.",al={"маґата","стара відьма","хто провідниця ґрімтотемів"}}},fp="13,473,17.558.0,20.575.0,12.516.1,24.238.0,35.236.0,61.300.0,41.364.0,29.270.0,25.291.0"}
P.entries["zone:undercity"] = {n="Андерсіті",s="Глибоко під розтрощеними руїнами Столиці Лордерона лежить Андерсіті — темна твердиня Відступників. Спершу Погибель висікла її з давніх королівських склепів і темниць, але Леді Сильвана Віндраннер захопила місто й перетворила на неприступне підземне святилище. Нині це осідок влади Відступників і важливий оплот Орди на півночі Східних Королівств.",h="Глибоко під розтрощеними руїнами Столиці Лордерона лежить Андерсіті — темна твердиня Відступників.",kw={"андерсіті","відступники","сильвана","лордерон","столиця","погибель","орда"},ang={["faction:Horde"]="Як головний плацдарм Орди у Східних Королівствах, Андерсіті забезпечує прямі рейси цепелінів до Дуротару й Базового Базового Табору Ґром'ґол.",["race:Human"]="Під землею вашого полеглого прадавнього королівства лежить похмуре спотворення королівських склепів Лордерона, де тепер бродять ходячі трупи ваших колишніх братів.",["race:Orc"]="Глибоко в цих самих темницях Альянс Лордерона колись тримав легендарного Вождя Оргріма Думхаммера, поки той не здійснив свою історичну втечу.",["race:Undead"]="Андерсіті — ваше суверенне святилище й батьківщина, висічена вашими власними руками після того, як ви зламали залізну хватку Короля-Ліча на своєму розумі."},sec={{t="Від королівських склепів до твердині Погибелі",b="Задовго до того, як чума прокотилася Лордероном, катакомби, темниці й каналізацію під палацом разом називали Андерсіті. Тут були гробниці знаті, найглибші в'язниці королівства — де колись тримали колишнього Вождя Оргріма Думхаммера, поки він не втік, — і найбідніші мешканці держави. Коли 20 року після відкриття Темного Порталу Артас Менетіл убив короля Теренаса й спустошив столицю, принц наказав своїм слугам-нежиті розкопати й розширити підземні ходи, перетворивши їх на укріплений осідок влади Погибелі."},{t="Постання Відступників",b="Погибель так і не побачила свою темну столицю завершеною. Коли після битви на Горі Гіджал сили Короля-Ліча ослабли, Леді Сильвана Віндраннер вирвалася з-під влади його колективного розуму й повела за собою тисячі нежиті. Вона заманила Артаса в засідку й відкинула його назад до Нортренду. Після запеклої тристоронньої громадянської війни з рештками Погибелі, жахолордами й людським спротивом Сильвана захопила недобудовані катакомби. Назвавши свій народ Відступниками, вона роками керувала роботами, що завершили розлоге підземне місто."},{t="Архітектура проклятих",b="Андерсіті збудовано концентричними кільцями, поділеними на квартали з різним призначенням. У самому серці — Торговий Квартал, сполучений великими підйомниками з руїнами палацу нагорі. Довкола нього — Воєнний Квартал, Квартал Розбійників, Магічний Квартал і отруйний Апотекаріум, де Королівське Аптекарське Товариство варить згубні чуми біля каналів, сповнених зеленого слизу. Ще глибше лежить Королівський Квартал, де Королева Баньші тримає двір разом зі своїм командувачем, повелителем жаху Варіматрасом, під охороною легіонів височенних гидот."}},faq={{q="Чим було Андерсіті до того, як його захопила нежить?",a="Під палацом Лордерона лежали давні склепи людських королів, а також міські темниці й величезна мережа каналізації. Тут тримали воєнних полонених, зокрема Оргріма Думхаммера, а в підземних тінях жили злиденні городяни. Сплюндрувавши столицю, принц Артас почав перетворювати ці катакомби на фортецю Погибелі, але Сильвана їх захопила.",al={"походження андерсіті","чим було андерсіті спершу","історія каналізації лордерона"}},{q="Чому місто збудоване під землею, а не на поверхні?",a="Наземне місто Лордерон у Третій війні було вщент зруйноване, і його було важко боронити від Багряного Хрестового Походу, сил Погибелі й уцілілих людей з Альянсу. Підземні тунелі давали природні укріплення, вузькі проходи й потаємність, тож Відступники змогли завершити розпочате Погибеллю будівництво й непомітно процвітати.",al={"чому жити під землею","чому не відбудувати лордерон","чому андерсіті під руїнами"}},{q="Хто править Андерсіті?",a="Містом править Леді Сильвана Віндраннер — Королева Баньші й королева Відступників. Вона править із Королівського Кварталу під охороною королівських вартових-Відступників і свого підкореного поплічника, жахолорда Варіматраса.",al={"хто провідник андерсіті","правитель андерсіті","хто керує андерсіті"}},{q="Що за пам'ятник королю Теренасу в руїнах нагорі?",a="Над головними підйомниками міста стоїть кам'яний пам'ятник убитому королю Теренасу Менетілу Другому. Його тіла там немає: труп короля спалили, а попіл розвіяли під час воскресіння Кел'Тузада. Уцілілі люди Альянсу відважно вирізьбили цей пам'ятник серед руїн, щоб пам'ять про останнього справжнього короля Лордерона жила далі.",al={"гробниця короля теренаса","могила в тронній залі лордерона","хто збудував гробницю над андерсіті"}},{q="Що за дивні звуки в тронній залі Лордерона?",a="У зруйнованій тронній залі над підйомниками Андерсіті досі живуть примарні відлуння минулого. Хто стане посередині, почує ледь чутні привидні звуки: святкові дзвони й шелест пелюсток троянд на честь повернення Артаса, застережливі слова пророка Медіва й останню розмову короля Теренаса з сином-батьковбивцею.",al={"привидні звуки в тронній залі","шепіт у тронній залі","голоси в тронній залі лордерона"}},{q="Чому Відступники пускають сюди інших членів Орди?",a="Відступники уклали союз із розрахунку з Ордою Вождя Тралла, щоб вижити, адже довкола них — ворожі фанатики Багряного Хрестового Походу й легіони Погибелі. Живим расам Орди отруйні випари й алхімічні ріки не дають дихати, та посланцям і мандрівникам дозволяють сюди приходити, щоб зміцнювати дипломатичні й військові зв'язки.",al={"чому орки в андерсіті","орда в андерсіті","чому андерсіті в орді"}}},fp="9,400,36.527.0,20.525.0,26.518.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Кратер Ун'Ґоро",s="Кратер Ун'Ґоро — первісні джунглі в глибокій западині між посушливими пустками Танарісу й Силітусу. Тут панують дикі динозаври, живі елементалі й вулкан у самому центрі, а пишна кальдера сповнена давніх реліквій Титанів і кристалів сили, чиє походження досі лишається глибокою таємницею.",h="Кратер Ун'Ґоро — первісні джунглі в глибокій западині між посушливими пустками Танарісу й Силітусу.",kw={"кратер ун'ґоро","дияволозаври","кристали сили","притулок маршала","титани","хребет вогняного шлейфу","пілони"},ang={["class:Druid"]="Друїди Кола Кенарія вивчають відокремлену екосистему Ун'Ґоро й беруть його багатий ґрунт, щоб вирощувати Ранкозерно, прагнучи збагнути чисту, неприборкану життєву силу, що живить кальдеру.",["faction:Alliance"]="Природознавці Альянсу гуртуються довкола Віллідена Маршала й Дж. Д. Коллі в Притулку Маршала, поспішаючи розгадати пілони Титанів і водночас охороняючи дослідників із Дарнасуса, що збирають зразки ґрунту.",["faction:Horde"]="Шукачі пригод з Орди часто прибувають через Танаріс, щоб помірятися силою з легендарними дияволозаврами й допомогти травникам Тандер Блафа вирощувати Ранкозерно з первісної землі Ун'Ґоро.",["profession:Herbalism"]="Багата волога западини живить рідкісні рослини: це одне з небагатьох місць Калімдору, де поряд ростуть Сліпотрав, Снолист і Золотий Сансам, а на схилах вулкана — Вогнецвіт.",["profession:Mining"]="Стрімкі стіни кратера й скелі Хребта Вогняного Шлейфу рясніють покладами мітрилу й жилами багатого торію, тож край — одне з найкращих місць для видобутку цінної руди."},sec={{t="Землі Богів",b="Затиснутий між пустелями, Кратер Ун'Ґоро кидає виклик географії південного Калімдору. Давні записи нічних ельфів про Війну Рухомих Пісків свідчать, що комахоподібних кіраджі спинили на краю кратера: вони не змогли проникнути в місце, яке їхньою мовою звалося «Землями Богів». Учені припускають, що кальдера була полігоном чи давньою оселею Титанів, коли ті творили Калімдор. Уздовж хребтів здіймаються кам'яні пілони, що гудуть від енергії, а крізь первісну землю проростають сині, червоні, зелені й жовті кристали."},{t="Дика екосистема",b="В Ун'Ґоро немає ні міст, ні селищ, ні корінних гуманоїдних спільнот. Натомість тут вирує неприборкане первісне життя. Дияволозаври, найгрізніші хижаки краю, нишпорять рівнинами Стежки Жаху, хижі кривавопелюстки шмагають усе довкола на болотах, а слизуни повзають смоляними ямами Лаккарі. У серці кратера височіє Хребет Вогняного Шлейфу — діючий вулкан, де кишать ворожі вогняні елементалі на чолі з істотою на ім'я Полум'яний бігун. Для дослідників і шкурників западина — небачене природне багатство, зокрема жадані шкури дияволозаврів, якщо, звісно, вдасться самому не стати чиєюсь здобиччю."},{t="Притулок Маршала",b="Цивілізація в кратері зводиться майже лише до Притулку Маршала — табору на висоті, у північних кручах. Експедиція вчених, природознавців і шукачів удачі на чолі з Вілліденом Маршалом намагалася описати скарби западини, та потворні звірі потріпали її й загнали на висоту. Нині притулок — обложений перевалочний пункт для відважних мандрівників, що вивчають загадкові кристали сили кратера, наносять на мапи вулканічну активність і пильно стежать за роями силітидів, які проривають південні хребти."}},faq={{q="Як потрапити в Кратер Ун'Ґоро?",a="У кратер ведуть природні спуски по його стінах: один — із південно-західного кута Танарісу біля Долини Будякових Кущів, другий — із північного сходу Силітусу. Нерозважливі шукачі пригод іноді стрибають зі скель, але без магії таке падіння смертельне. Притулок Маршала на півночі має польоти до Ґаджетзана й Цитаделі Кенаріуса.",al={"як зайти в ун'ґоро","вхід в ун'ґоро","як дістатися до кратера ун'ґоро"}},{q="Для чого кольорові кристали сили?",a="По всіх джунглях розкидані червоні, сині, зелені й жовті Кристали Сили. За допомогою гнома-дослідника Дж. Д. Коллі з Притулку Маршала дослідники можуть розшифрувати, як користуватися цими кристалами на Північному, Східному й Західному Пілонах. Поєднуючи певні кольори на відповідних пілонах, можна приборкати приховану енергію Титанів і виготовити захисні чи цілющі обереги.",al={"кристали ун'ґоро","червоні сині зелені жовті кристали","пілони сили"}},{q="Чому Ун'Ґоро такий буйний, хоч його оточують пустелі?",a="Учені вважають, що неприродна буйність Ун'Ґоро штучна й походить від Титанів, які творили світ. Титанічні провідники, тепло вулканічної діяльності Хребта Вогняного Шлейфу й прадавня енергія силових ліній живлять відокремлену, надзвичайно прискорену екосистему, що опирається посушливому клімату сусідніх Танарісу й Силітусу.",al={"чому ун'ґоро джунглі","зв'язок ун'ґоро з пустелею","як в ун'ґоро рослини"}},{q="Чому кіраджі називали це місце «Землями Богів»?",a="Згідно з табличками часів Війни Рухомих Пісків, рої комах зупинили свій наступ на порозі кратера. Геолог Ларксбейн, що переклав цей запис, пов'язує назву з гіпотезами, що в кратері колись жили Титани, і припускає, чи не пильнував Землі Богів сам Аман'Тул.",al={"земля богів значення","кіраджі ун'ґоро","чому силітиди не взяли ун'ґоро"}},{q="Для чого потрібен Ґрунт Ун'Ґоро?",a="По всьому кратеру лежать купи багатої, родючої землі. Зібраний ґрунт разом із насінням Тарлендріса у Вічнозеленій Торбинці дає змогу виростити Ранкозерно — містичну траву, яку дуже шукають дослідники з Тандер Блафа, Дарнасуса й Кола Кенарія.",al={"зразок ґрунту ун'ґоро","що робить ґрунт ун'ґоро","ґрунт ун'ґоро"}},{q="Чи є тут поселення людиноподібних чи підземелля?",a="У Кратері Ун'Ґоро немає ні підземель, ні корінних людиноподібних громад. Єдине постійне поселення — Притулок Маршала, невелика застава експедиції на північному краю. Окрім поодиноких мисливців-відлюдників чи заблукалих дослідників, решта кальдери цілком дика.",al={"підземелля ун'ґоро","хто живе в ун'ґоро","людиноподібні ун'ґоро"}}},fp="14,289,13.564.0,18.559.0,16.579.0,35.395.0,45.390.0,56.325.0,51.316.0,30.275.0,52.274.0"}
P.entries["zone:wailing"] = {n="Печери Стогонів",s="Під Оазою Буйних Вод у посушливих Пустках лежать Печери Стогонів — заплутана система підземних джерел і розколин, названа так через моторошний свист пари, що виривається з-під каменю. Те, що починалося як шляхетна спроба друїдів відродити вибілену сонцем савану Калімдору, обернулося на спотворений, отруйний підземний світ. Тепер печери кишать спотвореними звірами й занепалими учнями, яких зіпсувало глибоке протиприродне жахіття.",h="Під Оазою Буйних Вод у посушливих Пустках лежать Печери Стогонів — заплутана система підземних джерел і...",kw={"печери стогонів","наралекс","друїди ікла","смарагдове жахіття","мутанус пожирач","пустки","підземелля"},ang={["class:Druid"]="І для друїдів кенарійської традиції, і для тих, хто йде тауренським шляхом, печери — трагічне застереження про небезпеки Смарагдового Сну та урочистий обов'язок очистити світ від занепалих побратимів — Друїдів Ікла.",["race:NightElf"]="Наралекса шанували серед друїдів нічних ельфів, і трагедія його падіння через Смарагдове Жахіття — болюча катастрофа для його родичів за морем.",["race:Tauren"]="Спотворені води загрожують тендітним оазам, що живлять життя в усіх Пустках, тож очищення джерел украй важливе для племен Малгору та Перехрестя."},sec={{t="Шляхетне видіння, що стало отрутою",b="The night elf druid Naralex originally discovered this vast water system and devised an ambitious design: by opening a conduit straight into the Emerald Dream, he would siphon pure primal life essence through the subterranean springs, transforming the parched Barrens back into a thriving, verdant paradise. Deep within the caverns, Naralex slipped into communion with the Dream, anchored by his loyal acolytes. Tragically, rather than tapping into pure vitality, the druid's sleeping mind touched the Emerald Nightmare. The festering corruption instantly seized him, transforming his well-intentioned conduit into a valve pouring venom and madness into the underground waterways."},{t="Друїди Ікла",b="Коли темна сила Жахіття почала струменіти від безпорадного тіла Наралекса, його учні піддалися божевіллю. Зрікшись спокійної мудрості Кола Кенарія, вони утворили фанатичну секту Друїдів Ікла. Прибравши плазуючої подоби, ватажки секти — Леді Анакондра, Лорд Кобран, Лорд Пайтас і Лорд Серпентіс — тепер не борються з отруйною мутацією печер, а віддаються їй. Вони пильно оберігають свого сплячого наставника від будь-якого втручання ззовні, вірячи, що це спотворене буяння і є справжня еволюція природи."},{t="Жахіття у плоті",b="Зламати владу Друїдів Ікла ще не означає врятувати Наралекса. Коли його вцілілі, незіпсовані учні починають біля Скелі Сновидця обряд, щоб обережно вивести його з трансу, сплячий ельф у муках підсвідомості несамовито вивергає свій найглибший жах. Істота, що вихоплюється назовні, — жахливий, потворний мурлок на ймення Мутанус Пожирач — це тілесне втілення найгірших кошмарів Наралекса. Лише вбивши цю гидоту, можна розірвати зв'язок із Жахіттям, і тоді Наралекс прокинеться, обернеться птахом і полетить геть зі зіпсованих печер."}},faq={{q="Чому вони звуться Печерами Стогонів?",a="Печери дістали назву від журливих, виючих звуків, що лунають тунелями. Ці звуки виникають природно, коли підземні струмені пари й потужні пориви вітру проштовхуються крізь вузькі тріщини у вапняку.",al={"чому печери стогонів","походження назви","чому вони стогнуть"}},{q="Чому звірі всередині стали «девіантними»?",a="Коли Наралекс потрапив під владу Смарагдового Жахіття, отруйна енергія сну просочилася просто в підземні джерела. Життя в цих заражених водах і пиття з них перетворили звичайних рапторів, кроколісків і змій на неприродні «девіантні» різновиди.",al={"скверна збочених","чому раптори мутанти","походження збочених звірів"}},{q="Хто такі Друїди Ікла?",a="Колись це були віддані учні Наралекса — нічні ельфи й таурени. Спотворені разом із ним Жахіттям, вони втратили розум і викривили своє друїдське мистецтво на поклоніння зміям і отруті, взявши собі імена на кшталт Кобран, Пітас і Анакондра.",al={"друїди ікла","лор друїдів ікла","хто серпентіс"}},{q="Чому останній бос — велетенський мурлок на ім'я Мутанус?",a="Мутанус з'являється під час спроби пробудити Наралекса. Його природа й зв'язок зі сплячим друїдом розкриваються в ході ритуалу.",al={"чому мутанус мурлок","що таке мутанус","лор останнього боса"}},{q="Що станеться після перемоги над Мутанусом?",a="Після сутички учень і далі намагається пробудити Наралекса. Доля друїда розкривається наприкінці ритуалу.",al={"пробудження наралекса","кінцівка наралекса","що буде з наралексом"}},{q="Хто живе в печері над входом до печер?",a="У скелі над входом, схожій на очницю черепа, отаборилися вірні Колу Кенарія друїди, зокрема Налпак і Ебру. Вони шукають відважних мандрівників, щоб ті здобували шкури девіантних звірів і очищали спотворення, поки воно не поглинуло всі Пустки.",al={"печера над входом","нпс змієвого черепа","хто налпак та ебру"}}},fp="15,426,31.680.0,22.528.0,24.592.1,37.248.0,50.267.0,31.252.0,51.137.1,39.130.1,52.232.0"}
P.entries["zone:westernplaguelands"] = {n="Західні Чумні Землі",s="Колись родюча житниця північного Лордерону, Західні Чумні Землі нині задихаються під отруйним туманом і легіонами нежиті. Хоча казани Кел'Тузада занапастили тутешні ферми й містечка, ґрунт і досі вперто тримається за життя. Срібний Світанок, Альянс, Відступники й Багряний Хрестовий Похід ведуть на цих сплюндрованих полях відчайдушну боротьбу.",h="Колись родюча житниця північного Лордерону, Західні Чумні Землі нині задихаються під отруйним туманом і...",kw={"західні чумні землі","андоргал","гартглен","сколомансія","гробниця утера","чумні казани","табір студеного вітру"},ang={["class:Paladin"]="Осквернені поля Лордерону — скорботне випробування для святих воїнів: тут і паломництво до Гробниці Утера, і праведна війна з жахіттями Сколомансії та спотвореними фанатиками Гартглена.",["faction:Alliance"]="Табір Студеного Вітру — передовий гарнізон Альянсу, де Командир Ашлам Валорфіст керує походами, щоб знищити чумні казани й помститися за загиблі міста Лордерону.",["faction:Horde"]="Заслон позначає рубіж володінь Відступників; звідси Орда просувається на схід, щоб знешкодити командирів Погибелі й дати відсіч багряним фанатикам на своєму вразливому фланзі.",["profession:Herbalism"]="Скверна, що досі тут лишається, робить край одним із небагатьох місць, де серед спотворених соснових гаїв можуть укорінитися рідкісні й небезпечні рослини на кшталт Чумоцвіту й Сліз Артаса."},sec={{t="Житниця Лордерону",b="До Третьої війни цей край був зеленим поясом ферм, що тягнувся на схід від Галявин Тірісфалю до Озера Дарроумер. Гартглен правив північчю з Фортеці Марденгольд, а розлоге місто Андоргал порядкувало зберіганням і вивезенням зерна по всьому королівству. Саме через цю важливу роль житниці край став головною ціллю Кел'Тузада. Підмішавши Чуму Нежиття просто в зерно, яке відвантажували з Андоргала, Культ Проклятих обернув хліб Лордерону на його погибель."},{t="Край в облозі",b="Щоб отруїти ґрунт назавжди, Погибель поставила чотири величезні чумні казани в найбільших маєтках: на Полі Скверного Каменю, у Сльозах Далсона, у Звивистому Лігві та у Всиханні Гаррона. Нині біля цих смердючих чанів порядкують жахливі Володарі Казанів, що виганяють у повітря отруйний туман. Довколишні дерева скручуються від набряклих, пухлинних наростів, а спотворені звірі шаленіють у хащах. Під Каер Дарроу на Озері Дарроумер Темний Майстер Ґандлінґ навчає некромантів у Сколомансії, ще більше посилюючи загрозу нежиті."},{t="Розділені фракції",b="Попри всюдисущу Погибель, кілька фракцій утримують тут обложені опорні пункти. Багряний Хрестовий Похід контролює фортецю Гартглен на півночі, з шаленою ревністю винищуючи все, що вважає зараженим. На півдні сили Альянсу діють із Табору Студеного Вітру, а Відступники обороняють свої кордони біля Заслону. Боротьбу з казанами нежиті спрямовує й узгоджує нейтральний Срібний світанок, що допомагає героям обох фракцій і охороняє Гробницю Утера — останню справді освячену землю в краї."}},faq={{q="Чому чума вдарила по цьому краю так сильно?",a="Андоргал був сільськогосподарським торговим вузлом північного Лордерона. Кел'Тузад навмисно вдарив по місцевих запасах: заразив зерносховища й поставив величезні чумні казани на чотирьох великих фермах, щоб швидко поширити нежиття продовольчими поставками по всьому королівству.",al={"чому чума вдарила сильно","чому андорґал","чому тут казани"}},{q="Хто контролює Гартглен на півночі?",a="Гартгленом і його фортецею, Фортецею Марденгольд, править Багряний Хрестовий Похід. Колись це був місцевий адміністративний осередок Лордерона, а тепер фанатики страчують усіх чужинців, що наближаються до їхніх меж, підозрюючи кожного, хто не належить до хрестоносців.",al={"фракція гартглена","хто в марденгольді","чи гартглен дружній"}},{q="Де гравці Альянсу й Орди можуть знайти безпечні застави?",a="Альянс тримає Табір Студеного Вітру біля південного кордону з Горами Альтерак: там є розпорядник польотів і союзники зі Срібного Світанку. Орда діє з Бастіону на західному кордоні, біля входу з Галявин Тірісфалю.",al={"де польоти","табір орди зчз","табір альянсу зчз"}},{q="Для чого чумні казани на полях?",a="Ці казани, які Культ Проклятих поставив на Полі Скверного Каменю, у Сльозах Далсона, на Гнітючому полі й у Всиханні Гаррона, безперервно випускають чумні випари в повітря й ґрунт. Агенти Срібного Світанку наймають шукачів пригод, щоб убивати Володарів Казанів і створювати протидію отруйним зіллям.",al={"що за казани","призначення казанів","казан скверного каменю"}},{q="Що таке Сколомансія і де вона?",a="Сколомансія — підземна академія некромантії, яку тримають Погибель і Культ Проклятих. Вона схована під руїнами Каер Дарроу — острівної фортеці в південно-східних водах Озера Дарроумер.",al={"місце сколомансії","де сколомансія","підземелля кер дарроу"}},{q="Чи є в Західних Чумних Землях незіпсовані місця?",a="Гробниця Утера на Пагорбі Скорботи біля південного краю лишається цілком святою й не зачепленою пошестю. Вона стоїть як освячений пам'ятник полеглому Верховному Генералові Утерові Світлоносцеві й утраченому Ордену Срібної Длані.",al={"свята земля чумних земель","чи гробниця утера чиста","чи безпечна гробниця утера"}}},fp="19,377,28.525.0,18.542.0,16.525.0,41.284.0,37.251.0,56.229.0,58.284.0,44.220.0,51.244.0"}
P.entries["zone:westfall"] = {n="Вестфол",s="Колись Вестфол був родючою житницею Королівства Стормвінд, а тепер це вітряний, занедбаний край, захоплений розбійниками. Без підтримки Корони й без військових гарнізонів уцілілі хуторяни чіпляються за свої ферми, а Братство Дефіас дедалі міцніше стискає хватку з покинутого гірницького містечка Мунбрук.",h="Колись Вестфол був родючою житницею Королівства Стормвінд, а тепер це вітряний, занедбаний край, захоплений...",kw={"вестфол","братство дефіас","мунбрук","народне ополчення","сентінел гілл","мертві копальні","едвін венкліф"},ang={["class:Rogue"]="Тіньова війна у Вестфолі зіштовхує шпигунів SI:7 віч-на-віч із тямущими розвідниками, злодіями й убивцями Братства Дефіас.",["faction:Alliance"]="Якби не Народне ополчення, що тримає Сентінел Гілл, Братство Дефіас контролювало б південні підступи аж до Лісу Елвінн.",["profession:Cooking"]="Знесилені хуторяни Ферми Салдина обходяться жорсткою місцевою дичиною й навчають мандрівників варити ситну страву, відому як Вестфоллське Рагу.",["race:Human"]="Вестфол — болісне відображення політичного розкладу Стормвінда: фермерів, що голодують у пилюці, покинула та сама знать, яку вони годували своєю працею."},sec={{t="Покинутий край",b="Поколіннями Вестфол годував Королівство Стормвінд. Його пологі пасовища й пшеничні лани квітнули, аж поки наслідки Другої війни не принесли фінансового виснаження та політичної байдужості. Королівство спрямовувало ресурси деінде й не утримувало гарнізонів, і край занепав. Нині безплідні пасовища, виття морських вітрів, збунтовані големи жнив та набіги гнолів Річколапів роблять кожен день випробуванням для тих небагатьох упертих, хто відмовляється покинути свої хутори."},{t="Піднесення Братства",b="Крах Вестфолу пришвидшився, коли Гільдія Каменярів, якій не заплатили за відбудову Стормвінда, підняла відкритий заколот. Оголошені поза законом і вигнані, каменярі на чолі з Едвіном Венкліфом перетворилися на Братство Дефіас. Вони обрали Вестфол своєю твердинею: палили поля впертих фермерів, засолювали землю й захоплювали покинуті шахти. Тепер Братство, засівши в місті-примарі Мунбруку, фактично править більшою частиною краю — хіба що без титулу."},{t="Народне ополчення",b="Дім Вельмож не зважав на біду Вестфолу, тож місцеві мешканці взялися захищатися самі. На укріпленій заставі Сентінел Гілл Ґраян Стаутмантл зібрав Народне ополчення — загін добровольців, що намагається стримати гнолів і бандитів. Регулярних вояків і припасів зі Стормвінда немає, тож Ополчення покладається на мандрівних шукачів пригод, щоб відкинути хвилю Дефіас і вберегти ферми, що ще лишилися."},{t="Змова Мертвих Копалень",b="Справжній розмах загрози Дефіас прихований під землею. Глибоко в покинутих золотих шахтах Мертвих Копалень під Мунбруком Едвін Венкліф зібрав військо з головорізів, гоблінів і ренегатів. Це вже не просто розбій: Братство будує величезний броненосець, що має піднятися вздовж узбережжя й обстріляти Стормвінд просто з моря."}},faq={{q="Чому у Вестфолі стільки покинутих ферм?",a="Стормвінд вивів свої гарнізони, коли їхнє утримання стало надто дорогим, і край лишився без захисту. Невдовзі Братство Дефіас захопило сільську місцевість: прогнало хуторян, спалило поля й перепрограмувало механічних наглядачів урожаю на смертоносних вартових.",al={"покинуті ферми","чому вестфолл мертвий","чому поля порожні"}},{q="Чому Стормвінд не посилає війська на допомогу Вестфолу?",a="Скарбниця королівства виснажена, а Дім Вельмож вважає загрози в інших краях важливішими. До того ж придворні маніпуляції потай позбавили Вестфол уваги й припасів, і місцеві мешканці мусять цілком самі давати собі раду.",al={"чому немає армії стормвінда","де вартові","допомога стормвінда"}},{q="Що таке Народне ополчення?",a="Народне ополчення — добровольча самооборона, яку зорганізував Ґраян Стаутмантл на Сентінел Гіллі. Оскільки корона відмовилася посилати у Вестфол вояків, фермери й поселенці, що лишилися, об'єдналися, щоб відбиватися від Братства Дефіас і гнолів-Річколапів.",al={"народне ополчення","ополчення сентінел гілла","армія ґріана стаутмантла"}},{q="Хто очолює Братство Дефіас у Вестфолі?",a="Едвін Венкліф, колишній голова Гільдії Каменярів, що керував відбудовою Стормвінда. Після гіркої суперечки про платню, що закінчилася заворушеннями й загибеллю королеви Тіффін, Венкліф повів своїх робітників у Вестфол і вдався до збройного заколоту.",al={"лідер дефіасу","хто веде дефіас","венкліф"}},{q="Що сховано в Мунбруку?",a="Під непримітною стодолою в Мунбруку лежить вхід до Мертвих Копалень — величезної покинутої золотої копальні, яку Братство Дефіас перетворило на підземну фортецю й корабельню для війни зі Стормвіндом.",al={"таємниця мунбрука","що в мертвих копальнях","шахта мунбрука"}},{q="Чому механічні опудала нападають на людей?",a="Спочатку цих механічних наглядачів урожаю збудували, щоб доглядати поля й відлякувати шкідників, але гоблінські майстри, пов'язані з Дефіас, захопили й переробили їх, щоб ті патрулювали поля й убивали всіх непроханих гостей.",al={"жнивні големи нападають","стражі врожаю","злі опудала"}}},fp="8,337,18.502.0,27.479.0,20.427.0,24.379.1,44.289.0,52.262.0,29.269.0,45.267.0,32.226.1,51.200.0"}
P.entries["zone:wetlands"] = {n="Багнокрай",s="Багнокрай — величезне, оповите туманом болото між горами Каз Модану та берегами Затоки Барадін. Споконвіку терзаний війнами дворфів і навалами орків, він править за суворий буферний край між Айронфорджем і північними землями Лордерону. Укріплений порт Гавань Менетіл — головна рятівна нитка Альянсу в цій розмоклій глушині, яку заполонили орки Драконячої Пащі, мурлоки й гноли.",h="Багнокрай — величезне, оповите туманом болото між горами Каз Модану та берегами Затоки Барадін.",kw={"багнокрай","гавань менетіл","ґрім батол","драконяча паща","дун модр","темне залізо","болота"},ang={["faction:Alliance"]="Гавань Менетіл — головні глибоководні ворота Альянсу через Велике Море, що поєднують королівства сходу з експедиційними заставами в Калімдорі.",["profession:Mining"]="Пагорби й печерні глибини Каменя Тельґен приховують багаті рудні жили, зокрема рідкісні поклади інцендицитової руди, якої так прагнуть дворфійські гірники й інженери.",["race:Dwarf"]="Для дворфів Багнокрай — місце гірко-солодких спогадів: тут втрачено Дун Модр, тут сталася давня трагедія Ґрім Батолу, і тут досі тривають труди з оборони торгового шляху короля Маґні на північ."},sec={{t="Край води й руїн",b="Багнокрай, що простягається під височенним урвищем Каменетесної Греблі, — холодний, підтоплений простір, оповитий вічним туманом під одноманітним сірим небом. Колись тут квітли дворфійські поселення, а тепер болота всіяні затонулими кам'яними руїнами, розмоклими трясовинами й підступними драговинами. Шукачам пригод доводиться пробиратися вузькими проходами: або рухатися на північ з Лох Модану крізь забарикадовану ущелину Дун Алґаз, або перейти височенні арки Мосту Тандол з Аратійського нагір'я."},{t="Шрами Ґрім Батолу",b="Над східними околицями боліт похмуро нависає Ґрім Батол — колишня твердиня Вайлдгаммерів. Осквернена під час Війни Трьох Молотів, у Другу війну вона стала укріпленим сховком клану Драконячої Пащі. Коли червоні дракони вирвалися з орківського полону, їхня вогняна помста розгромила орківські сили й спустошила довколишні схили. Нині червоні драконорідні стережуть Брами Драконячої Пащі від будь-яких непроханих гостей, а здичавілі рештки клану Драконячої Пащі живуть у розкиданих по пагорбах таборах і далі нападають на мандрівників по всіх болотах."},{t="Порт західного узбережжя",b="Гавань Менетіл, що примостилася на березі Затоки Барадін, — живе серце торгівлі та постачання Альянсу в Каз Модані. Названий на честь короля Теренаса Менетіла II, цей стійкий порт поєднує Східні Королівства з далеким Калімдором: звідси регулярно ходять кораблі до Обердайна й Острова Терамор. Попри стратегічну військову вагу та міцну дворфійську архітектуру, гавані повсякчас загрожують прибережні мурлоки, болотяні істоти й морські розбійники, що полюють на судна в скелястих протоках."},{t="Обложені рубежі",b="Багнокрай — справжня зона бойових дій на кількох фронтах. На далекій півночі дворфи Темного Заліза під проводом чорнокнижника Балґараса Мерзенного підірвали Міст Тандол і захопили містечко Дун Модр, перерізавши сухопутні обози з припасами. Тим часом мохошкірі гноли безчинствують на центральних драговинах, загрожуючи навіть прадавнім охоронцям на кшталт Ретіеля Зеленовартового. Між свавільними загонами орків, лазутчиками Темного Заліза та проклятими уламками кораблів уздовж узбережжя утримати болота можна лише за невсипущої пильності."}},faq={{q="Як дістатися до Багнокраю пішки?",a="Шукачі пригод з Альянсу зазвичай ідуть на північ із Лох Модану гірським перевалом Дун Алґаз. Мандрівники Орди, що йдуть із півночі, можуть перейти Міст Тандол з Аратійського нагір'я. Будьте обережні: за обидва проходи змагаються ворожі сили, як-от орки Драконячої Пащі й дворфи Темного Заліза.",al={"як дістатися до багнокраю","шлях до багнокраю","пішки до багнокраю"}},{q="Куди пливуть кораблі з Гавані Менетіл?",a="З причалів Гавані Менетіл ходять два головні пороми на Калімдор: один корабель пливе через Велике Море до Обердайна на березі Темного Узбережжя, а другий — на південь, до Острова Терамор у Багні Пилоброду.",al={"човни менетілу","кораблі гавані менетіл","куди пливе човен у багнокраї"}},{q="Що таке Ґрім Батол і чому його охороняють?",a="Ґрім Батол — прадавня дворфійська фортеця, покинута після Війни Трьох Молотів і згодом зайнята кланом Драконячої Пащі. Після Другої війни звільнена червона драконячий рід вигнала орків і запечатала гору. Могутні червоні драконороди й вірмороди патрулюють Брами Драконячої Пащі, щоб ніхто не увійшов до проклятих залів.",al={"чому дракони біля ґрім батола","червоні дракони ґрім батол","брами драконячої пащі"}},{q="Що сталося з Дун Модром?",a="Дун Модр — північна дворфійська твердиня, що стерегла Міст Тандол. Нещодавно на неї напали й захопили дворфи Темного Заліза на чолі з Балґарасом Мерзенним. Уцілілі під проводом Раґа Ґармасона тримають обложений табір неподалік і борються за повернення свого містечка.",al={"хто зруйнував дун модр","руїни дун модра","темне залізо в дун модрі"}},{q="Хто такий Ретіель Зеленовартовий?",a="Ретіель — прадавній болотяний звір, що живе на Зеленому Поясі Багнокраю. Він просить мандрівників допомогти стримати навалу агресивних гнолів-Мохошкірих і знищити хворих болотяних повзунів, щоб драговина могла відродитися.",al={"зелений пояс","ретіель багнокрай","хто такий зеленовартовий"}},{q="Звідки в болоті всі ці орки?",a="Орки належать до клану Драконячої Пащі, що під час Другої війни укріпився в Ґрім Батолі. Розгромлені звільненою червоною драконячою зграєю, уцілілі орки втекли вниз, у болота й пагорби, звідки досі нападають на дороги й мандрівників.",al={"чому орки в багнокраї","драконяча паща багнокрай","клан драконячої пащі багнокрай"}}},fp="8,418,24.524.0,23.601.0,22.527.0,18.503.0,40.301.0,41.216.0,41.343.0,26.268.0,31.214.0,46.277.0"}
P.entries["zone:winterspring"] = {n="Вінтерспрінг",s="Вінтерспрінг — величезна засніжена долина високо на північно-східних схилах Гори Гіджал, просто над зачарованими лісами Місячного Гаю й Сквернолісся. Цей край, відомий лютими морозами, давніми руїнами Високородних і мандрівними грізними хижаками, тримається довкола нейтральної гоблінської застави Евірлук. Це земля суворих природних небезпек: тут знаходять прихисток рештки синього драконячого роду, а на південних висотах доводиться протистояти демонічній скверні.",h="Вінтерспрінг — величезна засніжена долина високо на північно-східних схилах Гори Гіджал, просто над...",kw={"вінтерспрінг","евірлук","мазторіл","кел'теріл","синій драконячий рід","фурболги","нордрассіл"},ang={["class:Druid"]="Вінтерспрінг, що лежить високо над Місячним Гаєм, має для вас священне значення: саме тут під час Третьої війни Малфуріон Стормрейдж пробудив Друїдів Кігтя від їхнього прадавнього сну.",["faction:Alliance"]="Герої Альянсу часто навідуються до Ріверн Фроствінд на Камені Морозних Шаблезубів і невтомно трудяться на лютому морозі, щоб заслужити вірність славетних скакунів — Морозних Шаблезубів з Вінтерспрінга.",["profession:Herbalism"]="Вінтерспрінг — єдине відоме місце, де росте Крижана шапка, незамінна гірська трава, яку дуже цінують для складних алхімічних сумішей; тут також трапляються Гірський Срібношавлій і рідкісні квіти Чорного Лотосу.",["profession:Mining"]="Крижані скелі й стіни печер долини багаті на цінні мінерали: тут часто трапляються жили малого й багатого торію, а також рідкісні поклади справжнього срібла.",["race:NightElf"]="Вінтерспрінг тісно пов'язаний з історією вашого народу: тут курганні лігва, де тисячоліттями спочивали Друїди Кігтя, трагічні руїни Кел'Теріла й оголені корені Нордрассіла, пошкоджені в Битві за Гору Гіджал."},sec={{t="Край вічного морозу",b="Вінтерспрінг лежить на тисячі футів вище за довколишні нетрі, під свіжим гірським повітрям і невпинними хуртовинами. Величезні оголені корені Світового Дерева, Нордрассіла, прорізають замети, наче височенні дерев'яні арки, вигнуті й покручені у вирішальних битвах Третьої війни. Хоча більшу частину північного Калімдору вкривають густі ліси й там тепліше, Вінтерспрінг — тихий край негустих гірських лісів, скелястих урвищ і замерзлих озер, де живуть грізні морозні шаблезуби, химери, єті й зимові ведмеді з густим хутром."},{t="Перехрестя й застави",b="Щоб дістатися цього високого плато, треба пройти давніми висіченими переходами Твердині Деревопащих, які стережуть неосквернені фурболги, що пильно оглядають кожного мандрівника з боку Сквернолісся чи Місячного Гаю. У центрі долини стоїть Евірлук — квітуче торговельне містечко, яким керує картель Стімвідл. Гобліни радо вітають шукачів пригод і з Альянсу, і з Орди, широко відчиняючи каси: це незамінний прихисток, де є інженерія, торгівля й теплі вогнища проти пекучого гірського морозу."},{t="Давні привиди й сині дракони",b="За століття до появи нинішніх поселень давні ельфи звели на березі озера місто Кел'Теріл. Коли безрозсудні чародії з Високородних розбили проклятий Кристал Зін-Малора, ними заволоділо безумство, і досі неспокійні привиди блукають серед зруйнованих колон і замерзлих вод. Південніше здіймаються печерні висоти Мазторілу — споконвічна твердиня синього драконячого роду в Калімдорі. Тут виводок Чароткача Малігоса під наглядом захисниці-матрони Гале пильнує потоки таємної магії й дає відсіч місцевим загрозам."},{t="Тінь над ущелиною",b="Спокій Вінтерспрінга різко уривається на самій південній межі, біля Ущелини Темного Шепоту. Там елітні демонічні сили — рештки легіонів Третьої війни — повзають зубчастими каньйонами, перекриваючи високі підступи до вершини Гори Гіджал. Тим часом місцеві фурболги Зимопаду піддалися мерзенній скверні, і незалежні дослідники на кшталт Донови Сноуден вивчають цю заразу, доки вона не поглинула всіх звірів долини."}},faq={{q="Як дістатися до Вінтерспрінга?",a="Мандрівникам треба пройти Твердинею Деревопащих — мережею підземних тунелів на північному сході Сквернолісся. Щоб мирно пройти печерами, треба здобути довіру місцевих фурболгів Деревопащих, які нападають на всіх непроханих гостей, що здаються їм ворожими. За східним виходом одразу відкриваються засніжені схили Вінтерспрінга.",al={"дістатися до вінтерспрінга","як зайти у вінтерспрінг","вхід у вінтерспрінг","тунель деревопащих вінтерспрінг"}},{q="Хто керує містечком Евірлук?",a="Евірлуком керує картель Стімвідл, гоблінський торговий концерн. Завдяки суворій гоблінській жазі прибутку й нейтралітету мандрівники і з Орди, і з Альянсу можуть користуватися тутешніми розпорядниками польотів, ремонтниками, банківськими сховищами й товарами, якщо не порушують миру в межах містечка.",al={"хто керує евірлуком","фракція евірлука","чи евірлук нейтральний"}},{q="Що за привиди блукають Озером Кел'Теріл?",a="Це духи нічних ельфів-Високородних, що десять тисяч років тому жили в прадавньому місті Кел'Теріл. Коли їхні чаклуни взялися до викраденого Кристала Зін-Малора, той розколовся й вивільнив страшне прокляття. Експедиції високих ельфів, що прибули сюди століттями пізніше, так само збожеволіли й тепер приречені блукати замерзлими руїнами поруч зі своїми предками.",al={"привиди озера кел'теріл","духи руїн кел'теріл","хто біля кел'теріл"}},{q="Чому фурболги-Зимопади агресивні?",a="Фурболги-Зимопади піддалися неприродному спотворенню, що шириться краєм і довело їхній клан до шаленої ворожості. Тоді як сусідні Деревопащі міцно тримаються здорового глузду, Зимопади потрапили під темний вплив, тож дослідники на кшталт Донови Сноуден вивчають їхню скверну й очищують їхні табори.",al={"чому зимопади ворожі","скверна зимопадів","донова сноуден фурболги"}},{q="Хто живе в Мазторілі?",a="Мазторіл — головне гніздовище й прихисток синьої драконячого роду на Калімдорі. Глибоко в його печерних шпилях вірмороди, добірні дракончата й прадавні дракони стережуть могутні драконячі реліквії й таємні знання під пильним оком Гале, супутниці Аспекта Малігоса.",al={"дракони мазторіла","що таке мазторіл","сині дракони вінтерспрінгу"}},{q="Що таке Ущелина Темного Шепоту?",a="Ущелина Темного Шепоту — підступний каньйон на крайньому півдні долини, де засіли могутні добірні демони, що лишилися після Третьої війни. Це добре охоронюване прикордоння вздовж небезпечних стежок, що ведуть до висот Гори Гіджал.",al={"демони темного шепоту","що в ущелині темного шепоту","брама гіджал вінтерспрінг"}},{q="Чи можна тут навчитися їздити на морозних шаблезубах чи приручити їх?",a="На Камені Морозних Шаблезубів далеко на півночі долини нічний ельф Ріверн Фроствінд доглядає місцевих білих котів. Шукачі пригод, які допоможуть йому з припасами й захистом прайду, можуть довести, що гідні дізнатися таємниці вирощування морозного шаблезуба й їзди на ньому.",al={"морозний шаблезуб їздова","рівен морозний шаблезуб","як отримати морозного шаблезуба"}}},fp="12,467,26.561.0,23.475.0,26.540.0,31.471.0,29.342.0,30.316.0,45.381.0,43.326.0,28.272.0,26.260.0,39.291.0"}
P.entries["zone:zephras"] = {n="Острів Зефрас",s="Острів Зефрас — летючий острів, що ширяє в Небесній Тверді, Царстві Стихій повітря. Це прадавня домівка небороджених і місце, де починається їхній шлях. Нині їхнє суспільство постало перед загрозою зникнення: магія, що тримає острів, поступово вивітрюється. Зв'язок із сусідніми небесними краями обірвався, і мешканці острова борються з розпадом стихій і напливом біженців.",h="Острів Зефрас — летючий острів, що ширяє в Небесній Тверді, Царстві Стихій повітря.",kw={"острів зефрас","небесна твердь","небороджені","елементалі","валанаар","повітряні кораблі","біженці"},ang={["class:Shaman"]="Острів Зефрас, що лежить просто в Царстві Стихій повітря, показує, що стається зі стихійними землями, коли духи, які тримають їх у рівновазі, раптом зникають.",["race:Skyborne"]="Острів Зефрас — ваша прадавня домівка й місце, де починається ваш шлях, хоча його тиха краса приховує нагальну кризу: земля розсипається, а сила стихій згасає."},sec={{t="Край у піднебессі",b="Острів Зефрас — відокремлений клаптик суходолу, що дрейфує в безкраїх вітрах Небесної Тверді. Поколіннями небороджені жили тут пліч-о-пліч із місцевими повітряними елементалями, які допомагали підтримувати магічні течії, що тримали острів у повітрі. Та кілька століть тому ці стихійні охоронці зникли без сліду. Без їхньої присутності й опіки приховані чари, що тримають землю, поволі почали слабнути, і Зефрас помалу тріщить і втрачає рівновагу."},{t="Обірвані обрії",b="Зефрас був не єдиним притулком небороджених в Царстві Стихій. Небесною Твердю дрейфували й острови-побратими — Анвілас і Сіроккас, — але після зникнення елементалів зв'язок між ними урвався. Останнім часом біженці з цих сусідніх островів, що розсипаються, зуміли дістатися Зефраса в пошуках безпеки й принесли похмурі звістки: інші острови буквально розпадаються в них під ногами."},{t="Поріг до Азерота",b="Їхній власний острів поволі руйнується, тож небороджені Зефраса почали вдивлятися за межі Небесної Тверді — в бік Азерота. Із небесних доків Валанаара тепер вирушають повітряні кораблі, щоб прокласти рідкісні рятівні шляхи до світу смертних. Ці подорожі поєднують повітряні володіння просто з місцями в Азероті — зокрема з околицями Даларану в Горах Альтерак і Плато Небоглядів у Малгорі."}},faq={{q="Де розташований Острів Зефрас?",a="Острів Зефрас лежить не на поверхні Азерота, а в Небесній Тверді — Царстві Стихій повітря. Він ширяє серед вічних хмар і вітряних течій цих ефірних володінь.",al={"де острів зефрас","де знаходиться зефрас","у якому царстві зефрас"}},{q="Чому Острів Зефрас розвалюється?",a="Острів тримався завдяки місцевим повітряним елементалям, які колись жили пліч-о-пліч із небородженими. Кілька століть тому ці елементалі зникли, і магічні основи, що тримають і бережуть летючу землю, з часом почали поволі слабнути й руйнуватися.",al={"чому зефрас руйнується","руйнування острова зефрас","острів, що гине"}},{q="Що таке Анвілас і Сіроккас?",a="Це сусідні летючі острови в Небесній Тверді, де теж живуть небороджені. Коли елементалі зникли, Острів Зефрас утратив зв'язок з обома, а біженці, що звідти тікають, розповідають, що і Анвілас, і Сіроккас розсипаються в небуття.",al={"анвілас","сіроккас","інші острови небороджених"}},{q="Як дістатися з Острова Зефрас до Азерота й назад?",a="Небороджені тримають небесні доки в поселенні Валанаар. Звідти повітряні кораблі перетинають межу царств і приземляються в Азероті — біля Даларану в Горах Альтерак і на Плато Небоглядів у Малгорі.",al={"як покинути зефрас","повітряні кораблі зефраса","подорож до азерота"}},{q="Хто такі небороджені?",a="Небороджені — мешканці Острова Зефрас і його небесних островів-побратимів. Вони поколіннями жили в Небесній Тверді, а тепер бачать, як їхня летюча батьківщина поволі руйнується, бо магія, що тримає її вкупі, згасає.",al={"раса небороджених","хто живе на зефрасі"}},{q="Хто ще живе на Острові Зефрас, окрім небороджених?",a="Окрім мирних сіл і біженців, острів потерпає від місцевих розбійників, нічнокігтів, що живуть у печерах, і звірів, які населяють такі місця, як Лігво Верескунів і Печера Нічнокігтів.",al={"мешканці зефраса","вороги на зефрасі"}}},fp="12,364,13.457.0,16.440.0,20.405.0,30.189.0,34.257.0,30.248.0,54.216.0,21.226.0,47.194.0"}
